INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('45', 'rm', 'Roma', 11, 13, 'Aku berkata kepada kamu, hai bangsa-bangsa bukan Yahudi. Justru karena aku adalah rasul untuk bangsa-bangsa bukan Yahudi, aku menganggap hal itu kemuliaan pelayananku,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 14, 'yaitu kalau-kalau aku dapat membangkitkan cemburu di dalam hati kaum sebangsaku menurut daging dan dapat menyelamatkan beberapa orang dari mereka.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 15, 'Sebab jika penolakan mereka berarti perdamaian bagi dunia, dapatkah penerimaan mereka mempunyai arti lain dari pada hidup dari antara orang mati?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 16, 'Jikalau roti sulung adalah kudus, maka seluruh adonan juga kudus, dan jikalau akar adalah kudus, maka cabang-cabang juga kudus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 17, 'Karena itu apabila beberapa cabang telah dipatahkan dan kamu sebagai tunas liar telah dicangkokkan di antaranya dan turut mendapat bagian dalam akar pohon zaitun yang penuh getah,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 18, 'janganlah kamu bermegah terhadap cabang-cabang itu! Jikalau kamu bermegah, ingatlah, bahwa bukan kamu yang menopang akar itu, melainkan akar itu yang menopang kamu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 19, 'Mungkin kamu akan berkata: ada cabang-cabang yang dipatahkan, supaya aku dicangkokkan di antaranya sebagai tunas.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 20, 'Baiklah! Mereka dipatahkan karena ketidakpercayaan mereka, dan kamu tegak tercacak karena iman. Janganlah kamu sombong, tetapi takutlah!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 21, 'Sebab kalau Allah tidak menyayangkan cabang-cabang asli, Ia juga tidak akan menyayangkan kamu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 22, 'Sebab itu perhatikanlah kemurahan Allah dan juga kekerasan-Nya, yaitu kekerasan atas orang-orang yang telah jatuh, tetapi atas kamu kemurahan-Nya, yaitu jika kamu tetap dalam kemurahan-Nya; jika tidak, kamupun akan dipotong juga.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 23, 'Tetapi merekapun akan dicangkokkan kembali, jika mereka tidak tetap dalam ketidakpercayaan mereka, sebab Allah berkuasa untuk mencangkokkan mereka kembali.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 24, 'Sebab jika kamu telah dipotong sebagai cabang dari pohon zaitun liar, dan bertentangan dengan keadaanmu itu kamu telah dicangkokkan pada pohon zaitun sejati, terlebih lagi mereka ini, yang menurut asal mereka akan dicangkokkan pada pohon zaitun mereka sendiri.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 25, 'Sebab, saudara-saudara, supaya kamu jangan menganggap dirimu pandai, aku mau agar kamu mengetahui rahasia ini: Sebagian dari Israel telah menjadi tegar sampai jumlah yang penuh dari bangsa-bangsa lain telah masuk.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 26, 'Dengan jalan demikian seluruh Israel akan diselamatkan, seperti ada tertulis: "Dari Sion akan datang Penebus, Ia akan menyingkirkan segala kefasikan dari pada Yakub.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 27, 'Dan inilah perjanjian-Ku dengan mereka, apabila Aku menghapuskan dosa mereka."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 28, 'Mengenai Injil mereka adalah seteru Allah oleh karena kamu, tetapi mengenai pilihan mereka adalah kekasih Allah oleh karena nenek moyang.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 29, 'Sebab Allah tidak menyesali kasih karunia dan panggilan-Nya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 30, 'Sebab sama seperti kamu dahulu tidak taat kepada Allah, tetapi sekarang beroleh kemurahan oleh ketidaktaatan mereka,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 31, 'demikian juga mereka sekarang tidak taat, supaya oleh kemurahan yang telah kamu peroleh, mereka juga akan beroleh kemurahan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 32, 'Sebab Allah telah mengurung semua orang dalam ketidaktaatan, supaya Ia dapat menunjukkan kemurahan-Nya atas mereka semua.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 33, 'O, alangkah dalamnya kekayaan, hikmat dan pengetahuan Allah! Sungguh tak terselidiki keputusan-keputusan-Nya dan sungguh tak terselami jalan-jalan-Nya!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 34, 'Sebab, siapakah yang mengetahui pikiran Tuhan? Atau siapakah yang pernah menjadi penasihat-Nya?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 35, 'Atau siapakah yang pernah memberikan sesuatu kepada-Nya, sehingga Ia harus menggantikannya?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 36, 'Sebab segala sesuatu adalah dari Dia, dan oleh Dia, dan kepada Dia: Bagi Dialah kemuliaan sampai selama-lamanya!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 1, 'Karena itu, saudara-saudara, demi kemurahan Allah aku menasihatkan kamu, supaya kamu mempersembahkan tubuhmu sebagai persembahan yang hidup, yang kudus dan yang berkenan kepada Allah: itu adalah ibadahmu yang sejati.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 2, 'Janganlah kamu menjadi serupa dengan dunia ini, tetapi berubahlah oleh pembaharuan budimu, sehingga kamu dapat membedakan manakah kehendak Allah: apa yang baik, yang berkenan kepada Allah dan yang sempurna.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 3, 'Berdasarkan kasih karunia yang dianugerahkan kepadaku, aku berkata kepada setiap orang di antara kamu: Janganlah kamu memikirkan hal-hal yang lebih tinggi dari pada yang patut kamu pikirkan, tetapi hendaklah kamu berpikir begitu rupa, sehingga kamu menguasai diri menurut ukuran iman, yang dikaruniakan Allah kepada kamu masing-masing.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 4, 'Sebab sama seperti pada satu tubuh kita mempunyai banyak anggota, tetapi tidak semua anggota itu mempunyai tugas yang sama,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 5, 'demikian juga kita, walaupun banyak, adalah satu tubuh di dalam Kristus; tetapi kita masing-masing adalah anggota yang seorang terhadap yang lain.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 6, 'Demikianlah kita mempunyai karunia yang berlain-lainan menurut kasih karunia yang dianugerahkan kepada kita: Jika karunia itu adalah untuk bernubuat baiklah kita melakukannya sesuai dengan iman kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 7, 'Jika karunia untuk melayani, baiklah kita melayani; jika karunia untuk mengajar, baiklah kita mengajar;', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 8, 'jika karunia untuk menasihati, baiklah kita menasihati. Siapa yang membagi-bagikan sesuatu, hendaklah ia melakukannya dengan hati yang ikhlas; siapa yang memberi pimpinan, hendaklah ia melakukannya dengan rajin; siapa yang menunjukkan kemurahan, hendaklah ia melakukannya dengan sukacita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 9, 'Hendaklah kasih itu jangan pura-pura! Jauhilah yang jahat dan lakukanlah yang baik.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 10, 'Hendaklah kamu saling mengasihi sebagai saudara dan saling mendahului dalam memberi hormat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 11, 'Janganlah hendaknya kerajinanmu kendor, biarlah rohmu menyala-nyala dan layanilah Tuhan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 12, 'Bersukacitalah dalam pengharapan, sabarlah dalam kesesakan, dan bertekunlah dalam doa!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 13, 'Bantulah dalam kekurangan orang-orang kudus dan usahakanlah dirimu untuk selalu memberikan tumpangan!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 14, 'Berkatilah siapa yang menganiaya kamu, berkatilah dan jangan mengutuk!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 15, 'Bersukacitalah dengan orang yang bersukacita, dan menangislah dengan orang yang menangis!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 16, 'Hendaklah kamu sehati sepikir dalam hidupmu bersama; janganlah kamu memikirkan perkara-perkara yang tinggi, tetapi arahkanlah dirimu kepada perkara-perkara yang sederhana. Janganlah menganggap dirimu pandai!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 17, 'Janganlah membalas kejahatan dengan kejahatan; lakukanlah apa yang baik bagi semua orang!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 18, 'Sedapat-dapatnya, kalau hal itu bergantung padamu, hiduplah dalam perdamaian dengan semua orang!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 19, 'Saudara-saudaraku yang kekasih, janganlah kamu sendiri menuntut pembalasan, tetapi berilah tempat kepada murka Allah, sebab ada tertulis: Pembalasan itu adalah hak-Ku. Akulah yang akan menuntut pembalasan, firman Tuhan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 20, 'Tetapi, jika seterumu lapar, berilah dia makan; jika ia haus, berilah dia minum! Dengan berbuat demikian kamu menumpukkan bara api di atas kepalanya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 12, 21, 'Janganlah kamu kalah terhadap kejahatan, tetapi kalahkanlah kejahatan dengan kebaikan!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 1, 'Tiap-tiap orang harus takluk kepada pemerintah yang di atasnya, sebab tidak ada pemerintah, yang tidak berasal dari Allah; dan pemerintah-pemerintah yang ada, ditetapkan oleh Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 2, 'Sebab itu barangsiapa melawan pemerintah, ia melawan ketetapan Allah dan siapa yang melakukannya, akan mendatangkan hukuman atas dirinya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 3, 'Sebab jika seorang berbuat baik, ia tidak usah takut kepada pemerintah, hanya jika ia berbuat jahat. Maukah kamu hidup tanpa takut terhadap pemerintah? Perbuatlah apa yang baik dan kamu akan beroleh pujian dari padanya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 4, 'Karena pemerintah adalah hamba Allah untuk kebaikanmu. Tetapi jika engkau berbuat jahat, takutlah akan dia, karena tidak percuma pemerintah menyandang pedang. Pemerintah adalah hamba Allah untuk membalaskan murka Allah atas mereka yang berbuat jahat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 5, 'Sebab itu perlu kita menaklukkan diri, bukan saja oleh karena kemurkaan Allah, tetapi juga oleh karena suara hati kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 6, 'Itulah juga sebabnya maka kamu membayar pajak. Karena mereka yang mengurus hal itu adalah pelayan-pelayan Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 7, 'Bayarlah kepada semua orang apa yang harus kamu bayar: pajak kepada orang yang berhak menerima pajak, cukai kepada orang yang berhak menerima cukai; rasa takut kepada orang yang berhak menerima rasa takut dan hormat kepada orang yang berhak menerima hormat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 8, 'Janganlah kamu berhutang apa-apa kepada siapapun juga, tetapi hendaklah kamu saling mengasihi. Sebab barangsiapa mengasihi sesamanya manusia, ia sudah memenuhi hukum Taurat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 9, 'Karena firman: jangan berzinah, jangan membunuh, jangan mencuri, jangan mengingini dan firman lain manapun juga, sudah tersimpul dalam firman ini, yaitu: Kasihilah sesamamu manusia seperti dirimu sendiri!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 10, 'Kasih tidak berbuat jahat terhadap sesama manusia, karena itu kasih adalah kegenapan hukum Taurat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 11, 'Hal ini harus kamu lakukan, karena kamu mengetahui keadaan waktu sekarang, yaitu bahwa saatnya telah tiba bagi kamu untuk bangun dari tidur. Sebab sekarang keselamatan sudah lebih dekat bagi kita dari pada waktu kita menjadi percaya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 12, 'Hari sudah jauh malam, telah hampir siang. Sebab itu marilah kita menanggalkan perbuatan-perbuatan kegelapan dan mengenakan perlengkapan senjata terang!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 13, 'Marilah kita hidup dengan sopan, seperti pada siang hari, jangan dalam pesta pora dan kemabukan, jangan dalam percabulan dan hawa nafsu, jangan dalam perselisihan dan iri hati.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 13, 14, 'Tetapi kenakanlah Tuhan Yesus Kristus sebagai perlengkapan senjata terang dan janganlah merawat tubuhmu untuk memuaskan keinginannya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 1, 'Terimalah orang yang lemah imannya tanpa mempercakapkan pendapatnya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 2, 'Yang seorang yakin, bahwa ia boleh makan segala jenis makanan, tetapi orang yang lemah imannya hanya makan sayur-sayuran saja.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 3, 'Siapa yang makan, janganlah menghina orang yang tidak makan, dan siapa yang tidak makan, janganlah menghakimi orang yang makan, sebab Allah telah menerima orang itu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 4, 'Siapakah kamu, sehingga kamu menghakimi hamba orang lain? Entahkah ia berdiri, entahkah ia jatuh, itu adalah urusan tuannya sendiri. Tetapi ia akan tetap berdiri, karena Tuhan berkuasa menjaga dia terus berdiri.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 5, 'Yang seorang menganggap hari yang satu lebih penting dari pada hari yang lain, tetapi yang lain menganggap semua hari sama saja. Hendaklah setiap orang benar-benar yakin dalam hatinya sendiri.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 6, 'Siapa yang berpegang pada suatu hari yang tertentu, ia melakukannya untuk Tuhan. Dan siapa makan, ia melakukannya untuk Tuhan, sebab ia mengucap syukur kepada Allah. Dan siapa tidak makan, ia melakukannya untuk Tuhan, dan ia juga mengucap syukur kepada Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 7, 'Sebab tidak ada seorangpun di antara kita yang hidup untuk dirinya sendiri, dan tidak ada seorangpun yang mati untuk dirinya sendiri.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 8, 'Sebab jika kita hidup, kita hidup untuk Tuhan, dan jika kita mati, kita mati untuk Tuhan. Jadi baik hidup atau mati, kita adalah milik Tuhan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 9, 'Sebab untuk itulah Kristus telah mati dan hidup kembali, supaya Ia menjadi Tuhan, baik atas orang-orang mati, maupun atas orang-orang hidup.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 10, 'Tetapi engkau, mengapakah engkau menghakimi saudaramu? Atau mengapakah engkau menghina saudaramu? Sebab kita semua harus menghadap takhta pengadilan Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 11, 'Karena ada tertulis: "Demi Aku hidup, demikianlah firman Tuhan, semua orang akan bertekuk lutut di hadapan-Ku dan semua orang akan memuliakan Allah."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 12, 'Demikianlah setiap orang di antara kita akan memberi pertanggungan jawab tentang dirinya sendiri kepada Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 13, 'Karena itu janganlah kita saling menghakimi lagi! Tetapi lebih baik kamu menganut pandangan ini: Jangan kita membuat saudara kita jatuh atau tersandung!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 14, 'Aku tahu dan yakin dalam Tuhan Yesus, bahwa tidak ada sesuatu yang najis dari dirinya sendiri. Hanya bagi orang yang beranggapan, bahwa sesuatu adalah najis, bagi orang itulah sesuatu itu najis.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 15, 'Sebab jika engkau menyakiti hati saudaramu oleh karena sesuatu yang engkau makan, maka engkau tidak hidup lagi menurut tuntutan kasih. Janganlah engkau membinasakan saudaramu oleh karena makananmu, karena Kristus telah mati untuk dia.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 16, 'Apa yang baik, yang kamu miliki, janganlah kamu biarkan difitnah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 17, 'Sebab Kerajaan Allah bukanlah soal makanan dan minuman, tetapi soal kebenaran, damai sejahtera dan sukacita oleh Roh Kudus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 18, 'Karena barangsiapa melayani Kristus dengan cara ini, ia berkenan pada Allah dan dihormati oleh manusia.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 19, 'Sebab itu marilah kita mengejar apa yang mendatangkan damai sejahtera dan yang berguna untuk saling membangun.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 20, 'Janganlah engkau merusakkan pekerjaan Allah oleh karena makanan! Segala sesuatu adalah suci, tetapi celakalah orang, jika oleh makanannya orang lain tersandung!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 21, 'Baiklah engkau jangan makan daging atau minum anggur, atau sesuatu yang menjadi batu sandungan untuk saudaramu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 22, 'Berpeganglah pada keyakinan yang engkau miliki itu, bagi dirimu sendiri di hadapan Allah. Berbahagialah dia, yang tidak menghukum dirinya sendiri dalam apa yang dianggapnya baik untuk dilakukan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 14, 23, 'Tetapi barangsiapa yang bimbang, kalau ia makan, ia telah dihukum, karena ia tidak melakukannya berdasarkan iman. Dan segala sesuatu yang tidak berdasarkan iman, adalah dosa.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 1, 'Kita, yang kuat, wajib menanggung kelemahan orang yang tidak kuat dan jangan kita mencari kesenangan kita sendiri.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 2, 'Setiap orang di antara kita harus mencari kesenangan sesama kita demi kebaikannya untuk membangunnya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 3, 'Karena Kristus juga tidak mencari kesenangan-Nya sendiri, tetapi seperti ada tertulis: "Kata-kata cercaan mereka, yang mencerca Engkau, telah mengenai aku."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 4, 'Sebab segala sesuatu yang ditulis dahulu, telah ditulis untuk menjadi pelajaran bagi kita, supaya kita teguh berpegang pada pengharapan oleh ketekunan dan penghiburan dari Kitab Suci.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 5, 'Semoga Allah, yang adalah sumber ketekunan dan penghiburan, mengaruniakan kerukunan kepada kamu, sesuai dengan kehendak Kristus Yesus,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 6, 'sehingga dengan satu hati dan satu suara kamu memuliakan Allah dan Bapa Tuhan kita, Yesus Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 7, 'Sebab itu terimalah satu akan yang lain, sama seperti Kristus juga telah menerima kita, untuk kemuliaan Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 8, 'Yang aku maksudkan ialah, bahwa oleh karena kebenaran Allah Kristus telah menjadi pelayan orang-orang bersunat untuk mengokohkan janji yang telah diberikan-Nya kepada nenek moyang kita,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 9, 'dan untuk memungkinkan bangsa-bangsa, supaya mereka memuliakan Allah karena rahmat-Nya, seperti ada tertulis: "Sebab itu aku akan memuliakan Engkau di antara bangsa-bangsa dan menyanyikan mazmur bagi nama-Mu."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 10, 'Dan selanjutnya: "Bersukacitalah, hai bangsa-bangsa, dengan umat-Nya."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 11, 'Dan lagi: "Pujilah Tuhan, hai kamu semua bangsa-bangsa, dan biarlah segala suku bangsa memuji Dia."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 12, 'Dan selanjutnya kata Yesaya: "Taruk dari pangkal Isai akan terbit, dan Ia akan bangkit untuk memerintah bangsa-bangsa, dan kepada-Nyalah bangsa-bangsa akan menaruh harapan."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 13, 'Semoga Allah, sumber pengharapan, memenuhi kamu dengan segala sukacita dan damai sejahtera dalam iman kamu, supaya oleh kekuatan Roh Kudus kamu berlimpah-limpah dalam pengharapan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 14, 'Saudara-saudaraku, aku sendiri memang yakin tentang kamu, bahwa kamu juga telah penuh dengan kebaikan dan dengan segala pengetahuan dan sanggup untuk saling menasihati.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 15, 'Namun, karena kasih karunia yang telah dianugerahkan Allah kepadaku, aku di sana sini dengan agak berani telah menulis kepadamu untuk mengingatkan kamu,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 16, 'yaitu bahwa aku boleh menjadi pelayan Kristus Yesus bagi bangsa-bangsa bukan Yahudi dalam pelayanan pemberitaan Injil Allah, supaya bangsa-bangsa bukan Yahudi dapat diterima oleh Allah sebagai persembahan yang berkenan kepada-Nya, yang disucikan oleh Roh Kudus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 17, 'Jadi dalam Kristus aku boleh bermegah tentang pelayananku bagi Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 18, 'Sebab aku tidak akan berani berkata-kata tentang sesuatu yang lain, kecuali tentang apa yang telah dikerjakan Kristus olehku, yaitu untuk memimpin bangsa-bangsa lain kepada ketaatan, oleh perkataan dan perbuatan,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 19, 'oleh kuasa tanda-tanda dan mujizat-mujizat dan oleh kuasa Roh. Demikianlah dalam perjalanan keliling dari Yerusalem sampai ke Ilirikum aku telah memberitakan sepenuhnya Injil Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 20, 'Dan dalam pemberitaan itu aku menganggap sebagai kehormatanku, bahwa aku tidak melakukannya di tempat-tempat, di mana nama Kristus telah dikenal orang, supaya aku jangan membangun di atas dasar, yang telah diletakkan orang lain,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 21, 'tetapi sesuai dengan yang ada tertulis: "Mereka, yang belum pernah menerima berita tentang Dia, akan melihat Dia, dan mereka, yang tidak pernah mendengarnya, akan mengertinya."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 22, 'Itulah sebabnya aku selalu terhalang untuk mengunjungi kamu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 23, 'Tetapi sekarang, karena aku tidak lagi mempunyai tempat kerja di daerah ini dan karena aku telah beberapa tahun lamanya ingin mengunjungi kamu,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 24, 'aku harap dalam perjalananku ke Spanyol aku dapat singgah di tempatmu dan bertemu dengan kamu, sehingga kamu dapat mengantarkan aku ke sana, setelah aku seketika menikmati pertemuan dengan kamu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 25, 'Tetapi sekarang aku sedang dalam perjalanan ke Yerusalem untuk mengantarkan bantuan kepada orang-orang kudus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 26, 'Sebab Makedonia dan Akhaya telah mengambil keputusan untuk menyumbangkan sesuatu kepada orang-orang miskin di antara orang-orang kudus di Yerusalem.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 27, 'Keputusan itu memang telah mereka ambil, tetapi itu adalah kewajiban mereka. Sebab, jika bangsa-bangsa lain telah beroleh bagian dalam harta rohani orang Yahudi, maka wajiblah juga bangsa-bangsa lain itu melayani orang Yahudi dengan harta duniawi mereka.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 28, 'Apabila aku sudah menunaikan tugas itu dan sudah menyerahkan hasil usaha bangsa-bangsa lain itu kepada mereka, aku akan berangkat ke Spanyol melalui kota kamu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 29, 'Dan aku tahu, bahwa jika aku datang mengunjungi kamu, aku akan melakukannya dengan penuh berkat Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 30, 'Tetapi demi Kristus, Tuhan kita, dan demi kasih Roh, aku menasihatkan kamu, saudara-saudara, untuk bergumul bersama-sama dengan aku dalam doa kepada Allah untuk aku,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 31, 'supaya aku terpelihara dari orang-orang yang tidak taat di Yudea, dan supaya pelayananku untuk Yerusalem disambut dengan baik oleh orang-orang kudus di sana,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 32, 'agar aku yang dengan sukacita datang kepadamu oleh kehendak Allah, beroleh kesegaran bersama-sama dengan kamu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 15, 33, 'Allah, sumber damai sejahtera, menyertai kamu sekalian! Amin.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 1, 'Aku meminta perhatianmu terhadap Febe, saudari kita yang melayani jemaat di Kengkrea,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 2, 'supaya kamu menyambut dia dalam Tuhan, sebagaimana seharusnya bagi orang-orang kudus, dan berikanlah kepadanya bantuan bila diperlukannya. Sebab ia sendiri telah memberikan bantuan kepada banyak orang, juga kepadaku sendiri.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 3, 'Sampaikan salam kepada Priskila dan Akwila, teman-teman sekerjaku dalam Kristus Yesus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 4, 'Mereka telah mempertaruhkan nyawanya untuk hidupku. Kepada mereka bukan aku saja yang berterima kasih, tetapi juga semua jemaat bukan Yahudi.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 5, 'Salam juga kepada jemaat di rumah mereka. Salam kepada Epenetus, saudara yang kukasihi, yang adalah buah pertama dari daerah Asia untuk Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 6, 'Salam kepada Maria, yang telah bekerja keras untuk kamu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 7, 'Salam kepada Andronikus dan Yunias, saudara-saudaraku sebangsa, yang pernah dipenjarakan bersama-sama dengan aku, yaitu orang-orang yang terpandang di antara para rasul dan yang telah menjadi Kristen sebelum aku.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 8, 'Salam kepada Ampliatus yang kukasihi dalam Tuhan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 9, 'Salam kepada Urbanus, teman sekerja kami dalam Kristus, dan salam kepada Stakhis, yang kukasihi.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 10, 'Salam kepada Apeles, yang telah tahan uji dalam Kristus. Salam kepada mereka, yang termasuk isi rumah Aristobulus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 11, 'Salam kepada Herodion, temanku sebangsa. Salam kepada mereka yang termasuk isi rumah Narkisus, yang ada dalam Tuhan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 12, 'Salam kepada Trifena dan Trifosa, yang bekerja membanting tulang dalam pelayanan Tuhan. Salam kepada Persis, yang kukasihi, yang telah bekerja membanting tulang dalam pelayanan Tuhan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 13, 'Salam kepada Rufus, orang pilihan dalam Tuhan, dan salam kepada ibunya, yang bagiku adalah juga ibu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 14, 'Salam kepada Asinkritus, Flegon, Hermes, Patrobas, Hermas dan saudara-saudara yang bersama-sama dengan mereka.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 15, 'Salam kepada Filologus, dan Yulia, Nereus dan saudaranya perempuan, dan Olimpas, dan juga kepada segala orang kudus yang bersama-sama dengan mereka.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 16, 'Bersalam-salamlah kamu dengan cium kudus. Salam kepada kamu dari semua jemaat Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 17, 'Tetapi aku menasihatkan kamu, saudara-saudara, supaya kamu waspada terhadap mereka, yang bertentangan dengan pengajaran yang telah kamu terima, menimbulkan perpecahan dan godaan. Sebab itu hindarilah mereka!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 18, 'Sebab orang-orang demikian tidak melayani Kristus, Tuhan kita, tetapi melayani perut mereka sendiri. Dan dengan kata-kata mereka yang muluk-muluk dan bahasa mereka yang manis mereka menipu orang-orang yang tulus hatinya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 19, 'Kabar tentang ketaatanmu telah terdengar oleh semua orang. Sebab itu aku bersukacita tentang kamu. Tetapi aku ingin supaya kamu bijaksana terhadap apa yang baik, dan bersih terhadap apa yang jahat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 20, 'Semoga Allah, sumber damai sejahtera, segera akan menghancurkan Iblis di bawah kakimu. Kasih karunia Yesus, Tuhan kita, menyertai kamu!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 21, 'Salam kepada kamu dari Timotius, temanku sekerja, dan dari Lukius, Yason dan Sosipater, teman-temanku sebangsa.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 22, 'Salam dalam Tuhan kepada kamu dari Tertius, yaitu aku, yang menulis surat ini.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 23, 'Salam kepada kamu dari Gayus, yang memberi tumpangan kepadaku, dan kepada seluruh jemaat. Salam kepada kamu dari Erastus, bendahara negeri, dan dari Kwartus, saudara kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 24, '(Kasih karunia Yesus Kristus, Tuhan kita, menyertai kamu sekalian! Amin.)', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 25, 'Bagi Dia, yang berkuasa menguatkan kamu, ?menurut Injil yang kumasyhurkan dan pemberitaan tentang Yesus Kristus, sesuai dengan pernyataan rahasia, yang didiamkan berabad-abad lamanya,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 26, 'tetapi yang sekarang telah dinyatakan dan yang menurut perintah Allah yang abadi, telah diberitakan oleh kitab-kitab para nabi kepada segala bangsa untuk membimbing mereka kepada ketaatan iman?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 16, 27, 'bagi Dia, satu-satunya Allah yang penuh hikmat, oleh Yesus Kristus: segala kemuliaan sampai selama-lamanya! Amin.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 1, 'Dari Paulus, yang oleh kehendak Allah dipanggil menjadi rasul Kristus Yesus, dan dari Sostenes, saudara kita,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 2, 'kepada jemaat Allah di Korintus, yaitu mereka yang dikuduskan dalam Kristus Yesus dan yang dipanggil menjadi orang-orang kudus, dengan semua orang di segala tempat, yang berseru kepada nama Tuhan kita Yesus Kristus, yaitu Tuhan mereka dan Tuhan kita.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 3, 'Kasih karunia dan damai sejahtera dari Allah, Bapa kita, dan dari Tuhan Yesus Kristus menyertai kamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 4, 'Aku senantiasa mengucap syukur kepada Allahku karena kamu atas kasih karunia Allah yang dianugerahkan-Nya kepada kamu dalam Kristus Yesus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 5, 'Sebab di dalam Dia kamu telah menjadi kaya dalam segala hal: dalam segala macam perkataan dan segala macam pengetahuan,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 6, 'sesuai dengan kesaksian tentang Kristus, yang telah diteguhkan di antara kamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 7, 'Demikianlah kamu tidak kekurangan dalam suatu karuniapun sementara kamu menantikan penyataan Tuhan kita Yesus Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 8, 'Ia juga akan meneguhkan kamu sampai kepada kesudahannya, sehingga kamu tak bercacat pada hari Tuhan kita Yesus Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 9, 'Allah, yang memanggil kamu kepada persekutuan dengan Anak-Nya Yesus Kristus, Tuhan kita, adalah setia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 10, 'Tetapi aku menasihatkan kamu, saudara-saudara, demi nama Tuhan kita Yesus Kristus, supaya kamu seia sekata dan jangan ada perpecahan di antara kamu, tetapi sebaliknya supaya kamu erat bersatu dan sehati sepikir.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 11, 'Sebab, saudara-saudaraku, aku telah diberitahukan oleh orang-orang dari keluarga Kloe tentang kamu, bahwa ada perselisihan di antara kamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 12, 'Yang aku maksudkan ialah, bahwa kamu masing-masing berkata: Aku dari golongan Paulus. Atau aku dari golongan Apolos. Atau aku dari golongan Kefas. Atau aku dari golongan Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 13, 'Adakah Kristus terbagi-bagi? Adakah Paulus disalibkan karena kamu? Atau adakah kamu dibaptis dalam nama Paulus?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 14, 'Aku mengucap syukur bahwa tidak ada seorangpun juga di antara kamu yang aku baptis selain Krispus dan Gayus,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 15, 'sehingga tidak ada orang yang dapat mengatakan, bahwa kamu dibaptis dalam namaku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 16, 'Juga keluarga Stefanus aku yang membaptisnya. Kecuali mereka aku tidak tahu, entahkah ada lagi orang yang aku baptis.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 17, 'Sebab Kristus mengutus aku bukan untuk membaptis, tetapi untuk memberitakan Injil; dan itupun bukan dengan hikmat perkataan, supaya salib Kristus jangan menjadi sia-sia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 18, 'Sebab pemberitaan tentang salib memang adalah kebodohan bagi mereka yang akan binasa, tetapi bagi kita yang diselamatkan pemberitaan itu adalah kekuatan Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 19, 'Karena ada tertulis: "Aku akan membinasakan hikmat orang-orang berhikmat dan kearifan orang-orang bijak akan Kulenyapkan."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 20, 'Di manakah orang yang berhikmat? Di manakah ahli Taurat? Di manakah pembantah dari dunia ini? Bukankah Allah telah membuat hikmat dunia ini menjadi kebodohan?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 21, 'Oleh karena dunia, dalam hikmat Allah, tidak mengenal Allah oleh hikmatnya, maka Allah berkenan menyelamatkan mereka yang percaya oleh kebodohan pemberitaan Injil.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 22, 'Orang-orang Yahudi menghendaki tanda dan orang-orang Yunani mencari hikmat,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 23, 'tetapi kami memberitakan Kristus yang disalibkan: untuk orang-orang Yahudi suatu batu sandungan dan untuk orang-orang bukan Yahudi suatu kebodohan,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 24, 'tetapi untuk mereka yang dipanggil, baik orang Yahudi, maupun orang bukan Yahudi, Kristus adalah kekuatan Allah dan hikmat Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 25, 'Sebab yang bodoh dari Allah lebih besar hikmatnya dari pada manusia dan yang lemah dari Allah lebih kuat dari pada manusia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 26, 'Ingat saja, saudara-saudara, bagaimana keadaan kamu, ketika kamu dipanggil: menurut ukuran manusia tidak banyak orang yang bijak, tidak banyak orang yang berpengaruh, tidak banyak orang yang terpandang.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 27, 'Tetapi apa yang bodoh bagi dunia, dipilih Allah untuk memalukan orang-orang yang berhikmat, dan apa yang lemah bagi dunia, dipilih Allah untuk memalukan apa yang kuat,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 28, 'dan apa yang tidak terpandang dan yang hina bagi dunia, dipilih Allah, bahkan apa yang tidak berarti, dipilih Allah untuk meniadakan apa yang berarti,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 29, 'supaya jangan ada seorang manusiapun yang memegahkan diri di hadapan Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 30, 'Tetapi oleh Dia kamu berada dalam Kristus Yesus, yang oleh Allah telah menjadi hikmat bagi kita. Ia membenarkan dan menguduskan dan menebus kita.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 1, 31, 'Karena itu seperti ada tertulis: "Barangsiapa yang bermegah, hendaklah ia bermegah di dalam Tuhan."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 1, 'Demikianlah pula, ketika aku datang kepadamu, saudara-saudara, aku tidak datang dengan kata-kata yang indah atau dengan hikmat untuk menyampaikan kesaksian Allah kepada kamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 2, 'Sebab aku telah memutuskan untuk tidak mengetahui apa-apa di antara kamu selain Yesus Kristus, yaitu Dia yang disalibkan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 3, 'Aku juga telah datang kepadamu dalam kelemahan dan dengan sangat takut dan gentar.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 4, 'Baik perkataanku maupun pemberitaanku tidak kusampaikan dengan kata-kata hikmat yang meyakinkan, tetapi dengan keyakinan akan kekuatan Roh,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 5, 'supaya iman kamu jangan bergantung pada hikmat manusia, tetapi pada kekuatan Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 6, 'Sungguhpun demikian kami memberitakan hikmat di kalangan mereka yang telah matang, yaitu hikmat yang bukan dari dunia ini, dan yang bukan dari penguasa-penguasa dunia ini, yaitu penguasa-penguasa yang akan ditiadakan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 7, 'Tetapi yang kami beritakan ialah hikmat Allah yang tersembunyi dan rahasia, yang sebelum dunia dijadikan, telah disediakan Allah bagi kemuliaan kita.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 8, 'Tidak ada dari penguasa dunia ini yang mengenalnya, sebab kalau sekiranya mereka mengenalnya, mereka tidak menyalibkan Tuhan yang mulia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 9, 'Tetapi seperti ada tertulis: "Apa yang tidak pernah dilihat oleh mata, dan tidak pernah didengar oleh telinga, dan yang tidak pernah timbul di dalam hati manusia: semua yang disediakan Allah untuk mereka yang mengasihi Dia."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 10, 'Karena kepada kita Allah telah menyatakannya oleh Roh, sebab Roh menyelidiki segala sesuatu, bahkan hal-hal yang tersembunyi dalam diri Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 11, 'Siapa gerangan di antara manusia yang tahu, apa yang terdapat di dalam diri manusia selain roh manusia sendiri yang ada di dalam dia? Demikian pulalah tidak ada orang yang tahu, apa yang terdapat di dalam diri Allah selain Roh Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 12, 'Kita tidak menerima roh dunia, tetapi roh yang berasal dari Allah, supaya kita tahu, apa yang dikaruniakan Allah kepada kita.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 13, 'Dan karena kami menafsirkan hal-hal rohani kepada mereka yang mempunyai Roh, kami berkata-kata tentang karunia-karunia Allah dengan perkataan yang bukan diajarkan kepada kami oleh hikmat manusia, tetapi oleh Roh.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 14, 'Tetapi manusia duniawi tidak menerima apa yang berasal dari Roh Allah, karena hal itu baginya adalah suatu kebodohan; dan ia tidak dapat memahaminya, sebab hal itu hanya dapat dinilai secara rohani.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 15, 'Tetapi manusia rohani menilai segala sesuatu, tetapi ia sendiri tidak dinilai oleh orang lain.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 2, 16, 'Sebab: "Siapakah yang mengetahui pikiran Tuhan, sehingga ia dapat menasihati Dia?" Tetapi kami memiliki pikiran Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 1, 'Dan aku, saudara-saudara, pada waktu itu tidak dapat berbicara dengan kamu seperti dengan manusia rohani, tetapi hanya dengan manusia duniawi, yang belum dewasa dalam Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 2, 'Susulah yang kuberikan kepadamu, bukanlah makanan keras, sebab kamu belum dapat menerimanya. Dan sekarangpun kamu belum dapat menerimanya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 3, 'Karena kamu masih manusia duniawi. Sebab, jika di antara kamu ada iri hati dan perselisihan bukankah hal itu menunjukkan, bahwa kamu manusia duniawi dan bahwa kamu hidup secara manusiawi?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 4, 'Karena jika yang seorang berkata: "Aku dari golongan Paulus," dan yang lain berkata: "Aku dari golongan Apolos," bukankah hal itu menunjukkan, bahwa kamu manusia duniawi yang bukan rohani?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 5, 'Jadi, apakah Apolos? Apakah Paulus? Pelayan-pelayan Tuhan yang olehnya kamu menjadi percaya, masing-masing menurut jalan yang diberikan Tuhan kepadanya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 6, 'Aku menanam, Apolos menyiram, tetapi Allah yang memberi pertumbuhan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 7, 'Karena itu yang penting bukanlah yang menanam atau yang menyiram, melainkan Allah yang memberi pertumbuhan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 8, 'Baik yang menanam maupun yang menyiram adalah sama; dan masing-masing akan menerima upahnya sesuai dengan pekerjaannya sendiri.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 9, 'Karena kami adalah kawan sekerja Allah; kamu adalah ladang Allah, bangunan Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 10, 'Sesuai dengan kasih karunia Allah, yang dianugerahkan kepadaku, aku sebagai seorang ahli bangunan yang cakap telah meletakkan dasar, dan orang lain membangun terus di atasnya. Tetapi tiap-tiap orang harus memperhatikan, bagaimana ia harus membangun di atasnya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 11, 'Karena tidak ada seorangpun yang dapat meletakkan dasar lain dari pada dasar yang telah diletakkan, yaitu Yesus Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 12, 'Entahkah orang membangun di atas dasar ini dengan emas, perak, batu permata, kayu, rumput kering atau jerami,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 13, 'sekali kelak pekerjaan masing-masing orang akan nampak. Karena hari Tuhan akan menyatakannya, sebab ia akan nampak dengan api dan bagaimana pekerjaan masing-masing orang akan diuji oleh api itu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 14, 'Jika pekerjaan yang dibangun seseorang tahan uji, ia akan mendapat upah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 15, 'Jika pekerjaannya terbakar, ia akan menderita kerugian, tetapi ia sendiri akan diselamatkan, tetapi seperti dari dalam api.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 16, 'Tidak tahukah kamu, bahwa kamu adalah bait Allah dan bahwa Roh Allah diam di dalam kamu?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 17, 'Jika ada orang yang membinasakan bait Allah, maka Allah akan membinasakan dia. Sebab bait Allah adalah kudus dan bait Allah itu ialah kamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 18, 'Janganlah ada orang yang menipu dirinya sendiri. Jika ada di antara kamu yang menyangka dirinya berhikmat menurut dunia ini, biarlah ia menjadi bodoh, supaya ia berhikmat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 19, 'Karena hikmat dunia ini adalah kebodohan bagi Allah. Sebab ada tertulis: "Ia yang menangkap orang berhikmat dalam kecerdikannya."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 20, 'Dan di tempat lain: "Tuhan mengetahui rancangan-rancangan orang berhikmat; sesungguhnya semuanya sia-sia belaka."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 21, 'Karena itu janganlah ada orang yang memegahkan dirinya atas manusia, sebab segala sesuatu adalah milikmu:', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 22, 'baik Paulus, Apolos, maupun Kefas, baik dunia, hidup, maupun mati, baik waktu sekarang, maupun waktu yang akan datang. Semuanya kamu punya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 3, 23, 'Tetapi kamu adalah milik Kristus dan Kristus adalah milik Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 1, 'Demikianlah hendaknya orang memandang kami: sebagai hamba-hamba Kristus, yang kepadanya dipercayakan rahasia Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 2, 'Yang akhirnya dituntut dari pelayan-pelayan yang demikian ialah, bahwa mereka ternyata dapat dipercayai.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 3, 'Bagiku sedikit sekali artinya entahkah aku dihakimi oleh kamu atau oleh suatu pengadilan manusia. Malahan diriku sendiripun tidak kuhakimi.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 4, 'Sebab memang aku tidak sadar akan sesuatu, tetapi bukan karena itulah aku dibenarkan. Dia, yang menghakimi aku, ialah Tuhan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 5, 'Karena itu, janganlah menghakimi sebelum waktunya, yaitu sebelum Tuhan datang. Ia akan menerangi, juga apa yang tersembunyi dalam kegelapan, dan Ia akan memperlihatkan apa yang direncanakan di dalam hati. Maka tiap-tiap orang akan menerima pujian dari Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 6, 'Saudara-saudara, kata-kata ini aku kenakan pada diriku sendiri dan pada Apolos, karena kamu, supaya dari teladan kami kamu belajar apakah artinya ungkapan: "Jangan melampaui yang ada tertulis", supaya jangan ada di antara kamu yang menyombongkan diri dengan jalan mengutamakan yang satu dari pada yang lain.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 7, 'Sebab siapakah yang menganggap engkau begitu penting? Dan apakah yang engkau punyai, yang tidak engkau terima? Dan jika engkau memang menerimanya, mengapakah engkau memegahkan diri, seolah-olah engkau tidak menerimanya?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 8, 'Kamu telah kenyang, kamu telah menjadi kaya, tanpa kami kamu telah menjadi raja. Ah, alangkah baiknya kalau benar demikian, bahwa kamu telah menjadi raja, sehingga kamipun turut menjadi raja dengan kamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 9, 'Sebab, menurut pendapatku, Allah memberikan kepada kami, para rasul, tempat yang paling rendah, sama seperti orang-orang yang telah dijatuhi hukuman mati, sebab kami telah menjadi tontonan bagi dunia, bagi malaikat-malaikat dan bagi manusia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 10, 'Kami bodoh oleh karena Kristus, tetapi kamu arif dalam Kristus. Kami lemah, tetapi kamu kuat. Kamu mulia, tetapi kami hina.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 11, 'Sampai pada saat ini kami lapar, haus, telanjang, dipukul dan hidup mengembara,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 12, 'kami melakukan pekerjaan tangan yang berat. Kalau kami dimaki, kami memberkati; kalau kami dianiaya, kami sabar;', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 13, 'kalau kami difitnah, kami tetap menjawab dengan ramah; kami telah menjadi sama dengan sampah dunia, sama dengan kotoran dari segala sesuatu, sampai pada saat ini.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 14, 'Hal ini kutuliskan bukan untuk memalukan kamu, tetapi untuk menegor kamu sebagai anak-anakku yang kukasihi.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 15, 'Sebab sekalipun kamu mempunyai beribu-ribu pendidik dalam Kristus, kamu tidak mempunyai banyak bapa. Karena akulah yang dalam Kristus Yesus telah menjadi bapamu oleh Injil yang kuberitakan kepadamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 16, 'Sebab itu aku menasihatkan kamu: turutilah teladanku!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 17, 'Justru itulah sebabnya aku mengirimkan kepadamu Timotius, yang adalah anakku yang kekasih dan yang setia dalam Tuhan. Ia akan memperingatkan kamu akan hidup yang kuturuti dalam Kristus Yesus, seperti yang kuajarkan di mana-mana dalam setiap jemaat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 18, 'Tetapi ada beberapa orang yang menjadi sombong, karena mereka menyangka, bahwa aku tidak akan datang lagi kepadamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 19, 'Tetapi aku akan segera datang kepadamu, kalau Tuhan menghendakinya. Maka aku akan tahu, bukan tentang perkataan orang-orang yang sombong itu, tetapi tentang kekuatan mereka.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 20, 'Sebab Kerajaan Allah bukan terdiri dari perkataan, tetapi dari kuasa.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 4, 21, 'Apakah yang kamu kehendaki? Haruskah aku datang kepadamu dengan cambuk atau dengan kasih dan dengan hati yang lemah lembut?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 1, 'Memang orang mendengar, bahwa ada percabulan di antara kamu, dan percabulan yang begitu rupa, seperti yang tidak terdapat sekalipun di antara bangsa-bangsa yang tidak mengenal Allah, yaitu bahwa ada orang yang hidup dengan isteri ayahnya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 2, 'Sekalipun demikian kamu sombong. Tidakkah lebih patut kamu berdukacita dan menjauhkan orang yang melakukan hal itu dari tengah-tengah kamu?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 3, 'Sebab aku, sekalipun secara badani tidak hadir, tetapi secara rohani hadir, aku?sama seperti aku hadir?telah menjatuhkan hukuman atas dia, yang telah melakukan hal yang semacam itu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 4, 'Bilamana kita berkumpul dalam roh, kamu bersama-sama dengan aku, dengan kuasa Yesus, Tuhan kita,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 5, 'orang itu harus kita serahkan dalam nama Tuhan Yesus kepada Iblis, sehingga binasa tubuhnya, agar rohnya diselamatkan pada hari Tuhan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 6, 'Kemegahanmu tidak baik. Tidak tahukah kamu, bahwa sedikit ragi mengkhamiri seluruh adonan?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 7, 'Buanglah ragi yang lama itu, supaya kamu menjadi adonan yang baru, sebab kamu memang tidak beragi. Sebab anak domba Paskah kita juga telah disembelih, yaitu Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 8, 'Karena itu marilah kita berpesta, bukan dengan ragi yang lama, bukan pula dengan ragi keburukan dan kejahatan, tetapi dengan roti yang tidak beragi, yaitu kemurnian dan kebenaran.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 9, 'Dalam suratku telah kutuliskan kepadamu, supaya kamu jangan bergaul dengan orang-orang cabul.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 10, 'Yang aku maksudkan bukanlah dengan semua orang cabul pada umumnya dari dunia ini atau dengan semua orang kikir dan penipu atau dengan semua penyembah berhala, karena jika demikian kamu harus meninggalkan dunia ini.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 11, 'Tetapi yang kutuliskan kepada kamu ialah, supaya kamu jangan bergaul dengan orang, yang sekalipun menyebut dirinya saudara, adalah orang cabul, kikir, penyembah berhala, pemfitnah, pemabuk atau penipu; dengan orang yang demikian janganlah kamu sekali-kali makan bersama-sama.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 12, 'Sebab dengan wewenang apakah aku menghakimi mereka, yang berada di luar jemaat? Bukankah kamu hanya menghakimi mereka yang berada di dalam jemaat?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 5, 13, 'Mereka yang berada di luar jemaat akan dihakimi Allah. Usirlah orang yang melakukan kejahatan dari tengah-tengah kamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 1, 'Apakah ada seorang di antara kamu, yang jika berselisih dengan orang lain, berani mencari keadilan pada orang-orang yang tidak benar, dan bukan pada orang-orang kudus?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 2, 'Atau tidak tahukah kamu, bahwa orang-orang kudus akan menghakimi dunia? Dan jika penghakiman dunia berada dalam tangan kamu, tidakkah kamu sanggup untuk mengurus perkara-perkara yang tidak berarti?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 3, 'Tidak tahukah kamu, bahwa kita akan menghakimi malaikat-malaikat? Jadi apalagi perkara-perkara biasa dalam hidup kita sehari-hari.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 4, 'Sekalipun demikian, jika kamu harus mengurus perkara-perkara biasa, kamu menyerahkan urusan itu kepada mereka yang tidak berarti dalam jemaat?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 5, 'Hal ini kukatakan untuk memalukan kamu. Tidak adakah seorang di antara kamu yang berhikmat, yang dapat mengurus perkara-perkara dari saudara-saudaranya?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 6, 'Adakah saudara yang satu mencari keadilan terhadap saudara yang lain, dan justru pada orang-orang yang tidak percaya?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 7, 'Adanya saja perkara di antara kamu yang seorang terhadap yang lain telah merupakan kekalahan bagi kamu. Mengapa kamu tidak lebih suka menderita ketidakadilan? Mengapakah kamu tidak lebih suka dirugikan?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 8, 'Tetapi kamu sendiri melakukan ketidakadilan dan kamu sendiri mendatangkan kerugian, dan hal itu kamu buat terhadap saudara-saudaramu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 9, 'Atau tidak tahukah kamu, bahwa orang-orang yang tidak adil tidak akan mendapat bagian dalam Kerajaan Allah? Janganlah sesat! Orang cabul, penyembah berhala, orang berzinah, banci, orang pemburit,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 10, 'pencuri, orang kikir, pemabuk, pemfitnah dan penipu tidak akan mendapat bagian dalam Kerajaan Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 11, 'Dan beberapa orang di antara kamu demikianlah dahulu. Tetapi kamu telah memberi dirimu disucikan, kamu telah dikuduskan, kamu telah dibenarkan dalam nama Tuhan Yesus Kristus dan dalam Roh Allah kita.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 12, 'Segala sesuatu halal bagiku, tetapi bukan semuanya berguna. Segala sesuatu halal bagiku, tetapi aku tidak membiarkan diriku diperhamba oleh suatu apapun.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 13, 'Makanan adalah untuk perut dan perut untuk makanan: tetapi kedua-duanya akan dibinasakan Allah. Tetapi tubuh bukanlah untuk percabulan, melainkan untuk Tuhan, dan Tuhan untuk tubuh.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 14, 'Allah, yang membangkitkan Tuhan, akan membangkitkan kita juga oleh kuasa-Nya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 15, 'Tidak tahukah kamu, bahwa tubuhmu adalah anggota Kristus? Akan kuambilkah anggota Kristus untuk menyerahkannya kepada percabulan? Sekali-kali tidak!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 16, 'Atau tidak tahukah kamu, bahwa siapa yang mengikatkan dirinya pada perempuan cabul, menjadi satu tubuh dengan dia? Sebab, demikianlah kata nas: "Keduanya akan menjadi satu daging."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 17, 'Tetapi siapa yang mengikatkan dirinya pada Tuhan, menjadi satu roh dengan Dia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 18, 'Jauhkanlah dirimu dari percabulan! Setiap dosa lain yang dilakukan manusia, terjadi di luar dirinya. Tetapi orang yang melakukan percabulan berdosa terhadap dirinya sendiri.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 19, 'Atau tidak tahukah kamu, bahwa tubuhmu adalah bait Roh Kudus yang diam di dalam kamu, Roh Kudus yang kamu peroleh dari Allah, ?dan bahwa kamu bukan milik kamu sendiri?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 6, 20, 'Sebab kamu telah dibeli dan harganya telah lunas dibayar: Karena itu muliakanlah Allah dengan tubuhmu!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 1, 'Dan sekarang tentang hal-hal yang kamu tuliskan kepadaku. Adalah baik bagi laki-laki, kalau ia tidak kawin,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 2, 'tetapi mengingat bahaya percabulan, baiklah setiap laki-laki mempunyai isterinya sendiri dan setiap perempuan mempunyai suaminya sendiri.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 3, 'Hendaklah suami memenuhi kewajibannya terhadap isterinya, demikian pula isteri terhadap suaminya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 4, 'Isteri tidak berkuasa atas tubuhnya sendiri, tetapi suaminya, demikian pula suami tidak berkuasa atas tubuhnya sendiri, tetapi isterinya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 5, 'Janganlah kamu saling menjauhi, kecuali dengan persetujuan bersama untuk sementara waktu, supaya kamu mendapat kesempatan untuk berdoa. Sesudah itu hendaklah kamu kembali hidup bersama-sama, supaya Iblis jangan menggodai kamu, karena kamu tidak tahan bertarak.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 6, 'Hal ini kukatakan kepadamu sebagai kelonggaran, bukan sebagai perintah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 7, 'Namun demikian alangkah baiknya, kalau semua orang seperti aku; tetapi setiap orang menerima dari Allah karunianya yang khas, yang seorang karunia ini, yang lain karunia itu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 8, 'Tetapi kepada orang-orang yang tidak kawin dan kepada janda-janda aku anjurkan, supaya baiklah mereka tinggal dalam keadaan seperti aku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 9, 'Tetapi kalau mereka tidak dapat menguasai diri, baiklah mereka kawin. Sebab lebih baik kawin dari pada hangus karena hawa nafsu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 10, 'Kepada orang-orang yang telah kawin aku?tidak, bukan aku, tetapi Tuhan?perintahkan, supaya seorang isteri tidak boleh menceraikan suaminya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 11, 'Dan jikalau ia bercerai, ia harus tetap hidup tanpa suami atau berdamai dengan suaminya. Dan seorang suami tidak boleh menceraikan isterinya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 12, 'Kepada orang-orang lain aku, bukan Tuhan, katakan: kalau ada seorang saudara beristerikan seorang yang tidak beriman dan perempuan itu mau hidup bersama-sama dengan dia, janganlah saudara itu menceraikan dia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 13, 'Dan kalau ada seorang isteri bersuamikan seorang yang tidak beriman dan laki-laki itu mau hidup bersama-sama dengan dia, janganlah ia menceraikan laki-laki itu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 14, 'Karena suami yang tidak beriman itu dikuduskan oleh isterinya dan isteri yang tidak beriman itu dikuduskan oleh suaminya. Andaikata tidak demikian, niscaya anak-anakmu adalah anak cemar, tetapi sekarang mereka adalah anak-anak kudus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 15, 'Tetapi kalau orang yang tidak beriman itu mau bercerai, biarlah ia bercerai; dalam hal yang demikian saudara atau saudari tidak terikat. Tetapi Allah memanggil kamu untuk hidup dalam damai sejahtera.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 16, 'Sebab bagaimanakah engkau mengetahui, hai isteri, apakah engkau tidak akan menyelamatkan suamimu? Atau bagaimanakah engkau mengetahui, hai suami, apakah engkau tidak akan menyelamatkan isterimu?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 17, 'Selanjutnya hendaklah tiap-tiap orang tetap hidup seperti yang telah ditentukan Tuhan baginya dan dalam keadaan seperti waktu ia dipanggil Allah. Inilah ketetapan yang kuberikan kepada semua jemaat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 18, 'Kalau seorang dipanggil dalam keadaan bersunat, janganlah ia berusaha meniadakan tanda-tanda sunat itu. Dan kalau seorang dipanggil dalam keadaan tidak bersunat, janganlah ia mau bersunat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 19, 'Sebab bersunat atau tidak bersunat tidak penting. Yang penting ialah mentaati hukum-hukum Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 20, 'Baiklah tiap-tiap orang tinggal dalam keadaan, seperti waktu ia dipanggil Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 21, 'Adakah engkau hamba waktu engkau dipanggil? Itu tidak apa-apa! Tetapi jikalau engkau mendapat kesempatan untuk dibebaskan, pergunakanlah kesempatan itu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 22, 'Sebab seorang hamba yang dipanggil oleh Tuhan dalam pelayanan-Nya, adalah orang bebas, milik Tuhan. Demikian pula orang bebas yang dipanggil Kristus, adalah hamba-Nya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 23, 'Kamu telah dibeli dan harganya telah lunas dibayar. Karena itu janganlah kamu menjadi hamba manusia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 24, 'Saudara-saudara, hendaklah tiap-tiap orang tinggal di hadapan Allah dalam keadaan seperti pada waktu ia dipanggil.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 25, 'Sekarang tentang para gadis. Untuk mereka aku tidak mendapat perintah dari Tuhan. Tetapi aku memberikan pendapatku sebagai seorang yang dapat dipercayai karena rahmat yang diterimanya dari Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 26, 'Aku berpendapat, bahwa, mengingat waktu darurat sekarang, adalah baik bagi manusia untuk tetap dalam keadaannya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 27, 'Adakah engkau terikat pada seorang perempuan? Janganlah engkau mengusahakan perceraian! Adakah engkau tidak terikat pada seorang perempuan? Janganlah engkau mencari seorang!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 28, 'Tetapi, kalau engkau kawin, engkau tidak berdosa. Dan kalau seorang gadis kawin, ia tidak berbuat dosa. Tetapi orang-orang yang demikian akan ditimpa kesusahan badani dan aku mau menghindarkan kamu dari kesusahan itu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 29, 'Saudara-saudara, inilah yang kumaksudkan, yaitu: waktu telah singkat! Karena itu dalam waktu yang masih sisa ini orang-orang yang beristeri harus berlaku seolah-olah mereka tidak beristeri;', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 30, 'dan orang-orang yang menangis seolah-olah tidak menangis; dan orang-orang yang bergembira seolah-olah tidak bergembira; dan orang-orang yang membeli seolah-olah tidak memiliki apa yang mereka beli;', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 31, 'pendeknya orang-orang yang mempergunakan barang-barang duniawi seolah-olah sama sekali tidak mempergunakannya. Sebab dunia seperti yang kita kenal sekarang akan berlalu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 32, 'Aku ingin, supaya kamu hidup tanpa kekuatiran. Orang yang tidak beristeri memusatkan perhatiannya pada perkara Tuhan, bagaimana Tuhan berkenan kepadanya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 33, 'Orang yang beristeri memusatkan perhatiannya pada perkara duniawi, bagaimana ia dapat menyenangkan isterinya,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 34, 'dan dengan demikian perhatiannya terbagi-bagi. Perempuan yang tidak bersuami dan anak-anak gadis memusatkan perhatian mereka pada perkara Tuhan, supaya tubuh dan jiwa mereka kudus. Tetapi perempuan yang bersuami memusatkan perhatiannya pada perkara duniawi, bagaimana ia dapat menyenangkan suaminya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 35, 'Semuanya ini kukatakan untuk kepentingan kamu sendiri, bukan untuk menghalang-halangi kamu dalam kebebasan kamu, tetapi sebaliknya supaya kamu melakukan apa yang benar dan baik, dan melayani Tuhan tanpa gangguan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 36, 'Tetapi jikalau seorang menyangka, bahwa ia tidak berlaku wajar terhadap gadisnya, jika gadisnya itu telah bertambah tua dan ia benar-benar merasa, bahwa mereka harus kawin, baiklah mereka kawin, kalau ia menghendakinya. Hal itu bukan dosa.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 37, 'Tetapi kalau ada seorang, yang tidak dipaksa untuk berbuat demikian, benar-benar yakin dalam hatinya dan benar-benar menguasai kemauannya, telah mengambil keputusan untuk tidak kawin dengan gadisnya, ia berbuat baik.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 38, 'Jadi orang yang kawin dengan gadisnya berbuat baik, dan orang yang tidak kawin dengan gadisnya berbuat lebih baik.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 39, 'Isteri terikat selama suaminya hidup. Kalau suaminya telah meninggal, ia bebas untuk kawin dengan siapa saja yang dikehendakinya, asal orang itu adalah seorang yang percaya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 7, 40, 'Tetapi menurut pendapatku, ia lebih berbahagia, kalau ia tetap tinggal dalam keadaannya. Dan aku berpendapat, bahwa aku juga mempunyai Roh Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 1, 'Tentang daging persembahan berhala kita tahu: "kita semua mempunyai pengetahuan." Pengetahuan yang demikian membuat orang menjadi sombong, tetapi kasih membangun.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 2, 'Jika ada seorang menyangka, bahwa ia mempunyai sesuatu "pengetahuan", maka ia belum juga mencapai pengetahuan, sebagaimana yang harus dicapainya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 3, 'Tetapi orang yang mengasihi Allah, ia dikenal oleh Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 4, 'Tentang hal makan daging persembahan berhala kita tahu: "tidak ada berhala di dunia dan tidak ada Allah lain dari pada Allah yang esa."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 5, 'Sebab sungguhpun ada apa yang disebut "allah", baik di sorga, maupun di bumi?dan memang benar ada banyak "allah" dan banyak "tuhan" yang demikian?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 6, 'namun bagi kita hanya ada satu Allah saja, yaitu Bapa, yang dari pada-Nya berasal segala sesuatu dan yang untuk Dia kita hidup, dan satu Tuhan saja, yaitu Yesus Kristus, yang oleh-Nya segala sesuatu telah dijadikan dan yang karena Dia kita hidup.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 7, 'Tetapi bukan semua orang yang mempunyai pengetahuan itu. Ada orang, yang karena masih terus terikat pada berhala-berhala, makan daging itu sebagai daging persembahan berhala. Dan oleh karena hati nurani mereka lemah, hati nurani mereka itu dinodai olehnya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 8, '"Makanan tidak membawa kita lebih dekat kepada Allah. Kita tidak rugi apa-apa, kalau tidak kita makan dan kita tidak untung apa-apa, kalau kita makan."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 9, 'Tetapi jagalah, supaya kebebasanmu ini jangan menjadi batu sandungan bagi mereka yang lemah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 10, 'Karena apabila orang melihat engkau yang mempunyai "pengetahuan", sedang duduk makan di dalam kuil berhala, bukankah orang yang lemah hati nuraninya itu dikuatkan untuk makan daging persembahan berhala?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 11, 'Dengan jalan demikian orang yang lemah, yaitu saudaramu, yang untuknya Kristus telah mati, menjadi binasa karena "pengetahuan" mu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 12, 'Jika engkau secara demikian berdosa terhadap saudara-saudaramu dan melukai hati nurani mereka yang lemah, engkau pada hakekatnya berdosa terhadap Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 8, 13, 'Karena itu apabila makanan menjadi batu sandungan bagi saudaraku, aku untuk selama-lamanya tidak akan mau makan daging lagi, supaya aku jangan menjadi batu sandungan bagi saudaraku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 1, 'Bukankah aku rasul? Bukankah aku orang bebas? Bukankah aku telah melihat Yesus, Tuhan kita? Bukankah kamu adalah buah pekerjaanku dalam Tuhan?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 2, 'Sekalipun bagi orang lain aku bukanlah rasul, tetapi bagi kamu aku adalah rasul. Sebab hidupmu dalam Tuhan adalah meterai dari kerasulanku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 3, 'Inilah pembelaanku terhadap mereka yang mengeritik aku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 4, 'Tidakkah kami mempunyai hak untuk makan dan minum?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 5, 'Tidakkah kami mempunyai hak untuk membawa seorang isteri Kristen, dalam perjalanan kami, seperti yang dilakukan rasul-rasul lain dan saudara-saudara Tuhan dan Kefas?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 6, 'Atau hanya aku dan Barnabas sajakah yang tidak mempunyai hak untuk dibebaskan dari pekerjaan tangan?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 7, 'Siapakah yang pernah turut dalam peperangan atas biayanya sendiri? Siapakah yang menanami kebun anggur dan tidak memakan buahnya? Atau siapakah yang menggembalakan kawanan domba dan yang tidak minum susu domba itu?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 8, 'Apa yang kukatakan ini bukanlah hanya pikiran manusia saja. Bukankah hukum Taurat juga berkata-kata demikian?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 9, 'Sebab dalam hukum Musa ada tertulis: "Janganlah engkau memberangus mulut lembu yang sedang mengirik!" Lembukah yang Allah perhatikan?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 10, 'Atau kitakah yang Ia maksudkan? Ya, untuk kitalah hal ini ditulis, yaitu pembajak harus membajak dalam pengharapan dan pengirik harus mengirik dalam pengharapan untuk memperoleh bagiannya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 11, 'Jadi, jika kami telah menaburkan benih rohani bagi kamu, berlebih-lebihank kalau kami menuai hasil duniawi dari pada kamu?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 12, 'Kalau orang lain mempunyai hak untuk mengharapkan hal itu dari pada kamu, bukankah kami mempunyai hak yang lebih besar? Tetapi kami tidak mempergunakan hak itu. Sebaliknya, kami menanggung segala sesuatu, supaya jangan kami mengadakan rintangan bagi pemberitaan Injil Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 13, 'Tidak tahukah kamu, bahwa mereka yang melayani dalam tempat kudus mendapat penghidupannya dari tempat kudus itu dan bahwa mereka yang melayani mezbah, mendapat bahagian mereka dari mezbah itu?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 14, 'Demikian pula Tuhan telah menetapkan, bahwa mereka yang memberitakan Injil, harus hidup dari pemberitaan Injil itu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 15, 'Tetapi aku tidak pernah mempergunakan satupun dari hak-hak itu. Aku tidak menulis semuanya ini, supaya akupun diperlakukan juga demikian. Sebab aku lebih suka mati dari pada?! Sungguh, kemegahanku tidak dapat ditiadakan siapapun juga!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 16, 'Karena jika aku memberitakan Injil, aku tidak mempunyai alasan untuk memegahkan diri. Sebab itu adalah keharusan bagiku. Celakalah aku, jika aku tidak memberitakan Injil.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 17, 'Kalau andaikata aku melakukannya menurut kehendakku sendiri, memang aku berhak menerima upah. Tetapi karena aku melakukannya bukan menurut kehendakku sendiri, pemberitaan itu adalah tugas penyelenggaraan yang ditanggungkan kepadaku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 18, 'Kalau demikian apakah upahku? Upahku ialah ini: bahwa aku boleh memberitakan Injil tanpa upah, dan bahwa aku tidak mempergunakan hakku sebagai pemberita Injil.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 19, 'Sungguhpun aku bebas terhadap semua orang, aku menjadikan diriku hamba dari semua orang, supaya aku boleh memenangkan sebanyak mungkin orang.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 20, 'Demikianlah bagi orang Yahudi aku menjadi seperti orang Yahudi, supaya aku memenangkan orang-orang Yahudi. Bagi orang-orang yang hidup di bawah hukum Taurat aku menjadi seperti orang yang hidup di bawah hukum Taurat, sekalipun aku sendiri tidak hidup di bawah hukum Taurat, supaya aku dapat memenangkan mereka yang hidup di bawah hukum Taurat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 21, 'Bagi orang-orang yang tidak hidup di bawah hukum Taurat aku menjadi seperti orang yang tidak hidup di bawah hukum Taurat, sekalipun aku tidak hidup di luar hukum Allah, karena aku hidup di bawah hukum Kristus, supaya aku dapat memenangkan mereka yang tidak hidup di bawah hukum Taurat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 22, 'Bagi orang-orang yang lemah aku menjadi seperti orang yang lemah, supaya aku dapat menyelamatkan mereka yang lemah. Bagi semua orang aku telah menjadi segala-galanya, supaya aku sedapat mungkin memenangkan beberapa orang dari antara mereka.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 23, 'Segala sesuatu ini aku lakukan karena Injil, supaya aku mendapat bagian dalamnya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 24, 'Tidak tahukah kamu, bahwa dalam gelanggang pertandingan semua peserta turut berlari, tetapi bahwa hanya satu orang saja yang mendapat hadiah? Karena itu larilah begitu rupa, sehingga kamu memperolehnya!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 25, 'Tiap-tiap orang yang turut mengambil bagian dalam pertandingan, menguasai dirinya dalam segala hal. Mereka berbuat demikian untuk memperoleh suatu mahkota yang fana, tetapi kita untuk memperoleh suatu mahkota yang abadi.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 26, 'Sebab itu aku tidak berlari tanpa tujuan dan aku bukan petinju yang sembarangan saja memukul.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 9, 27, 'Tetapi aku melatih tubuhku dan menguasainya seluruhnya, supaya sesudah memberitakan Injil kepada orang lain, jangan aku sendiri ditolak.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 1, 'Aku mau, supaya kamu mengetahui, saudara-saudara, bahwa nenek moyang kita semua berada di bawah perlindungan awan dan bahwa mereka semua telah melintasi laut.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 2, 'Untuk menjadi pengikut Musa mereka semua telah dibaptis dalam awan dan dalam laut.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 3, 'Mereka semua makan makanan rohani yang sama', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 4, 'dan mereka semua minum minuman rohani yang sama, sebab mereka minum dari batu karang rohani yang mengikuti mereka, dan batu karang itu ialah Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 5, 'Tetapi sungguhpun demikian Allah tidak berkenan kepada bagian yang terbesar dari mereka, karena mereka ditewaskan di padang gurun.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 6, 'Semuanya ini telah terjadi sebagai contoh bagi kita untuk memperingatkan kita, supaya jangan kita menginginkan hal-hal yang jahat seperti yang telah mereka perbuat,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 7, 'dan supaya jangan kita menjadi penyembah-penyembah berhala, sama seperti beberapa orang dari mereka, seperti ada tertulis: "Maka duduklah bangsa itu untuk makan dan minum; kemudian bangunlah mereka dan bersukaria."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 8, 'Janganlah kita melakukan percabulan, seperti yang dilakukan oleh beberapa orang dari mereka, sehingga pada satu hari telah tewas dua puluh tiga ribu orang.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 9, 'Dan janganlah kita mencobai Tuhan, seperti yang dilakukan oleh beberapa orang dari mereka, sehingga mereka mati dipagut ular.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 10, 'Dan janganlah bersungut-sungut, seperti yang dilakukan oleh beberapa orang dari mereka, sehingga mereka dibinasakan oleh malaikat maut.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 11, 'Semuanya ini telah menimpa mereka sebagai contoh dan dituliskan untuk menjadi peringatan bagi kita yang hidup pada waktu, di mana zaman akhir telah tiba.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 12, 'Sebab itu siapa yang menyangka, bahwa ia teguh berdiri, hati-hatilah supaya ia jangan jatuh!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 13, 'Pencobaan-pencobaan yang kamu alami ialah pencobaan-pencobaan biasa, yang tidak melebihi kekuatan manusia. Sebab Allah setia dan karena itu Ia tidak akan membiarkan kamu dicobai melampaui kekuatanmu. Pada waktu kamu dicobai Ia akan memberikan kepadamu jalan ke luar, sehingga kamu dapat menanggungnya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 14, 'Karena itu, saudara-saudaraku yang kekasih, jauhilah penyembahan berhala!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 15, 'Aku berbicara kepadamu sebagai orang-orang yang bijaksana. Pertimbangkanlah sendiri apa yang aku katakan!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 16, 'Bukankah cawan pengucapan syukur, yang atasnya kita ucapkan syukur, adalah persekutuan dengan darah Kristus? Bukankah roti yang kita pecah-pecahkan adalah persekutuan dengan tubuh Kristus?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 17, 'Karena roti adalah satu, maka kita, sekalipun banyak, adalah satu tubuh, karena kita semua mendapat bagian dalam roti yang satu itu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 18, 'Perhatikanlah bangsa Israel menurut daging: bukankah mereka yang makan apa yang dipersembahkan mendapat bagian dalam pelayanan mezbah?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 19, 'Apakah yang kumaksudkan dengan perkataan itu? Bahwa persembahan berhala adalah sesuatu? Atau bahwa berhala adalah sesuatu?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 20, 'Bukan! Apa yang kumaksudkan ialah, bahwa persembahan mereka adalah persembahan kepada roh-roh jahat, bukan kepada Allah. Dan aku tidak mau, bahwa kamu bersekutu dengan roh-roh jahat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 21, 'Kamu tidak dapat minum dari cawan Tuhan dan juga dari cawan roh-roh jahat. Kamu tidak dapat mendapat bagian dalam perjamuan Tuhan dan juga dalam perjamuan roh-roh jahat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 22, 'Atau maukah kita membangkitkan cemburu Tuhan? Apakah kita lebih kuat dari pada Dia?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 23, '"Segala sesuatu diperbolehkan." Benar, tetapi bukan segala sesuatu berguna. "Segala sesuatu diperbolehkan." Benar, tetapi bukan segala sesuatu membangun.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 24, 'Jangan seorangpun yang mencari keuntungannya sendiri, tetapi hendaklah tiap-tiap orang mencari keuntungan orang lain.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 25, 'Kamu boleh makan segala sesuatu yang dijual di pasar daging, tanpa mengadakan pemeriksaan karena keberatan-keberatan hati nurani.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 26, 'Karena: "bumi serta segala isinya adalah milik Tuhan."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 27, 'Kalau kamu diundang makan oleh seorang yang tidak percaya, dan undangan itu kamu terima, makanlah apa saja yang dihidangkan kepadamu, tanpa mengadakan pemeriksaan karena keberatan-keberatan hati nurani.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 28, 'Tetapi kalau seorang berkata kepadamu: "Itu persembahan berhala!" janganlah engkau memakannya, oleh karena dia yang mengatakan hal itu kepadamu dan karena keberatan-keberatan hati nurani.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 29, 'Yang aku maksudkan dengan keberatan-keberatan bukanlah keberatan-keberata hati nuranimu sendiri, tetapi keberatan-keberatan hati nurani orang lain itu. Mungkin ada orang yang berkata: "Mengapa kebebasanku harus ditentukan oleh keberatan-keberatan hati nurani orang lain?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 30, 'Kalau aku mengucap syukur atas apa yang aku turut memakannya, mengapa orang berkata jahat tentang aku karena makanan, yang atasnya aku mengucap syukur?"', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 31, 'Aku menjawab: Jika engkau makan atau jika engkau minum, atau jika engkau melakukan sesuatu yang lain, lakukanlah semuanya itu untuk kemuliaan Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 32, 'Janganlah kamu menimbulkan syak dalam hati orang, baik orang Yahudi atau orang Yunani, maupun Jemaat Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 10, 33, 'Sama seperti aku juga berusaha menyenangkan hati semua orang dalam segala hal, bukan untuk kepentingan diriku, tetapi untuk kepentingan orang banyak, supaya mereka beroleh selamat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 1, 'Jadilah pengikutku, sama seperti aku juga menjadi pengikut Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 2, 'Aku harus memuji kamu, sebab dalam segala sesuatu kamu tetap mengingat akan aku dan teguh berpegang pada ajaran yang kuteruskan kepadamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 3, 'Tetapi aku mau, supaya kamu mengetahui hal ini, yaitu Kepala dari tiap-tiap laki-laki ialah Kristus, kepala dari perempuan ialah laki-laki dan Kepala dari Kristus ialah Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 4, 'Tiap-tiap laki-laki yang berdoa atau bernubuat dengan kepala yang bertudung, menghina kepalanya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 5, 'Tetapi tiap-tiap perempuan yang berdoa atau bernubuat dengan kepala yang tidak bertudung, menghina kepalanya, sebab ia sama dengan perempuan yang dicukur rambutnya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 6, 'Sebab jika perempuan tidak mau menudungi kepalanya, maka haruslah ia juga menggunting rambutnya. Tetapi jika bagi perempuan adalah penghinaan, bahwa rambutnya digunting atau dicukur, maka haruslah ia menudungi kepalanya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 7, 'Sebab laki-laki tidak perlu menudungi kepalanya: ia menyinarkan gambaran dan kemuliaan Allah. Tetapi perempuan menyinarkan kemuliaan laki-laki.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 8, 'Sebab laki-laki tidak berasal dari perempuan, tetapi perempuan berasal dari laki-laki.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 9, 'Dan laki-laki tidak diciptakan karena perempuan, tetapi perempuan diciptakan karena laki-laki.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 10, 'Sebab itu, perempuan harus memakai tanda wibawa di kepalanya oleh karena para malaikat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 11, 'Namun demikian, dalam Tuhan tidak ada perempuan tanpa laki-laki dan tidak ada laki-laki tanpa perempuan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 12, 'Sebab sama seperti perempuan berasal dari laki-laki, demikian pula laki-laki dilahirkan oleh perempuan; dan segala sesuatu berasal dari Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 13, 'Pertimbangkanlah sendiri: Patutkah perempuan berdoa kepada Allah dengan kepala yang tidak bertudung?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 14, 'Bukankah alam sendiri menyatakan kepadamu, bahwa adalah kehinaan bagi laki-laki, jika ia berambut panjang,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 15, 'tetapi bahwa adalah kehormatan bagi perempuan, jika ia berambut panjang? Sebab rambut diberikan kepada perempuan untuk menjadi penudung.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 16, 'Tetapi jika ada orang yang mau membantah, kami maupun Jemaat-jemaat Allah tidak mempunyai kebiasaan yang demikian.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 17, 'Dalam peraturan-peraturan yang berikut aku tidak dapat memuji kamu, sebab pertemuan-pertemuanmu tidak mendatangkan kebaikan, tetapi mendatangkan keburukan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 18, 'Sebab pertama-tama aku mendengar, bahwa apabila kamu berkumpul sebagai Jemaat, ada perpecahan di antara kamu, dan hal itu sedikit banyak aku percaya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 19, 'Sebab di antara kamu harus ada perpecahan, supaya nyata nanti siapakah di antara kamu yang tahan uji.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 20, 'Apabila kamu berkumpul, kamu bukanlah berkumpul untuk makan perjamuan Tuhan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 21, 'Sebab pada perjamuan itu tiap-tiap orang memakan dahulu makanannya sendiri, sehingga yang seorang lapar dan yang lain mabuk.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 22, 'Apakah kamu tidak mempunyai rumah sendiri untuk makan dan minum? Atau maukah kamu menghinakan Jemaat Allah dan memalukan orang-orang yang tidak mempunyai apa-apa? Apakah yang kukatakan kepada kamu? Memuji kamu? Dalam hal ini aku tidak memuji.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 23, 'Sebab apa yang telah kuteruskan kepadamu, telah aku terima dari Tuhan, yaitu bahwa Tuhan Yesus, pada malam waktu Ia diserahkan, mengambil roti', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 24, 'dan sesudah itu Ia mengucap syukur atasnya; Ia memecah-mecahkannya dan berkata: "Inilah tubuh-Ku, yang diserahkan bagi kamu; perbuatlah ini menjadi peringatan akan Aku!"', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 25, 'Demikian juga Ia mengambil cawan, sesudah makan, lalu berkata: "Cawan ini adalah perjanjian baru yang dimeteraikan oleh darah-Ku; perbuatlah ini, setiap kali kamu meminumnya, menjadi peringatan akan Aku!"', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 26, 'Sebab setiap kali kamu makan roti ini dan minum cawan ini, kamu memberitakan kematian Tuhan sampai Ia datang.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 27, 'Jadi barangsiapa dengan cara yang tidak layak makan roti atau minum cawan Tuhan, ia berdosa terhadap tubuh dan darah Tuhan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 28, 'Karena itu hendaklah tiap-tiap orang menguji dirinya sendiri dan baru sesudah itu ia makan roti dan minum dari cawan itu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 29, 'Karena barangsiapa makan dan minum tanpa mengakui tubuh Tuhan, ia mendatangkan hukuman atas dirinya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 30, 'Sebab itu banyak di antara kamu yang lemah dan sakit, dan tidak sedikit yang meninggal.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 31, 'Kalau kita menguji diri kita sendiri, hukuman tidak menimpa kita.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 32, 'Tetapi kalau kita menerima hukuman dari Tuhan, kita dididik, supaya kita tidak akan dihukum bersama-sama dengan dunia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 33, 'Karena itu, saudara-saudaraku, jika kamu berkumpul untuk makan, nantikanlah olehmu seorang akan yang lain.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 11, 34, 'Kalau ada orang yang lapar, baiklah ia makan dahulu di rumahnya, supaya jangan kamu berkumpul untuk dihukum. Hal-hal yang lain akan kuatur, kalau aku datang.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 1, 'Sekarang tentang karunia-karunia Roh. Aku mau, saudara-saudara, supaya kamu mengetahui kebenarannya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 2, 'Kamu tahu, bahwa pada waktu kamu masih belum mengenal Allah, kamu tanpa berpikir ditarik kepada berhala-berhala yang bisu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 3, 'Karena itu aku mau meyakinkan kamu, bahwa tidak ada seorangpun yang berkata-kata oleh Roh Allah, dapat berkata: "Terkutuklah Yesus!" dan tidak ada seorangpun, yang dapat mengaku: "Yesus adalah Tuhan", selain oleh Roh Kudus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 4, 'Ada rupa-rupa karunia, tetapi satu Roh.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 5, 'Dan ada rupa-rupa pelayanan, tetapi satu Tuhan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 6, 'Dan ada berbagai-bagai perbuatan ajaib, tetapi Allah adalah satu yang mengerjakan semuanya dalam semua orang.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 7, 'Tetapi kepada tiap-tiap orang dikaruniakan penyataan Roh untuk kepentingan bersama.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 8, 'Sebab kepada yang seorang Roh memberikan karunia untuk berkata-kata dengan hikmat, dan kepada yang lain Roh yang sama memberikan karunia berkata-kata dengan pengetahuan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 9, 'Kepada yang seorang Roh yang sama memberikan iman, dan kepada yang lain Ia memberikan karunia untuk menyembuhkan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 10, 'Kepada yang seorang Roh memberikan kuasa untuk mengadakan mujizat, dan kepada yang lain Ia memberikan karunia untuk bernubuat, dan kepada yang lain lagi Ia memberikan karunia untuk membedakan bermacam-macam roh. Kepada yang seorang Ia memberikan karunia untuk berkata-kata dengan bahasa roh, dan kepada yang lain Ia memberikan karunia untuk menafsirkan bahasa roh itu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 11, 'Tetapi semuanya ini dikerjakan oleh Roh yang satu dan yang sama, yang memberikan karunia kepada tiap-tiap orang secara khusus, seperti yang dikehendaki-Nya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 12, 'Karena sama seperti tubuh itu satu dan anggota-anggotanya banyak, dan segala anggota itu, sekalipun banyak, merupakan satu tubuh, demikian pula Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 13, 'Sebab dalam satu Roh kita semua, baik orang Yahudi, maupun orang Yunani, baik budak, maupun orang merdeka, telah dibaptis menjadi satu tubuh dan kita semua diberi minum dari satu Roh.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 14, 'Karena tubuh juga tidak terdiri dari satu anggota, tetapi atas banyak anggota.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 15, 'Andaikata kaki berkata: "Karena aku bukan tangan, aku tidak termasuk tubuh", jadi benarkah ia tidak termasuk tubuh?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 16, 'Dan andaikata telinga berkata: "Karena aku bukan mata, aku tidak termasuk tubuh", jadi benarkah ia tidak termasuk tubuh?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 17, 'Andaikata tubuh seluruhnya adalah mata, di manakah pendengaran? Andaikata seluruhnya adalah telinga, di manakah penciuman?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 18, 'Tetapi Allah telah memberikan kepada anggota, masing-masing secara khusus, suatu tempat pada tubuh, seperti yang dikehendaki-Nya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 19, 'Andaikata semuanya adalah satu anggota, di manakah tubuh?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 20, 'Memang ada banyak anggota, tetapi hanya satu tubuh.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 21, 'Jadi mata tidak dapat berkata kepada tangan: "Aku tidak membutuhkan engkau." Dan kepala tidak dapat berkata kepada kaki: "Aku tidak membutuhkan engkau."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 22, 'Malahan justru anggota-anggota tubuh yang nampaknya paling lemah, yang paling dibutuhkan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 23, 'Dan kepada anggota-anggota tubuh yang menurut pemandangan kita kurang terhormat, kita berikan penghormatan khusus. Dan terhadap anggota-anggota kita yang tidak elok, kita berikan perhatian khusus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 24, 'Hal itu tidak dibutuhkan oleh anggota-anggota kita yang elok. Allah telah menyusun tubuh kita begitu rupa, sehingga kepada anggota-anggota yang tidak mulia diberikan penghormatan khusus,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 25, 'supaya jangan terjadi perpecahan dalam tubuh, tetapi supaya anggota-anggota yang berbeda itu saling memperhatikan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 26, 'Karena itu jika satu anggota menderita, semua anggota turut menderita; jika satu anggota dihormati, semua anggota turut bersukacita.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 27, 'Kamu semua adalah tubuh Kristus dan kamu masing-masing adalah anggotanya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 28, 'Dan Allah telah menetapkan beberapa orang dalam Jemaat: pertama sebagai rasul, kedua sebagai nabi, ketiga sebagai pengajar. Selanjutnya mereka yang mendapat karunia untuk mengadakan mujizat, untuk menyembuhkan, untuk melayani, untuk memimpin, dan untuk berkata-kata dalam bahasa roh.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 29, 'Adakah mereka semua rasul, atau nabi, atau pengajar? Adakah mereka semua mendapat karunia untuk mengadakan mujizat,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 30, 'atau untuk menyembuhkan, atau untuk berkata-kata dalam bahasa roh, atau untuk menafsirkan bahasa roh?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 12, 31, 'Jadi berusahalah untuk memperoleh karunia-karunia yang paling utama. Dan aku menunjukkan kepadamu jalan yang lebih utama lagi.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 1, 'Sekalipun aku dapat berkata-kata dengan semua bahasa manusia dan bahasa malaikat, tetapi jika aku tidak mempunyai kasih, aku sama dengan gong yang berkumandang dan canang yang gemerincing.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 2, 'Sekalipun aku mempunyai karunia untuk bernubuat dan aku mengetahui segala rahasia dan memiliki seluruh pengetahuan; dan sekalipun aku memiliki iman yang sempurna untuk memindahkan gunung, tetapi jika aku tidak mempunyai kasih, aku sama sekali tidak berguna.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 3, 'Dan sekalipun aku membagi-bagikan segala sesuatu yang ada padaku, bahkan menyerahkan tubuhku untuk dibakar, tetapi jika aku tidak mempunyai kasih, sedikitpun tidak ada faedahnya bagiku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 4, 'Kasih itu sabar; kasih itu murah hati; ia tidak cemburu. Ia tidak memegahkan diri dan tidak sombong.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 5, 'Ia tidak melakukan yang tidak sopan dan tidak mencari keuntungan diri sendiri. Ia tidak pemarah dan tidak menyimpan kesalahan orang lain.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 6, 'Ia tidak bersukacita karena ketidakadilan, tetapi karena kebenaran.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 7, 'Ia menutupi segala sesuatu, percaya segala sesuatu, mengharapkan segala sesuatu, sabar menanggung segala sesuatu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 8, 'Kasih tidak berkesudahan; nubuat akan berakhir; bahasa roh akan berhenti; pengetahuan akan lenyap.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 9, 'Sebab pengetahuan kita tidak lengkap dan nubuat kita tidak sempurna.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 10, 'Tetapi jika yang sempurna tiba, maka yang tidak sempurna itu akan lenyap.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 11, 'Ketika aku kanak-kanak, aku berkata-kata seperti kanak-kanak, aku merasa seperti kanak-kanak, aku berpikir seperti kanak-kanak. Sekarang sesudah aku menjadi dewasa, aku meninggalkan sifat kanak-kanak itu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 12, 'Karena sekarang kita melihat dalam cermin suatu gambaran yang samar-samar, tetapi nanti kita akan melihat muka dengan muka. Sekarang aku hanya mengenal dengan tidak sempurna, tetapi nanti aku akan mengenal dengan sempurna, seperti aku sendiri dikenal.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 13, 13, 'Demikianlah tinggal ketiga hal ini, yaitu iman, pengharapan dan kasih, dan yang paling besar di antaranya ialah kasih.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 1, 'Kejarlah kasih itu dan usahakanlah dirimu memperoleh karunia-karunia Roh, terutama karunia untuk bernubuat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 2, 'Siapa yang berkata-kata dengan bahasa roh, tidak berkata-kata kepada manusia, tetapi kepada Allah. Sebab tidak ada seorangpun yang mengerti bahasanya; oleh Roh ia mengucapkan hal-hal yang rahasia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 3, 'Tetapi siapa yang bernubuat, ia berkata-kata kepada manusia, ia membangun, menasihati dan menghibur.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 4, 'Siapa yang berkata-kata dengan bahasa roh, ia membangun dirinya sendiri, tetapi siapa yang bernubuat, ia membangun Jemaat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 5, 'Aku suka, supaya kamu semua berkata-kata dengan bahasa roh, tetapi lebih dari pada itu, supaya kamu bernubuat. Sebab orang yang bernubuat lebih berharga dari pada orang yang berkata-kata dengan bahasa roh, kecuali kalau orang itu juga menafsirkannya, sehingga Jemaat dapat dibangun.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 6, 'Jadi, saudara-saudara, jika aku datang kepadamu dan berkata-kata dengan bahasa roh, apakah gunanya itu bagimu, jika aku tidak menyampaikan kepadamu penyataan Allah atau pengetahuan atau nubuat atau pengajaran?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 7, 'Sama halnya dengan alat-alat yang tidak berjiwa, tetapi yang berbunyi, seperti seruling dan kecapi?bagaimanakah orang dapat mengetahui lagu apakah yang dimainkan seruling atau kecapi, kalau keduanya tidak mengeluarkan bunyi yang berbeda?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 8, 'Atau, jika nafiri tidak mengeluarkan bunyi yang terang, siapakah yang menyiapkan diri untuk berperang?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 9, 'Demikianlah juga kamu yang berkata-kata dengan bahasa roh: jika kamu tidak mempergunakan kata-kata yang jelas, bagaimanakah orang dapat mengerti apa yang kamu katakan? Kata-katamu sia-sia saja kamu ucapkan di udara!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 10, 'Ada banyak?entah berapa banyak?macam bahasa di dunia; sekalipun demikian tidak ada satupun di antaranya yang mempunyai bunyi yang tidak berarti.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 11, 'Tetapi jika aku tidak mengetahui arti bahasa itu, aku menjadi orang asing bagi dia yang mempergunakannya dan dia orang asing bagiku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 12, 'Demikian pula dengan kamu: Kamu memang berusaha untuk memperoleh karunia-karunia Roh, tetapi lebih dari pada itu hendaklah kamu berusaha mempergunakannya untuk membangun Jemaat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 13, 'Karena itu siapa yang berkata-kata dengan bahasa roh, ia harus berdoa, supaya kepadanya diberikan juga karunia untuk menafsirkannya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 14, 'Sebab jika aku berdoa dengan bahasa roh, maka rohkulah yang berdoa, tetapi akal budiku tidak turut berdoa.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 15, 'Jadi, apakah yang harus kubuat? Aku akan berdoa dengan rohku, tetapi aku akan berdoa juga dengan akal budiku; aku akan menyanyi dan memuji dengan rohku, tetapi aku akan menyanyi dan memuji juga dengan akal budiku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 16, 'Sebab, jika engkau mengucap syukur dengan rohmu saja, bagaimanakah orang biasa yang hadir sebagai pendengar dapat mengatakan "amin" atas pengucapan syukurmu? Bukankah ia tidak tahu apa yang engkau katakan?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 17, 'Sebab sekalipun pengucapan syukurmu itu sangat baik, tetapi orang lain tidak dibangun olehnya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 18, 'Aku mengucap syukur kepada Allah, bahwa aku berkata-kata dengan bahasa roh lebih dari pada kamu semua.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 19, 'Tetapi dalam pertemuan Jemaat aku lebih suka mengucapkan lima kata yang dapat dimengerti untuk mengajar orang lain juga, dari pada beribu-ribu kata dengan bahasa roh.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 20, 'Saudara-saudara, janganlah sama seperti anak-anak dalam pemikiranmu. Jadilah anak-anak dalam kejahatan, tetapi orang dewasa dalam pemikiranmu!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 21, 'Dalam hukum Taurat ada tertulis: "Oleh orang-orang yang mempunyai bahasa lain dan oleh mulut orang-orang asing Aku akan berbicara kepada bangsa ini, namun demikian mereka tidak akan mendengarkan Aku, firman Tuhan."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 22, 'Karena itu karunia bahasa roh adalah tanda, bukan untuk orang yang beriman, tetapi untuk orang yang tidak beriman; sedangkan karunia untuk bernubuat adalah tanda, bukan untuk orang yang tidak beriman, tetapi untuk orang yang beriman.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 23, 'Jadi, kalau seluruh Jemaat berkumpul bersama-sama dan tiap-tiap orang berkata-kata dengan bahasa roh, lalu masuklah orang-orang luar atau orang-orang yang tidak beriman, tidakkah akan mereka katakan, bahwa kamu gila?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 24, 'Tetapi kalau semua bernubuat, lalu masuk orang yang tidak beriman atau orang baru, ia akan diyakinkan oleh semua dan diselidiki oleh semua;', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 25, 'segala rahasia yang terkandung di dalam hatinya akan menjadi nyata, sehingga ia akan sujud menyembah Allah dan mengaku: "Sungguh, Allah ada di tengah-tengah kamu."', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 26, 'Jadi bagaimana sekarang, saudara-saudara? Bilamana kamu berkumpul, hendaklah tiap-tiap orang mempersembahkan sesuatu: yang seorang mazmur, yang lain pengajaran, atau penyataan Allah, atau karunia bahasa roh, atau karunia untuk menafsirkan bahasa roh, tetapi semuanya itu harus dipergunakan untuk membangun.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 27, 'Jika ada yang berkata-kata dengan bahasa roh, biarlah dua atau sebanyak-banyaknya tiga orang, seorang demi seorang, dan harus ada seorang lain untuk menafsirkannya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 28, 'Jika tidak ada orang yang dapat menafsirkannya, hendaklah mereka berdiam diri dalam pertemuan Jemaat dan hanya boleh berkata-kata kepada dirinya sendiri dan kepada Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 29, 'Tentang nabi-nabi?baiklah dua atau tiga orang di antaranya berkata-kata dan yang lain menanggapi apa yang mereka katakan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 30, 'Tetapi jika seorang lain yang duduk di situ mendapat penyataan, maka yang pertama itu harus berdiam diri.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 31, 'Sebab kamu semua boleh bernubuat seorang demi seorang, sehingga kamu semua dapat belajar dan beroleh kekuatan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 32, 'Karunia nabi takluk kepada nabi-nabi.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 33, 'Sebab Allah tidak menghendaki kekacauan, tetapi damai sejahtera.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 34, 'Sama seperti dalam semua Jemaat orang-orang kudus, perempuan-perempuan harus berdiam diri dalam pertemuan-pertemuan Jemaat. Sebab mereka tidak diperbolehkan untuk berbicara. Mereka harus menundukkan diri, seperti yang dikatakan juga oleh hukum Taurat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 35, 'Jika mereka ingin mengetahui sesuatu, baiklah mereka menanyakannya kepada suaminya di rumah. Sebab tidak sopan bagi perempuan untuk berbicara dalam pertemuan Jemaat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 36, 'Atau adakah firman Allah mulai dari kamu? Atau hanya kepada kamu sajakah firman itu telah datang?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 37, 'Jika seorang menganggap dirinya nabi atau orang yang mendapat karunia rohani, ia harus sadar, bahwa apa yang kukatakan kepadamu adalah perintah Tuhan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 38, 'Tetapi jika ia tidak mengindahkannya, janganlah kamu mengindahkan dia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 39, 'Karena itu, saudara-saudaraku, usahakanlah dirimu untuk memperoleh karunia untuk bernubuat dan janganlah melarang orang yang berkata-kata dengan bahasa roh.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 14, 40, 'Tetapi segala sesuatu harus berlangsung dengan sopan dan teratur.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 1, 'Dan sekarang, saudara-saudara, aku mau mengingatkan kamu kepada Injil yang aku beritakan kepadamu dan yang kamu terima, dan yang di dalamnya kamu teguh berdiri.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 2, 'Oleh Injil itu kamu diselamatkan, asal kamu teguh berpegang padanya, seperti yang telah kuberitakan kepadamu?kecuali kalau kamu telah sia-sia saja menjadi percaya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 3, 'Sebab yang sangat penting telah kusampaikan kepadamu, yaitu apa yang telah kuterima sendiri, ialah bahwa Kristus telah mati karena dosa-dosa kita, sesuai dengan Kitab Suci,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 4, 'bahwa Ia telah dikuburkan, dan bahwa Ia telah dibangkitkan, pada hari yang ketiga, sesuai dengan Kitab Suci;', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 5, 'bahwa Ia telah menampakkan diri kepada Kefas dan kemudian kepada kedua belas murid-Nya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 6, 'Sesudah itu Ia menampakkan diri kepada lebih dari lima ratus saudara sekaligus; kebanyakan dari mereka masih hidup sampai sekarang, tetapi beberapa di antaranya telah meninggal.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 7, 'Selanjutnya Ia menampakkan diri kepada Yakobus, kemudian kepada semua rasul.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 8, 'Dan yang paling akhir dari semuanya Ia menampakkan diri juga kepadaku, sama seperti kepada anak yang lahir sebelum waktunya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 9, 'Karena aku adalah yang paling hina dari semua rasul, sebab aku telah menganiaya Jemaat Allah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 10, 'Tetapi karena kasih karunia Allah aku adalah sebagaimana aku ada sekarang, dan kasih karunia yang dianugerahkan-Nya kepadaku tidak sia-sia. Sebaliknya, aku telah bekerja lebih keras dari pada mereka semua; tetapi bukannya aku, melainkan kasih karunia Allah yang menyertai aku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 11, 'Sebab itu, baik aku, maupun mereka, demikianlah kami mengajar dan demikianlah kamu menjadi percaya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 12, 'Jadi, bilamana kami beritakan, bahwa Kristus dibangkitkan dari antara orang mati, bagaimana mungkin ada di antara kamu yang mengatakan, bahwa tidak ada kebangkitan orang mati?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 13, 'Kalau tidak ada kebangkitan orang mati, maka Kristus juga tidak dibangkitkan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 14, 'Tetapi andaikata Kristus tidak dibangkitkan, maka sia-sialah pemberitaan kami dan sia-sialah juga kepercayaan kamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 15, 'Lebih dari pada itu kami ternyata berdusta terhadap Allah, karena tentang Dia kami katakan, bahwa Ia telah membangkitkan Kristus padahal Ia tidak membangkitkan-Nya, kalau andaikata benar, bahwa orang mati tidak dibangkitkan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 16, 'Sebab jika benar orang mati tidak dibangkitkan, maka Kristus juga tidak dibangkitkan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 17, 'Dan jika Kristus tidak dibangkitkan, maka sia-sialah kepercayaan kamu dan kamu masih hidup dalam dosamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 18, 'Demikianlah binasa juga orang-orang yang mati dalam Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 19, 'Jikalau kita hanya dalam hidup ini saja menaruh pengharapan pada Kristus, maka kita adalah orang-orang yang paling malang dari segala manusia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 20, 'Tetapi yang benar ialah, bahwa Kristus telah dibangkitkan dari antara orang mati, sebagai yang sulung dari orang-orang yang telah meninggal.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 21, 'Sebab sama seperti maut datang karena satu orang manusia, demikian juga kebangkitan orang mati datang karena satu orang manusia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 22, 'Karena sama seperti semua orang mati dalam persekutuan dengan Adam, demikian pula semua orang akan dihidupkan kembali dalam persekutuan dengan Kristus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 23, 'Tetapi tiap-tiap orang menurut urutannya: Kristus sebagai buah sulung; sesudah itu mereka yang menjadi milik-Nya pada waktu kedatangan-Nya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 24, 'Kemudian tiba kesudahannya, yaitu bilamana Ia menyerahkan Kerajaan kepada Allah Bapa, sesudah Ia membinasakan segala pemerintahan, kekuasaan dan kekuatan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 25, 'Karena Ia harus memegang pemerintahan sebagai Raja sampai Allah meletakkan semua musuh-Nya di bawah kaki-Nya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 26, 'Musuh yang terakhir, yang dibinasakan ialah maut.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 27, 'Sebab segala sesuatu telah ditaklukkan-Nya di bawah kaki-Nya. Tetapi kalau dikatakan, bahwa "segala sesuatu telah ditaklukkan", maka teranglah, bahwa Ia sendiri yang telah menaklukkan segala sesuatu di bawah kaki Kristus itu tidak termasuk di dalamnya.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 28, 'Tetapi kalau segala sesuatu telah ditaklukkan di bawah Kristus, maka Ia sendiri sebagai Anak akan menaklukkan diri-Nya di bawah Dia, yang telah menaklukkan segala sesuatu di bawah-Nya, supaya Allah menjadi semua di dalam semua.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 29, 'Jika tidak demikian, apakah faedahnya perbuatan orang-orang yang dibaptis bagi orang mati? Kalau orang mati sama sekali tidak dibangkitkan, mengapa mereka mau dibaptis bagi orang-orang yang telah meninggal?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 30, 'Dan kami juga?mengapakah kami setiap saat membawa diri kami ke dalam bahaya?', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 31, 'Saudara-saudara, tiap-tiap hari aku berhadapan dengan maut. Demi kebanggaanku akan kamu dalam Kristus Yesus, Tuhan kita, aku katakan, bahwa hal ini benar.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 32, 'Kalau hanya berdasarkan pertimbangan-pertimbangan manusia saja aku telah berjuang melawan binatang buas di Efesus, apakah gunanya hal itu bagiku? Jika orang mati tidak dibangkitkan, maka "marilah kita makan dan minum, sebab besok kita mati".', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 33, 'Janganlah kamu sesat: Pergaulan yang buruk merusakkan kebiasaan yang baik.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 34, 'Sadarlah kembali sebaik-baiknya dan jangan berbuat dosa lagi! Ada di antara kamu yang tidak mengenal Allah. Hal ini kukatakan, supaya kamu merasa malu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 35, 'Tetapi mungkin ada orang yang bertanya: "Bagaimanakah orang mati dibangkitkan? Dan dengan tubuh apakah mereka akan datang kembali?"', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 36, 'Hai orang bodoh! Apa yang engkau sendiri taburkan, tidak akan tumbuh dan hidup, kalau ia tidak mati dahulu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 37, 'Dan yang engkau taburkan bukanlah tubuh tanaman yang akan tumbuh, tetapi biji yang tidak berkulit, umpamanya biji gandum atau biji lain.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 38, 'Tetapi Allah memberikan kepadanya suatu tubuh, seperti yang dikehendaki-Nya: Ia memberikan kepada tiap-tiap biji tubuhnya sendiri.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 39, 'Bukan semua daging sama: daging manusia lain dari pada daging binatang, lain dari pada daging burung, lain dari pada daging ikan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 40, 'Ada tubuh sorgawi dan ada tubuh duniawi, tetapi kemuliaan tubuh sorgawi lain dari pada kemuliaan tubuh duniawi.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 41, 'Kemuliaan matahari lain dari pada kemuliaan bulan, dan kemuliaan bulan lain dari pada kemuliaan bintang-bintang, dan kemuliaan bintang yang satu berbeda dengan kemuliaan bintang yang lain.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 42, 'Demikianlah pula halnya dengan kebangkitan orang mati. Ditaburkan dalam kebinasaan, dibangkitkan dalam ketidakbinasaan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 43, 'Ditaburkan dalam kehinaan, dibangkitkan dalam kemuliaan. Ditaburkan dalam kelemahan, dibangkitkan dalam kekuatan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 44, 'Yang ditaburkan adalah tubuh alamiah, yang dibangkitkan adalah tubuh rohaniah. Jika ada tubuh alamiah, maka ada pula tubuh rohaniah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 45, 'Seperti ada tertulis: "Manusia pertama, Adam menjadi makhluk yang hidup", tetapi Adam yang akhir menjadi roh yang menghidupkan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 46, 'Tetapi yang mula-mula datang bukanlah yang rohaniah, tetapi yang alamiah; kemudian barulah datang yang rohaniah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 47, 'Manusia pertama berasal dari debu tanah dan bersifat jasmani, manusia kedua berasal dari sorga.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 48, 'Makhluk-makhluk alamiah sama dengan dia yang berasal dari debu tanah dan makhluk-makhluk sorgawi sama dengan Dia yang berasal dari sorga.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 49, 'Sama seperti kita telah memakai rupa dari yang alamiah, demikian pula kita akan memakai rupa dari yang sorgawi.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 50, 'Saudara-saudara, inilah yang hendak kukatakan kepadamu, yaitu bahwa daging dan darah tidak mendapat bagian dalam Kerajaan Allah dan bahwa yang binasa tidak mendapat bagian dalam apa yang tidak binasa.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 51, 'Sesungguhnya aku menyatakan kepadamu suatu rahasia: kita tidak akan mati semuanya, tetapi kita semuanya akan diubah,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 52, 'dalam sekejap mata, pada waktu bunyi nafiri yang terakhir. Sebab nafiri akan berbunyi dan orang-orang mati akan dibangkitkan dalam keadaan yang tidak dapat binasa dan kita semua akan diubah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 53, 'Karena yang dapat binasa ini harus mengenakan yang tidak dapat binasa, dan yang dapat mati ini harus mengenakan yang tidak dapat mati.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 54, 'Dan sesudah yang dapat binasa ini mengenakan yang tidak dapat binasa dan yang dapat mati ini mengenakan yang tidak dapat mati, maka akan genaplah firman Tuhan yang tertulis: "Maut telah ditelan dalam kemenangan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 55, 'Hai maut di manakah kemenanganmu? Hai maut, di manakah sengatmu?"', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 56, 'Sengat maut ialah dosa dan kuasa dosa ialah hukum Taurat.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 57, 'Tetapi syukur kepada Allah, yang telah memberikan kepada kita kemenangan oleh Yesus Kristus, Tuhan kita.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 15, 58, 'Karena itu, saudara-saudaraku yang kekasih, berdirilah teguh, jangan goyah, dan giatlah selalu dalam pekerjaan Tuhan! Sebab kamu tahu, bahwa dalam persekutuan dengan Tuhan jerih payahmu tidak sia-sia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 1, 'Tentang pengumpulan uang bagi orang-orang kudus, hendaklah kamu berbuat sesuai dengan petunjuk-petunjuk yang kuberikan kepada Jemaat-jemaat di Galatia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 2, 'Pada hari pertama dari tiap-tiap minggu hendaklah kamu masing-masing?sesuai dengan apa yang kamu peroleh?menyisihkan sesuatu dan menyimpannya di rumah, supaya jangan pengumpulan itu baru diadakan, kalau aku datang.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 3, 'Sesudah aku tiba, aku akan mengutus orang-orang, yang kamu anggap layak, dengan surat ke Yerusalem untuk menyampaikan pemberianmu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 4, 'Kalau ternyata penting, bahwa aku juga pergi, maka mereka akan pergi bersama-sama dengan aku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 5, 'Aku akan datang kepadamu, sesudah aku melintasi Makedonia, sebab aku akan melintasi Makedonia.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 6, 'Dan di Korintus mungkin aku akan tinggal beberapa lamanya dengan kamu atau mungkin aku akan tinggal selama musim dingin, sehingga kamu dapat menolong aku untuk melanjutkan perjalananku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 7, 'Sebab sekarang aku tidak mau melihat kamu hanya sepintas lalu saja. Aku harap dapat tinggal agak lama dengan kamu, jika diperkenankan Tuhan.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 8, 'Tetapi aku akan tinggal di Efesus sampai hari raya Pentakosta,', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 9, 'sebab di sini banyak kesempatan bagiku untuk mengerjakan pekerjaan yang besar dan penting, sekalipun ada banyak penentang.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 10, 'Jika Timotius datang kepadamu, usahakanlah supaya ia berada di tengah-tengah kamu tanpa takut, sebab ia mengerjakan pekerjaan Tuhan, sama seperti aku.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 11, 'Jadi, janganlah ada orang yang menganggapnya rendah! Tetapi tolonglah dia, supaya ia melanjutkan perjalanannya dengan selamat, agar ia datang kembali kepadaku, sebab aku di sini menunggu kedatangannya bersama-sama dengan saudara-saudara yang lain.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 12, 'Tentang saudara Apolos: telah berulang-ulang aku mendesaknya untuk bersama-sama dengan saudara-saudara lain mengunjungi kamu, tetapi ia sama sekali tidak mau datang sekarang. Kalau ada kesempatan baik nanti, ia akan datang.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 13, 'Berjaga-jagalah! Berdirilah dengan teguh dalam iman! Bersikaplah sebagai laki-laki! Dan tetap kuat!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 14, 'Lakukanlah segala pekerjaanmu dalam kasih!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 15, 'Ada suatu permintaan lagi kepadamu, saudara-saudara. Kamu tahu, bahwa Stefanus dan keluarganya adalah orang-orang yang pertama-tama bertobat di Akhaya, dan bahwa mereka telah mengabdikan diri kepada pelayanan orang-orang kudus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 16, 'Karena itu taatilah orang-orang yang demikian dan setiap orang yang turut bekerja dan berjerih payah.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 17, 'Aku bergembira atas kedatangan Stefanus, Fortunatus dan Akhaikus, karena mereka melengkapi apa yang masih kurang padamu;', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 18, 'karena mereka menyegarkan rohku dan roh kamu. Hargailah orang-orang yang demikian!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 19, 'Salam kepadamu dari Jemaat-jemaat di Asia Kecil. Akwila, Priskila dan Jemaat di rumah mereka menyampaikan berlimpah-limpah salam kepadamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 20, 'Salam kepadamu dari saudara-saudara semuanya. Sampaikanlah salam seorang kepada yang lain dengan cium kudus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 21, 'Dengan tanganku sendiri aku menulis ini: Salam dari Paulus.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 22, 'Siapa yang tidak mengasihi Tuhan, terkutuklah ia. Maranata!', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 23, 'Kasih karunia Tuhan Yesus menyertai kamu.', 'id', 'TB'),
  ('46', '1kor', '1 Korintus', 16, 24, 'Kasihku menyertai kamu sekalian dalam Kristus Yesus.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 1, 'Dari Paulus, yang oleh kehendak Allah menjadi rasul Kristus Yesus, dan dari Timotius saudara kita, kepada jemaat Allah di Korintus dengan semua orang kudus di seluruh Akhaya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 2, 'Kasih karunia dan damai sejahtera dari Allah, Bapa kita, dan dari Tuhan Yesus Kristus menyertai kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 3, 'Terpujilah Allah, Bapa Tuhan kita Yesus Kristus, Bapa yang penuh belas kasihan dan Allah sumber segala penghiburan,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 4, 'yang menghibur kami dalam segala penderitaan kami, sehingga kami sanggup menghibur mereka, yang berada dalam bermacam-macam penderitaan dengan penghiburan yang kami terima sendiri dari Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 5, 'Sebab sama seperti kami mendapat bagian berlimpah-limpah dalam kesengsaraan Kristus, demikian pula oleh Kristus kami menerima penghiburan berlimpah-limpah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 6, 'Jika kami menderita, hal itu menjadi penghiburan dan keselamatan kamu; jika kami dihibur, maka hal itu adalah untuk penghiburan kamu, sehingga kamu beroleh kekuatan untuk dengan sabar menderita kesengsaraan yang sama seperti yang kami derita juga.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 7, 'Dan pengharapan kami akan kamu adalah teguh, karena kami tahu, bahwa sama seperti kamu turut mengambil bagian dalam kesengsaraan kami, kamu juga turut mengambil bagian dalam penghiburan kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 8, 'Sebab kami mau, saudara-saudara, supaya kamu tahu akan penderitaan yang kami alami di Asia Kecil. Beban yang ditanggungkan atas kami adalah begitu besar dan begitu berat, sehingga kami telah putus asa juga akan hidup kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 9, 'Bahkan kami merasa, seolah-olah kami telah dijatuhi hukuman mati. Tetapi hal itu terjadi, supaya kami jangan menaruh kepercayaan pada diri kami sendiri, tetapi hanya kepada Allah yang membangkitkan orang-orang mati.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 10, 'Dari kematian yang begitu ngeri Ia telah dan akan menyelamatkan kami: kepada-Nya kami menaruh pengharapan kami, bahwa Ia akan menyelamatkan kami lagi,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 11, 'karena kamu juga turut membantu mendoakan kami, supaya banyak orang mengucap syukur atas karunia yang kami peroleh berkat banyaknya doa mereka untuk kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 12, 'Inilah yang kami megahkan, yaitu bahwa suara hati kami memberi kesaksian kepada kami, bahwa hidup kami di dunia ini, khususnya dalam hubungan kami dengan kamu, dikuasai oleh ketulusan dan kemurnian dari Allah bukan oleh hikmat duniawi, tetapi oleh kekuatan kasih karunia Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 13, 'Sebab kami hanya menuliskan kepada kamu apa yang dapat kamu baca dan pahamkan. Dan aku harap, mudah-mudahan kamu akan memahaminya sepenuhnya,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 14, 'seperti yang telah kamu pahamkan sebagiannya dari kami, yaitu bahwa pada hari Tuhan Yesus kamu akan bermegah atas kami seperti kami juga akan bermegah atas kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 15, 'Berdasarkan keyakinan ini aku pernah merencanakan untuk mengunjungi kamu dahulu, supaya kamu boleh menerima kasih karunia untuk kedua kalinya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 16, 'Kemudian aku mau meneruskan perjalananku ke Makedonia, lalu dari Makedonia kembali lagi kepada kamu, supaya kamu menolong aku dalam perjalananku ke Yudea.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 17, 'Jadi, adakah aku bertindak serampangan dalam merencanakan hal ini? Atau adakah aku membuat rencanaku itu menurut keinginanku sendiri, sehingga padaku serentak terdapat "ya" dan "tidak"?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 18, 'Demi Allah yang setia, janji kami kepada kamu bukanlah serentak "ya" dan "tidak".', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 19, 'Karena Yesus Kristus, Anak Allah, yang telah kami beritakan di tengah-tengah kamu, yaitu olehku dan oleh Silwanus dan Timotius, bukanlah "ya" dan "tidak", tetapi sebaliknya di dalam Dia hanya ada "ya".', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 20, 'Sebab Kristus adalah "ya" bagi semua janji Allah. Itulah sebabnya oleh Dia kita mengatakan "Amin" untuk memuliakan Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 21, 'Sebab Dia yang telah meneguhkan kami bersama-sama dengan kamu di dalam Kristus, adalah Allah yang telah mengurapi,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 22, 'memeteraikan tanda milik-Nya atas kita dan yang memberikan Roh Kudus di dalam hati kita sebagai jaminan dari semua yang telah disediakan untuk kita.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 23, 'Tetapi aku memanggil Allah sebagai saksiku?Ia mengenal aku?,bahwa sebabnya aku tidak datang ke Korintus ialah untuk menyayangkan kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 1, 24, 'Bukan karena kami mau memerintahkan apa yang harus kamu percayai, karena kamu berdiri teguh dalam imanmu. Sebaliknya, kami mau turut bekerja untuk sukacitamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 1, 'Aku telah mengambil keputusan di dalam hatiku, bahwa aku tidak akan datang lagi kepadamu dalam dukacita.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 2, 'Sebab, jika aku mendukakan hatimu, siapa lagi yang dapat membuat aku menjadi gembira selain dia yang berdukacita karena aku.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 3, 'Dan justru itulah maksud suratku ini, yaitu supaya jika aku datang, jangan aku berdukacita oleh mereka, yang harus membuat aku menjadi gembira. Sebab aku yakin tentang kamu semua, bahwa sukacitaku adalah juga sukacitamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 4, 'Aku menulis kepada kamu dengan hati yang sangat cemas dan sesak dan dengan mencucurkan banyak air mata, bukan supaya kamu bersedih hati, tetapi supaya kamu tahu betapa besarnya kasihku kepada kamu semua.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 5, 'Tetapi jika ada orang yang menyebabkan kesedihan, maka bukan hatiku yang disedihkannya, melainkan hati kamu sekalian, atau sekurang-kurangnya?supaya jangan aku melebih-lebihkan?,hati beberapa orang di antara kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 6, 'Bagi orang yang demikian sudahlah cukup tegoran dari sebagian besar dari kamu,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 7, 'sehingga kamu sebaliknya harus mengampuni dan menghibur dia, supaya ia jangan binasa oleh kesedihan yang terlampau berat.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 8, 'Sebab itu aku menasihatkan kamu, supaya kamu sungguh-sungguh mengasihi dia.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 9, 'Sebab justru itulah maksudnya aku menulis surat kepada kamu, yaitu untuk menguji kamu, apakah kamu taat dalam segala sesuatu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 10, 'Sebab barangsiapa yang kamu ampuni kesalahannya, aku mengampuninya juga. Sebab jika aku mengampuni, ?seandainya ada yang harus kuampuni?,maka hal itu kubuat oleh karena kamu di hadapan Kristus,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 11, 'supaya Iblis jangan beroleh keuntungan atas kita, sebab kita tahu apa maksudnya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 12, 'Ketika aku tiba di Troas untuk memberitakan Injil Kristus, aku dapati, bahwa Tuhan telah membuka jalan untuk pekerjaan di sana.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 13, 'Tetapi hatiku tidak merasa tenang, karena aku tidak menjumpai saudaraku Titus. Sebab itu aku minta diri dan berangkat ke Makedonia.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 14, 'Tetapi syukur bagi Allah, yang dalam Kristus selalu membawa kami di jalan kemenangan-Nya. Dengan perantaraan kami Ia menyebarkan keharuman pengenalan akan Dia di mana-mana.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 15, 'Sebab bagi Allah kami adalah bau yang harum dari Kristus di tengah-tengah mereka yang diselamatkan dan di antara mereka yang binasa.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 16, 'Bagi yang terakhir kami adalah bau kematian yang mematikan dan bagi yang pertama bau kehidupan yang menghidupkan. Tetapi siapakah yang sanggup menunaikan tugas yang demikian?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 2, 17, 'Sebab kami tidak sama dengan banyak orang lain yang mencari keuntungan dari firman Allah. Sebaliknya dalam Kristus kami berbicara sebagaimana mestinya dengan maksud-maksud murni atas perintah Allah dan di hadapan-Nya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 1, 'Adakah kami mulai lagi memujikan diri kami? Atau perlukah kami seperti orang-orang lain menunjukkan surat pujian kepada kamu atau dari kamu?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 2, 'Kamu adalah surat pujian kami yang tertulis dalam hati kami dan yang dikenal dan yang dapat dibaca oleh semua orang.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 3, 'Karena telah ternyata, bahwa kamu adalah surat Kristus, yang ditulis oleh pelayanan kami, ditulis bukan dengan tinta, tetapi dengan Roh dari Allah yang hidup, bukan pada loh-loh batu, melainkan pada loh-loh daging, yaitu di dalam hati manusia.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 4, 'Demikianlah besarnya keyakinan kami kepada Allah oleh Kristus.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 5, 'Dengan diri kami sendiri kami tidak sanggup untuk memperhitungkan sesuatu seolah-olah pekerjaan kami sendiri; tidak, kesanggupan kami adalah pekerjaan Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 6, 'Ialah membuat kami juga sanggup menjadi pelayan-pelayan dari suatu perjanjian baru, yang tidak terdiri dari hukum yang tertulis, tetapi dari Roh, sebab hukum yang tertulis mematikan, tetapi Roh menghidupkan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 7, 'Pelayanan yang memimpin kepada kematian terukir dengan huruf pada loh-loh batu. Namun demikian kemuliaan Allah menyertainya waktu ia diberikan. Sebab sekalipun pudar juga, cahaya muka Musa begitu cemerlang, sehingga mata orang-orang Israel tidak tahan menatapnya. Jika pelayanan itu datang dengan kemuliaan yang demikian', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 8, 'betapa lebih besarnya lagi kemuliaan yang menyertai pelayanan Roh!', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 9, 'Sebab, jika pelayanan yang memimpin kepada penghukuman itu mulia, betapa lebih mulianya lagi pelayanan yang memimpin kepada pembenaran.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 10, 'Sebenarnya apa yang dahulu dianggap mulia, jika dibandingkan dengan kemuliaan yang mengatasi segala sesuatu ini, sama sekali tidak mempunyai arti.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 11, 'Sebab, jika yang pudar itu disertai dengan kemuliaan, betapa lebihnya lagi yang tidak pudar itu disertai kemuliaan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 12, 'Karena kami mempunyai pengharapan yang demikian, maka kami bertindak dengan penuh keberanian,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 13, 'tidak seperti Musa, yang menyelubungi mukanya, supaya mata orang-orang Israel jangan melihat hilangnya cahaya yang sementara itu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 14, 'Tetapi pikiran mereka telah menjadi tumpul, sebab sampai pada hari ini selubung itu masih tetap menyelubungi mereka, jika mereka membaca perjanjian lama itu tanpa disingkapkan, karena hanya Kristus saja yang dapat menyingkapkannya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 15, 'Bahkan sampai pada hari ini, setiap kali mereka membaca kitab Musa, ada selubung yang menutupi hati mereka.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 16, 'Tetapi apabila hati seorang berbalik kepada Tuhan, maka selubung itu diambil dari padanya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 17, 'Sebab Tuhan adalah Roh; dan di mana ada Roh Allah, di situ ada kemerdekaan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 3, 18, 'Dan kita semua mencerminkan kemuliaan Tuhan dengan muka yang tidak berselubung. Dan karena kemuliaan itu datangnya dari Tuhan yang adalah Roh, maka kita diubah menjadi serupa dengan gambar-Nya, dalam kemuliaan yang semakin besar.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 1, 'Oleh kemurahan Allah kami telah menerima pelayanan ini. Karena itu kami tidak tawar hati.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 2, 'Tetapi kami menolak segala perbuatan tersembunyi yang memalukan; kami tidak berlaku licik dan tidak memalsukan firman Allah. Sebaliknya kami menyatakan kebenaran dan dengan demikian kami menyerahkan diri kami untuk dipertimbangkan oleh semua orang di hadapan Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 3, 'Jika Injil yang kami beritakan masih tertutup juga, maka ia tertutup untuk mereka, yang akan binasa,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 4, 'yaitu orang-orang yang tidak percaya, yang pikirannya telah dibutakan oleh ilah zaman ini, sehingga mereka tidak melihat cahaya Injil tentang kemuliaan Kristus, yang adalah gambaran Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 5, 'Sebab bukan diri kami yang kami beritakan, tetapi Yesus Kristus sebagai Tuhan, dan diri kami sebagai hambamu karena kehendak Yesus.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 6, 'Sebab Allah yang telah berfirman: "Dari dalam gelap akan terbit terang!", Ia juga yang membuat terang-Nya bercahaya di dalam hati kita, supaya kita beroleh terang dari pengetahuan tentang kemuliaan Allah yang nampak pada wajah Kristus.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 7, 'Tetapi harta ini kami punyai dalam bejana tanah liat, supaya nyata, bahwa kekuatan yang melimpah-limpah itu berasal dari Allah, bukan dari diri kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 8, 'Dalam segala hal kami ditindas, namun tidak terjepit; kami habis akal, namun tidak putus asa;', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 9, 'kami dianiaya, namun tidak ditinggalkan sendirian, kami dihempaskan, namun tidak binasa.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 10, 'Kami senantiasa membawa kematian Yesus di dalam tubuh kami, supaya kehidupan Yesus juga menjadi nyata di dalam tubuh kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 11, 'Sebab kami, yang masih hidup ini, terus-menerus diserahkan kepada maut karena Yesus, supaya juga hidup Yesus menjadi nyata di dalam tubuh kami yang fana ini.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 12, 'Maka demikianlah maut giat di dalam diri kami dan hidup giat di dalam kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 13, 'Namun karena kami memiliki roh iman yang sama, seperti ada tertulis: "Aku percaya, sebab itu aku berkata-kata", maka kami juga percaya dan sebab itu kami juga berkata-kata.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 14, 'Karena kami tahu, bahwa Ia, yang telah membangkitkan Tuhan Yesus, akan membangkitkan kami juga bersama-sama dengan Yesus. Dan Ia akan menghadapkan kami bersama-sama dengan kamu kepada diri-Nya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 15, 'Sebab semuanya itu terjadi oleh karena kamu, supaya kasih karunia, yang semakin besar berhubung dengan semakin banyaknya orang yang menjadi percaya, menyebabkan semakin melimpahnya ucapan syukur bagi kemuliaan Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 16, 'Sebab itu kami tidak tawar hati, tetapi meskipun manusia lahiriah kami semakin merosot, namun manusia batiniah kami dibaharui dari sehari ke sehari.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 17, 'Sebab penderitaan ringan yang sekarang ini, mengerjakan bagi kami kemuliaan kekal yang melebihi segala-galanya, jauh lebih besar dari pada penderitaan kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 4, 18, 'Sebab kami tidak memperhatikan yang kelihatan, melainkan yang tak kelihatan, karena yang kelihatan adalah sementara, sedangkan yang tak kelihatan adalah kekal.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 1, 'Karena kami tahu, bahwa jika kemah tempat kediaman kita di bumi ini dibongkar, Allah telah menyediakan suatu tempat kediaman di sorga bagi kita, suatu tempat kediaman yang kekal, yang tidak dibuat oleh tangan manusia.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 2, 'Selama kita di dalam kemah ini, kita mengeluh, karena kita rindu mengenakan tempat kediaman sorgawi di atas tempat kediaman kita yang sekarang ini,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 3, 'sebab dengan demikian kita berpakaian dan tidak kedapatan telanjang.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 4, 'Sebab selama masih diam di dalam kemah ini, kita mengeluh oleh beratnya tekanan, karena kita mau mengenakan pakaian yang baru itu tanpa menanggalkan yang lama, supaya yang fana itu ditelan oleh hidup.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 5, 'Tetapi Allahlah yang justru mempersiapkan kita untuk hal itu dan yang mengaruniakan Roh, kepada kita sebagai jaminan segala sesuatu yang telah disediakan bagi kita.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 6, 'Maka oleh karena itu hati kami senantiasa tabah, meskipun kami sadar, bahwa selama kami mendiami tubuh ini, kami masih jauh dari Tuhan,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 7, '?sebab hidup kami ini adalah hidup karena percaya, bukan karena melihat?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 8, 'tetapi hati kami tabah, dan terlebih suka kami beralih dari tubuh ini untuk menetap pada Tuhan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 9, 'Sebab itu juga kami berusaha, baik kami diam di dalam tubuh ini, maupun kami diam di luarnya, supaya kami berkenan kepada-Nya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 10, 'Sebab kita semua harus menghadap takhta pengadilan Kristus, supaya setiap orang memperoleh apa yang patut diterimanya, sesuai dengan yang dilakukannya dalam hidupnya ini, baik ataupun jahat.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 11, 'Kami tahu apa artinya takut akan Tuhan, karena itu kami berusaha meyakinkan orang. Bagi Allah hati kami nyata dengan terang dan aku harap hati kami nyata juga demikian bagi pertimbangan kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 12, 'Dengan ini kami tidak berusaha memuji-muji diri kami sekali lagi kepada kamu, tetapi kami mau memberi kesempatan kepada kamu untuk memegahkan kami, supaya kamu dapat menghadapi orang-orang yang bermegah karena hal-hal lahiriah dan bukan batiniah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 13, 'Sebab jika kami tidak menguasai diri, hal itu adalah dalam pelayanan Allah, dan jika kami menguasai diri, hal itu adalah untuk kepentingan kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 14, 'Sebab kasih Kristus yang menguasai kami, karena kami telah mengerti, bahwa jika satu orang sudah mati untuk semua orang, maka mereka semua sudah mati.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 15, 'Dan Kristus telah mati untuk semua orang, supaya mereka yang hidup, tidak lagi hidup untuk dirinya sendiri, tetapi untuk Dia, yang telah mati dan telah dibangkitkan untuk mereka.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 16, 'Sebab itu kami tidak lagi menilai seorang jugapun menurut ukuran manusia. Dan jika kami pernah menilai Kristus menurut ukuran manusia, sekarang kami tidak lagi menilai-Nya demikian.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 17, 'Jadi siapa yang ada di dalam Kristus, ia adalah ciptaan baru: yang lama sudah berlalu, sesungguhnya yang baru sudah datang.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 18, 'Dan semuanya ini dari Allah, yang dengan perantaraan Kristus telah mendamaikan kita dengan diri-Nya dan yang telah mempercayakan pelayanan pendamaian itu kepada kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 19, 'Sebab Allah mendamaikan dunia dengan diri-Nya oleh Kristus dengan tidak memperhitungkan pelanggaran mereka. Ia telah mempercayakan berita pendamaian itu kepada kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 20, 'Jadi kami ini adalah utusan-utusan Kristus, seakan-akan Allah menasihati kamu dengan perantaraan kami; dalam nama Kristus kami meminta kepadamu: berilah dirimu didamaikan dengan Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 5, 21, 'Dia yang tidak mengenal dosa telah dibuat-Nya menjadi dosa karena kita, supaya dalam Dia kita dibenarkan oleh Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 1, 'Sebagai teman-teman sekerja, kami menasihatkan kamu, supaya kamu jangan membuat menjadi sia-sia kasih karunia Allah, yang telah kamu terima.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 2, 'Sebab Allah berfirman: "Pada waktu Aku berkenan, Aku akan mendengarkan engkau, dan pada hari Aku menyelamatkan, Aku akan menolong engkau." Sesungguhnya, waktu ini adalah waktu perkenanan itu; sesungguhnya, hari ini adalah hari penyelamatan itu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 3, 'Dalam hal apapun kami tidak memberi sebab orang tersandung, supaya pelayanan kami jangan sampai dicela.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 4, 'Sebaliknya, dalam segala hal kami menunjukkan, bahwa kami adalah pelayan Allah, yaitu: dalam menahan dengan penuh kesabaran dalam penderitaan, kesesakan dan kesukaran,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 5, 'dalam menanggung dera, dalam penjara dan kerusuhan, dalam berjerih payah, dalam berjaga-jaga dan berpuasa;', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 6, 'dalam kemurnian hati, pengetahuan, kesabaran, dan kemurahan hati; dalam Roh Kudus dan kasih yang tidak munafik;', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 7, 'dalam pemberitaan kebenaran dan kekuasaan Allah; dengan menggunakan senjata-senjata keadilan untuk menyerang ataupun untuk membela', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 8, 'ketika dihormati dan ketika dihina; ketika diumpat atau ketika dipuji; ketika dianggap sebagai penipu, namun dipercayai,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 9, 'sebagai orang yang tidak dikenal, namun terkenal; sebagai orang yang nyaris mati, dan sungguh kami hidup; sebagai orang yang dihajar, namun tidak mati;', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 10, 'sebagai orang berdukacita, namun senantiasa bersukacita; sebagai orang miskin, namun memperkaya banyak orang; sebagai orang tak bermilik, sekalipun kami memiliki segala sesuatu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 11, 'Hai orang Korintus! Kami telah berbicara terus terang kepada kamu, hati kami terbuka lebar-lebar bagi kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 12, 'Dan bagi kamu ada tempat yang luas dalam hati kami, tetapi bagi kami hanya tersedia tempat yang sempit di dalam hati kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 13, 'Maka sekarang, supaya timbal balik?aku berkata seperti kepada anak-anakku?:Bukalah hati kamu selebar-lebarnya!', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 14, 'Janganlah kamu merupakan pasangan yang tidak seimbang dengan orang-orang yang tak percaya. Sebab persamaan apakah terdapat antara kebenaran dan kedurhakaan? Atau bagaimanakah terang dapat bersatu dengan gelap?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 15, 'Persamaan apakah yang terdapat antara Kristus dan Belial? Apakah bagian bersama orang-orang percaya dengan orang-orang tak percaya?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 16, 'Apakah hubungan bait Allah dengan berhala? Karena kita adalah bait dari Allah yang hidup menurut firman Allah ini: "Aku akan diam bersama-sama dengan mereka dan hidup di tengah-tengah mereka, dan Aku akan menjadi Allah mereka, dan mereka akan menjadi umat-Ku.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 17, 'Sebab itu: Keluarlah kamu dari antara mereka, dan pisahkanlah dirimu dari mereka, firman Tuhan, dan janganlah menjamah apa yang najis, maka Aku akan menerima kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 6, 18, 'Dan Aku akan menjadi Bapamu, dan kamu akan menjadi anak-anak-Ku laki-laki dan anak-anak-Ku perempuan demikianlah firman Tuhan, Yang Mahakuasa."', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 1, 'Saudara-saudaraku yang kekasih, karena kita sekarang memiliki janji-janji itu, marilah kita menyucikan diri kita dari semua pencemaran jasmani dan rohani, dan dengan demikian menyempurnakan kekudusan kita dalam takut akan Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 2, 'Berilah tempat bagi kami di dalam hati kamu! Kami tidak pernah berbuat salah terhadap seorangpun, tidak seorangpun yang kami rugikan, dan tidak dari seorangpun kami cari untung.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 3, 'Aku berkata demikian, bukan untuk menjatuhkan hukuman atas kamu, sebab tadi telah aku katakan, bahwa kamu telah beroleh tempat di dalam hati kami, sehingga kita sehidup semati.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 4, 'Aku sangat berterus terang terhadap kamu; tetapi aku juga sangat memegahkan kamu. Dalam segala penderitaan kami aku sangat terhibur dan sukacitaku melimpah-limpah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 5, 'Bahkan ketika kami tiba di Makedonia, kami tidak beroleh ketenangan bagi tubuh kami. Di mana-mana kami mengalami kesusahan: dari luar pertengkaran dan dari dalam ketakutan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 6, 'Tetapi Allah, yang menghiburkan orang yang rendah hati, telah menghiburkan kami dengan kedatangan Titus.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 7, 'Bukan hanya oleh kedatangannya saja, tetapi juga oleh penghiburan yang dinikmatinya di tengah-tengah kamu. Karena ia telah memberitahukan kepada kami tentang kerinduanmu, keluhanmu, kesungguhanmu untuk membela aku, sehingga makin bertambahlah sukacitaku.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 8, 'Jadi meskipun aku telah menyedihkan hatimu dengan suratku itu, namun aku tidak menyesalkannya. Memang pernah aku menyesalkannya, karena aku lihat, bahwa surat itu menyedihkan hatimu?kendatipun untuk seketika saja lamanya?,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 9, 'namun sekarang aku bersukacita, bukan karena kamu telah berdukacita, melainkan karena dukacitamu membuat kamu bertobat. Sebab dukacitamu itu adalah menurut kehendak Allah, sehingga kamu sedikitpun tidak dirugikan oleh karena kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 10, 'Sebab dukacita menurut kehendak Allah menghasilkan pertobatan yang membawa keselamatan dan yang tidak akan disesalkan, tetapi dukacita yang dari dunia ini menghasilkan kematian.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 11, 'Sebab perhatikanlah betapa justru dukacita yang menurut kehendak Allah itu mengerjakan pada kamu kesungguhan yang besar, bahkan pembelaan diri, kejengkelan, ketakutan, kerinduan, kegiatan, penghukuman! Di dalam semuanya itu kamu telah membuktikan, bahwa kamu tidak bersalah di dalam perkara itu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 12, 'Sebab itu, jika aku telah menulis surat kepada kamu, maka bukanlah oleh karena orang yang berbuat salah, atau oleh karena orang yang menderita perbuatan salah, melainkan supaya kerelaanmu terhadap kami menjadi nyata bagi kamu di hadapan Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 13, 'Sebab itulah kami menjadi terhibur. Dan selain penghiburan yang kami peroleh itu, kami lebih lagi bersukacita oleh karena sukacita Titus, sebab kamu semua menyegarkan hatinya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 14, 'Aku memegahkan kamu kepadanya, dan kamu tidak mengecewakan aku. Kami senantiasa mengatakan apa yang benar kepada kamu, demikian juga kemegahan kami di hadapan Titus sudah ternyata benar.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 15, 'Dan kasihnya bertambah besar terhadap kamu, apabila ia mengingat ketaatan kamu semua, bagaimana kamu menyambut kedatangannya dengan takut dan gentar.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 7, 16, 'Aku bersukacita, sebab aku dapat menaruh kepercayaan kepada kamu dalam segala hal.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 1, 'Saudara-saudara, kami hendak memberitahukan kepada kamu tentang kasih karunia yang dianugerahkan kepada jemaat-jemaat di Makedonia.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 2, 'Selagi dicobai dengan berat dalam pelbagai penderitaan, sukacita mereka meluap dan meskipun mereka sangat miskin, namun mereka kaya dalam kemurahan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 3, 'Aku bersaksi, bahwa mereka telah memberikan menurut kemampuan mereka, bahkan melampaui kemampuan mereka.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 4, 'Dengan kerelaan sendiri mereka meminta dan mendesak kepada kami, supaya mereka juga beroleh kasih karunia untuk mengambil bagian dalam pelayanan kepada orang-orang kudus.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 5, 'Mereka memberikan lebih banyak dari pada yang kami harapkan. Mereka memberikan diri mereka, pertama-tama kepada Allah, kemudian oleh karena kehendak Allah juga kepada kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 6, 'Sebab itu kami mendesak kepada Titus, supaya ia mengunjungi kamu dan menyelesaikan pelayanan kasih itu sebagaimana ia telah memulainya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 7, 'Maka sekarang, sama seperti kamu kaya dalam segala sesuatu, ?dalam iman, dalam perkataan, dalam pengetahuan, dalam kesungguhan untuk membantu, dan dalam kasihmu terhadap kami?demikianlah juga hendaknya kamu kaya dalam pelayanan kasih ini.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 8, 'Aku mengatakan hal itu bukan sebagai perintah, melainkan, dengan menunjukkan usaha orang-orang lain untuk membantu, aku mau menguji keikhlasan kasih kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 9, 'Karena kamu telah mengenal kasih karunia Tuhan kita Yesus Kristus, bahwa Ia, yang oleh karena kamu menjadi miskin, sekalipun Ia kaya, supaya kamu menjadi kaya oleh karena kemiskinan-Nya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 10, 'Inilah pendapatku tentang hal itu, yang mungkin berfaedah bagimu. Memang sudah sejak tahun yang lalu kamu mulai melaksanakannya dan mengambil keputusan untuk menyelesaikannya juga.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 11, 'Maka sekarang, selesaikan jugalah pelaksanaannya itu! Hendaklah pelaksanaannya sepadan dengan kerelaanmu, dan lakukanlah itu dengan apa yang ada padamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 12, 'Sebab jika kamu rela untuk memberi, maka pemberianmu akan diterima, kalau pemberianmu itu berdasarkan apa yang ada padamu, bukan berdasarkan apa yang tidak ada padamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 13, 'Sebab kamu dibebani bukanlah supaya orang-orang lain mendapat keringanan, tetapi supaya ada keseimbangan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 14, 'Maka hendaklah sekarang ini kelebihan kamu mencukupkan kekurangan mereka, agar kelebihan mereka kemudian mencukupkan kekurangan kamu, supaya ada keseimbangan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 15, 'Seperti ada tertulis: "Orang yang mengumpulkan banyak, tidak kelebihan dan orang yang mengumpulkan sedikit, tidak kekurangan."', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 16, 'Syukur kepada Allah, yang oleh karena kamu mengaruniakan kesungguhan yang demikian juga dalam hati Titus untuk membantu kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 17, 'Memang ia menyambut anjuran kami, tetapi dalam kesungguhannya yang besar itu ia dengan sukarela pergi kepada kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 18, 'Bersama-sama dengan dia kami mengutus saudara kita, yang terpuji di semua jemaat karena pekerjaannya dalam pemberitaan Injil.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 19, 'Dan bukan itu saja! Ia juga telah ditunjuk oleh jemaat-jemaat untuk menemani kami dalam pelayanan kasih ini, yang kami lakukan untuk kemuliaan Tuhan dan sebagai bukti kerelaan kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 20, 'Sebab kami hendak menghindarkan hal ini: bahwa ada orang yang dapat mencela kami dalam hal pelayanan kasih yang kami lakukan dan yang hasilnya sebesar ini.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 21, 'Karena kami memikirkan yang baik, bukan hanya di hadapan Tuhan, tetapi juga di hadapan manusia.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 22, 'Bersama-sama dengan mereka kami utus seorang lain lagi, yakni saudara kita, yang telah beberapa kali kami uji dan ternyata selalu berusaha untuk membantu. Dan sekarang ia makin berusaha karena besarnya kepercayaannya kepada kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 23, 'Titus adalah temanku yang bekerja bersama-sama dengan aku untuk kamu; saudara-saudara kami yang lain itu adalah utusan jemaat-jemaat dan suatu kemuliaan bagi Kristus.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 8, 24, 'Karena itu tunjukkanlah kepada mereka di hadapan jemaat-jemaat bukti kasihmu dan bukti kemegahanku atas kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 1, 'Tentang pelayanan kepada orang-orang kudus tidak perlu lagi aku menuliskannya kepada kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 2, 'Aku telah tahu kerelaan hatimu tentang mana aku megahkan kamu kepada orang-orang Makedonia. Kataku: "Akhaya sudah siap sedia sejak tahun yang lampau." Dan kegiatanmu telah menjadi perangsang bagi banyak orang.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 3, 'Aku mengutus saudara-saudara itu, agar kemegahan kami dalam hal ini atas kamu jangan ternyata menjadi sia-sia, tetapi supaya kamu benar-benar siap sedia seperti yang telah kukatakan,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 4, 'supaya, apabila orang-orang Makedonia datang bersama-sama dengan aku, jangan mereka mendapati kamu belum siap sedia, sehingga kami?untuk tidak mengatakan kamu?merasa malu atas keyakinan kami itu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 5, 'Sebab itu aku merasa perlu mendorong saudara-saudara itu untuk berangkat mendahului aku, supaya mereka lebih dahulu mengurus pemberian yang telah kamu janjikan sebelumnya, agar nanti tersedia sebagai bukti kemurahan hati kamu dan bukan sebagai pemberian yang dipaksakan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 6, 'Camkanlah ini: Orang yang menabur sedikit, akan menuai sedikit juga, dan orang yang menabur banyak, akan menuai banyak juga.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 7, 'Hendaklah masing-masing memberikan menurut kerelaan hatinya, jangan dengan sedih hati atau karena paksaan, sebab Allah mengasihi orang yang memberi dengan sukacita.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 8, 'Dan Allah sanggup melimpahkan segala kasih karunia kepada kamu, supaya kamu senantiasa berkecukupan di dalam segala sesuatu dan malah berkelebihan di dalam pelbagai kebajikan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 9, 'Seperti ada tertulis: "Ia membagi-bagikan, Ia memberikan kepada orang miskin, kebenaran-Nya tetap untuk selamanya."', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 10, 'Ia yang menyediakan benih bagi penabur, dan roti untuk dimakan, Ia juga yang akan menyediakan benih bagi kamu dan melipatgandakannya dan menumbuhkan buah-buah kebenaranmu;', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 11, 'kamu akan diperkaya dalam segala macam kemurahan hati, yang membangkitkan syukur kepada Allah oleh karena kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 12, 'Sebab pelayanan kasih yang berisi pemberian ini bukan hanya mencukupkan keperluan-keperluan orang-orang kudus, tetapi juga melimpahkan ucapan syukur kepada Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 13, 'Dan oleh sebab kamu telah tahan uji dalam pelayanan itu, mereka memuliakan Allah karena ketaatan kamu dalam pengakuan akan Injil Kristus dan karena kemurahan hatimu dalam membagikan segala sesuatu dengan mereka dan dengan semua orang,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 14, 'sedangkan di dalam doa mereka, mereka juga merindukan kamu oleh karena kasih karunia Allah yang melimpah di atas kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 9, 15, 'Syukur kepada Allah karena karunia-Nya yang tak terkatakan itu!', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 1, 'Aku, Paulus, seorang yang tidak berani bila berhadapan muka dengan kamu, tetapi berani terhadap kamu bila berjauhan, aku memperingatkan kamu demi Kristus yang lemah lembut dan ramah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 2, 'Aku meminta kepada kamu: jangan kamu memaksa aku untuk menunjukkan keberanianku dari dekat, sebagaimana aku berniat bertindak keras terhadap orang-orang tertentu yang menyangka, bahwa kami hidup secara duniawi.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 3, 'Memang kami masih hidup di dunia, tetapi kami tidak berjuang secara duniawi,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 4, 'karena senjata kami dalam perjuangan bukanlah senjata duniawi, melainkan senjata yang diperlengkapi dengan kuasa Allah, yang sanggup untuk meruntuhkan benteng-benteng.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 5, 'Kami mematahkan setiap siasat orang dan merubuhkan setiap kubu yang dibangun oleh keangkuhan manusia untuk menentang pengenalan akan Allah. Kami menawan segala pikiran dan menaklukkannya kepada Kristus,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 6, 'dan kami siap sedia juga untuk menghukum setiap kedurhakaan, bila ketaatan kamu telah menjadi sempurna.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 7, 'Tengoklah yang nyata di depan mata kamu! Kalau ada seorang benar-benar yakin, bahwa ia adalah milik Kristus, hendaklah ia berpikir di dalam hatinya, bahwa kami juga adalah milik Kristus sama seperti dia.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 8, 'Bahkan, jikalau aku agak berlebih-lebihan bermegah atas kuasa, yang dikaruniakan Tuhan kepada kami untuk membangun dan bukan untuk meruntuhkan kamu, maka dalam hal itu aku tidak akan mendapat malu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 9, 'Tetapi aku tidak mau kelihatan seolah-olah aku menakut-nakuti kamu dengan surat-suratku.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 10, 'Sebab, kata orang, surat-suratnya memang tegas dan keras, tetapi bila berhadapan muka sikapnya lemah dan perkataan-perkataannya tidak berarti.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 11, 'Tetapi hendaklah orang-orang yang berkata demikian menginsafi, bahwa tindakan kami, bila berhadapan muka, sama seperti perkataan kami dalam surat-surat kami, bila tidak berhadapan muka.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 12, 'Memang kami tidak berani menggolongkan diri kepada atau membandingkan diri dengan orang-orang tertentu yang memujikan diri sendiri. Mereka mengukur dirinya dengan ukuran mereka sendiri dan membandingkan dirinya dengan diri mereka sendiri. Alangkah bodohnya mereka!', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 13, 'Sebaliknya kami tidak mau bermegah melampaui batas, melainkan tetap di dalam batas-batas daerah kerja yang dipatok Allah bagi kami, yang meluas sampai kepada kamu juga.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 14, 'Sebab dalam memberitakan Injil Kristus kami telah sampai kepada kamu, sehingga kami tidak melewati batas daerah kerja kami, seolah-olah kami belum sampai kepada kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 15, 'Kami tidak bermegah atas pekerjaan yang dilakukan oleh orang lain di daerah kerja yang tidak dipatok untuk kami. Tetapi kami berharap, bahwa apabila imanmu makin bertumbuh, kami akan mendapat penghormatan lebih besar lagi di antara kamu, jika dibandingkan dengan daerah kerja yang dipatok untuk kami.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 16, 'Ya, kami hidup, supaya kami dapat memberitakan Injil di daerah-daerah yang lebih jauh dari pada daerah kamu dan tidak bermegah atas hasil-hasil yang dicapai orang lain di daerah kerja yang dipatok untuk mereka.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 17, '"Tetapi barangsiapa bermegah, hendaklah ia bermegah di dalam Tuhan."', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 10, 18, 'Sebab bukan orang yang memuji diri yang tahan uji, melainkan orang yang dipuji Tuhan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 1, 'Alangkah baiknya, jika kamu sabar terhadap kebodohanku yang kecil itu. Memang kamu sabar terhadap aku!', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 2, 'Sebab aku cemburu kepada kamu dengan cemburu ilahi. Karena aku telah mempertunangkan kamu kepada satu laki-laki untuk membawa kamu sebagai perawan suci kepada Kristus.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 3, 'Tetapi aku takut, kalau-kalau pikiran kamu disesatkan dari kesetiaan kamu yang sejati kepada Kristus, sama seperti Hawa diperdayakan oleh ular itu dengan kelicikannya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 4, 'Sebab kamu sabar saja, jika ada seorang datang memberitakan Yesus yang lain dari pada yang telah kami beritakan, atau memberikan kepada kamu roh yang lain dari pada yang telah kamu terima atau Injil yang lain dari pada yang telah kamu terima.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 5, 'Tetapi menurut pendapatku sedikitpun aku tidak kurang dari pada rasul-rasul yang tak ada taranya itu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 6, 'Jikalau aku kurang paham dalam hal berkata-kata, tidaklah demikian dalam hal pengetahuan; sebab kami telah menyatakannya kepada kamu pada segala waktu dan di dalam segala hal.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 7, 'Apakah aku berbuat salah, jika aku merendahkan diri untuk meninggikan kamu, karena aku memberitakan Injil Allah kepada kamu dengan cuma-cuma?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 8, 'Jemaat-jemaat lain telah kurampok dengan menerima tunjangan dari mereka, supaya aku dapat melayani kamu!', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 9, 'Dan ketika aku dalam kekurangan di tengah-tengah kamu, aku tidak menyusahkan seorangpun, sebab apa yang kurang padaku, dicukupkan oleh saudara-saudara yang datang dari Makedonia. Dalam segala hal aku menjaga diriku, supaya jangan menjadi beban bagi kamu, dan aku akan tetap berbuat demikian.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 10, 'Demi kebenaran Kristus di dalam diriku, aku tegaskan, bahwa kemegahanku itu tidak akan dirintangi oleh siapapun di daerah-daerah Akhaya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 11, 'Mengapa tidak? Apakah karena aku tidak mengasihi kamu? Allah mengetahuinya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 12, 'Tetapi apa yang kulakukan, akan tetap kulakukan untuk mencegah mereka yang mencari kesempatan guna menyatakan, bahwa mereka sama dengan kami dalam hal yang dapat dimegahkan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 13, 'Sebab orang-orang itu adalah rasul-rasul palsu, pekerja-pekerja curang, yang menyamar sebagai rasul-rasul Kristus.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 14, 'Hal itu tidak usah mengherankan, sebab Iblispun menyamar sebagai malaikat Terang.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 15, 'Jadi bukanlah suatu hal yang ganjil, jika pelayan-pelayannya menyamar sebagai pelayan-pelayan kebenaran. Kesudahan mereka akan setimpal dengan perbuatan mereka.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 16, 'Kuulangi lagi: jangan hendaknya ada orang yang menganggap aku bodoh. Dan jika kamu juga menganggap demikian, terimalah aku sebagai orang bodoh supaya akupun boleh bermegah sedikit.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 17, 'Apa yang aku katakan, aku mengatakannya bukan sebagai seorang yang berkata menurut firman Tuhan, melainkan sebagai seorang bodoh yang berkeyakinan, bahwa ia boleh bermegah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 18, 'Karena banyak orang yang bermegah secara duniawi, aku mau bermegah juga.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 19, 'Sebab kamu suka sabar terhadap orang bodoh, karena kamu begitu bijaksana:', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 20, 'karena kamu sabar, jika orang memperhambakan kamu, jika orang menghisap kamu, jika orang menguasai kamu, jika orang berlaku angkuh terhadap kamu, jika orang menampar kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 21, 'Dengan sangat malu aku harus mengakui, bahwa dalam hal semacam itu kami terlalu lemah. Tetapi jika orang-orang lain berani membanggakan sesuatu, maka akupun?aku berkata dalam kebodohan?berani juga!', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 22, 'Apakah mereka orang Ibrani? Aku juga orang Ibrani! Apakah mereka orang Israel? Aku juga orang Israel. Apakah mereka keturunan Abraham? Aku juga keturunan Abraham!', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 23, 'Apakah mereka pelayan Kristus? ?aku berkata seperti orang gila?aku lebih lagi! Aku lebih banyak berjerih lelah; lebih sering di dalam penjara; didera di luar batas; kerap kali dalam bahaya maut.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 24, 'Lima kali aku disesah orang Yahudi, setiap kali empat puluh kurang satu pukulan,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 25, 'tiga kali aku didera, satu kali aku dilempari dengan batu, tiga kali mengalami karam kapal, sehari semalam aku terkatung-katung di tengah laut.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 26, 'Dalam perjalananku aku sering diancam bahaya banjir dan bahaya penyamun, bahaya dari pihak orang-orang Yahudi dan dari pihak orang-orang bukan Yahudi; bahaya di kota, bahaya di padang gurun, bahaya di tengah laut, dan bahaya dari pihak saudara-saudara palsu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 27, 'Aku banyak berjerih lelah dan bekerja berat; kerap kali aku tidak tidur; aku lapar dan dahaga; kerap kali aku berpuasa, kedinginan dan tanpa pakaian,', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 28, 'dan, dengan tidak menyebut banyak hal lain lagi, urusanku sehari-hari, yaitu untuk memelihara semua jemaat-jemaat.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 29, 'Jika ada orang merasa lemah, tidakkah aku turut merasa lemah? Jika ada orang tersandung, tidakkah hatiku hancur oleh dukacita?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 30, 'Jika aku harus bermegah, maka aku akan bermegah atas kelemahanku.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 31, 'Allah, yaitu Bapa dari Yesus, Tuhan kita, yang terpuji sampai selama-lamanya, tahu, bahwa aku tidak berdusta.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 32, 'Di Damsyik wali negeri raja Aretas menyuruh mengawal kota orang-orang Damsyik untuk menangkap aku.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 11, 33, 'Tetapi dalam sebuah keranjang aku diturunkan dari sebuah tingkap ke luar tembok kota dan dengan demikian aku terluput dari tangannya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 1, 'Aku harus bermegah, sekalipun memang hal itu tidak ada faedahnya, namun demikian aku hendak memberitakan penglihatan-penglihatan dan penyataan-penyataan yang kuterima dari Tuhan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 2, 'Aku tahu tentang seorang Kristen; empat belas tahun yang lampau?entah di dalam tubuh, aku tidak tahu, entah di luar tubuh, aku tidak tahu, Allah yang mengetahuinya?orang itu tiba-tiba diangkat ke tingkat yang ketiga dari sorga.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 3, 'Aku juga tahu tentang orang itu, ?entah di dalam tubuh entah di luar tubuh, aku tidak tahu, Allah yang mengetahuinya?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 4, 'ia tiba-tiba diangkat ke Firdaus dan ia mendengar kata-kata yang tak terkatakan, yang tidak boleh diucapkan manusia.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 5, 'Atas orang itu aku hendak bermegah, tetapi atas diriku sendiri aku tidak akan bermegah, selain atas kelemahan-kelemahanku.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 6, 'Sebab sekiranya aku hendak bermegah juga, aku bukan orang bodoh lagi, karena aku mengatakan kebenaran. Tetapi aku menahan diriku, supaya jangan ada orang yang menghitungkan kepadaku lebih dari pada yang mereka lihat padaku atau yang mereka dengar dari padaku.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 7, 'Dan supaya aku jangan meninggikan diri karena penyataan-penyataan yang luar biasa itu, maka aku diberi suatu duri di dalam dagingku, yaitu seorang utusan Iblis untuk menggocoh aku, supaya aku jangan meninggikan diri.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 8, 'Tentang hal itu aku sudah tiga kali berseru kepada Tuhan, supaya utusan Iblis itu mundur dari padaku.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 9, 'Tetapi jawab Tuhan kepadaku: "Cukuplah kasih karunia-Ku bagimu, sebab justru dalam kelemahanlah kuasa-Ku menjadi sempurna." Sebab itu terlebih suka aku bermegah atas kelemahanku, supaya kuasa Kristus turun menaungi aku.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 10, 'Karena itu aku senang dan rela di dalam kelemahan, di dalam siksaan, di dalam kesukaran, di dalam penganiayaan dan kesesakan oleh karena Kristus. Sebab jika aku lemah, maka aku kuat.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 11, 'Sungguh aku telah menjadi bodoh; tetapi kamu yang memaksa aku. Sebenarnya aku harus kamu puji. Karena meskipun aku tidak berarti sedikitpun, namun di dalam segala hal aku tidak kalah terhadap rasul-rasul yang luar biasa itu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 12, 'Segala sesuatu yang membuktikan, bahwa aku adalah seorang rasul, telah dilakukan di tengah-tengah kamu dengan segala kesabaran oleh tanda-tanda, mujizat-mujizat dan kuasa-kuasa.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 13, 'Sebab dalam hal manakah kamu dikebelakangkan dibandingkan dengan jemaat-jemaat lain, selain dari pada dalam hal ini, yaitu bahwa aku sendiri tidak menjadi suatu beban kepada kamu? Maafkanlah ketidakadilanku ini!', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 14, 'Sesungguhnya sekarang sudah untuk ketiga kalinya aku siap untuk mengunjungi kamu, dan aku tidak akan merupakan suatu beban bagi kamu. Sebab bukan hartamu yang kucari, melainkan kamu sendiri. Karena bukan anak-anak yang harus mengumpulkan harta untuk orang tuanya, melainkan orang tualah untuk anak-anaknya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 15, 'Karena itu aku suka mengorbankan milikku, bahkan mengorbankan diriku untuk kamu. Jadi jika aku sangat mengasihi kamu, masakan aku semakin kurang dikasihi?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 16, 'Baiklah, aku sendiri tidak merupakan suatu beban bagi kamu, tetapi?kamu katakan?dalam kelicikanku aku telah menjerat kamu dengan tipu daya.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 17, 'Jadi pernahkah aku mengambil untung dari pada kamu oleh seorang dari antara mereka, yang kuutus kepada kamu?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 18, 'Memang aku telah meminta Titus untuk pergi dan bersama-sama dengan dia aku mengutus saudara yang lain itu. Adakah Titus mengambil untung dari pada kamu? Tidakkah kami berdua hidup menurut roh yang sama dan tidakkah kami berlaku menurut cara yang sama?', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 19, 'Sudah lama agaknya kamu menyangka, bahwa kami hendak membela diri di depan kamu. Di hadapan Allah dan demi Kristus kami berkata: semua ini, saudara-saudaraku yang kekasih, terjadi untuk membangun iman kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 20, 'Sebab aku kuatir, bahwa apabila aku datang aku mendapati kamu tidak seperti yang kuinginkan dan kamu mendapati aku tidak seperti yang kamu inginkan. Aku kuatir akan adanya perselisihan, iri hati, amarah, kepentingan diri sendiri, fitnah, bisik-bisikan, keangkuhan, dan kerusuhan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 12, 21, 'Aku kuatir, bahwa apabila aku datang lagi, Allahku akan merendahkan aku di depan kamu, dan bahwa aku akan berdukacita terhadap banyak orang yang di masa yang lampau berbuat dosa dan belum lagi bertobat dari kecemaran, percabulan dan ketidaksopanan yang mereka lakukan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 1, 'Ini adalah untuk ketiga kalinya aku datang kepada kamu: Baru dengan keterangan dua atau tiga orang saksi suatu perkara sah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 2, 'Kepada mereka, yang di masa yang lampau berbuat dosa, dan kepada semua orang lain, telah kukatakan terlebih dahulu dan aku akan mengatakannya sekali lagi?sekarang pada waktu aku berjauhan dengan kamu tepat seperti pada waktu kedatanganku kedua kalinya?bahwa aku tidak akan menyayangkan mereka pada waktu aku datang lagi.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 3, 'Karena kamu ingin suatu bukti, bahwa Kristus berkata-kata dengan perantaraan aku, dan Ia tidak lemah terhadap kamu, melainkan berkuasa di tengah-tengah kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 4, 'Karena sekalipun Ia telah disalibkan oleh karena kelemahan, namun Ia hidup karena kuasa Allah. Memang kami adalah lemah di dalam Dia, tetapi kami akan hidup bersama-sama dengan Dia untuk kamu karena kuasa Allah.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 5, 'Ujilah dirimu sendiri, apakah kamu tetap tegak di dalam iman. Selidikilah dirimu! Apakah kamu tidak yakin akan dirimu, bahwa Kristus Yesus ada di dalam diri kamu? Sebab jika tidak demikian, kamu tidak tahan uji.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 6, 'Tetapi aku harap, bahwa kamu tahu, bahwa bukan kami yang tidak tahan uji.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 7, 'Kami berdoa kepada Allah, agar kamu jangan berbuat jahat bukan supaya kami ternyata tahan uji, melainkan supaya kamu ini boleh berbuat apa yang baik, sekalipun kami sendiri tampaknya tidak tahan uji.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 8, 'Karena kami tidak dapat berbuat apa-apa melawan kebenaran; yang dapat kami perbuat ialah untuk kebenaran.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 9, 'Sebab kami bersukacita, apabila kami lemah dan kamu kuat. Dan inilah yang kami doakan, yaitu supaya kamu menjadi sempurna.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 10, 'Itulah sebabnya sekali ini aku menulis kepada kamu ketika aku berjauhan dengan kamu, supaya bila aku berada di tengah-tengah kamu, aku tidak terpaksa bertindak keras menurut kuasa yang dianugerahkan Tuhan kepadaku untuk membangun dan bukan untuk meruntuhkan.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 11, 'Akhirnya, saudara-saudaraku, bersukacitalah, usahakanlah dirimu supaya sempurna. Terimalah segala nasihatku! Sehati sepikirlah kamu, dan hiduplah dalam damai sejahtera; maka Allah, sumber kasih dan damai sejahtera akan menyertai kamu!', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 12, 'Berilah salam seorang kepada yang lain dengan cium yang kudus.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 13, '(13-12b) Salam dari semua orang kudus kepada kamu.', 'id', 'TB'),
  ('47', '2kor', '2 Korintus', 13, 14, '(13-13) Kasih karunia Tuhan Yesus Kristus, dan kasih Allah, dan persekutuan Roh Kudus menyertai kamu sekalian.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 1, 'Dari Paulus, seorang rasul, bukan karena manusia, juga bukan oleh seorang manusia, melainkan oleh Yesus Kristus dan Allah, Bapa, yang telah membangkitkan Dia dari antara orang mati,', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 2, 'dan dari semua saudara yang ada bersama-sama dengan aku, kepada jemaat-jemaat di Galatia:', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 3, 'kasih karunia menyertai kamu dan damai sejahtera dari Allah, Bapa kita, dan dari Tuhan Yesus Kristus,', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 4, 'yang telah menyerahkan diri-Nya karena dosa-dosa kita, untuk melepaskan kita dari dunia jahat yang sekarang ini, menurut kehendak Allah dan Bapa kita.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 5, 'Bagi-Nyalah kemuliaan selama-lamanya! Amin.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 6, 'Aku heran, bahwa kamu begitu lekas berbalik dari pada Dia, yang oleh kasih karunia Kristus telah memanggil kamu, dan mengikuti suatu injil lain,', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 7, 'yang sebenarnya bukan Injil. Hanya ada orang yang mengacaukan kamu dan yang bermaksud untuk memutarbalikkan Injil Kristus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 8, 'Tetapi sekalipun kami atau seorang malaikat dari sorga yang memberitakan kepada kamu suatu injil yang berbeda dengan Injil yang telah kami beritakan kepadamu, terkutuklah dia.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 9, 'Seperti yang telah kami katakan dahulu, sekarang kukatakan sekali lagi: jikalau ada orang yang memberitakan kepadamu suatu injil, yang berbeda dengan apa yang telah kamu terima, terkutuklah dia.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 10, 'Jadi bagaimana sekarang: adakah kucari kesukaan manusia atau kesukaan Allah? Adakah kucoba berkenan kepada manusia? Sekiranya aku masih mau mencoba berkenan kepada manusia, maka aku bukanlah hamba Kristus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 11, 'Sebab aku menegaskan kepadamu, saudara-saudaraku, bahwa Injil yang kuberitakan itu bukanlah injil manusia.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 12, 'Karena aku bukan menerimanya dari manusia, dan bukan manusia yang mengajarkannya kepadaku, tetapi aku menerimanya oleh penyataan Yesus Kristus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 13, 'Sebab kamu telah mendengar tentang hidupku dahulu dalam agama Yahudi: tanpa batas aku menganiaya jemaat Allah dan berusaha membinasakannya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 14, 'Dan di dalam agama Yahudi aku jauh lebih maju dari banyak teman yang sebaya dengan aku di antara bangsaku, sebagai orang yang sangat rajin memelihara adat istiadat nenek moyangku.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 15, 'Tetapi waktu Ia, yang telah memilih aku sejak kandungan ibuku dan memanggil aku oleh kasih karunia-Nya,', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 16, 'berkenan menyatakan Anak-Nya di dalam aku, supaya aku memberitakan Dia di antara bangsa-bangsa bukan Yahudi, maka sesaatpun aku tidak minta pertimbangan kepada manusia;', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 17, 'juga aku tidak pergi ke Yerusalem mendapatkan mereka yang telah menjadi rasul sebelum aku, tetapi aku berangkat ke tanah Arab dan dari situ kembali lagi ke Damsyik.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 18, 'Lalu, tiga tahun kemudian, aku pergi ke Yerusalem untuk mengunjungi Kefas, dan aku menumpang lima belas hari di rumahnya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 19, 'Tetapi aku tidak melihat seorangpun dari rasul-rasul yang lain, kecuali Yakobus, saudara Tuhan Yesus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 20, 'Di hadapan Allah kutegaskan: apa yang kutuliskan kepadamu ini benar, aku tidak berdusta.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 21, 'Kemudian aku pergi ke daerah-daerah Siria dan Kilikia.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 22, 'Tetapi rupaku tetap tidak dikenal oleh jemaat-jemaat Kristus di Yudea.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 23, 'Mereka hanya mendengar, bahwa ia yang dahulu menganiaya mereka, sekarang memberitakan iman, yang pernah hendak dibinasakannya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 1, 24, 'Dan mereka memuliakan Allah karena aku.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 1, 'Kemudian setelah lewat empat belas tahun, aku pergi pula ke Yerusalem dengan Barnabas dan Tituspun kubawa juga.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 2, 'Aku pergi berdasarkan suatu penyataan. Dan kepada mereka kubentangkan Injil yang kuberitakan di antara bangsa-bangsa bukan Yahudi?dalam percakapan tersendiri kepada mereka yang terpandang?,supaya jangan dengan percuma aku berusaha atau telah berusaha.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 3, 'Tetapi kendatipun Titus, yang bersama-sama dengan aku, adalah seorang Yunani, namun ia tidak dipaksa untuk menyunatkan dirinya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 4, 'Memang ada desakan dari saudara-saudara palsu yang menyusup masuk, yaitu mereka yang menyelundup ke dalam untuk menghadang kebebasan kita yang kita miliki di dalam Kristus Yesus, supaya dengan jalan itu mereka dapat memperhambakan kita.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 5, 'Tetapi sesaatpun kami tidak mau mundur dan tunduk kepada mereka, agar kebenaran Injil dapat tinggal tetap pada kamu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 6, 'Dan mengenai mereka yang dianggap terpandang itu?bagaimana kedudukan mereka dahulu, itu tidak penting bagiku, sebab Allah tidak memandang muka?bagaimanapun juga, mereka yang terpandang itu tidak memaksakan sesuatu yang lain kepadaku.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 7, 'Tetapi sebaliknya, setelah mereka melihat bahwa kepadaku telah dipercayakan pemberitaan Injil untuk orang-orang tak bersunat, sama seperti kepada Petrus untuk orang-orang bersunat', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 8, '?karena Ia yang telah memberikan kekuatan kepada Petrus untuk menjadi rasul bagi orang-orang bersunat, Ia juga yang telah memberikan kekuatan kepadaku untuk orang-orang yang tidak bersunat.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 9, 'Dan setelah melihat kasih karunia yang dianugerahkan kepadaku, maka Yakobus, Kefas dan Yohanes, yang dipandang sebagai sokoguru jemaat, berjabat tangan dengan aku dan dengan Barnabas sebagai tanda persekutuan, supaya kami pergi kepada orang-orang yang tidak bersunat dan mereka kepada orang-orang yang bersunat;', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 10, 'hanya kami harus tetap mengingat orang-orang miskin dan memang itulah yang sungguh-sungguh kuusahakan melakukannya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 11, 'Tetapi waktu Kefas datang ke Antiokhia, aku berterang-terang menentangnya, sebab ia salah.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 12, 'Karena sebelum beberapa orang dari kalangan Yakobus datang, ia makan sehidangan dengan saudara-saudara yang tidak bersunat, tetapi setelah mereka datang, ia mengundurkan diri dan menjauhi mereka karena takut akan saudara-saudara yang bersunat.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 13, 'Dan orang-orang Yahudi yang lainpun turut berlaku munafik dengan dia, sehingga Barnabas sendiri turut terseret oleh kemunafikan mereka.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 14, 'Tetapi waktu kulihat, bahwa kelakuan mereka itu tidak sesuai dengan kebenaran Injil, aku berkata kepada Kefas di hadapan mereka semua: "Jika engkau, seorang Yahudi, hidup secara kafir dan bukan secara Yahudi, bagaimanakah engkau dapat memaksa saudara-saudara yang tidak bersunat untuk hidup secara Yahudi?"', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 15, 'Menurut kelahiran kami adalah orang Yahudi dan bukan orang berdosa dari bangsa-bangsa lain.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 16, 'Kamu tahu, bahwa tidak seorangpun yang dibenarkan oleh karena melakukan hukum Taurat, tetapi hanya oleh karena iman dalam Kristus Yesus. Sebab itu kamipun telah percaya kepada Kristus Yesus, supaya kami dibenarkan oleh karena iman dalam Kristus dan bukan oleh karena melakukan hukum Taurat. Sebab: "tidak ada seorangpun yang dibenarkan" oleh karena melakukan hukum Taurat.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 17, 'Tetapi jika kami sendiri, sementara kami berusaha untuk dibenarkan dalam Kristus ternyata adalah orang-orang berdosa, apakah hal itu berarti, bahwa Kristus adalah pelayan dosa? Sekali-kali tidak.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 18, 'Karena, jikalau aku membangun kembali apa yang telah kurombak, aku menyatakan diriku sebagai pelanggar hukum Taurat.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 19, 'Sebab aku telah mati oleh hukum Taurat untuk hukum Taurat, supaya aku hidup untuk Allah. Aku telah disalibkan dengan Kristus;', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 20, 'namun aku hidup, tetapi bukan lagi aku sendiri yang hidup, melainkan Kristus yang hidup di dalam aku. Dan hidupku yang kuhidupi sekarang di dalam daging, adalah hidup oleh iman dalam Anak Allah yang telah mengasihi aku dan menyerahkan diri-Nya untuk aku.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 2, 21, 'Aku tidak menolak kasih karunia Allah. Sebab sekiranya ada kebenaran oleh hukum Taurat, maka sia-sialah kematian Kristus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 1, 'Hai orang-orang Galatia yang bodoh, siapakah yang telah mempesona kamu? Bukankah Yesus Kristus yang disalibkan itu telah dilukiskan dengan terang di depanmu?', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 2, 'Hanya ini yang hendak kuketahui dari pada kamu: Adakah kamu telah menerima Roh karena melakukan hukum Taurat atau karena percaya kepada pemberitaan Injil?', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 3, 'Adakah kamu sebodoh itu? Kamu telah mulai dengan Roh, maukah kamu sekarang mengakhirinya di dalam daging?', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 4, 'Sia-siakah semua yang telah kamu alami sebanyak itu? Masakan sia-sia!', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 5, 'Jadi bagaimana sekarang, apakah Ia yang menganugerahkan Roh kepada kamu dengan berlimpah-limpah dan yang melakukan mujizat di antara kamu, berbuat demikian karena kamu melakukan hukum Taurat atau karena kamu percaya kepada pemberitaan Injil?', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 6, 'Secara itu jugalah Abraham percaya kepada Allah, maka Allah memperhitungkan hal itu kepadanya sebagai kebenaran.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 7, 'Jadi kamu lihat, bahwa mereka yang hidup dari iman, mereka itulah anak-anak Abraham.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 8, 'Dan Kitab Suci, yang sebelumnya mengetahui, bahwa Allah membenarkan orang-orang bukan Yahudi oleh karena iman, telah terlebih dahulu memberitakan Injil kepada Abraham: "Olehmu segala bangsa akan diberkati."', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 9, 'Jadi mereka yang hidup dari iman, merekalah yang diberkati bersama-sama dengan Abraham yang beriman itu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 10, 'Karena semua orang, yang hidup dari pekerjaan hukum Taurat, berada di bawah kutuk. Sebab ada tertulis: "Terkutuklah orang yang tidak setia melakukan segala sesuatu yang tertulis dalam kitab hukum Taurat."', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 11, 'Dan bahwa tidak ada orang yang dibenarkan di hadapan Allah karena melakukan hukum Taurat adalah jelas, karena: "Orang yang benar akan hidup oleh iman."', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 12, 'Tetapi dasar hukum Taurat bukanlah iman, melainkan siapa yang melakukannya, akan hidup karenanya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 13, 'Kristus telah menebus kita dari kutuk hukum Taurat dengan jalan menjadi kutuk karena kita, sebab ada tertulis: "Terkutuklah orang yang digantung pada kayu salib!"', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 14, 'Yesus Kristus telah membuat ini, supaya di dalam Dia berkat Abraham sampai kepada bangsa-bangsa lain, sehingga oleh iman kita menerima Roh yang telah dijanjikan itu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 15, 'Saudara-saudara, baiklah kupergunakan suatu contoh dari hidup sehari-hari. Suatu wasiat yang telah disahkan, sekalipun ia dari manusia, tidak dapat dibatalkan atau ditambahi oleh seorangpun.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 16, 'Adapun kepada Abraham diucapkan segala janji itu dan kepada keturunannya. Tidak dikatakan "kepada keturunan-keturunannya" seolah-olah dimaksud banyak orang, tetapi hanya satu orang: "dan kepada keturunanmu", yaitu Kristus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 17, 'Maksudku ialah: Janji yang sebelumnya telah disahkan Allah, tidak dapat dibatalkan oleh hukum Taurat, yang baru terbit empat ratus tiga puluh tahun kemudian, sehingga janji itu hilang kekuatannya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 18, 'Sebab, jikalau apa yang ditentukan Allah berasal dari hukum Taurat, ia tidak berasal dari janji; tetapi justru oleh janjilah Allah telah menganugerahkan kasih karunia-Nya kepada Abraham.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 19, 'Kalau demikian, apakah maksudnya hukum Taurat? Ia ditambahkan oleh karena pelanggaran-pelanggaran?sampai datang keturunan yang dimaksud oleh janji itu?dan ia disampaikan dengan perantaraan malaikat-malaikat ke dalam tangan seorang pengantara.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 20, 'Seorang pengantara bukan hanya mewakili satu orang saja, sedangkan Allah adalah satu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 21, 'Kalau demikian, bertentangankah hukum Taurat dengan janji-janji Allah? Sekali-kali tidak. Sebab andaikata hukum Taurat diberikan sebagai sesuatu yang dapat menghidupkan, maka memang kebenaran berasal dari hukum Taurat.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 22, 'Tetapi Kitab Suci telah mengurung segala sesuatu di bawah kekuasaan dosa, supaya oleh karena iman dalam Yesus Kristus janji itu diberikan kepada mereka yang percaya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 23, 'Sebelum iman itu datang kita berada di bawah pengawalan hukum Taurat, dan dikurung sampai iman itu telah dinyatakan.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 24, 'Jadi hukum Taurat adalah penuntun bagi kita sampai Kristus datang, supaya kita dibenarkan karena iman.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 25, 'Sekarang iman itu telah datang, karena itu kita tidak berada lagi di bawah pengawasan penuntun.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 26, 'Sebab kamu semua adalah anak-anak Allah karena iman di dalam Yesus Kristus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 27, 'Karena kamu semua, yang dibaptis dalam Kristus, telah mengenakan Kristus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 28, 'Dalam hal ini tidak ada orang Yahudi atau orang Yunani, tidak ada hamba atau orang merdeka, tidak ada laki-laki atau perempuan, karena kamu semua adalah satu di dalam Kristus Yesus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 3, 29, 'Dan jikalau kamu adalah milik Kristus, maka kamu juga adalah keturunan Abraham dan berhak menerima janji Allah.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 1, 'Yang dimaksud ialah: selama seorang ahli waris belum akil balig, sedikitpun ia tidak berbeda dengan seorang hamba, sungguhpun ia adalah tuan dari segala sesuatu;', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 2, 'tetapi ia berada di bawah perwalian dan pengawasan sampai pada saat yang telah ditentukan oleh bapanya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 3, 'Demikian pula kita: selama kita belum akil balig, kita takluk juga kepada roh-roh dunia.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 4, 'Tetapi setelah genap waktunya, maka Allah mengutus Anak-Nya, yang lahir dari seorang perempuan dan takluk kepada hukum Taurat.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 5, 'Ia diutus untuk menebus mereka, yang takluk kepada hukum Taurat, supaya kita diterima menjadi anak.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 6, 'Dan karena kamu adalah anak, maka Allah telah menyuruh Roh Anak-Nya ke dalam hati kita, yang berseru: "ya Abba, ya Bapa!"', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 7, 'Jadi kamu bukan lagi hamba, melainkan anak; jikalau kamu anak, maka kamu juga adalah ahli-ahli waris, oleh Allah.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 8, 'Dahulu, ketika kamu tidak mengenal Allah, kamu memperhambakan diri kepada allah-allah yang pada hakekatnya bukan Allah.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 9, 'Tetapi sekarang sesudah kamu mengenal Allah, atau lebih baik, sesudah kamu dikenal Allah, bagaimanakah kamu berbalik lagi kepada roh-roh dunia yang lemah dan miskin dan mau mulai memperhambakan diri lagi kepadanya?', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 10, 'Kamu dengan teliti memelihara hari-hari tertentu, bulan-bulan, masa-masa yang tetap dan tahun-tahun.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 11, 'Aku kuatir kalau-kalau susah payahku untuk kamu telah sia-sia.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 12, 'Aku minta kepadamu, saudara-saudara, jadilah sama seperti aku, sebab akupun telah menjadi sama seperti kamu. Belum pernah kualami sesuatu yang tidak baik dari padamu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 13, 'Kamu tahu, bahwa aku pertama kali telah memberitakan Injil kepadamu oleh karena aku sakit pada tubuhku.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 14, 'Sungguhpun demikian keadaan tubuhku itu, yang merupakan pencobaan bagi kamu, namun kamu tidak menganggapnya sebagai sesuatu yang hina dan yang menjijikkan, tetapi kamu telah menyambut aku, sama seperti menyambut seorang malaikat Allah, malahan sama seperti menyambut Kristus Yesus sendiri.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 15, 'Betapa bahagianya kamu pada waktu itu! Dan sekarang, di manakah bahagiamu itu? Karena aku dapat bersaksi tentang kamu, bahwa jika mungkin, kamu telah mencungkil matamu dan memberikannya kepadaku.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 16, 'Apakah dengan mengatakan kebenaran kepadamu aku telah menjadi musuhmu?', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 17, 'Mereka dengan giat berusaha untuk menarik kamu, tetapi tidak dengan tulus hati, karena mereka mau mengucilkan kamu, supaya kamu dengan giat mengikuti mereka.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 18, 'Memang baik kalau orang dengan giat berusaha menarik orang lain dalam perkara-perkara yang baik, asal pada setiap waktu dan bukan hanya bila aku ada di antaramu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 19, 'Hai anak-anakku, karena kamu aku menderita sakit bersalin lagi, sampai rupa Kristus menjadi nyata di dalam kamu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 20, 'Betapa rinduku untuk berada di antara kamu pada saat ini dan dapat berbicara dengan suara yang lain, karena aku telah habis akal menghadapi kamu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 21, 'Katakanlah kepadaku, hai kamu yang mau hidup di bawah hukum Taurat, tidakkah kamu mendengarkan hukum Taurat?', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 22, 'Bukankah ada tertulis, bahwa Abraham mempunyai dua anak, seorang dari perempuan yang menjadi hambanya dan seorang dari perempuan yang merdeka?', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 23, 'Tetapi anak dari perempuan yang menjadi hambanya itu diperanakkan menurut daging dan anak dari perempuan yang merdeka itu oleh karena janji.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 24, 'Ini adalah suatu kiasan. Sebab kedua perempuan itu adalah dua ketentuan Allah: yang satu berasal dari gunung Sinai dan melahirkan anak-anak perhambaan, itulah Hagar?', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 25, 'Hagar ialah gunung Sinai di tanah Arab?dan ia sama dengan Yerusalem yang sekarang, karena ia hidup dalam perhambaan dengan anak-anaknya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 26, 'Tetapi Yerusalem sorgawi adalah perempuan yang merdeka, dan ialah ibu kita.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 27, 'Karena ada tertulis: "Bersukacitalah, hai si mandul yang tidak pernah melahirkan! Bergembira dan bersorak-sorailah, hai engkau yang tidak pernah menderita sakit bersalin! Sebab yang ditinggalkan suaminya akan mempunyai lebih banyak anak dari pada yang bersuami."', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 28, 'Dan kamu, saudara-saudara, kamu sama seperti Ishak adalah anak-anak janji.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 29, 'Tetapi seperti dahulu, dia, yang diperanakkan menurut daging, menganiaya yang diperanakkan menurut Roh, demikian juga sekarang ini.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 30, 'Tetapi apa kata nas Kitab Suci? "Usirlah hamba perempuan itu beserta anaknya, sebab anak hamba perempuan itu tidak akan menjadi ahli waris bersama-sama dengan anak perempuan merdeka itu."', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 4, 31, 'Karena itu, saudara-saudara, kita bukanlah anak-anak hamba perempuan, melainkan anak-anak perempuan merdeka.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 1, 'Supaya kita sungguh-sungguh merdeka, Kristus telah memerdekakan kita. Karena itu berdirilah teguh dan jangan mau lagi dikenakan kuk perhambaan.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 2, 'Sesungguhnya, aku, Paulus, berkata kepadamu: jikalau kamu menyunatkan dirimu, Kristus sama sekali tidak akan berguna bagimu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 3, 'Sekali lagi aku katakan kepada setiap orang yang menyunatkan dirinya, bahwa ia wajib melakukan seluruh hukum Taurat.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 4, 'Kamu lepas dari Kristus, jikalau kamu mengharapkan kebenaran oleh hukum Taurat; kamu hidup di luar kasih karunia.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 5, 'Sebab oleh Roh, dan karena iman, kita menantikan kebenaran yang kita harapkan.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 6, 'Sebab bagi orang-orang yang ada di dalam Kristus Yesus hal bersunat atau tidak bersunat tidak mempunyai sesuatu arti, hanya iman yang bekerja oleh kasih.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 7, 'Dahulu kamu berlomba dengan baik. Siapakah yang menghalang-halangi kamu, sehingga kamu tidak menuruti kebenaran lagi?', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 8, 'Ajakan untuk tidak menurutinya lagi bukan datang dari Dia, yang memanggil kamu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 9, 'Sedikit ragi sudah mengkhamirkan seluruh adonan.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 10, 'Dalam Tuhan aku yakin tentang kamu, bahwa kamu tidak mempunyai pendirian lain dari pada pendirian ini. Tetapi barangsiapa yang mengacaukan kamu, ia akan menanggung hukumannya, siapapun juga dia.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 11, 'Dan lagi aku ini, saudara-saudara, jikalau aku masih memberitakan sunat, mengapakah aku masih dianiaya juga? Sebab kalau demikian, salib bukan batu sandungan lagi.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 12, 'Baiklah mereka yang menghasut kamu itu mengebirikan saja dirinya!', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 13, 'Saudara-saudara, memang kamu telah dipanggil untuk merdeka. Tetapi janganlah kamu mempergunakan kemerdekaan itu sebagai kesempatan untuk kehidupan dalam dosa, melainkan layanilah seorang akan yang lain oleh kasih.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 14, 'Sebab seluruh hukum Taurat tercakup dalam satu firman ini, yaitu: "Kasihilah sesamamu manusia seperti dirimu sendiri!"', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 15, 'Tetapi jikalau kamu saling menggigit dan saling menelan, awaslah, supaya jangan kamu saling membinasakan.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 16, 'Maksudku ialah: hiduplah oleh Roh, maka kamu tidak akan menuruti keinginan daging.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 17, 'Sebab keinginan daging berlawanan dengan keinginan Roh dan keinginan Roh berlawanan dengan keinginan daging?karena keduanya bertentangan?sehingga kamu setiap kali tidak melakukan apa yang kamu kehendaki.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 18, 'Akan tetapi jikalau kamu memberi dirimu dipimpin oleh Roh, maka kamu tidak hidup di bawah hukum Taurat.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 19, 'Perbuatan daging telah nyata, yaitu: percabulan, kecemaran, hawa nafsu,', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 20, 'penyembahan berhala, sihir, perseteruan, perselisihan, iri hati, amarah, kepentingan diri sendiri, percideraan, roh pemecah,', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 21, 'kedengkian, kemabukan, pesta pora dan sebagainya. Terhadap semuanya itu kuperingatkan kamu?seperti yang telah kubuat dahulu?bahwa barangsiapa melakukan hal-hal yang demikian, ia tidak akan mendapat bagian dalam Kerajaan Allah.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 22, 'Tetapi buah Roh ialah: kasih, sukacita, damai sejahtera, kesabaran, kemurahan, kebaikan, kesetiaan,', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 23, 'kelemahlembutan, penguasaan diri. Tidak ada hukum yang menentang hal-hal itu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 24, 'Barangsiapa menjadi milik Kristus Yesus, ia telah menyalibkan daging dengan segala hawa nafsu dan keinginannya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 25, 'Jikalau kita hidup oleh Roh, baiklah hidup kita juga dipimpin oleh Roh,', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 5, 26, 'dan janganlah kita gila hormat, janganlah kita saling menantang dan saling mendengki.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 1, 'Saudara-saudara, kalaupun seorang kedapatan melakukan suatu pelanggaran, maka kamu yang rohani, harus memimpin orang itu ke jalan yang benar dalam roh lemah lembut, sambil menjaga dirimu sendiri, supaya kamu juga jangan kena pencobaan.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 2, 'Bertolong-tolonganlah menanggung bebanmu! Demikianlah kamu memenuhi hukum Kristus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 3, 'Sebab kalau seorang menyangka, bahwa ia berarti, padahal ia sama sekali tidak berarti, ia menipu dirinya sendiri.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 4, 'Baiklah tiap-tiap orang menguji pekerjaannya sendiri; maka ia boleh bermegah melihat keadaannya sendiri dan bukan melihat keadaan orang lain.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 5, 'Sebab tiap-tiap orang akan memikul tanggungannya sendiri.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 6, 'Dan baiklah dia, yang menerima pengajaran dalam Firman, membagi segala sesuatu yang ada padanya dengan orang yang memberikan pengajaran itu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 7, 'Jangan sesat! Allah tidak membiarkan diri-Nya dipermainkan. Karena apa yang ditabur orang, itu juga yang akan dituainya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 8, 'Sebab barangsiapa menabur dalam dagingnya, ia akan menuai kebinasaan dari dagingnya, tetapi barangsiapa menabur dalam Roh, ia akan menuai hidup yang kekal dari Roh itu.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 9, 'Janganlah kita jemu-jemu berbuat baik, karena apabila sudah datang waktunya, kita akan menuai, jika kita tidak menjadi lemah.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 10, 'Karena itu, selama masih ada kesempatan bagi kita, marilah kita berbuat baik kepada semua orang, tetapi terutama kepada kawan-kawan kita seiman.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 11, 'Lihatlah, bagaimana besarnya huruf-huruf yang kutulis kepadamu dengan tanganku sendiri.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 12, 'Mereka yang secara lahiriah suka menonjolkan diri, merekalah yang berusaha memaksa kamu untuk bersunat, hanya dengan maksud, supaya mereka tidak dianiaya karena salib Kristus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 13, 'Sebab mereka yang menyunatkan dirinyapun, tidak memelihara hukum Taurat. Tetapi mereka menghendaki, supaya kamu menyunatkan diri, agar mereka dapat bermegah atas keadaanmu yang lahiriah.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 14, 'Tetapi aku sekali-kali tidak mau bermegah, selain dalam salib Tuhan kita Yesus Kristus, sebab olehnya dunia telah disalibkan bagiku dan aku bagi dunia.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 15, 'Sebab bersunat atau tidak bersunat tidak ada artinya, tetapi menjadi ciptaan baru, itulah yang ada artinya.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 16, 'Dan semua orang, yang memberi dirinya dipimpin oleh patokan ini, turunlah kiranya damai sejahtera dan rahmat atas mereka dan atas Israel milik Allah.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 17, 'Selanjutnya janganlah ada orang yang menyusahkan aku, karena pada tubuhku ada tanda-tanda milik Yesus.', 'id', 'TB'),
  ('48', 'gal', 'Galatia', 6, 18, 'Kasih karunia Tuhan kita Yesus Kristus menyertai roh kamu, saudara-saudara! Amin.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 1, 'Dari Paulus, rasul Kristus Yesus oleh kehendak Allah, kepada orang-orang kudus di Efesus, orang-orang percaya dalam Kristus Yesus.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 2, 'Kasih karunia dan damai sejahtera dari Allah, Bapa kita dan dari Tuhan Yesus Kristus menyertai kamu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 3, 'Terpujilah Allah dan Bapa Tuhan kita Yesus Kristus yang dalam Kristus telah mengaruniakan kepada kita segala berkat rohani di dalam sorga.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 4, 'Sebab di dalam Dia Allah telah memilih kita sebelum dunia dijadikan, supaya kita kudus dan tak bercacat di hadapan-Nya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 5, 'Dalam kasih Ia telah menentukan kita dari semula oleh Yesus Kristus untuk menjadi anak-anak-Nya, sesuai dengan kerelaan kehendak-Nya,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 6, 'supaya terpujilah kasih karunia-Nya yang mulia, yang dikaruniakan-Nya kepada kita di dalam Dia, yang dikasihi-Nya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 7, 'Sebab di dalam Dia dan oleh darah-Nya kita beroleh penebusan, yaitu pengampunan dosa, menurut kekayaan kasih karunia-Nya,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 8, 'yang dilimpahkan-Nya kepada kita dalam segala hikmat dan pengertian.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 9, 'Sebab Ia telah menyatakan rahasia kehendak-Nya kepada kita, sesuai dengan rencana kerelaan-Nya, yaitu rencana kerelaan yang dari semula telah ditetapkan-Nya di dalam Kristus', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 10, 'sebagai persiapan kegenapan waktu untuk mempersatukan di dalam Kristus sebagai Kepala segala sesuatu, baik yang di sorga maupun yang di bumi.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 11, 'Aku katakan "di dalam Kristus", karena di dalam Dialah kami mendapat bagian yang dijanjikan?kami yang dari semula ditentukan untuk menerima bagian itu sesuai dengan maksud Allah, yang di dalam segala sesuatu bekerja menurut keputusan kehendak-Nya?', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 12, 'supaya kami, yang sebelumnya telah menaruh harapan pada Kristus, boleh menjadi puji-pujian bagi kemuliaan-Nya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 13, 'Di dalam Dia kamu juga?karena kamu telah mendengar firman kebenaran, yaitu Injil keselamatanmu?di dalam Dia kamu juga, ketika kamu percaya, dimeteraikan dengan Roh Kudus, yang dijanjikan-Nya itu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 14, 'Dan Roh Kudus itu adalah jaminan bagian kita sampai kita memperoleh seluruhnya, yaitu penebusan yang menjadikan kita milik Allah, untuk memuji kemuliaan-Nya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 15, 'Karena itu, setelah aku mendengar tentang imanmu dalam Tuhan Yesus dan tentang kasihmu terhadap semua orang kudus,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 16, 'akupun tidak berhenti mengucap syukur karena kamu. Dan aku selalu mengingat kamu dalam doaku,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 17, 'dan meminta kepada Allah Tuhan kita Yesus Kristus, yaitu Bapa yang mulia itu, supaya Ia memberikan kepadamu Roh hikmat dan wahyu untuk mengenal Dia dengan benar.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 18, 'Dan supaya Ia menjadikan mata hatimu terang, agar kamu mengerti pengharapan apakah yang terkandung dalam panggilan-Nya: betapa kayanya kemuliaan bagian yang ditentukan-Nya bagi orang-orang kudus,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 19, 'dan betapa hebat kuasa-Nya bagi kita yang percaya, sesuai dengan kekuatan kuasa-Nya,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 20, 'yang dikerjakan-Nya di dalam Kristus dengan membangkitkan Dia dari antara orang mati dan mendudukkan Dia di sebelah kanan-Nya di sorga,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 21, 'jauh lebih tinggi dari segala pemerintah dan penguasa dan kekuasaan dan kerajaan dan tiap-tiap nama yang dapat disebut, bukan hanya di dunia ini saja, melainkan juga di dunia yang akan datang.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 22, 'Dan segala sesuatu telah diletakkan-Nya di bawah kaki Kristus dan Dia telah diberikan-Nya kepada jemaat sebagai Kepala dari segala yang ada.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 1, 23, 'Jemaat yang adalah tubuh-Nya, yaitu kepenuhan Dia, yang memenuhi semua dan segala sesuatu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 1, 'Kamu dahulu sudah mati karena pelanggaran-pelanggaran dan dosa-dosamu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 2, 'Kamu hidup di dalamnya, karena kamu mengikuti jalan dunia ini, karena kamu mentaati penguasa kerajaan angkasa, yaitu roh yang sekarang sedang bekerja di antara orang-orang durhaka.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 3, 'Sebenarnya dahulu kami semua juga terhitung di antara mereka, ketika kami hidup di dalam hawa nafsu daging dan menuruti kehendak daging dan pikiran kami yang jahat. Pada dasarnya kami adalah orang-orang yang harus dimurkai, sama seperti mereka yang lain.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 4, 'Tetapi Allah yang kaya dengan rahmat, oleh karena kasih-Nya yang besar, yang dilimpahkan-Nya kepada kita,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 5, 'telah menghidupkan kita bersama-sama dengan Kristus, sekalipun kita telah mati oleh kesalahan-kesalahan kita?oleh kasih karunia kamu diselamatkan?', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 6, 'dan di dalam Kristus Yesus Ia telah membangkitkan kita juga dan memberikan tempat bersama-sama dengan Dia di sorga,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 7, 'supaya pada masa yang akan datang Ia menunjukkan kepada kita kekayaan kasih karunia-Nya yang melimpah-limpah sesuai dengan kebaikan-Nya terhadap kita dalam Kristus Yesus.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 8, 'Sebab karena kasih karunia kamu diselamatkan oleh iman; itu bukan hasil usahamu, tetapi pemberian Allah,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 9, 'itu bukan hasil pekerjaanmu: jangan ada orang yang memegahkan diri.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 10, 'Karena kita ini buatan Allah, diciptakan dalam Kristus Yesus untuk melakukan pekerjaan baik, yang dipersiapkan Allah sebelumnya. Ia mau, supaya kita hidup di dalamnya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 11, 'Karena itu ingatlah, bahwa dahulu kamu?sebagai orang-orang bukan Yahudi menurut daging, yang disebut orang-orang tak bersunat oleh mereka yang menamakan dirinya "sunat", yaitu sunat lahiriah yang dikerjakan oleh tangan manusia, ?', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 12, 'bahwa waktu itu kamu tanpa Kristus, tidak termasuk kewargaan Israel dan tidak mendapat bagian dalam ketentuan-ketentuan yang dijanjikan, tanpa pengharapan dan tanpa Allah di dalam dunia.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 13, 'Tetapi sekarang di dalam Kristus Yesus kamu, yang dahulu "jauh", sudah menjadi "dekat" oleh darah Kristus.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 14, 'Karena Dialah damai sejahtera kita, yang telah mempersatukan kedua pihak dan yang telah merubuhkan tembok pemisah, yaitu perseteruan,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 15, 'sebab dengan mati-Nya sebagai manusia Ia telah membatalkan hukum Taurat dengan segala perintah dan ketentuannya, untuk menciptakan keduanya menjadi satu manusia baru di dalam diri-Nya, dan dengan itu mengadakan damai sejahtera,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 16, 'dan untuk memperdamaikan keduanya, di dalam satu tubuh, dengan Allah oleh salib, dengan melenyapkan perseteruan pada salib itu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 17, 'Ia datang dan memberitakan damai sejahtera kepada kamu yang "jauh" dan damai sejahtera kepada mereka yang "dekat",', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 18, 'karena oleh Dia kita kedua pihak dalam satu Roh beroleh jalan masuk kepada Bapa.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 19, 'Demikianlah kamu bukan lagi orang asing dan pendatang, melainkan kawan sewarga dari orang-orang kudus dan anggota-anggota keluarga Allah,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 20, 'yang dibangun di atas dasar para rasul dan para nabi, dengan Kristus Yesus sebagai batu penjuru.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 21, 'Di dalam Dia tumbuh seluruh bangunan, rapih tersusun, menjadi bait Allah yang kudus, di dalam Tuhan.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 2, 22, 'Di dalam Dia kamu juga turut dibangunkan menjadi tempat kediaman Allah, di dalam Roh.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 1, 'Itulah sebabnya aku ini, Paulus, orang yang dipenjarakan karena Kristus Yesus untuk kamu orang-orang yang tidak mengenal Allah', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 2, '?memang kamu telah mendengar tentang tugas penyelenggaraan kasih karunia Allah, yang dipercayakan kepadaku karena kamu,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 3, 'yaitu bagaimana rahasianya dinyatakan kepadaku dengan wahyu, seperti yang telah kutulis di atas dengan singkat.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 4, 'Apabila kamu membacanya, kamu dapat mengetahui dari padanya pengertianku akan rahasia Kristus,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 5, 'yang pada zaman angkatan-angkatan dahulu tidak diberitakan kepada anak-anak manusia, tetapi yang sekarang dinyatakan di dalam Roh kepada rasul-rasul dan nabi-nabi-Nya yang kudus,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 6, 'yaitu bahwa orang-orang bukan Yahudi, karena Berita Injil, turut menjadi ahli-ahli waris dan anggota-anggota tubuh dan peserta dalam janji yang diberikan dalam Kristus Yesus.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 7, 'Dari Injil itu aku telah menjadi pelayannya menurut pemberian kasih karunia Allah, yang dianugerahkan kepadaku sesuai dengan pengerjaan kuasa-Nya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 8, 'Kepadaku, yang paling hina di antara segala orang kudus, telah dianugerahkan kasih karunia ini, untuk memberitakan kepada orang-orang bukan Yahudi kekayaan Kristus, yang tidak terduga itu,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 9, 'dan untuk menyatakan apa isinya tugas penyelenggaraan rahasia yang telah berabad-abad tersembunyi dalam Allah, yang menciptakan segala sesuatu,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 10, 'supaya sekarang oleh jemaat diberitahukan pelbagai ragam hikmat Allah kepada pemerintah-pemerintah dan penguasa-penguasa di sorga,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 11, 'sesuai dengan maksud abadi, yang telah dilaksanakan-Nya dalam Kristus Yesus, Tuhan kita.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 12, 'Di dalam Dia kita beroleh keberanian dan jalan masuk kepada Allah dengan penuh kepercayaan oleh iman kita kepada-Nya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 13, 'Sebab itu aku minta kepadamu, supaya kamu jangan tawar hati melihat kesesakanku karena kamu, karena kesesakanku itu adalah kemuliaanmu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 14, 'Itulah sebabnya aku sujud kepada Bapa,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 15, 'yang dari pada-Nya semua turunan yang di dalam sorga dan di atas bumi menerima namanya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 16, 'Aku berdoa supaya Ia, menurut kekayaan kemuliaan-Nya, menguatkan dan meneguhkan kamu oleh Roh-Nya di dalam batinmu,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 17, 'sehingga oleh imanmu Kristus diam di dalam hatimu dan kamu berakar serta berdasar di dalam kasih.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 18, 'Aku berdoa, supaya kamu bersama-sama dengan segala orang kudus dapat memahami, betapa lebarnya dan panjangnya dan tingginya dan dalamnya kasih Kristus,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 19, 'dan dapat mengenal kasih itu, sekalipun ia melampaui segala pengetahuan. Aku berdoa, supaya kamu dipenuhi di dalam seluruh kepenuhan Allah.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 20, 'Bagi Dialah, yang dapat melakukan jauh lebih banyak dari pada yang kita doakan atau pikirkan, seperti yang ternyata dari kuasa yang bekerja di dalam kita,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 3, 21, 'bagi Dialah kemuliaan di dalam jemaat dan di dalam Kristus Yesus turun-temurun sampai selama-lamanya. Amin.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 1, 'Sebab itu aku menasihatkan kamu, aku, orang yang dipenjarakan karena Tuhan, supaya hidupmu sebagai orang-orang yang telah dipanggil berpadanan dengan panggilan itu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 2, 'Hendaklah kamu selalu rendah hati, lemah lembut, dan sabar. Tunjukkanlah kasihmu dalam hal saling membantu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 3, 'Dan berusahalah memelihara kesatuan Roh oleh ikatan damai sejahtera:', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 4, 'satu tubuh, dan satu Roh, sebagaimana kamu telah dipanggil kepada satu pengharapan yang terkandung dalam panggilanmu,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 5, 'satu Tuhan, satu iman, satu baptisan,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 6, 'satu Allah dan Bapa dari semua, Allah yang di atas semua dan oleh semua dan di dalam semua.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 7, 'Tetapi kepada kita masing-masing telah dianugerahkan kasih karunia menurut ukuran pemberian Kristus.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 8, 'Itulah sebabnya kata nas: "Tatkala Ia naik ke tempat tinggi, Ia membawa tawanan-tawanan; Ia memberikan pemberian-pemberian kepada manusia."', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 9, 'Bukankah "Ia telah naik" berarti, bahwa Ia juga telah turun ke bagian bumi yang paling bawah?', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 10, 'Ia yang telah turun, Ia juga yang telah naik jauh lebih tinggi dari pada semua langit, untuk memenuhkan segala sesuatu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 11, 'Dan Ialah yang memberikan baik rasul-rasul maupun nabi-nabi, baik pemberita-pemberita Injil maupun gembala-gembala dan pengajar-pengajar,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 12, 'untuk memperlengkapi orang-orang kudus bagi pekerjaan pelayanan, bagi pembangunan tubuh Kristus,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 13, 'sampai kita semua telah mencapai kesatuan iman dan pengetahuan yang benar tentang Anak Allah, kedewasaan penuh, dan tingkat pertumbuhan yang sesuai dengan kepenuhan Kristus,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 14, 'sehingga kita bukan lagi anak-anak, yang diombang-ambingkan oleh rupa-rupa angin pengajaran, oleh permainan palsu manusia dalam kelicikan mereka yang menyesatkan,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 15, 'tetapi dengan teguh berpegang kepada kebenaran di dalam kasih kita bertumbuh di dalam segala hal ke arah Dia, Kristus, yang adalah Kepala.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 16, 'Dari pada-Nyalah seluruh tubuh, ?yang rapih tersusun dan diikat menjadi satu oleh pelayanan semua bagiannya, sesuai dengan kadar pekerjaan tiap-tiap anggota?menerima pertumbuhannya dan membangun dirinya dalam kasih.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 17, 'Sebab itu kukatakan dan kutegaskan ini kepadamu di dalam Tuhan: Jangan hidup lagi sama seperti orang-orang yang tidak mengenal Allah dengan pikirannya yang sia-sia', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 18, 'dan pengertiannya yang gelap, jauh dari hidup persekutuan dengan Allah, karena kebodohan yang ada di dalam mereka dan karena kedegilan hati mereka.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 19, 'Perasaan mereka telah tumpul, sehingga mereka menyerahkan diri kepada hawa nafsu dan mengerjakan dengan serakah segala macam kecemaran.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 20, 'Tetapi kamu bukan demikian. Kamu telah belajar mengenal Kristus.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 21, 'Karena kamu telah mendengar tentang Dia dan menerima pengajaran di dalam Dia menurut kebenaran yang nyata dalam Yesus,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 22, 'yaitu bahwa kamu, berhubung dengan kehidupan kamu yang dahulu, harus menanggalkan manusia lama, yang menemui kebinasaannya oleh nafsunya yang menyesatkan,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 23, 'supaya kamu dibaharui di dalam roh dan pikiranmu,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 24, 'dan mengenakan manusia baru, yang telah diciptakan menurut kehendak Allah di dalam kebenaran dan kekudusan yang sesungguhnya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 25, 'Karena itu buanglah dusta dan berkatalah benar seorang kepada yang lain, karena kita adalah sesama anggota.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 26, 'Apabila kamu menjadi marah, janganlah kamu berbuat dosa: janganlah matahari terbenam, sebelum padam amarahmu', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 27, 'dan janganlah beri kesempatan kepada Iblis.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 28, 'Orang yang mencuri, janganlah ia mencuri lagi, tetapi baiklah ia bekerja keras dan melakukan pekerjaan yang baik dengan tangannya sendiri, supaya ia dapat membagikan sesuatu kepada orang yang berkekurangan.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 29, 'Janganlah ada perkataan kotor keluar dari mulutmu, tetapi pakailah perkataan yang baik untuk membangun, di mana perlu, supaya mereka yang mendengarnya, beroleh kasih karunia.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 30, 'Dan janganlah kamu mendukakan Roh Kudus Allah, yang telah memeteraikan kamu menjelang hari penyelamatan.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 31, 'Segala kepahitan, kegeraman, kemarahan, pertikaian dan fitnah hendaklah dibuang dari antara kamu, demikian pula segala kejahatan.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 4, 32, 'Tetapi hendaklah kamu ramah seorang terhadap yang lain, penuh kasih mesra dan saling mengampuni, sebagaimana Allah di dalam Kristus telah mengampuni kamu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 1, 'Sebab itu jadilah penurut-penurut Allah, seperti anak-anak yang kekasih', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 2, 'dan hiduplah di dalam kasih, sebagaimana Kristus Yesus juga telah mengasihi kamu dan telah menyerahkan diri-Nya untuk kita sebagai persembahan dan korban yang harum bagi Allah.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 3, 'Tetapi percabulan dan rupa-rupa kecemaran atau keserakahan disebut sajapun jangan di antara kamu, sebagaimana sepatutnya bagi orang-orang kudus.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 4, 'Demikian juga perkataan yang kotor, yang kosong atau yang sembrono?karena hal-hal ini tidak pantas?tetapi sebaliknya ucapkanlah syukur.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 5, 'Karena ingatlah ini baik-baik: tidak ada orang sundal, orang cemar atau orang serakah, artinya penyembah berhala, yang mendapat bagian di dalam Kerajaan Kristus dan Allah.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 6, 'Janganlah kamu disesatkan orang dengan kata-kata yang hampa, karena hal-hal yang demikian mendatangkan murka Allah atas orang-orang durhaka.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 7, 'Sebab itu janganlah kamu berkawan dengan mereka.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 8, 'Memang dahulu kamu adalah kegelapan, tetapi sekarang kamu adalah terang di dalam Tuhan. Sebab itu hiduplah sebagai anak-anak terang,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 9, 'karena terang hanya berbuahkan kebaikan dan keadilan dan kebenaran,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 10, 'dan ujilah apa yang berkenan kepada Tuhan.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 11, 'Janganlah turut mengambil bagian dalam perbuatan-perbuatan kegelapan yang tidak berbuahkan apa-apa, tetapi sebaliknya telanjangilah perbuatan-perbuatan itu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 12, 'Sebab menyebutkan sajapun apa yang dibuat oleh mereka di tempat-tempat yang tersembunyi telah memalukan.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 13, 'Tetapi segala sesuatu yang sudah ditelanjangi oleh terang itu menjadi nampak, sebab semua yang nampak adalah terang.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 14, 'Itulah sebabnya dikatakan: "Bangunlah, hai kamu yang tidur dan bangkitlah dari antara orang mati dan Kristus akan bercahaya atas kamu."', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 15, 'Karena itu, perhatikanlah dengan saksama, bagaimana kamu hidup, janganlah seperti orang bebal, tetapi seperti orang arif,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 16, 'dan pergunakanlah waktu yang ada, karena hari-hari ini adalah jahat.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 17, 'Sebab itu janganlah kamu bodoh, tetapi usahakanlah supaya kamu mengerti kehendak Tuhan.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 18, 'Dan janganlah kamu mabuk oleh anggur, karena anggur menimbulkan hawa nafsu, tetapi hendaklah kamu penuh dengan Roh,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 19, 'dan berkata-katalah seorang kepada yang lain dalam mazmur, kidung puji-pujian dan nyanyian rohani. Bernyanyi dan bersoraklah bagi Tuhan dengan segenap hati.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 20, 'Ucaplah syukur senantiasa atas segala sesuatu dalam nama Tuhan kita Yesus Kristus kepada Allah dan Bapa kita', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 21, 'dan rendahkanlah dirimu seorang kepada yang lain di dalam takut akan Kristus.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 22, 'Hai isteri, tunduklah kepada suamimu seperti kepada Tuhan,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 23, 'karena suami adalah kepala isteri sama seperti Kristus adalah kepala jemaat. Dialah yang menyelamatkan tubuh.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 24, 'Karena itu sebagaimana jemaat tunduk kepada Kristus, demikian jugalah isteri kepada suami dalam segala sesuatu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 25, 'Hai suami, kasihilah isterimu sebagaimana Kristus telah mengasihi jemaat dan telah menyerahkan diri-Nya baginya', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 26, 'untuk menguduskannya, sesudah Ia menyucikannya dengan memandikannya dengan air dan firman,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 27, 'supaya dengan demikian Ia menempatkan jemaat di hadapan diri-Nya dengan cemerlang tanpa cacat atau kerut atau yang serupa itu, tetapi supaya jemaat kudus dan tidak bercela.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 28, 'Demikian juga suami harus mengasihi isterinya sama seperti tubuhnya sendiri: Siapa yang mengasihi isterinya mengasihi dirinya sendiri.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 29, 'Sebab tidak pernah orang membenci tubuhnya sendiri, tetapi mengasuhnya dan merawatinya, sama seperti Kristus terhadap jemaat,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 30, 'karena kita adalah anggota tubuh-Nya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 31, 'Sebab itu laki-laki akan meninggalkan ayahnya dan ibunya dan bersatu dengan isterinya, sehingga keduanya itu menjadi satu daging.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 32, 'Rahasia ini besar, tetapi yang aku maksudkan ialah hubungan Kristus dan jemaat.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 5, 33, 'Bagaimanapun juga, bagi kamu masing-masing berlaku: kasihilah isterimu seperti dirimu sendiri dan isteri hendaklah menghormati suaminya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 1, 'Hai anak-anak, taatilah orang tuamu di dalam Tuhan, karena haruslah demikian.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 2, 'Hormatilah ayahmu dan ibumu?ini adalah suatu perintah yang penting, seperti yang nyata dari janji ini:', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 3, 'supaya kamu berbahagia dan panjang umurmu di bumi.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 4, 'Dan kamu, bapa-bapa, janganlah bangkitkan amarah di dalam hati anak-anakmu, tetapi didiklah mereka di dalam ajaran dan nasihat Tuhan.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 5, 'Hai hamba-hamba, taatilah tuanmu yang di dunia dengan takut dan gentar, dan dengan tulus hati, sama seperti kamu taat kepada Kristus,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 6, 'jangan hanya di hadapan mereka saja untuk menyenangkan hati orang, tetapi sebagai hamba-hamba Kristus yang dengan segenap hati melakukan kehendak Allah,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 7, 'dan yang dengan rela menjalankan pelayanannya seperti orang-orang yang melayani Tuhan dan bukan manusia.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 8, 'Kamu tahu, bahwa setiap orang, baik hamba, maupun orang merdeka, kalau ia telah berbuat sesuatu yang baik, ia akan menerima balasannya dari Tuhan.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 9, 'Dan kamu tuan-tuan, perbuatlah demikian juga terhadap mereka dan jauhkanlah ancaman. Ingatlah, bahwa Tuhan mereka dan Tuhan kamu ada di sorga dan Ia tidak memandang muka.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 10, 'Akhirnya, hendaklah kamu kuat di dalam Tuhan, di dalam kekuatan kuasa-Nya.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 11, 'Kenakanlah seluruh perlengkapan senjata Allah, supaya kamu dapat bertahan melawan tipu muslihat Iblis;', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 12, 'karena perjuangan kita bukanlah melawan darah dan daging, tetapi melawan pemerintah-pemerintah, melawan penguasa-penguasa, melawan penghulu-penghulu dunia yang gelap ini, melawan roh-roh jahat di udara.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 13, 'Sebab itu ambillah seluruh perlengkapan senjata Allah, supaya kamu dapat mengadakan perlawanan pada hari yang jahat itu dan tetap berdiri, sesudah kamu menyelesaikan segala sesuatu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 14, 'Jadi berdirilah tegap, berikatpinggangkan kebenaran dan berbajuzirahkan keadilan,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 15, 'kakimu berkasutkan kerelaan untuk memberitakan Injil damai sejahtera;', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 16, 'dalam segala keadaan pergunakanlah perisai iman, sebab dengan perisai itu kamu akan dapat memadamkan semua panah api dari si jahat,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 17, 'dan terimalah ketopong keselamatan dan pedang Roh, yaitu firman Allah,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 18, 'dalam segala doa dan permohonan. Berdoalah setiap waktu di dalam Roh dan berjaga-jagalah di dalam doamu itu dengan permohonan yang tak putus-putusnya untuk segala orang Kudus,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 19, 'juga untuk aku, supaya kepadaku, jika aku membuka mulutku, dikaruniakan perkataan yang benar, agar dengan keberanian aku memberitakan rahasia Injil,', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 20, 'yang kulayani sebagai utusan yang dipenjarakan. Berdoalah supaya dengan keberanian aku menyatakannya, sebagaimana seharusnya aku berbicara.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 21, 'Supaya kamu juga mengetahui keadaan dan hal ihwalku, maka Tikhikus, saudara kita yang kekasih dan pelayan yang setia di dalam Tuhan, akan memberitahukan semuanya kepada kamu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 22, 'Dengan maksud inilah ia kusuruh kepadamu, yaitu supaya kamu tahu hal ihwal kami dan supaya ia menghibur hatimu.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 23, 'Damai sejahtera dan kasih dengan iman dari Allah, Bapa dan dari Tuhan Yesus Kristus menyertai sekalian saudara.', 'id', 'TB'),
  ('49', 'ef', 'Efesus', 6, 24, 'Kasih karunia menyertai semua orang, yang mengasihi Tuhan kita Yesus Kristus dengan kasih yang tidak binasa.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 1, 'Dari Paulus dan Timotius, hamba-hamba Kristus Yesus, kepada semua orang kudus dalam Kristus Yesus di Filipi, dengan para penilik jemaat dan diaken.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 2, 'Kasih karunia dan damai sejahtera dari Allah, Bapa kita, dan dari Tuhan Yesus Kristus menyertai kamu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 3, 'Aku mengucap syukur kepada Allahku setiap kali aku mengingat kamu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 4, 'Dan setiap kali aku berdoa untuk kamu semua, aku selalu berdoa dengan sukacita.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 5, 'Aku mengucap syukur kepada Allahku karena persekutuanmu dalam Berita Injil mulai dari hari pertama sampai sekarang ini.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 6, 'Akan hal ini aku yakin sepenuhnya, yaitu Ia, yang memulai pekerjaan yang baik di antara kamu, akan meneruskannya sampai pada akhirnya pada hari Kristus Yesus.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 7, 'Memang sudahlah sepatutnya aku berpikir demikian akan kamu semua, sebab kamu ada di dalam hatiku, oleh karena kamu semua turut mendapat bagian dalam kasih karunia yang diberikan kepadaku, baik pada waktu aku dipenjarakan, maupun pada waktu aku membela dan meneguhkan Berita Injil.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 8, 'Sebab Allah adalah saksiku betapa aku dengan kasih mesra Kristus Yesus merindukan kamu sekalian.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 9, 'Dan inilah doaku, semoga kasihmu makin melimpah dalam pengetahuan yang benar dan dalam segala macam pengertian,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 10, 'sehingga kamu dapat memilih apa yang baik, supaya kamu suci dan tak bercacat menjelang hari Kristus,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 11, 'penuh dengan buah kebenaran yang dikerjakan oleh Yesus Kristus untuk memuliakan dan memuji Allah.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 12, 'Aku menghendaki, saudara-saudara, supaya kamu tahu, bahwa apa yang terjadi atasku ini justru telah menyebabkan kemajuan Injil,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 13, 'sehingga telah jelas bagi seluruh istana dan semua orang lain, bahwa aku dipenjarakan karena Kristus.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 14, 'Dan kebanyakan saudara dalam Tuhan telah beroleh kepercayaan karena pemenjaraanku untuk bertambah berani berkata-kata tentang firman Allah dengan tidak takut.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 15, 'Ada orang yang memberitakan Kristus karena dengki dan perselisihan, tetapi ada pula yang memberitakan-Nya dengan maksud baik.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 16, 'Mereka ini memberitakan Kristus karena kasih, sebab mereka tahu, bahwa aku ada di sini untuk membela Injil,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 17, 'tetapi yang lain karena kepentingan sendiri dan dengan maksud yang tidak ikhlas, sangkanya dengan demikian mereka memperberat bebanku dalam penjara.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 18, 'Tetapi tidak mengapa, sebab bagaimanapun juga, Kristus diberitakan, baik dengan maksud palsu maupun dengan jujur. Tentang hal itu aku bersukacita. Dan aku akan tetap bersukacita,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 19, 'karena aku tahu, bahwa kesudahan semuanya ini ialah keselamatanku oleh doamu dan pertolongan Roh Yesus Kristus.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 20, 'Sebab yang sangat kurindukan dan kuharapkan ialah bahwa aku dalam segala hal tidak akan beroleh malu, melainkan seperti sediakala, demikianpun sekarang, Kristus dengan nyata dimuliakan di dalam tubuhku, baik oleh hidupku, maupun oleh matiku.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 21, 'Karena bagiku hidup adalah Kristus dan mati adalah keuntungan.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 22, 'Tetapi jika aku harus hidup di dunia ini, itu berarti bagiku bekerja memberi buah. Jadi mana yang harus kupilih, aku tidak tahu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 23, 'Aku didesak dari dua pihak: aku ingin pergi dan diam bersama-sama dengan Kristus?itu memang jauh lebih baik;', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 24, 'tetapi lebih perlu untuk tinggal di dunia ini karena kamu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 25, 'Dan dalam keyakinan ini tahulah aku: aku akan tinggal dan akan bersama-sama lagi dengan kamu sekalian supaya kamu makin maju dan bersukacita dalam iman,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 26, 'sehingga kemegahanmu dalam Kristus Yesus makin bertambah karena aku, apabila aku kembali kepada kamu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 27, 'Hanya, hendaklah hidupmu berpadanan dengan Injil Kristus, supaya, apabila aku datang aku melihat, dan apabila aku tidak datang aku mendengar, bahwa kamu teguh berdiri dalam satu roh, dan sehati sejiwa berjuang untuk iman yang timbul dari Berita Injil,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 28, 'dengan tiada digentarkan sedikitpun oleh lawanmu. Bagi mereka semuanya itu adalah tanda kebinasaan, tetapi bagi kamu tanda keselamatan, dan itu datangnya dari Allah.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 29, 'Sebab kepada kamu dikaruniakan bukan saja untuk percaya kepada Kristus, melainkan juga untuk menderita untuk Dia,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 1, 30, 'dalam pergumulan yang sama seperti yang dahulu kamu lihat padaku, dan yang sekarang kamu dengar tentang aku.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 1, 'Jadi karena dalam Kristus ada nasihat, ada penghiburan kasih, ada persekutuan Roh, ada kasih mesra dan belas kasihan,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 2, 'karena itu sempurnakanlah sukacitaku dengan ini: hendaklah kamu sehati sepikir, dalam satu kasih, satu jiwa, satu tujuan,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 3, 'dengan tidak mencari kepentingan sendiri atau puji-pujian yang sia-sia. Sebaliknya hendaklah dengan rendah hati yang seorang menganggap yang lain lebih utama dari pada dirinya sendiri;', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 4, 'dan janganlah tiap-tiap orang hanya memperhatikan kepentingannya sendiri, tetapi kepentingan orang lain juga.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 5, 'Hendaklah kamu dalam hidupmu bersama, menaruh pikiran dan perasaan yang terdapat juga dalam Kristus Yesus,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 6, 'yang walaupun dalam rupa Allah, tidak menganggap kesetaraan dengan Allah itu sebagai milik yang harus dipertahankan,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 7, 'melainkan telah mengosongkan diri-Nya sendiri, dan mengambil rupa seorang hamba, dan menjadi sama dengan manusia.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 8, 'Dan dalam keadaan sebagai manusia, Ia telah merendahkan diri-Nya dan taat sampai mati, bahkan sampai mati di kayu salib.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 9, 'Itulah sebabnya Allah sangat meninggikan Dia dan mengaruniakan kepada-Nya nama di atas segala nama,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 10, 'supaya dalam nama Yesus bertekuk lutut segala yang ada di langit dan yang ada di atas bumi dan yang ada di bawah bumi,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 11, 'dan segala lidah mengaku: "Yesus Kristus adalah Tuhan," bagi kemuliaan Allah, Bapa!', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 12, 'Hai saudara-saudaraku yang kekasih, kamu senantiasa taat; karena itu tetaplah kerjakan keselamatanmu dengan takut dan gentar, bukan saja seperti waktu aku masih hadir, tetapi terlebih pula sekarang waktu aku tidak hadir,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 13, 'karena Allahlah yang mengerjakan di dalam kamu baik kemauan maupun pekerjaan menurut kerelaan-Nya.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 14, 'Lakukanlah segala sesuatu dengan tidak bersungut-sungut dan berbantah-bantahan,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 15, 'supaya kamu tiada beraib dan tiada bernoda, sebagai anak-anak Allah yang tidak bercela di tengah-tengah angkatan yang bengkok hatinya dan yang sesat ini, sehingga kamu bercahaya di antara mereka seperti bintang-bintang di dunia,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 16, 'sambil berpegang pada firman kehidupan, agar aku dapat bermegah pada hari Kristus, bahwa aku tidak percuma berlomba dan tidak percuma bersusah-susah.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 17, 'Tetapi sekalipun darahku dicurahkan pada korban dan ibadah imanmu, aku bersukacita dan aku bersukacita dengan kamu sekalian.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 18, 'Dan kamu juga harus bersukacita demikian dan bersukacitalah dengan aku.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 19, 'Tetapi dalam Tuhan Yesus kuharap segera mengirimkan Timotius kepadamu, supaya tenang juga hatiku oleh kabar tentang hal ihwalmu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 20, 'Karena tak ada seorang padaku, yang sehati dan sepikir dengan dia dan yang begitu bersungguh-sungguh memperhatikan kepentinganmu;', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 21, 'sebab semuanya mencari kepentingannya sendiri, bukan kepentingan Kristus Yesus.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 22, 'Kamu tahu bahwa kesetiaannya telah teruji dan bahwa ia telah menolong aku dalam pelayanan Injil sama seperti seorang anak menolong bapanya.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 23, 'Dialah yang kuharap untuk kukirimkan dengan segera, sesudah jelas bagiku bagaimana jalannya perkaraku;', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 24, 'tetapi dalam Tuhan aku percaya, bahwa aku sendiripun akan segera datang.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 25, 'Sementara itu kuanggap perlu mengirimkan Epafroditus kepadamu, yaitu saudaraku dan teman sekerja serta teman seperjuanganku, yang kamu utus untuk melayani aku dalam keperluanku.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 26, 'Karena ia sangat rindu kepada kamu sekalian dan susah juga hatinya, sebab kamu mendengar bahwa ia sakit.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 27, 'Memang benar ia sakit dan nyaris mati, tetapi Allah mengasihani dia, dan bukan hanya dia saja, melainkan aku juga, supaya dukacitaku jangan bertambah-tambah.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 28, 'Itulah sebabnya aku lebih cepat mengirimkan dia, supaya bila kamu melihat dia, kamu dapat bersukacita pula dan berkurang dukacitaku.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 29, 'Jadi sambutlah dia dalam Tuhan dengan segala sukacita dan hormatilah orang-orang seperti dia.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 2, 30, 'Sebab oleh karena pekerjaan Kristus ia nyaris mati dan ia mempertaruhkan jiwanya untuk memenuhi apa yang masih kurang dalam pelayananmu kepadaku.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 1, 'Akhirnya, saudara-saudaraku, bersukacitalah dalam Tuhan. (3-1b) Menuliskan hal ini lagi kepadamu tidaklah berat bagiku dan memberi kepastian kepadamu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 2, 'Hati-hatilah terhadap anjing-anjing, hati-hatilah terhadap pekerja-pekerja yang jahat, hati-hatilah terhadap penyunat-penyunat yang palsu,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 3, 'karena kitalah orang-orang bersunat, yang beribadah oleh Roh Allah, dan bermegah dalam Kristus Yesus dan tidak menaruh percaya pada hal-hal lahiriah.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 4, 'Sekalipun aku juga ada alasan untuk menaruh percaya pada hal-hal lahiriah. Jika ada orang lain menyangka dapat menaruh percaya pada hal-hal lahiriah, aku lebih lagi:', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 5, 'disunat pada hari kedelapan, dari bangsa Israel, dari suku Benyamin, orang Ibrani asli, tentang pendirian terhadap hukum Taurat aku orang Farisi,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 6, 'tentang kegiatan aku penganiaya jemaat, tentang kebenaran dalam mentaati hukum Taurat aku tidak bercacat.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 7, 'Tetapi apa yang dahulu merupakan keuntungan bagiku, sekarang kuanggap rugi karena Kristus.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 8, 'Malahan segala sesuatu kuanggap rugi, karena pengenalan akan Kristus Yesus, Tuhanku, lebih mulia dari pada semuanya. Oleh karena Dialah aku telah melepaskan semuanya itu dan menganggapnya sampah, supaya aku memperoleh Kristus,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 9, 'dan berada dalam Dia bukan dengan kebenaranku sendiri karena mentaati hukum Taurat, melainkan dengan kebenaran karena kepercayaan kepada Kristus, yaitu kebenaran yang Allah anugerahkan berdasarkan kepercayaan.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 10, 'Yang kukehendaki ialah mengenal Dia dan kuasa kebangkitan-Nya dan persekutuan dalam penderitaan-Nya, di mana aku menjadi serupa dengan Dia dalam kematian-Nya,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 11, 'supaya aku akhirnya beroleh kebangkitan dari antara orang mati.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 12, 'Bukan seolah-olah aku telah memperoleh hal ini atau telah sempurna, melainkan aku mengejarnya, kalau-kalau aku dapat juga menangkapnya, karena akupun telah ditangkap oleh Kristus Yesus.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 13, 'Saudara-saudara, aku sendiri tidak menganggap, bahwa aku telah menangkapnya, tetapi ini yang kulakukan: aku melupakan apa yang telah di belakangku dan mengarahkan diri kepada apa yang di hadapanku,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 14, 'dan berlari-lari kepada tujuan untuk memperoleh hadiah, yaitu panggilan sorgawi dari Allah dalam Kristus Yesus.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 15, 'Karena itu marilah kita, yang sempurna, berpikir demikian. Dan jikalau lain pikiranmu tentang salah satu hal, hal itu akan dinyatakan Allah juga kepadamu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 16, 'Tetapi baiklah tingkat pengertian yang telah kita capai kita lanjutkan menurut jalan yang telah kita tempuh.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 17, 'Saudara-saudara, ikutilah teladanku dan perhatikanlah mereka, yang hidup sama seperti kami yang menjadi teladanmu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 18, 'Karena, seperti yang telah kerap kali kukatakan kepadamu, dan yang kunyatakan pula sekarang sambil menangis, banyak orang yang hidup sebagai seteru salib Kristus.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 19, 'Kesudahan mereka ialah kebinasaan, Tuhan mereka ialah perut mereka, kemuliaan mereka ialah aib mereka, pikiran mereka semata-mata tertuju kepada perkara duniawi.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 20, 'Karena kewargaan kita adalah di dalam sorga, dan dari situ juga kita menantikan Tuhan Yesus Kristus sebagai Juruselamat,', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 3, 21, 'yang akan mengubah tubuh kita yang hina ini, sehingga serupa dengan tubuh-Nya yang mulia, menurut kuasa-Nya yang dapat menaklukkan segala sesuatu kepada diri-Nya.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 1, 'Karena itu, saudara-saudara yang kukasihi dan yang kurindukan, sukacitaku dan mahkotaku, berdirilah juga dengan teguh dalam Tuhan, hai saudara-saudaraku yang kekasih!', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 2, 'Euodia kunasihati dan Sintikhe kunasihati, supaya sehati sepikir dalam Tuhan.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 3, 'Bahkan, kuminta kepadamu juga, Sunsugos, temanku yang setia: tolonglah mereka. Karena mereka telah berjuang dengan aku dalam pekabaran Injil, bersama-sama dengan Klemens dan kawan-kawanku sekerja yang lain, yang nama-namanya tercantum dalam kitab kehidupan.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 4, 'Bersukacitalah senantiasa dalam Tuhan! Sekali lagi kukatakan: Bersukacitalah!', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 5, 'Hendaklah kebaikan hatimu diketahui semua orang. Tuhan sudah dekat!', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 6, 'Janganlah hendaknya kamu kuatir tentang apapun juga, tetapi nyatakanlah dalam segala hal keinginanmu kepada Allah dalam doa dan permohonan dengan ucapan syukur.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 7, 'Damai sejahtera Allah, yang melampaui segala akal, akan memelihara hati dan pikiranmu dalam Kristus Yesus.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 8, 'Jadi akhirnya, saudara-saudara, semua yang benar, semua yang mulia, semua yang adil, semua yang suci, semua yang manis, semua yang sedap didengar, semua yang disebut kebajikan dan patut dipuji, pikirkanlah semuanya itu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 9, 'Dan apa yang telah kamu pelajari dan apa yang telah kamu terima, dan apa yang telah kamu dengar dan apa yang telah kamu lihat padaku, lakukanlah itu. Maka Allah sumber damai sejahtera akan menyertai kamu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 10, 'Aku sangat bersukacita dalam Tuhan, bahwa akhirnya pikiranmu dan perasaanmu bertumbuh kembali untuk aku. Memang selalu ada perhatianmu, tetapi tidak ada kesempatan bagimu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 11, 'Kukatakan ini bukanlah karena kekurangan, sebab aku telah belajar mencukupkan diri dalam segala keadaan.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 12, 'Aku tahu apa itu kekurangan dan aku tahu apa itu kelimpahan. Dalam segala hal dan dalam segala perkara tidak ada sesuatu yang merupakan rahasia bagiku; baik dalam hal kenyang, maupun dalam hal kelaparan, baik dalam hal kelimpahan maupun dalam hal kekurangan.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 13, 'Segala perkara dapat kutanggung di dalam Dia yang memberi kekuatan kepadaku.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 14, 'Namun baik juga perbuatanmu, bahwa kamu telah mengambil bagian dalam kesusahanku.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 15, 'Kamu sendiri tahu juga, hai orang-orang Filipi; pada waktu aku baru mulai mengabarkan Injil, ketika aku berangkat dari Makedonia, tidak ada satu jemaatpun yang mengadakan perhitungan hutang dan piutang dengan aku selain dari pada kamu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 16, 'Karena di Tesalonikapun kamu telah satu dua kali mengirimkan bantuan kepadaku.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 17, 'Tetapi yang kuutamakan bukanlah pemberian itu, melainkan buahnya, yang makin memperbesar keuntunganmu.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 18, 'Kini aku telah menerima semua yang perlu dari padamu, malahan lebih dari pada itu. Aku berkelimpahan, karena aku telah menerima kirimanmu dari Epafroditus, suatu persembahan yang harum, suatu korban yang disukai dan yang berkenan kepada Allah.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 19, 'Allahku akan memenuhi segala keperluanmu menurut kekayaan dan kemuliaan-Nya dalam Kristus Yesus.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 20, 'Dimuliakanlah Allah dan Bapa kita selama-lamanya! Amin.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 21, 'Sampaikanlah salamku kepada tiap-tiap orang kudus dalam Kristus Yesus. Salam kepadamu dari saudara-saudara, yang bersama-sama dengan aku.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 22, 'Salam kepadamu dari segala orang kudus, khususnya dari mereka yang di istana Kaisar.', 'id', 'TB'),
  ('50', 'flp', 'Filipi', 4, 23, 'Kasih karunia Tuhan Yesus Kristus menyertai rohmu!', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 1, 'Dari Paulus, rasul Kristus Yesus, oleh kehendak Allah, dan Timotius saudara kita,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 2, 'kepada saudara-saudara yang kudus dan yang percaya dalam Kristus di Kolose. Kasih karunia dan damai sejahtera dari Allah, Bapa kita, menyertai kamu.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 3, 'Kami selalu mengucap syukur kepada Allah, Bapa Tuhan kita Yesus Kristus, setiap kali kami berdoa untuk kamu,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 4, 'karena kami telah mendengar tentang imanmu dalam Kristus Yesus dan tentang kasihmu terhadap semua orang kudus,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 5, 'oleh karena pengharapan, yang disediakan bagi kamu di sorga. Tentang pengharapan itu telah lebih dahulu kamu dengar dalam firman kebenaran, yaitu Injil,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 6, 'yang sudah sampai kepada kamu. Injil itu berbuah dan berkembang di seluruh dunia, demikian juga di antara kamu sejak waktu kamu mendengarnya dan mengenal kasih karunia Allah dengan sebenarnya.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 7, 'Semuanya itu telah kamu ketahui dari Epafras, kawan pelayan yang kami kasihi, yang bagi kamu adalah pelayan Kristus yang setia.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 8, 'Dialah juga yang telah menyatakan kepada kami kasihmu dalam Roh.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 9, 'Sebab itu sejak waktu kami mendengarnya, kami tiada berhenti-henti berdoa untuk kamu. Kami meminta, supaya kamu menerima segala hikmat dan pengertian yang benar, untuk mengetahui kehendak Tuhan dengan sempurna,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 10, 'sehingga hidupmu layak di hadapan-Nya serta berkenan kepada-Nya dalam segala hal, dan kamu memberi buah dalam segala pekerjaan yang baik dan bertumbuh dalam pengetahuan yang benar tentang Allah,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 11, 'dan dikuatkan dengan segala kekuatan oleh kuasa kemuliaan-Nya untuk menanggung segala sesuatu dengan tekun dan sabar,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 12, 'dan mengucap syukur dengan sukacita kepada Bapa, yang melayakkan kamu untuk mendapat bagian dalam apa yang ditentukan untuk orang-orang kudus di dalam kerajaan terang.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 13, 'Ia telah melepaskan kita dari kuasa kegelapan dan memindahkan kita ke dalam Kerajaan Anak-Nya yang kekasih;', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 14, 'di dalam Dia kita memiliki penebusan kita, yaitu pengampunan dosa.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 15, 'Ia adalah gambar Allah yang tidak kelihatan, yang sulung, lebih utama dari segala yang diciptakan,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 16, 'karena di dalam Dialah telah diciptakan segala sesuatu, yang ada di sorga dan yang ada di bumi, yang kelihatan dan yang tidak kelihatan, baik singgasana, maupun kerajaan, baik pemerintah, maupun penguasa; segala sesuatu diciptakan oleh Dia dan untuk Dia.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 17, 'Ia ada terlebih dahulu dari segala sesuatu dan segala sesuatu ada di dalam Dia.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 18, 'Ialah kepala tubuh, yaitu jemaat. Ialah yang sulung, yang pertama bangkit dari antara orang mati, sehingga Ia yang lebih utama dalam segala sesuatu.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 19, 'Karena seluruh kepenuhan Allah berkenan diam di dalam Dia,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 20, 'dan oleh Dialah Ia memperdamaikan segala sesuatu dengan diri-Nya, baik yang ada di bumi, maupun yang ada di sorga, sesudah Ia mengadakan pendamaian oleh darah salib Kristus.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 21, 'Juga kamu yang dahulu hidup jauh dari Allah dan yang memusuhi-Nya dalam hati dan pikiran seperti yang nyata dari perbuatanmu yang jahat,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 22, 'sekarang diperdamaikan-Nya, di dalam tubuh jasmani Kristus oleh kematian-Nya, untuk menempatkan kamu kudus dan tak bercela dan tak bercacat di hadapan-Nya.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 23, 'Sebab itu kamu harus bertekun dalam iman, tetap teguh dan tidak bergoncang, dan jangan mau digeser dari pengharapan Injil, yang telah kamu dengar dan yang telah dikabarkan di seluruh alam di bawah langit, dan yang aku ini, Paulus, telah menjadi pelayannya.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 24, 'Sekarang aku bersukacita bahwa aku boleh menderita karena kamu, dan menggenapkan dalam dagingku apa yang kurang pada penderitaan Kristus, untuk tubuh-Nya, yaitu jemaat.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 25, 'Aku telah menjadi pelayan jemaat itu sesuai dengan tugas yang dipercayakan Allah kepadaku untuk meneruskan firman-Nya dengan sepenuhnya kepada kamu,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 26, 'yaitu rahasia yang tersembunyi dari abad ke abad dan dari turunan ke turunan, tetapi yang sekarang dinyatakan kepada orang-orang kudus-Nya.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 27, 'Kepada mereka Allah mau memberitahukan, betapa kaya dan mulianya rahasia itu di antara bangsa-bangsa lain, yaitu: Kristus ada di tengah-tengah kamu, Kristus yang adalah pengharapan akan kemuliaan!', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 28, 'Dialah yang kami beritakan, apabila tiap-tiap orang kami nasihati dan tiap-tiap orang kami ajari dalam segala hikmat, untuk memimpin tiap-tiap orang kepada kesempurnaan dalam Kristus.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 1, 29, 'Itulah yang kuusahakan dan kupergumulkan dengan segala tenaga sesuai dengan kuasa-Nya, yang bekerja dengan kuat di dalam aku.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 1, 'Karena aku mau, supaya kamu tahu, betapa beratnya perjuangan yang kulakukan untuk kamu, dan untuk mereka yang di Laodikia dan untuk semuanya, yang belum mengenal aku pribadi,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 2, 'supaya hati mereka terhibur dan mereka bersatu dalam kasih, sehingga mereka memperoleh segala kekayaan dan keyakinan pengertian, dan mengenal rahasia Allah, yaitu Kristus,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 3, 'sebab di dalam Dialah tersembunyi segala harta hikmat dan pengetahuan.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 4, 'Hal ini kukatakan, supaya jangan ada yang memperdayakan kamu dengan kata-kata yang indah.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 5, 'Sebab meskipun aku sendiri tidak ada di antara kamu, tetapi dalam roh aku bersama-sama dengan kamu dan aku melihat dengan sukacita tertib hidupmu dan keteguhan imanmu dalam Kristus.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 6, 'Kamu telah menerima Kristus Yesus, Tuhan kita. Karena itu hendaklah hidupmu tetap di dalam Dia.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 7, 'Hendaklah kamu berakar di dalam Dia dan dibangun di atas Dia, hendaklah kamu bertambah teguh dalam iman yang telah diajarkan kepadamu, dan hendaklah hatimu melimpah dengan syukur.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 8, 'Hati-hatilah, supaya jangan ada yang menawan kamu dengan filsafatnya yang kosong dan palsu menurut ajaran turun-temurun dan roh-roh dunia, tetapi tidak menurut Kristus.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 9, 'Sebab dalam Dialah berdiam secara jasmaniah seluruh kepenuhan ke-Allahan,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 10, 'dan kamu telah dipenuhi di dalam Dia. Dialah kepala semua pemerintah dan penguasa.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 11, 'Dalam Dia kamu telah disunat, bukan dengan sunat yang dilakukan oleh manusia, tetapi dengan sunat Kristus, yang terdiri dari penanggalan akan tubuh yang berdosa,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 12, 'karena dengan Dia kamu dikuburkan dalam baptisan, dan di dalam Dia kamu turut dibangkitkan juga oleh kepercayaanmu kepada kerja kuasa Allah, yang telah membangkitkan Dia dari orang mati.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 13, 'Kamu juga, meskipun dahulu mati oleh pelanggaranmu dan oleh karena tidak disunat secara lahiriah, telah dihidupkan Allah bersama-sama dengan Dia, sesudah Ia mengampuni segala pelanggaran kita,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 14, 'dengan menghapuskan surat hutang, yang oleh ketentuan-ketentuan hukum mendakwa dan mengancam kita. Dan itu ditiadakan-Nya dengan memakukannya pada kayu salib:', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 15, 'Ia telah melucuti pemerintah-pemerintah dan penguasa-penguasa dan menjadikan mereka tontonan umum dalam kemenangan-Nya atas mereka.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 16, 'Karena itu janganlah kamu biarkan orang menghukum kamu mengenai makanan dan minuman atau mengenai hari raya, bulan baru ataupun hari Sabat;', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 17, 'semuanya ini hanyalah bayangan dari apa yang harus datang, sedang wujudnya ialah Kristus.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 18, 'Janganlah kamu biarkan kemenanganmu digagalkan oleh orang yang pura-pura merendahkan diri dan beribadah kepada malaikat, serta berkanjang pada penglihatan-penglihatan dan tanpa alasan membesar-besarkan diri oleh pikirannya yang duniawi,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 19, 'sedang ia tidak berpegang teguh kepada Kepala, dari mana seluruh tubuh, yang ditunjang dan diikat menjadi satu oleh urat-urat dan sendi-sendi, menerima pertumbuhan ilahinya.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 20, 'Apabila kamu telah mati bersama-sama dengan Kristus dan bebas dari roh-roh dunia, mengapakah kamu menaklukkan dirimu pada rupa-rupa peraturan, seolah-olah kamu masih hidup di dunia:', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 21, 'jangan jamah ini, jangan kecap itu, jangan sentuh ini;', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 22, 'semuanya itu hanya mengenai barang yang binasa oleh pemakaian dan hanya menurut perintah-perintah dan ajaran-ajaran manusia.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 2, 23, 'Peraturan-peraturan ini, walaupun nampaknya penuh hikmat dengan ibadah buatan sendiri, seperti merendahkan diri, menyiksa diri, tidak ada gunanya selain untuk memuaskan hidup duniawi.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 1, 'Karena itu, kalau kamu dibangkitkan bersama dengan Kristus, carilah perkara yang di atas, di mana Kristus ada, duduk di sebelah kanan Allah.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 2, 'Pikirkanlah perkara yang di atas, bukan yang di bumi.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 3, 'Sebab kamu telah mati dan hidupmu tersembunyi bersama dengan Kristus di dalam Allah.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 4, 'Apabila Kristus, yang adalah hidup kita, menyatakan diri kelak, kamupun akan menyatakan diri bersama dengan Dia dalam kemuliaan.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 5, 'Karena itu matikanlah dalam dirimu segala sesuatu yang duniawi, yaitu percabulan, kenajisan, hawa nafsu, nafsu jahat dan juga keserakahan, yang sama dengan penyembahan berhala,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 6, 'semuanya itu mendatangkan murka Allah (atas orang-orang durhaka).', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 7, 'Dahulu kamu juga melakukan hal-hal itu ketika kamu hidup di dalamnya.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 8, 'Tetapi sekarang, buanglah semuanya ini, yaitu marah, geram, kejahatan, fitnah dan kata-kata kotor yang keluar dari mulutmu.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 9, 'Jangan lagi kamu saling mendustai, karena kamu telah menanggalkan manusia lama serta kelakuannya,', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 10, 'dan telah mengenakan manusia baru yang terus-menerus diperbaharui untuk memperoleh pengetahuan yang benar menurut gambar Khaliknya;', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 11, 'dalam hal ini tiada lagi orang Yunani atau orang Yahudi, orang bersunat atau orang tak bersunat, orang Barbar atau orang Skit, budak atau orang merdeka, tetapi Kristus adalah semua dan di dalam segala sesuatu.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 12, 'Karena itu, sebagai orang-orang pilihan Allah yang dikuduskan dan dikasihi-Nya, kenakanlah belas kasihan, kemurahan, kerendahan hati, kelemahlembutan dan kesabaran.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 13, 'Sabarlah kamu seorang terhadap yang lain, dan ampunilah seorang akan yang lain apabila yang seorang menaruh dendam terhadap yang lain, sama seperti Tuhan telah mengampuni kamu, kamu perbuat jugalah demikian.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 14, 'Dan di atas semuanya itu: kenakanlah kasih, sebagai pengikat yang mempersatukan dan menyempurnakan.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 15, 'Hendaklah damai sejahtera Kristus memerintah dalam hatimu, karena untuk itulah kamu telah dipanggil menjadi satu tubuh. Dan bersyukurlah.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 16, 'Hendaklah perkataan Kristus diam dengan segala kekayaannya di antara kamu, sehingga kamu dengan segala hikmat mengajar dan menegur seorang akan yang lain dan sambil menyanyikan mazmur, dan puji-pujian dan nyanyian rohani, kamu mengucap syukur kepada Allah di dalam hatimu.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 17, 'Dan segala sesuatu yang kamu lakukan dengan perkataan atau perbuatan, lakukanlah semuanya itu dalam nama Tuhan Yesus, sambil mengucap syukur oleh Dia kepada Allah, Bapa kita.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 18, 'Hai isteri-isteri, tunduklah kepada suamimu, sebagaimana seharusnya di dalam Tuhan.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 19, 'Hai suami-suami, kasihilah isterimu dan janganlah berlaku kasar terhadap dia.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 20, 'Hai anak-anak, taatilah orang tuamu dalam segala hal, karena itulah yang indah di dalam Tuhan.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 21, 'Hai bapa-bapa, janganlah sakiti hati anakmu, supaya jangan tawar hatinya.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 22, 'Hai hamba-hamba, taatilah tuanmu yang di dunia ini dalam segala hal, jangan hanya di hadapan mereka saja untuk menyenangkan mereka, melainkan dengan tulus hati karena takut akan Tuhan.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 23, 'Apapun juga yang kamu perbuat, perbuatlah dengan segenap hatimu seperti untuk Tuhan dan bukan untuk manusia.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 24, 'Kamu tahu, bahwa dari Tuhanlah kamu akan menerima bagian yang ditentukan bagimu sebagai upah. Kristus adalah tuan dan kamu hamba-Nya.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 3, 25, 'Barangsiapa berbuat kesalahan, ia akan menanggung kesalahannya itu, karena Tuhan tidak memandang orang.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 1, 'Hai tuan-tuan, berlakulah adil dan jujur terhadap hambamu; ingatlah, kamu juga mempunyai tuan di sorga.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 2, 'Bertekunlah dalam doa dan dalam pada itu berjaga-jagalah sambil mengucap syukur.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 3, 'Berdoa jugalah untuk kami, supaya Allah membuka pintu untuk pemberitaan kami, sehingga kami dapat berbicara tentang rahasia Kristus, yang karenanya aku dipenjarakan.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 4, 'Dengan demikian aku dapat menyatakannya, sebagaimana seharusnya.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 5, 'Hiduplah dengan penuh hikmat terhadap orang-orang luar, pergunakanlah waktu yang ada.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 6, 'Hendaklah kata-katamu senantiasa penuh kasih, jangan hambar, sehingga kamu tahu, bagaimana kamu harus memberi jawab kepada setiap orang.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 7, 'Semua hal ihwalku akan diberitahukan kepada kamu oleh Tikhikus, saudara kita yang kekasih, hamba yang setia dan kawan pelayan dalam Tuhan.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 8, 'Ia kusuruh kepadamu dengan maksud, supaya kamu tahu akan hal ihwal kami dan supaya ia menghibur hatimu.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 9, 'Ia kusuruh bersama-sama dengan Onesimus, saudara kita yang setia dan yang kekasih, seorang dari antaramu. Mereka akan memberitahukan kepadamu segala sesuatu yang terjadi di sini.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 10, 'Salam kepada kamu dari Aristarkhus, temanku sepenjara dan dari Markus, kemenakan Barnabas?tentang dia kamu telah menerima pesan; terimalah dia, apabila dia datang kepadamu?', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 11, 'dan dari Yesus, yang dinamai Yustus. Hanya ketiga orang ini dari antara mereka yang bersunat yang menjadi temanku sekerja untuk Kerajaan Allah; mereka itu telah menjadi penghibur bagiku.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 12, 'Salam dari Epafras kepada kamu; ia seorang dari antaramu, hamba Kristus Yesus, yang selalu bergumul dalam doanya untuk kamu, supaya kamu berdiri teguh, sebagai orang-orang yang dewasa dan yang berkeyakinan penuh dengan segala hal yang dikehendaki Allah.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 13, 'Sebab aku dapat memberi kesaksian tentang dia, bahwa ia sangat bersusah payah untuk kamu dan untuk mereka yang di Laodikia dan Hierapolis.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 14, 'Salam kepadamu dari tabib Lukas yang kekasih dan dari Demas.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 15, 'Sampaikan salam kami kepada saudara-saudara di Laodikia; juga kepada Nimfa dan jemaat yang ada di rumahnya.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 16, 'Dan bilamana surat ini telah dibacakan di antara kamu, usahakanlah, supaya dibacakan juga di jemaat Laodikia dan supaya surat yang untuk Laodikia dibacakan juga kepadamu.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 17, 'Dan sampaikanlah kepada Arkhipus: Perhatikanlah, supaya pelayanan yang kauterima dalam Tuhan kaujalankan sepenuhnya.', 'id', 'TB'),
  ('51', 'kol', 'Kolose', 4, 18, 'Salam dari padaku, Paulus. Salam ini kutulis dengan tanganku sendiri. Ingatlah akan belengguku. Kasih karunia menyertai kamu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 1, 1, 'Dari Paulus, Silwanus dan Timotius kepada jemaat orang-orang Tesalonika yang di dalam Allah Bapa dan di dalam Tuhan Yesus Kristus. Kasih karunia dan damai sejahtera menyertai kamu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 1, 2, 'Kami selalu mengucap syukur kepada Allah karena kamu semua dan menyebut kamu dalam doa kami.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 1, 3, 'Sebab kami selalu mengingat pekerjaan imanmu, usaha kasihmu dan ketekunan pengharapanmu kepada Tuhan kita Yesus Kristus di hadapan Allah dan Bapa kita.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 1, 4, 'Dan kami tahu, hai saudara-saudara yang dikasihi Allah, bahwa Ia telah memilih kamu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 1, 5, 'Sebab Injil yang kami beritakan bukan disampaikan kepada kamu dengan kata-kata saja, tetapi juga dengan kekuatan oleh Roh Kudus dan dengan suatu kepastian yang kokoh. Memang kamu tahu, bagaimana kami bekerja di antara kamu oleh karena kamu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 1, 6, 'Dan kamu telah menjadi penurut kami dan penurut Tuhan; dalam penindasan yang berat kamu telah menerima firman itu dengan sukacita yang dikerjakan oleh Roh Kudus,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 1, 7, 'sehingga kamu telah menjadi teladan untuk semua orang yang percaya di wilayah Makedonia dan Akhaya.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 1, 8, 'Karena dari antara kamu firman Tuhan bergema bukan hanya di Makedonia dan Akhaya saja, tetapi di semua tempat telah tersiar kabar tentang imanmu kepada Allah, sehingga kami tidak usah mengatakan apa-apa tentang hal itu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 1, 9, 'Sebab mereka sendiri berceritera tentang kami, bagaimana kami kamu sambut dan bagaimana kamu berbalik dari berhala-berhala kepada Allah untuk melayani Allah yang hidup dan yang benar,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 1, 10, 'dan untuk menantikan kedatangan Anak-Nya dari sorga, yang telah dibangkitkan-Nya dari antara orang mati, yaitu Yesus, yang menyelamatkan kita dari murka yang akan datang.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 1, 'Kamu sendiripun memang tahu, saudara-saudara, bahwa kedatangan kami di antaramu tidaklah sia-sia.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 2, 'Tetapi sungguhpun kami sebelumnya, seperti kamu tahu, telah dianiaya dan dihina di Filipi, namun dengan pertolongan Allah kita, kami beroleh keberanian untuk memberitakan Injil Allah kepada kamu dalam perjuangan yang berat.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 3, 'Sebab nasihat kami tidak lahir dari kesesatan atau dari maksud yang tidak murni dan juga tidak disertai tipu daya.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 4, 'Sebaliknya, karena Allah telah menganggap kami layak untuk mempercayakan Injil kepada kami, karena itulah kami berbicara, bukan untuk menyukakan manusia, melainkan untuk menyukakan Allah yang menguji hati kita.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 5, 'Karena kami tidak pernah bermulut manis?hal itu kamu ketahui?dan tidak pernah mempunyai maksud loba yang tersembunyi?Allah adalah saksi?', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 6, 'juga tidak pernah kami mencari pujian dari manusia, baik dari kamu, maupun dari orang-orang lain, sekalipun kami dapat berbuat demikian sebagai rasul-rasul Kristus.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 7, 'Tetapi kami berlaku ramah di antara kamu, sama seperti seorang ibu mengasuh dan merawati anaknya.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 8, 'Demikianlah kami, dalam kasih sayang yang besar akan kamu, bukan saja rela membagi Injil Allah dengan kamu, tetapi juga hidup kami sendiri dengan kamu, karena kamu telah kami kasihi.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 9, 'Sebab kamu masih ingat, saudara-saudara, akan usaha dan jerih lelah kami. Sementara kami bekerja siang malam, supaya jangan menjadi beban bagi siapapun juga di antara kamu, kami memberitakan Injil Allah kepada kamu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 10, 'Kamu adalah saksi, demikian juga Allah, betapa saleh, adil dan tak bercacatnya kami berlaku di antara kamu, yang percaya.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 11, 'Kamu tahu, betapa kami, seperti bapa terhadap anak-anaknya, telah menasihati kamu dan menguatkan hatimu seorang demi seorang,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 12, 'dan meminta dengan sangat, supaya kamu hidup sesuai dengan kehendak Allah, yang memanggil kamu ke dalam Kerajaan dan kemuliaan-Nya.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 13, 'Dan karena itulah kami tidak putus-putusnya mengucap syukur juga kepada Allah, sebab kamu telah menerima firman Allah yang kami beritakan itu, bukan sebagai perkataan manusia, tetapi?dan memang sungguh-sungguh demikian?sebagai firman Allah, yang bekerja juga di dalam kamu yang percaya.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 14, 'Sebab kamu, saudara-saudara, telah menjadi penurut jemaat-jemaat Allah di Yudea, jemaat-jemaat di dalam Kristus Yesus, karena kamu juga telah menderita dari teman-teman sebangsamu segala sesuatu yang mereka derita dari orang-orang Yahudi.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 15, 'Bahkan orang-orang Yahudi itu telah membunuh Tuhan Yesus dan para nabi dan telah menganiaya kami. Apa yang berkenan kepada Allah tidak mereka pedulikan dan semua manusia mereka musuhi,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 16, 'karena mereka mau menghalang-halangi kami memberitakan firman kepada bangsa-bangsa lain untuk keselamatan mereka. Demikianlah mereka terus-menerus menambah dosa mereka sampai genap jumlahnya dan sekarang murka telah menimpa mereka sepenuh-penuhnya.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 17, 'Tetapi kami, saudara-saudara, yang seketika terpisah dari kamu, jauh di mata, tetapi tidak jauh di hati, sungguh-sungguh, dengan rindu yang besar, telah berusaha untuk datang menjenguk kamu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 18, 'Sebab kami telah berniat untuk datang kepada kamu?aku, Paulus, malahan lebih dari sekali?,tetapi Iblis telah mencegah kami.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 19, 'Sebab siapakah pengharapan kami atau sukacita kami atau mahkota kemegahan kami di hadapan Yesus, Tuhan kita, pada waktu kedatangan-Nya, kalau bukan kamu?', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 2, 20, 'Sungguh, kamulah kemuliaan kami dan sukacita kami.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 1, 'Kami tidak dapat tahan lagi, karena itu kami mengambil keputusan untuk tinggal seorang diri di Atena.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 2, 'Lalu kami mengirim Timotius, saudara yang bekerja dengan kami untuk Allah dalam pemberitaan Injil Kristus, untuk menguatkan hatimu dan menasihatkan kamu tentang imanmu,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 3, 'supaya jangan ada orang yang goyang imannya karena kesusahan-kesusahan ini. Kamu sendiri tahu, bahwa kita ditentukan untuk itu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 4, 'Sebab, juga waktu kami bersama-sama dengan kamu, telah kami katakan kepada kamu, bahwa kita akan mengalami kesusahan. Dan hal itu, seperti kamu tahu, telah terjadi.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 5, 'Itulah sebabnya, maka aku, karena tidak dapat tahan lagi, telah mengirim dia, supaya aku tahu tentang imanmu, karena aku kuatir kalau-kalau kamu telah dicobai oleh si penggoda dan kalau-kalau usaha kami menjadi sia-sia.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 6, 'Tetapi sekarang, setelah Timotius datang kembali dari kamu dan membawa kabar yang menggembirakan tentang imanmu dan kasihmu, dan bahwa kamu selalu menaruh kenang-kenangan yang baik akan kami dan ingin untuk berjumpa dengan kami, seperti kami juga ingin untuk berjumpa dengan kamu,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 7, 'maka kami juga, saudara-saudara, dalam segala kesesakan dan kesukaran kami menjadi terhibur oleh kamu dan oleh imanmu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 8, 'Sekarang kami hidup kembali, asal saja kamu teguh berdiri di dalam Tuhan.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 9, 'Sebab ucapan syukur apakah yang dapat kami persembahkan kepada Allah atas segala sukacita, yang kami peroleh karena kamu, di hadapan Allah kita?', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 10, 'Siang malam kami berdoa sungguh-sungguh, supaya kita bertemu muka dengan muka dan menambahkan apa yang masih kurang pada imanmu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 11, 'Kiranya Dia, Allah dan Bapa kita, dan Yesus, Tuhan kita, membukakan kami jalan kepadamu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 12, 'Dan kiranya Tuhan menjadikan kamu bertambah-tambah dan berkelimpahan dalam kasih seorang terhadap yang lain dan terhadap semua orang, sama seperti kami juga mengasihi kamu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 3, 13, 'Kiranya Dia menguatkan hatimu, supaya tak bercacat dan kudus, di hadapan Allah dan Bapa kita pada waktu kedatangan Yesus, Tuhan kita, dengan semua orang kudus-Nya.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 1, 'Akhirnya, saudara-saudara, kami minta dan nasihatkan kamu dalam Tuhan Yesus: Kamu telah mendengar dari kami bagaimana kamu harus hidup supaya berkenan kepada Allah. Hal itu memang telah kamu turuti, tetapi baiklah kamu melakukannya lebih bersungguh-sungguh lagi.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 2, 'Kamu tahu juga petunjuk-petunjuk mana yang telah kami berikan kepadamu atas nama Tuhan Yesus.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 3, 'Karena inilah kehendak Allah: pengudusanmu, yaitu supaya kamu menjauhi percabulan,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 4, 'supaya kamu masing-masing mengambil seorang perempuan menjadi isterimu sendiri dan hidup di dalam pengudusan dan penghormatan,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 5, 'bukan di dalam keinginan hawa nafsu, seperti yang dibuat oleh orang-orang yang tidak mengenal Allah,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 6, 'dan supaya dalam hal-hal ini orang jangan memperlakukan saudaranya dengan tidak baik atau memperdayakannya. Karena Tuhan adalah pembalas dari semuanya ini, seperti yang telah kami katakan dan tegaskan dahulu kepadamu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 7, 'Allah memanggil kita bukan untuk melakukan apa yang cemar, melainkan apa yang kudus.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 8, 'Karena itu siapa yang menolak ini bukanlah menolak manusia, melainkan menolak Allah yang telah memberikan juga Roh-Nya yang kudus kepada kamu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 9, 'Tentang kasih persaudaraan tidak perlu dituliskan kepadamu, karena kamu sendiri telah belajar kasih mengasihi dari Allah.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 10, 'Hal itu kamu lakukan juga terhadap semua saudara di seluruh wilayah Makedonia. Tetapi kami menasihati kamu, saudara-saudara, supaya kamu lebih bersungguh-sungguh lagi melakukannya.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 11, 'Dan anggaplah sebagai suatu kehormatan untuk hidup tenang, untuk mengurus persoalan-persoalan sendiri dan bekerja dengan tangan, seperti yang telah kami pesankan kepadamu,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 12, 'sehingga kamu hidup sebagai orang-orang yang sopan di mata orang luar dan tidak bergantung pada mereka.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 13, 'Selanjutnya kami tidak mau, saudara-saudara, bahwa kamu tidak mengetahui tentang mereka yang meninggal, supaya kamu jangan berdukacita seperti orang-orang lain yang tidak mempunyai pengharapan.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 14, 'Karena jikalau kita percaya, bahwa Yesus telah mati dan telah bangkit, maka kita percaya juga bahwa mereka yang telah meninggal dalam Yesus akan dikumpulkan Allah bersama-sama dengan Dia.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 15, 'Ini kami katakan kepadamu dengan firman Tuhan: kita yang hidup, yang masih tinggal sampai kedatangan Tuhan, sekali-kali tidak akan mendahului mereka yang telah meninggal.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 16, 'Sebab pada waktu tanda diberi, yaitu pada waktu penghulu malaikat berseru dan sangkakala Allah berbunyi, maka Tuhan sendiri akan turun dari sorga dan mereka yang mati dalam Kristus akan lebih dahulu bangkit;', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 17, 'sesudah itu, kita yang hidup, yang masih tinggal, akan diangkat bersama-sama dengan mereka dalam awan menyongsong Tuhan di angkasa. Demikianlah kita akan selama-lamanya bersama-sama dengan Tuhan.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 4, 18, 'Karena itu hiburkanlah seorang akan yang lain dengan perkataan-perkataan ini.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 1, 'Tetapi tentang zaman dan masa, saudara-saudara, tidak perlu dituliskan kepadamu,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 2, 'karena kamu sendiri tahu benar-benar, bahwa hari Tuhan datang seperti pencuri pada malam.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 3, 'Apabila mereka mengatakan: Semuanya damai dan aman?maka tiba-tiba mereka ditimpa oleh kebinasaan, seperti seorang perempuan yang hamil ditimpa oleh sakit bersalin?mereka pasti tidak akan luput.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 4, 'Tetapi kamu, saudara-saudara, kamu tidak hidup di dalam kegelapan, sehingga hari itu tiba-tiba mendatangi kamu seperti pencuri,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 5, 'karena kamu semua adalah anak-anak terang dan anak-anak siang. Kita bukanlah orang-orang malam atau orang-orang kegelapan.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 6, 'Sebab itu baiklah jangan kita tidur seperti orang-orang lain, tetapi berjaga-jaga dan sadar.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 7, 'Sebab mereka yang tidur, tidur waktu malam dan mereka yang mabuk, mabuk waktu malam.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 8, 'Tetapi kita, yang adalah orang-orang siang, baiklah kita sadar, berbajuzirahkan iman dan kasih, dan berketopongkan pengharapan keselamatan.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 9, 'Karena Allah tidak menetapkan kita untuk ditimpa murka, tetapi untuk beroleh keselamatan oleh Yesus Kristus, Tuhan kita,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 10, 'yang sudah mati untuk kita, supaya entah kita berjaga-jaga, entah kita tidur, kita hidup bersama-sama dengan Dia.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 11, 'Karena itu nasihatilah seorang akan yang lain dan saling membangunlah kamu seperti yang memang kamu lakukan.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 12, 'Kami minta kepadamu, saudara-saudara, supaya kamu menghormati mereka yang bekerja keras di antara kamu, yang memimpin kamu dalam Tuhan dan yang menegor kamu;', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 13, 'dan supaya kamu sungguh-sungguh menjunjung mereka dalam kasih karena pekerjaan mereka. Hiduplah selalu dalam damai seorang dengan yang lain.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 14, 'Kami juga menasihati kamu, saudara-saudara, tegorlah mereka yang hidup dengan tidak tertib, hiburlah mereka yang tawar hati, belalah mereka yang lemah, sabarlah terhadap semua orang.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 15, 'Perhatikanlah, supaya jangan ada orang yang membalas jahat dengan jahat, tetapi usahakanlah senantiasa yang baik, terhadap kamu masing-masing dan terhadap semua orang.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 16, 'Bersukacitalah senantiasa.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 17, 'Tetaplah berdoa.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 18, 'Mengucap syukurlah dalam segala hal, sebab itulah yang dikehendaki Allah di dalam Kristus Yesus bagi kamu.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 19, 'Janganlah padamkan Roh,', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 20, 'dan janganlah anggap rendah nubuat-nubuat.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 21, 'Ujilah segala sesuatu dan peganglah yang baik.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 22, 'Jauhkanlah dirimu dari segala jenis kejahatan.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 23, 'Semoga Allah damai sejahtera menguduskan kamu seluruhnya dan semoga roh, jiwa dan tubuhmu terpelihara sempurna dengan tak bercacat pada kedatangan Yesus Kristus, Tuhan kita.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 24, 'Ia yang memanggil kamu adalah setia, Ia juga akan menggenapinya.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 25, 'Saudara-saudara, doakanlah kami.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 26, 'Sampaikanlah salam kami kepada semua saudara dengan cium yang kudus.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 27, 'Demi nama Tuhan aku minta dengan sangat kepadamu, supaya surat ini dibacakan kepada semua saudara.', 'id', 'TB'),
  ('52', '1tes', '1 Tesalonika', 5, 28, 'Kasih karunia Yesus Kristus, Tuhan kita, menyertai kamu!', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 1, 'Dari Paulus, Silwanus dan Timotius, kepada jemaat orang-orang Tesalonika di dalam Allah Bapa kita dan di dalam Tuhan Yesus Kristus.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 2, 'Kasih karunia dan damai sejahtera dari Allah, Bapa kita, dan dari Tuhan Yesus Kristus menyertai kamu.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 3, 'Kami wajib selalu mengucap syukur kepada Allah karena kamu, saudara-saudara. Dan memang patutlah demikian, karena imanmu makin bertambah dan kasihmu seorang akan yang lain makin kuat di antara kamu,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 4, 'sehingga dalam jemaat-jemaat Allah kami sendiri bermegah tentang kamu karena ketabahanmu dan imanmu dalam segala penganiayaan dan penindasan yang kamu derita:', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 5, 'suatu bukti tentang adilnya penghakiman Allah, yang menyatakan bahwa kamu layak menjadi warga Kerajaan Allah, kamu yang sekarang menderita karena Kerajaan itu.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 6, 'Sebab memang adil bagi Allah untuk membalaskan penindasan kepada mereka yang menindas kamu', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 7, 'dan untuk memberikan kelegaan kepada kamu yang ditindas, dan juga kepada kami, pada waktu Tuhan Yesus dari dalam sorga menyatakan diri-Nya bersama-sama dengan malaikat-malaikat-Nya, dalam kuasa-Nya, di dalam api yang bernyala-nyala,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 8, 'dan mengadakan pembalasan terhadap mereka yang tidak mau mengenal Allah dan tidak mentaati Injil Yesus, Tuhan kita.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 9, 'Mereka ini akan menjalani hukuman kebinasaan selama-lamanya, dijauhkan dari hadirat Tuhan dan dari kemuliaan kekuatan-Nya,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 10, 'apabila Ia datang pada hari itu untuk dimuliakan di antara orang-orang kudus-Nya dan untuk dikagumi oleh semua orang yang percaya, sebab kesaksian yang kami bawa kepadamu telah kamu percayai.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 11, 'Karena itu kami senantiasa berdoa juga untuk kamu, supaya Allah kita menganggap kamu layak bagi panggilan-Nya dan dengan kekuatan-Nya menyempurnakan kehendakmu untuk berbuat baik dan menyempurnakan segala pekerjaan imanmu,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 1, 12, 'sehingga nama Yesus, Tuhan kita, dimuliakan di dalam kamu dan kamu di dalam Dia, menurut kasih karunia Allah kita dan Tuhan Yesus Kristus.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 1, 'Tentang kedatangan Tuhan kita Yesus Kristus dan terhimpunnya kita dengan Dia kami minta kepadamu, saudara-saudara,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 2, 'supaya kamu jangan lekas bingung dan gelisah, baik oleh ilham roh, maupun oleh pemberitaan atau surat yang dikatakan dari kami, seolah-olah hari Tuhan telah tiba.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 3, 'Janganlah kamu memberi dirimu disesatkan orang dengan cara yang bagaimanapun juga! Sebab sebelum Hari itu haruslah datang dahulu murtad dan haruslah dinyatakan dahulu manusia durhaka, yang harus binasa,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 4, 'yaitu lawan yang meninggikan diri di atas segala yang disebut atau yang disembah sebagai Allah. Bahkan ia duduk di Bait Allah dan mau menyatakan diri sebagai Allah.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 5, 'Tidakkah kamu ingat, bahwa hal itu telah kerapkali kukatakan kepadamu, ketika aku masih bersama-sama dengan kamu?', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 6, 'Dan sekarang kamu tahu apa yang menahan dia, sehingga ia baru akan menyatakan diri pada waktu yang telah ditentukan baginya.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 7, 'Karena secara rahasia kedurhakaan telah mulai bekerja, tetapi sekarang masih ada yang menahan. Kalau yang menahannya itu telah disingkirkan,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 8, 'pada waktu itulah si pendurhaka baru akan menyatakan dirinya, tetapi Tuhan Yesus akan membunuhnya dengan nafas mulut-Nya dan akan memusnahkannya, kalau Ia datang kembali.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 9, 'Kedatangan si pendurhaka itu adalah pekerjaan Iblis, dan akan disertai rupa-rupa perbuatan ajaib, tanda-tanda dan mujizat-mujizat palsu,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 10, 'dengan rupa-rupa tipu daya jahat terhadap orang-orang yang harus binasa karena mereka tidak menerima dan mengasihi kebenaran yang dapat menyelamatkan mereka.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 11, 'Dan itulah sebabnya Allah mendatangkan kesesatan atas mereka, yang menyebabkan mereka percaya akan dusta,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 12, 'supaya dihukum semua orang yang tidak percaya akan kebenaran dan yang suka kejahatan.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 13, 'Akan tetapi kami harus selalu mengucap syukur kepada Allah karena kamu, saudara-saudara, yang dikasihi Tuhan, sebab Allah dari mulanya telah memilih kamu untuk diselamatkan dalam Roh yang menguduskan kamu dan dalam kebenaran yang kamu percayai.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 14, 'Untuk itulah Ia telah memanggil kamu oleh Injil yang kami beritakan, sehingga kamu boleh memperoleh kemuliaan Yesus Kristus, Tuhan kita.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 15, 'Sebab itu, berdirilah teguh dan berpeganglah pada ajaran-ajaran yang kamu terima dari ajaran-ajaran yang kamu terima dari kami, baik secara lisan, maupun secara tertulis.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 16, 'Dan Ia, Tuhan kita Yesus Kristus, dan Allah, Bapa kita, yang dalam kasih karunia-Nya telah mengasihi kita dan yang telah menganugerahkan penghiburan abadi dan pengharapan baik kepada kita,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 2, 17, 'kiranya menghibur dan menguatkan hatimu dalam pekerjaan dan perkataan yang baik.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 1, 'Selanjutnya, saudara-saudara, berdoalah untuk kami, supaya firman Tuhan beroleh kemajuan dan dimuliakan, sama seperti yang telah terjadi di antara kamu,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 2, 'dan supaya kami terlepas dari para pengacau dan orang-orang jahat, sebab bukan semua orang beroleh iman.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 3, 'Tetapi Tuhan adalah setia. Ia akan menguatkan hatimu dan memelihara kamu terhadap yang jahat.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 4, 'Dan kami percaya dalam Tuhan, bahwa apa yang kami pesankan kepadamu, kamu lakukan dan akan kamu lakukan.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 5, 'Kiranya Tuhan tetap menujukan hatimu kepada kasih Allah dan kepada ketabahan Kristus.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 6, 'Tetapi kami berpesan kepadamu, saudara-saudara, dalam nama Tuhan Yesus Kristus, supaya kamu menjauhkan diri dari setiap saudara yang tidak melakukan pekerjaannya dan yang tidak menurut ajaran yang telah kamu terima dari kami.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 7, 'Sebab kamu sendiri tahu, bagaimana kamu harus mengikuti teladan kami, karena kami tidak lalai bekerja di antara kamu,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 8, 'dan tidak makan roti orang dengan percuma, tetapi kami berusaha dan berjerih payah siang malam, supaya jangan menjadi beban bagi siapapun di antara kamu.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 9, 'Bukan karena kami tidak berhak untuk itu, melainkan karena kami mau menjadikan diri kami teladan bagi kamu, supaya kamu ikuti.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 10, 'Sebab, juga waktu kami berada di antara kamu, kami memberi peringatan ini kepada kamu: jika seorang tidak mau bekerja, janganlah ia makan.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 11, 'Kami katakan ini karena kami dengar, bahwa ada orang yang tidak tertib hidupnya dan tidak bekerja, melainkan sibuk dengan hal-hal yang tidak berguna.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 12, 'Orang-orang yang demikian kami peringati dan nasihati dalam Tuhan Yesus Kristus, supaya mereka tetap tenang melakukan pekerjaannya dan dengan demikian makan makanannya sendiri.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 13, 'Dan kamu, saudara-saudara, janganlah jemu-jemu berbuat apa yang baik.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 14, 'Jika ada orang yang tidak mau mendengarkan apa yang kami katakan dalam surat ini, tandailah dia dan jangan bergaul dengan dia, supaya ia menjadi malu,', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 15, 'tetapi janganlah anggap dia sebagai musuh, tetapi tegorlah dia sebagai seorang saudara.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 16, 'Dan Ia, Tuhan damai sejahtera, kiranya mengaruniakan damai sejahtera-Nya terus-menerus, dalam segala hal, kepada kamu. Tuhan menyertai kamu sekalian.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 17, 'Salam dari padaku, Paulus. Salam ini kutulis dengan tanganku sendiri. Inilah tanda dalam setiap surat: beginilah tulisanku.', 'id', 'TB'),
  ('53', '2tes', '2 Tesalonika', 3, 18, 'Kasih karunia Yesus Kristus, Tuhan kita, menyertai kamu sekalian!', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 1, 'Dari Paulus, rasul Kristus Yesus menurut perintah Allah, Juruselamat kita, dan Kristus Yesus, dasar pengharapan kita,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 2, 'kepada Timotius, anakku yang sah di dalam iman: kasih karunia, rahmat dan damai sejahtera dari Allah Bapa dan Kristus Yesus, Tuhan kita, menyertai engkau.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 3, 'Ketika aku hendak meneruskan perjalananku ke wilayah Makedonia, aku telah mendesak engkau supaya engkau tinggal di Efesus dan menasihatkan orang-orang tertentu, agar mereka jangan mengajarkan ajaran lain', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 4, 'ataupun sibuk dengan dongeng dan silsilah yang tiada putus-putusnya, yang hanya menghasilkan persoalan belaka, dan bukan tertib hidup keselamatan yang diberikan Allah dalam iman.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 5, 'Tujuan nasihat itu ialah kasih yang timbul dari hati yang suci, dari hati nurani yang murni dan dari iman yang tulus ikhlas.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 6, 'Tetapi ada orang yang tidak sampai pada tujuan itu dan yang sesat dalam omongan yang sia-sia.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 7, 'Mereka itu hendak menjadi pengajar hukum Taurat tanpa mengerti perkataan mereka sendiri dan pokok-pokok yang secara mutlak mereka kemukakan.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 8, 'Kita tahu bahwa hukum Taurat itu baik kalau tepat digunakan,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 9, 'yakni dengan keinsafan bahwa hukum Taurat itu bukanlah bagi orang yang benar, melainkan bagi orang durhaka dan orang lalim, bagi orang fasik dan orang berdosa, bagi orang duniawi dan yang tak beragama, bagi pembunuh bapa dan pembunuh ibu, bagi pembunuh pada umumnya,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 10, 'bagi orang cabul dan pemburit, bagi penculik, bagi pendusta, bagi orang makan sumpah dan seterusnya segala sesuatu yang bertentangan dengan ajaran sehat', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 11, 'yang berdasarkan Injil dari Allah yang mulia dan maha bahagia, seperti yang telah dipercayakan kepadaku.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 12, 'Aku bersyukur kepada Dia, yang menguatkan aku, yaitu Kristus Yesus, Tuhan kita, karena Ia menganggap aku setia dan mempercayakan pelayanan ini kepadaku?', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 13, 'aku yang tadinya seorang penghujat dan seorang penganiaya dan seorang ganas, tetapi aku telah dikasihani-Nya, karena semuanya itu telah kulakukan tanpa pengetahuan yaitu di luar iman.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 14, 'Malah kasih karunia Tuhan kita itu telah dikaruniakan dengan limpahnya kepadaku dengan iman dan kasih dalam Kristus Yesus.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 15, 'Perkataan ini benar dan patut diterima sepenuhnya: "Kristus Yesus datang ke dunia untuk menyelamatkan orang berdosa," dan di antara mereka akulah yang paling berdosa.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 16, 'Tetapi justru karena itu aku dikasihani, agar dalam diriku ini, sebagai orang yang paling berdosa, Yesus Kristus menunjukkan seluruh kesabaran-Nya. Dengan demikian aku menjadi contoh bagi mereka yang kemudian percaya kepada-Nya dan mendapat hidup yang kekal.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 17, 'Hormat dan kemuliaan sampai selama-lamanya bagi Raja segala zaman, Allah yang kekal, yang tak nampak, yang esa! Amin.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 18, 'Tugas ini kuberikan kepadamu, Timotius anakku, sesuai dengan apa yang telah dinubuatkan tentang dirimu, supaya dikuatkan oleh nubuat itu engkau memperjuangkan perjuangan yang baik dengan iman dan hati nurani yang murni.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 19, 'Beberapa orang telah menolak hati nuraninya yang murni itu, dan karena itu kandaslah iman mereka,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 1, 20, 'di antaranya Himeneus dan Aleksander, yang telah kuserahkan kepada Iblis, supaya jera mereka menghujat.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 1, 'Pertama-tama aku menasihatkan: Naikkanlah permohonan, doa syafaat dan ucapan syukur untuk semua orang,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 2, 'untuk raja-raja dan untuk semua pembesar, agar kita dapat hidup tenang dan tenteram dalam segala kesalehan dan kehormatan.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 3, 'Itulah yang baik dan yang berkenan kepada Allah, Juruselamat kita,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 4, 'yang menghendaki supaya semua orang diselamatkan dan memperoleh pengetahuan akan kebenaran.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 5, 'Karena Allah itu esa dan esa pula Dia yang menjadi pengantara antara Allah dan manusia, yaitu manusia Kristus Yesus,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 6, 'yang telah menyerahkan diri-Nya sebagai tebusan bagi semua manusia: itu kesaksian pada waktu yang ditentukan.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 7, 'Untuk kesaksian itulah aku telah ditetapkan sebagai pemberita dan rasul?yang kukatakan ini benar, aku tidak berdusta?dan sebagai pengajar orang-orang bukan Yahudi, dalam iman dan kebenaran.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 8, 'Oleh karena itu aku ingin, supaya di mana-mana orang laki-laki berdoa dengan menadahkan tangan yang suci, tanpa marah dan tanpa perselisihan.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 9, 'Demikian juga hendaknya perempuan. Hendaklah ia berdandan dengan pantas, dengan sopan dan sederhana, rambutnya jangan berkepang-kepang, jangan memakai emas atau mutiara ataupun pakaian yang mahal-mahal,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 10, 'tetapi hendaklah ia berdandan dengan perbuatan baik, seperti yang layak bagi perempuan yang beribadah.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 11, 'Seharusnyalah perempuan berdiam diri dan menerima ajaran dengan patuh.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 12, 'Aku tidak mengizinkan perempuan mengajar dan juga tidak mengizinkannya memerintah laki-laki; hendaklah ia berdiam diri.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 13, 'Karena Adam yang pertama dijadikan, kemudian barulah Hawa.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 14, 'Lagipula bukan Adam yang tergoda, melainkan perempuan itulah yang tergoda dan jatuh ke dalam dosa.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 2, 15, 'Tetapi perempuan akan diselamatkan karena melahirkan anak, asal ia bertekun dalam iman dan kasih dan pengudusan dengan segala kesederhanaan.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 1, 'Benarlah perkataan ini: "Orang yang menghendaki jabatan penilik jemaat menginginkan pekerjaan yang indah."', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 2, 'Karena itu penilik jemaat haruslah seorang yang tak bercacat, suami dari satu isteri, dapat menahan diri, bijaksana, sopan, suka memberi tumpangan, cakap mengajar orang,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 3, 'bukan peminum, bukan pemarah melainkan peramah, pendamai, bukan hamba uang,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 4, 'seorang kepala keluarga yang baik, disegani dan dihormati oleh anak-anaknya.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 5, 'Jikalau seorang tidak tahu mengepalai keluarganya sendiri, bagaimanakah ia dapat mengurus Jemaat Allah?', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 6, 'Janganlah ia seorang yang baru bertobat, agar jangan ia menjadi sombong dan kena hukuman Iblis.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 7, 'Hendaklah ia juga mempunyai nama baik di luar jemaat, agar jangan ia digugat orang dan jatuh ke dalam jerat Iblis.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 8, 'Demikian juga diaken-diaken haruslah orang terhormat, jangan bercabang lidah, jangan penggemar anggur, jangan serakah,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 9, 'melainkan orang yang memelihara rahasia iman dalam hati nurani yang suci.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 10, 'Mereka juga harus diuji dahulu, baru ditetapkan dalam pelayanan itu setelah ternyata mereka tak bercacat.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 11, 'Demikian pula isteri-isteri hendaklah orang terhormat, jangan pemfitnah, hendaklah dapat menahan diri dan dapat dipercayai dalam segala hal.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 12, 'Diaken haruslah suami dari satu isteri dan mengurus anak-anaknya dan keluarganya dengan baik.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 13, 'Karena mereka yang melayani dengan baik beroleh kedudukan yang baik sehingga dalam iman kepada Kristus Yesus mereka dapat bersaksi dengan leluasa.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 14, 'Semuanya itu kutuliskan kepadamu, walaupun kuharap segera dapat mengunjungi engkau.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 15, 'Jadi jika aku terlambat, sudahlah engkau tahu bagaimana orang harus hidup sebagai keluarga Allah, yakni jemaat dari Allah yang hidup, tiang penopang dan dasar kebenaran.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 3, 16, 'Dan sesungguhnya agunglah rahasia ibadah kita: "Dia, yang telah menyatakan diri-Nya dalam rupa manusia, dibenarkan dalam Roh; yang menampakkan diri-Nya kepada malaikat-malaikat, diberitakan di antara bangsa-bangsa yang tidak mengenal Allah; yang dipercayai di dalam dunia, diangkat dalam kemuliaan."', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 1, 'Tetapi Roh dengan tegas mengatakan bahwa di waktu-waktu kemudian, ada orang yang akan murtad lalu mengikuti roh-roh penyesat dan ajaran setan-setan', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 2, 'oleh tipu daya pendusta-pendusta yang hati nuraninya memakai cap mereka.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 3, 'Mereka itu melarang orang kawin, melarang orang makan makanan yang diciptakan Allah supaya dengan pengucapan syukur dimakan oleh orang yang percaya dan yang telah mengenal kebenaran.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 4, 'Karena semua yang diciptakan Allah itu baik dan suatupun tidak ada yang haram, jika diterima dengan ucapan syukur,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 5, 'sebab semuanya itu dikuduskan oleh firman Allah dan oleh doa.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 6, 'Dengan selalu mengingatkan hal-hal itu kepada saudara-saudara kita, engkau akan menjadi seorang pelayan Kristus Yesus yang baik, terdidik dalam soal-soal pokok iman kita dan dalam ajaran sehat yang telah kauikuti selama ini.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 7, 'Tetapi jauhilah takhayul dan dongeng nenek-nenek tua. Latihlah dirimu beribadah.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 8, 'Latihan badani terbatas gunanya, tetapi ibadah itu berguna dalam segala hal, karena mengandung janji, baik untuk hidup ini maupun untuk hidup yang akan datang.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 9, 'Perkataan ini benar dan patut diterima sepenuhnya.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 10, 'Itulah sebabnya kita berjerih payah dan berjuang, karena kita menaruh pengharapan kita kepada Allah yang hidup, Juruselamat semua manusia, terutama mereka yang percaya.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 11, 'Beritakanlah dan ajarkanlah semuanya itu.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 12, 'Jangan seorangpun menganggap engkau rendah karena engkau muda. Jadilah teladan bagi orang-orang percaya, dalam perkataanmu, dalam tingkah lakumu, dalam kasihmu, dalam kesetiaanmu dan dalam kesucianmu.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 13, 'Sementara itu, sampai aku datang bertekunlah dalam membaca Kitab-kitab Suci, dalam membangun dan dalam mengajar.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 14, 'Jangan lalai dalam mempergunakan karunia yang ada padamu, yang telah diberikan kepadamu oleh nubuat dan dengan penumpangan tangan sidang penatua.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 15, 'Perhatikanlah semuanya itu, hiduplah di dalamnya supaya kemajuanmu nyata kepada semua orang.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 4, 16, 'Awasilah dirimu sendiri dan awasilah ajaranmu. Bertekunlah dalam semuanya itu, karena dengan berbuat demikian engkau akan menyelamatkan dirimu dan semua orang yang mendengar engkau.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 1, 'Janganlah engkau keras terhadap orang yang tua, melainkan tegorlah dia sebagai bapa. Tegorlah orang-orang muda sebagai saudaramu,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 2, 'perempuan-perempuan tua sebagai ibu dan perempuan-perempuan muda sebagai adikmu dengan penuh kemurnian.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 3, 'Hormatilah janda-janda yang benar-benar janda.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 4, 'Tetapi jikalau seorang janda mempunyai anak atau cucu, hendaknya mereka itu pertama-tama belajar berbakti kepada kaum keluarganya sendiri dan membalas budi orang tua dan nenek mereka, karena itulah yang berkenan kepada Allah.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 5, 'Sedangkan seorang janda yang benar-benar janda, yang ditinggalkan seorang diri, menaruh harapannya kepada Allah dan bertekun dalam permohonan dan doa siang malam.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 6, 'Tetapi seorang janda yang hidup mewah dan berlebih-lebihan, ia sudah mati selagi hidup.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 7, 'Peringatkanlah hal-hal ini juga kepada janda-janda itu agar mereka hidup dengan tidak bercela.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 8, 'Tetapi jika ada seorang yang tidak memeliharakan sanak saudaranya, apalagi seisi rumahnya, orang itu murtad dan lebih buruk dari orang yang tidak beriman.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 9, 'Yang didaftarkan sebagai janda, hanyalah mereka yang tidak kurang dari enam puluh tahun, yang hanya satu kali bersuami', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 10, 'dan yang terbukti telah melakukan pekerjaan yang baik, seperti mengasuh anak, memberi tumpangan, membasuh kaki saudara-saudara seiman, menolong orang yang hidup dalam kesesakan?pendeknya mereka yang telah menggunakan segala kesempatan untuk berbuat baik.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 11, 'Tolaklah pendaftaran janda-janda yang lebih muda. Karena apabila mereka sekali digairahkan oleh keberahian yang menceraikan mereka dari Kristus, mereka itu ingin kawin', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 12, 'dan dengan memungkiri kesetiaan mereka yang semula kepada-Nya, mereka mendatangkan hukuman atas dirinya.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 13, 'Lagipula dengan keluar masuk rumah orang, mereka membiasakan diri bermalas-malas dan bukan hanya bermalas-malas saja, tetapi juga meleter dan mencampuri soal orang lain dan mengatakan hal-hal yang tidak pantas.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 14, 'Karena itu aku mau supaya janda-janda yang muda kawin lagi, beroleh anak, memimpin rumah tangganya dan jangan memberi alasan kepada lawan untuk memburuk-burukkan nama kita.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 15, 'Karena beberapa janda telah tersesat mengikut Iblis.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 16, 'Jika seorang laki-laki atau perempuan yang percaya mempunyai anggota keluarga yang janda, hendaklah ia membantu mereka sehingga mereka jangan menjadi beban bagi jemaat. Dengan demikian jemaat dapat membantu mereka yang benar-benar janda.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 17, 'Penatua-penatua yang baik pimpinannya patut dihormati dua kali lipat, terutama mereka yang dengan jerih payah berkhotbah dan mengajar.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 18, 'Bukankah Kitab Suci berkata: "Janganlah engkau memberangus mulut lembu yang sedang mengirik," dan lagi "seorang pekerja patut mendapat upahnya."', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 19, 'Janganlah engkau menerima tuduhan atas seorang penatua kecuali kalau didukung dua atau tiga orang saksi.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 20, 'Mereka yang berbuat dosa hendaklah kautegor di depan semua orang agar yang lain itupun takut.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 21, 'Di hadapan Allah dan Kristus Yesus dan malaikat-malaikat pilihan-Nya kupesankan dengan sungguh kepadamu: camkanlah petunjuk ini tanpa prasangka dan bertindaklah dalam segala sesuatu tanpa memihak.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 22, 'Janganlah engkau terburu-buru menumpangkan tangan atas seseorang dan janganlah terbawa-bawa ke dalam dosa orang lain. Jagalah kemurnian dirimu.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 23, 'Janganlah lagi minum air saja, melainkan tambahkanlah anggur sedikit, berhubung pencernaanmu terganggu dan tubuhmu sering lemah.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 24, 'Dosa beberapa orang menyolok, seakan-akan mendahului mereka ke pengadilan, tetapi dosa beberapa orang lagi baru menjadi nyata kemudian.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 5, 25, 'Demikianpun perbuatan baik itu segera nyata dan kalau tidak demikian, ia tidak dapat terus tinggal tersembunyi.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 1, 'Semua orang yang menanggung beban perbudakan hendaknya menganggap tuan mereka layak mendapat segala penghormatan, agar nama Allah dan ajaran kita jangan dihujat orang.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 2, 'Jika tuan mereka seorang percaya, janganlah ia kurang disegani karena bersaudara dalam Kristus, melainkan hendaklah ia dilayani mereka dengan lebih baik lagi, karena tuan yang menerima berkat pelayanan mereka ialah saudara yang percaya dan yang kekasih. (6-2b) Ajarkanlah dan nasihatkanlah semuanya ini.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 3, 'Jika seorang mengajarkan ajaran lain dan tidak menurut perkataan sehat?yakni perkataan Tuhan kita Yesus Kristus?dan tidak menurut ajaran yang sesuai dengan ibadah kita,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 4, 'ia adalah seorang yang berlagak tahu padahal tidak tahu apa-apa. Penyakitnya ialah mencari-cari soal dan bersilat kata, yang menyebabkan dengki, cidera, fitnah, curiga,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 5, 'percekcokan antara orang-orang yang tidak lagi berpikiran sehat dan yang kehilangan kebenaran, yang mengira ibadah itu adalah suatu sumber keuntungan.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 6, 'Memang ibadah itu kalau disertai rasa cukup, memberi keuntungan besar.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 7, 'Sebab kita tidak membawa sesuatu apa ke dalam dunia dan kitapun tidak dapat membawa apa-apa ke luar.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 8, 'Asal ada makanan dan pakaian, cukuplah.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 9, 'Tetapi mereka yang ingin kaya terjatuh ke dalam pencobaan, ke dalam jerat dan ke dalam berbagai-bagai nafsu yang hampa dan yang mencelakakan, yang menenggelamkan manusia ke dalam keruntuhan dan kebinasaan.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 10, 'Karena akar segala kejahatan ialah cinta uang. Sebab oleh memburu uanglah beberapa orang telah menyimpang dari iman dan menyiksa dirinya dengan berbagai-bagai duka.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 11, 'Tetapi engkau hai manusia Allah, jauhilah semuanya itu, kejarlah keadilan, ibadah, kesetiaan, kasih, kesabaran dan kelembutan.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 12, 'Bertandinglah dalam pertandingan iman yang benar dan rebutlah hidup yang kekal. Untuk itulah engkau telah dipanggil dan telah engkau ikrarkan ikrar yang benar di depan banyak saksi.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 13, 'Di hadapan Allah yang memberikan hidup kepada segala sesuatu dan di hadapan Kristus Yesus yang telah mengikrarkan ikrar yang benar itu juga di muka Pontius Pilatus, kuserukan kepadamu:', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 14, 'Turutilah perintah ini, dengan tidak bercacat dan tidak bercela, hingga pada saat Tuhan kita Yesus Kristus menyatakan diri-Nya,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 15, 'yaitu saat yang akan ditentukan oleh Penguasa yang satu-satunya dan yang penuh bahagia, Raja di atas segala raja dan Tuan di atas segala tuan.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 16, 'Dialah satu-satunya yang tidak takluk kepada maut, bersemayam dalam terang yang tak terhampiri. Seorangpun tak pernah melihat Dia dan memang manusia tidak dapat melihat Dia. Bagi-Nyalah hormat dan kuasa yang kekal! Amin.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 17, 'Peringatkanlah kepada orang-orang kaya di dunia ini agar mereka jangan tinggi hati dan jangan berharap pada sesuatu yang tak tentu seperti kekayaan, melainkan pada Allah yang dalam kekayaan-Nya memberikan kepada kita segala sesuatu untuk dinikmati.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 18, 'Peringatkanlah agar mereka itu berbuat baik, menjadi kaya dalam kebajikan, suka memberi dan membagi', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 19, 'dan dengan demikian mengumpulkan suatu harta sebagai dasar yang baik bagi dirinya di waktu yang akan datang untuk mencapai hidup yang sebenarnya.', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 20, 'Hai Timotius, peliharalah apa yang telah dipercayakan kepadamu. Hindarilah omongan yang kosong dan yang tidak suci dan pertentangan-pertentangan yang berasal dari apa yang disebut pengetahuan,', 'id', 'TB'),
  ('54', '1tim', '1 Timotius', 6, 21, 'karena ada beberapa orang yang mengajarkannya dan dengan demikian telah menyimpang dari iman. Kasih karunia menyertai kamu!', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 1, 'Dari Paulus, rasul Kristus Yesus oleh kehendak Allah untuk memberitakan janji tentang hidup dalam Kristus Yesus,', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 2, 'kepada Timotius, anakku yang kekasih: kasih karunia, rahmat dan damai sejahtera dari Allah Bapa dan Kristus Yesus, Tuhan kita, menyertai engkau.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 3, 'Aku mengucap syukur kepada Allah, yang kulayani dengan hati nurani yang murni seperti yang dilakukan nenek moyangku. Dan selalu aku mengingat engkau dalam permohonanku, baik siang maupun malam.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 4, 'Dan apabila aku terkenang akan air matamu yang kaucurahkan, aku ingin melihat engkau kembali supaya penuhlah kesukaanku.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 5, 'Sebab aku teringat akan imanmu yang tulus ikhlas, yaitu iman yang pertama-tama hidup di dalam nenekmu Lois dan di dalam ibumu Eunike dan yang aku yakin hidup juga di dalam dirimu.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 6, 'Karena itulah kuperingatkan engkau untuk mengobarkan karunia Allah yang ada padamu oleh penumpangan tanganku atasmu.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 7, 'Sebab Allah memberikan kepada kita bukan roh ketakutan, melainkan roh yang membangkitkan kekuatan, kasih dan ketertiban.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 8, 'Jadi janganlah malu bersaksi tentang Tuhan kita dan janganlah malu karena aku, seorang hukuman karena Dia, melainkan ikutlah menderita bagi Injil-Nya oleh kekuatan Allah.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 9, 'Dialah yang menyelamatkan kita dan memanggil kita dengan panggilan kudus, bukan berdasarkan perbuatan kita, melainkan berdasarkan maksud dan kasih karunia-Nya sendiri, yang telah dikaruniakan kepada kita dalam Kristus Yesus sebelum permulaan zaman', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 10, 'dan yang sekarang dinyatakan oleh kedatangan Juruselamat kita Yesus Kristus, yang oleh Injil telah mematahkan kuasa maut dan mendatangkan hidup yang tidak dapat binasa.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 11, 'Untuk Injil inilah aku telah ditetapkan sebagai pemberita, sebagai rasul dan sebagai guru.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 12, 'Itulah sebabnya aku menderita semuanya ini, tetapi aku tidak malu; karena aku tahu kepada siapa aku percaya dan aku yakin bahwa Dia berkuasa memeliharakan apa yang telah dipercayakan-Nya kepadaku hingga pada hari Tuhan.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 13, 'Peganglah segala sesuatu yang telah engkau dengar dari padaku sebagai contoh ajaran yang sehat dan lakukanlah itu dalam iman dan kasih dalam Kristus Yesus.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 14, 'Peliharalah harta yang indah, yang telah dipercayakan-Nya kepada kita, oleh Roh Kudus yang diam di dalam kita.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 15, 'Engkau tahu bahwa semua mereka yang di daerah Asia Kecil berpaling dari padaku; termasuk Figelus dan Hermogenes.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 16, 'Tuhan kiranya mengaruniakan rahmat-Nya kepada keluarga Onesiforus yang telah berulang-ulang menyegarkan hatiku. Ia tidak malu menjumpai aku di dalam penjara.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 17, 'Ketika di Roma, ia berusaha mencari aku dan sudah juga menemui aku.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 1, 18, 'Kiranya Tuhan menunjukkan rahmat-Nya kepadanya pada hari-Nya. Betapa banyaknya pelayanan yang ia lakukan di Efesus engkau lebih mengetahuinya dari padaku.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 1, 'Sebab itu, hai anakku, jadilah kuat oleh kasih karunia dalam Kristus Yesus.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 2, 'Apa yang telah engkau dengar dari padaku di depan banyak saksi, percayakanlah itu kepada orang-orang yang dapat dipercayai, yang juga cakap mengajar orang lain.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 3, 'Ikutlah menderita sebagai seorang prajurit yang baik dari Kristus Yesus.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 4, 'Seorang prajurit yang sedang berjuang tidak memusingkan dirinya dengan soal-soal penghidupannya, supaya dengan demikian ia berkenan kepada komandannya.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 5, 'Seorang olahragawan hanya dapat memperoleh mahkota sebagai juara, apabila ia bertanding menurut peraturan-peraturan olahraga.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 6, 'Seorang petani yang bekerja keras haruslah yang pertama menikmati hasil usahanya.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 7, 'Perhatikanlah apa yang kukatakan; Tuhan akan memberi kepadamu pengertian dalam segala sesuatu.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 8, 'Ingatlah ini: Yesus Kristus, yang telah bangkit dari antara orang mati, yang telah dilahirkan sebagai keturunan Daud, itulah yang kuberitakan dalam Injilku.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 9, 'Karena pemberitaan Injil inilah aku menderita, malah dibelenggu seperti seorang penjahat, tetapi firman Allah tidak terbelenggu.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 10, 'Karena itu aku sabar menanggung semuanya itu bagi orang-orang pilihan Allah, supaya mereka juga mendapat keselamatan dalam Kristus Yesus dengan kemuliaan yang kekal.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 11, 'Benarlah perkataan ini: "Jika kita mati dengan Dia, kitapun akan hidup dengan Dia;', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 12, 'jika kita bertekun, kitapun akan ikut memerintah dengan Dia; jika kita menyangkal Dia, Diapun akan menyangkal kita;', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 13, 'jika kita tidak setia, Dia tetap setia, karena Dia tidak dapat menyangkal diri-Nya."', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 14, 'Ingatkanlah dan pesankanlah semuanya itu dengan sungguh-sungguh kepada mereka di hadapan Allah, agar jangan mereka bersilat kata, karena hal itu sama sekali tidak berguna, malah mengacaukan orang yang mendengarnya.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 15, 'Usahakanlah supaya engkau layak di hadapan Allah sebagai seorang pekerja yang tidak usah malu, yang berterus terang memberitakan perkataan kebenaran itu.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 16, 'Tetapi hindarilah omongan yang kosong dan yang tak suci yang hanya menambah kefasikan.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 17, 'Perkataan mereka menjalar seperti penyakit kanker. Di antara mereka termasuk Himeneus dan Filetus,', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 18, 'yang telah menyimpang dari kebenaran dengan mengajarkan bahwa kebangkitan kita telah berlangsung dan dengan demikian merusak iman sebagian orang.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 19, 'Tetapi dasar yang diletakkan Allah itu teguh dan meterainya ialah: "Tuhan mengenal siapa kepunyaan-Nya" dan "Setiap orang yang menyebut nama Tuhan hendaklah meninggalkan kejahatan."', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 20, 'Dalam rumah yang besar bukan hanya terdapat perabot dari emas dan perak, melainkan juga dari kayu dan tanah; yang pertama dipakai untuk maksud yang mulia dan yang terakhir untuk maksud yang kurang mulia.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 21, 'Jika seorang menyucikan dirinya dari hal-hal yang jahat, ia akan menjadi perabot rumah untuk maksud yang mulia, ia dikuduskan, dipandang layak untuk dipakai tuannya dan disediakan untuk setiap pekerjaan yang mulia.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 22, 'Sebab itu jauhilah nafsu orang muda, kejarlah keadilan, kesetiaan, kasih dan damai bersama-sama dengan mereka yang berseru kepada Tuhan dengan hati yang murni.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 23, 'Hindarilah soal-soal yang dicari-cari, yang bodoh dan tidak layak. Engkau tahu bahwa soal-soal itu menimbulkan pertengkaran,', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 24, 'sedangkan seorang hamba Tuhan tidak boleh bertengkar, tetapi harus ramah terhadap semua orang. Ia harus cakap mengajar, sabar', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 25, 'dan dengan lemah lembut dapat menuntun orang yang suka melawan, sebab mungkin Tuhan memberikan kesempatan kepada mereka untuk bertobat dan memimpin mereka sehingga mereka mengenal kebenaran,', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 2, 26, 'dan dengan demikian mereka menjadi sadar kembali, karena terlepas dari jerat Iblis yang telah mengikat mereka pada kehendaknya.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 1, 'Ketahuilah bahwa pada hari-hari terakhir akan datang masa yang sukar.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 2, 'Manusia akan mencintai dirinya sendiri dan menjadi hamba uang. Mereka akan membual dan menyombongkan diri, mereka akan menjadi pemfitnah, mereka akan berontak terhadap orang tua dan tidak tahu berterima kasih, tidak mempedulikan agama,', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 3, 'tidak tahu mengasihi, tidak mau berdamai, suka menjelekkan orang, tidak dapat mengekang diri, garang, tidak suka yang baik,', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 4, 'suka mengkhianat, tidak berpikir panjang, berlagak tahu, lebih menuruti hawa nafsu dari pada menuruti Allah.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 5, 'Secara lahiriah mereka menjalankan ibadah mereka, tetapi pada hakekatnya mereka memungkiri kekuatannya. Jauhilah mereka itu!', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 6, 'Sebab di antara mereka terdapat orang-orang yang menyelundup ke rumah orang lain dan menjerat perempuan-perempuan lemah yang sarat dengan dosa dan dikuasai oleh berbagai-bagai nafsu,', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 7, 'yang walaupun selalu ingin diajar, namun tidak pernah dapat mengenal kebenaran.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 8, 'Sama seperti Yanes dan Yambres menentang Musa, demikian juga mereka menentang kebenaran. Akal mereka bobrok dan iman mereka tidak tahan uji.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 9, 'Tetapi sudah pasti mereka tidak akan lebih maju, karena seperti dalam hal Yanes dan Yambres, kebodohan merekapun akan nyata bagi semua orang.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 10, 'Tetapi engkau telah mengikuti ajaranku, cara hidupku, pendirianku, imanku, kesabaranku, kasihku dan ketekunanku.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 11, 'Engkau telah ikut menderita penganiayaan dan sengsara seperti yang telah kuderita di Antiokhia dan di Ikonium dan di Listra. Semua penganiayaan itu kuderita dan Tuhan telah melepaskan aku dari padanya.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 12, 'Memang setiap orang yang mau hidup beribadah di dalam Kristus Yesus akan menderita aniaya,', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 13, 'sedangkan orang jahat dan penipu akan bertambah jahat, mereka menyesatkan dan disesatkan.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 14, 'Tetapi hendaklah engkau tetap berpegang pada kebenaran yang telah engkau terima dan engkau yakini, dengan selalu mengingat orang yang telah mengajarkannya kepadamu.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 15, 'Ingatlah juga bahwa dari kecil engkau sudah mengenal Kitab Suci yang dapat memberi hikmat kepadamu dan menuntun engkau kepada keselamatan oleh iman kepada Kristus Yesus.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 16, 'Segala tulisan yang diilhamkan Allah memang bermanfaat untuk mengajar, untuk menyatakan kesalahan, untuk memperbaiki kelakuan dan untuk mendidik orang dalam kebenaran.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 3, 17, 'Dengan demikian tiap-tiap manusia kepunyaan Allah diperlengkapi untuk setiap perbuatan baik.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 1, 'Di hadapan Allah dan Kristus Yesus yang akan menghakimi orang yang hidup dan yang mati, aku berpesan dengan sungguh-sungguh kepadamu demi penyataan-Nya dan demi Kerajaan-Nya:', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 2, 'Beritakanlah firman, siap sedialah baik atau tidak baik waktunya, nyatakanlah apa yang salah, tegorlah dan nasihatilah dengan segala kesabaran dan pengajaran.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 3, 'Karena akan datang waktunya, orang tidak dapat lagi menerima ajaran sehat, tetapi mereka akan mengumpulkan guru-guru menurut kehendaknya untuk memuaskan keinginan telinganya.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 4, 'Mereka akan memalingkan telinganya dari kebenaran dan membukanya bagi dongeng.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 5, 'Tetapi kuasailah dirimu dalam segala hal, sabarlah menderita, lakukanlah pekerjaan pemberita Injil dan tunaikanlah tugas pelayananmu!', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 6, 'Mengenai diriku, darahku sudah mulai dicurahkan sebagai persembahan dan saat kematianku sudah dekat.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 7, 'Aku telah mengakhiri pertandingan yang baik, aku telah mencapai garis akhir dan aku telah memelihara iman.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 8, 'Sekarang telah tersedia bagiku mahkota kebenaran yang akan dikaruniakan kepadaku oleh Tuhan, Hakim yang adil, pada hari-Nya; tetapi bukan hanya kepadaku, melainkan juga kepada semua orang yang merindukan kedatangan-Nya.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 9, 'Berusahalah supaya segera datang kepadaku,', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 10, 'karena Demas telah mencintai dunia ini dan meninggalkan aku. Ia telah berangkat ke Tesalonika. Kreskes telah pergi ke Galatia dan Titus ke Dalmatia.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 11, 'Hanya Lukas yang tinggal dengan aku. Jemputlah Markus dan bawalah ia ke mari, karena pelayanannya penting bagiku.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 12, 'Tikhikus telah kukirim ke Efesus.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 13, 'Jika engkau ke mari bawa juga jubah yang kutinggalkan di Troas di rumah Karpus dan juga kitab-kitabku, terutama perkamen itu.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 14, 'Aleksander, tukang tembaga itu, telah banyak berbuat kejahatan terhadap aku. Tuhan akan membalasnya menurut perbuatannya.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 15, 'Hendaklah engkau juga waspada terhadap dia, karena dia sangat menentang ajaran kita.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 16, 'Pada waktu pembelaanku yang pertama tidak seorangpun yang membantu aku, semuanya meninggalkan aku?kiranya hal itu jangan ditanggungkan atas mereka?,', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 17, 'tetapi Tuhan telah mendampingi aku dan menguatkan aku, supaya dengan perantaraanku Injil diberitakan dengan sepenuhnya dan semua orang bukan Yahudi mendengarkannya. Dengan demikian aku lepas dari mulut singa.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 18, 'Dan Tuhan akan melepaskan aku dari setiap usaha yang jahat. Dia akan menyelamatkan aku, sehingga aku masuk ke dalam Kerajaan-Nya di sorga. Bagi-Nyalah kemuliaan selama-lamanya! Amin.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 19, 'Salam kepada Priska dan Akwila dan kepada keluarga Onesiforus.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 20, 'Erastus tinggal di Korintus dan Trofimus kutinggalkan dalam keadaan sakit di Miletus.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 21, 'Berusahalah ke mari sebelum musim dingin. Salam dari Ebulus dan Pudes dan Linus dan Klaudia dan dari semua saudara.', 'id', 'TB'),
  ('55', '2tim', '2 Timotius', 4, 22, 'Tuhan menyertai rohmu. Kasih karunia-Nya menyertai kamu!', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 1, 'Dari Paulus, hamba Allah dan rasul Yesus Kristus untuk memelihara iman orang-orang pilihan Allah dan pengetahuan akan kebenaran seperti yang nampak dalam ibadah kita,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 2, 'dan berdasarkan pengharapan akan hidup yang kekal yang sebelum permulaan zaman sudah dijanjikan oleh Allah yang tidak berdusta,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 3, 'dan yang pada waktu yang dikehendaki-Nya telah menyatakan firman-Nya dalam pemberitaan Injil yang telah dipercayakan kepadaku sesuai dengan perintah Allah, Juruselamat kita.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 4, 'Kepada Titus, anakku yang sah menurut iman kita bersama: kasih karunia dan damai sejahtera dari Allah Bapa dan Kristus Yesus, Juruselamat kita, menyertai engkau.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 5, 'Aku telah meninggalkan engkau di Kreta dengan maksud ini, supaya engkau mengatur apa yang masih perlu diatur dan supaya engkau menetapkan penatua-penatua di setiap kota, seperti yang telah kupesankan kepadamu,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 6, 'yakni orang-orang yang tak bercacat, yang mempunyai hanya satu isteri, yang anak-anaknya hidup beriman dan tidak dapat dituduh karena hidup tidak senonoh atau hidup tidak tertib.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 7, 'Sebab sebagai pengatur rumah Allah seorang penilik jemaat harus tidak bercacat, tidak angkuh, bukan pemberang, bukan peminum, bukan pemarah, tidak serakah,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 8, 'melainkan suka memberi tumpangan, suka akan yang baik, bijaksana, adil, saleh, dapat menguasai diri', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 9, 'dan berpegang kepada perkataan yang benar, yang sesuai dengan ajaran yang sehat, supaya ia sanggup menasihati orang berdasarkan ajaran itu dan sanggup meyakinkan penentang-penentangnya.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 10, 'Karena sudah banyak orang hidup tidak tertib, terutama di antara mereka yang berpegang pada hukum sunat. Dengan omongan yang sia-sia mereka menyesatkan pikiran.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 11, 'Orang-orang semacam itu harus ditutup mulutnya, karena mereka mengacau banyak keluarga dengan mengajarkan yang tidak-tidak untuk mendapat untung yang memalukan.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 12, 'Seorang dari kalangan mereka, nabi mereka sendiri, pernah berkata: "Dasar orang Kreta pembohong, binatang buas, pelahap yang malas."', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 13, 'Kesaksian itu benar. Karena itu tegorlah mereka dengan tegas supaya mereka menjadi sehat dalam iman,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 14, 'dan tidak lagi mengindahkan dongeng-dongeng Yahudi dan hukum-hukum manusia yang berpaling dari kebenaran.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 15, 'Bagi orang suci semuanya suci; tetapi bagi orang najis dan bagi orang tidak beriman suatupun tidak ada yang suci, karena baik akal maupun suara hati mereka najis.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 1, 16, 'Mereka mengaku mengenal Allah, tetapi dengan perbuatan mereka, mereka menyangkal Dia. Mereka keji dan durhaka dan tidak sanggup berbuat sesuatu yang baik.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 1, 'Tetapi engkau, beritakanlah apa yang sesuai dengan ajaran yang sehat:', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 2, 'Laki-laki yang tua hendaklah hidup sederhana, terhormat, bijaksana, sehat dalam iman, dalam kasih dan dalam ketekunan.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 3, 'Demikian juga perempuan-perempuan yang tua, hendaklah mereka hidup sebagai orang-orang beribadah, jangan memfitnah, jangan menjadi hamba anggur, tetapi cakap mengajarkan hal-hal yang baik', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 4, 'dan dengan demikian mendidik perempuan-perempuan muda mengasihi suami dan anak-anaknya,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 5, 'hidup bijaksana dan suci, rajin mengatur rumah tangganya, baik hati dan taat kepada suaminya, agar Firman Allah jangan dihujat orang.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 6, 'Demikian juga orang-orang muda; nasihatilah mereka supaya mereka menguasai diri dalam segala hal', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 7, 'dan jadikanlah dirimu sendiri suatu teladan dalam berbuat baik. Hendaklah engkau jujur dan bersungguh-sungguh dalam pengajaranmu,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 8, 'sehat dan tidak bercela dalam pemberitaanmu sehingga lawan menjadi malu, karena tidak ada hal-hal buruk yang dapat mereka sebarkan tentang kita.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 9, 'Hamba-hamba hendaklah taat kepada tuannya dalam segala hal dan berkenan kepada mereka, jangan membantah,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 10, 'jangan curang, tetapi hendaklah selalu tulus dan setia, supaya dengan demikian mereka dalam segala hal memuliakan ajaran Allah, Juruselamat kita.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 11, 'Karena kasih karunia Allah yang menyelamatkan semua manusia sudah nyata.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 12, 'Ia mendidik kita supaya kita meninggalkan kefasikan dan keinginan-keingina duniawi dan supaya kita hidup bijaksana, adil dan beribadah di dalam dunia sekarang ini', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 13, 'dengan menantikan penggenapan pengharapan kita yang penuh bahagia dan penyataan kemuliaan Allah yang Mahabesar dan Juruselamat kita Yesus Kristus,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 14, 'yang telah menyerahkan diri-Nya bagi kita untuk membebaskan kita dari segala kejahatan dan untuk menguduskan bagi diri-Nya suatu umat, kepunyaan-Nya sendiri, yang rajin berbuat baik.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 2, 15, 'Beritakanlah semuanya itu, nasihatilah dan yakinkanlah orang dengan segala kewibawaanmu. Janganlah ada orang yang menganggap engkau rendah.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 1, 'Ingatkanlah mereka supaya mereka tunduk pada pemerintah dan orang-orang yang berkuasa, taat dan siap untuk melakukan setiap pekerjaan yang baik.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 2, 'Janganlah mereka memfitnah, janganlah mereka bertengkar, hendaklah mereka selalu ramah dan bersikap lemah lembut terhadap semua orang.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 3, 'Karena dahulu kita juga hidup dalam kejahilan: tidak taat, sesat, menjadi hamba berbagai-bagai nafsu dan keinginan, hidup dalam kejahatan dan kedengkian, keji, saling membenci.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 4, 'Tetapi ketika nyata kemurahan Allah, Juruselamat kita, dan kasih-Nya kepada manusia,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 5, 'pada waktu itu Dia telah menyelamatkan kita, bukan karena perbuatan baik yang telah kita lakukan, tetapi karena rahmat-Nya oleh permandian kelahiran kembali dan oleh pembaharuan yang dikerjakan oleh Roh Kudus,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 6, 'yang sudah dilimpahkan-Nya kepada kita oleh Yesus Kristus, Juruselamat kita,', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 7, 'supaya kita, sebagai orang yang dibenarkan oleh kasih karunia-Nya, berhak menerima hidup yang kekal, sesuai dengan pengharapan kita.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 8, 'Perkataan ini benar dan aku mau supaya engkau dengan yakin menguatkannya, agar mereka yang sudah percaya kepada Allah sungguh-sungguh berusaha melakukan pekerjaan yang baik. Itulah yang baik dan berguna bagi manusia.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 9, 'Tetapi hindarilah persoalan yang dicari-cari dan yang bodoh, persoalan silsilah, percekcokan dan pertengkaran mengenai hukum Taurat, karena semua itu tidak berguna dan sia-sia belaka.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 10, 'Seorang bidat yang sudah satu dua kali kaunasihati, hendaklah engkau jauhi.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 11, 'Engkau tahu bahwa orang yang semacam itu benar-benar sesat dan dengan dosanya menghukum dirinya sendiri.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 12, 'Segera sesudah kukirim Artemas atau Tikhikus kepadamu, berusahalah datang kepadaku di Nikopolis, karena sudah kuputuskan untuk tinggal di tempat itu selama musim dingin ini.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 13, 'Tolonglah sebaik-baiknya Zenas, ahli Taurat itu, dan Apolos, dalam perjalanan mereka, agar mereka jangan kekurangan sesuatu apa.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 14, 'Dan biarlah orang-orang kita juga belajar melakukan pekerjaan yang baik untuk dapat memenuhi keperluan hidup yang pokok, supaya hidup mereka jangan tidak berbuah.', 'id', 'TB'),
  ('56', 'tit', 'Titus', 3, 15, 'Salam dari semua orang yang bersama aku di sini dan sampaikanlah salamku kepada mereka yang mengasihi kami di dalam iman. Kasih karunia menyertai kamu sekalian!', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 1, 'Dari Paulus, seorang hukuman karena Kristus Yesus dan dari Timotius saudara kita, kepada Filemon yang kekasih, teman sekerja kami', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 2, 'dan kepada Apfia saudara perempuan kita dan kepada Arkhipus, teman seperjuangan kita dan kepada jemaat di rumahmu:', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 3, 'Kasih karunia dan damai sejahtera dari Allah, Bapa kita dan dari Tuhan Yesus Kristus menyertai kamu.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 4, 'Aku mengucap syukur kepada Allahku, setiap kali aku mengingat engkau dalam doaku,', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 5, 'karena aku mendengar tentang kasihmu kepada semua orang kudus dan tentang imanmu kepada Tuhan Yesus.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 6, 'Dan aku berdoa, agar persekutuanmu di dalam iman turut mengerjakan pengetahuan akan yang baik di antara kita untuk Kristus.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 7, 'Dari kasihmu sudah kuperoleh kegembiraan besar dan kekuatan, sebab hati orang-orang kudus telah kauhiburkan, saudaraku.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 8, 'Karena itu, sekalipun di dalam Kristus aku mempunyai kebebasan penuh untuk memerintahkan kepadamu apa yang harus engkau lakukan,', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 9, 'tetapi mengingat kasihmu itu, lebih baik aku memintanya dari padamu. Aku, Paulus, yang sudah menjadi tua, lagipula sekarang dipenjarakan karena Kristus Yesus,', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 10, 'mengajukan permintaan kepadamu mengenai anakku yang kudapat selagi aku dalam penjara, yakni Onesimus', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 11, '?dahulu memang dia tidak berguna bagimu, tetapi sekarang sangat berguna baik bagimu maupun bagiku.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 12, 'Dia kusuruh kembali kepadamu?dia, yaitu buah hatiku?.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 13, 'Sebenarnya aku mau menahan dia di sini sebagai gantimu untuk melayani aku selama aku dipenjarakan karena Injil,', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 14, 'tetapi tanpa persetujuanmu, aku tidak mau berbuat sesuatu, supaya yang baik itu jangan engkau lakukan seolah-olah dengan paksa, melainkan dengan sukarela.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 15, 'Sebab mungkin karena itulah dia dipisahkan sejenak dari padamu, supaya engkau dapat menerimanya untuk selama-lamanya,', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 16, 'bukan lagi sebagai hamba, melainkan lebih dari pada hamba, yaitu sebagai saudara yang kekasih, bagiku sudah demikian, apalagi bagimu, baik secara manusia maupun di dalam Tuhan.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 17, 'Kalau engkau menganggap aku temanmu seiman, terimalah dia seperti aku sendiri.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 18, 'Dan kalau dia sudah merugikan engkau ataupun berhutang padamu, tanggungkanlah semuanya itu kepadaku?', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 19, 'aku, Paulus, menjaminnya dengan tulisan tanganku sendiri: Aku akan membayarnya?agar jangan kukatakan: "Tanggungkanlah semuanya itu kepadamu!" ?karena engkau berhutang padaku, yaitu dirimu sendiri.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 20, 'Ya saudaraku, semoga engkau berguna bagiku di dalam Tuhan: Hiburkanlah hatiku di dalam Kristus!', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 21, 'Dengan percaya kepada ketaatanmu, kutuliskan ini kepadamu. Aku tahu, lebih dari pada permintaanku ini akan kaulakukan.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 22, 'Dalam pada itu bersedialah juga memberi tumpangan kepadaku, karena aku harap oleh doamu aku akan dikembalikan kepadamu.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 23, 'Salam kepadamu dari Epafras, temanku sepenjara karena Kristus Yesus,', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 24, 'dan dari Markus, Aristarkhus, Demas dan Lukas, teman-teman sekerjaku.', 'id', 'TB'),
  ('57', 'flm', 'Filemon', 1, 25, 'Kasih karunia Tuhan Yesus Kristus menyertai roh kamu!', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 1, 'Setelah pada zaman dahulu Allah berulang kali dan dalam pelbagai cara berbicara kepada nenek moyang kita dengan perantaraan nabi-nabi,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 2, 'maka pada zaman akhir ini Ia telah berbicara kepada kita dengan perantaraan Anak-Nya, yang telah Ia tetapkan sebagai yang berhak menerima segala yang ada. Oleh Dia Allah telah menjadikan alam semesta.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 3, 'Ia adalah cahaya kemuliaan Allah dan gambar wujud Allah dan menopang segala yang ada dengan firman-Nya yang penuh kekuasaan. Dan setelah Ia selesai mengadakan penyucian dosa, Ia duduk di sebelah kanan Yang Mahabesar, di tempat yang tinggi,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 4, 'jauh lebih tinggi dari pada malaikat-malaikat, sama seperti nama yang dikaruniakan kepada-Nya jauh lebih indah dari pada nama mereka.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 5, 'Karena kepada siapakah di antara malaikat-malaikat itu pernah Ia katakan: "Anak-Ku Engkau! Engkau telah Kuperanakkan pada hari ini?" dan "Aku akan menjadi Bapa-Nya, dan Ia akan menjadi Anak-Ku?"', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 6, 'Dan ketika Ia membawa pula Anak-Nya yang sulung ke dunia, Ia berkata: "Semua malaikat Allah harus menyembah Dia."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 7, 'Dan tentang malaikat-malaikat Ia berkata: "Yang membuat malaikat-malaikat-N menjadi badai dan pelayan-pelayan-Nya menjadi nyala api."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 8, 'Tetapi tentang Anak Ia berkata: "Takhta-Mu, ya Allah, tetap untuk seterusnya dan selamanya, dan tongkat kerajaan-Mu adalah tongkat kebenaran.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 9, 'Engkau mencintai keadilan dan membenci kefasikan; sebab itu Allah, Allah-Mu telah mengurapi Engkau dengan minyak sebagai tanda kesukaan, melebihi teman-teman sekutu-Mu."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 10, 'Dan: "Pada mulanya, ya Tuhan, Engkau telah meletakkan dasar bumi, dan langit adalah buatan tangan-Mu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 11, 'Semuanya itu akan binasa, tetapi Engkau tetap ada, dan semuanya itu akan menjadi usang seperti pakaian;', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 12, 'seperti jubah akan Engkau gulungkan mereka, dan seperti persalinan mereka akan diubah, tetapi Engkau tetap sama, dan tahun-tahun-Mu tidak berkesudahan."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 13, 'Dan kepada siapakah di antara malaikat itu pernah Ia berkata: "Duduklah di sebelah kanan-Ku, sampai Kubuat musuh-musuh-Mu menjadi tumpuan kaki-Mu?"', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 1, 14, 'Bukankah mereka semua adalah roh-roh yang melayani, yang diutus untuk melayani mereka yang harus memperoleh keselamatan?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 1, 'Karena itu harus lebih teliti kita memperhatikan apa yang telah kita dengar, supaya kita jangan hanyut dibawa arus.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 2, 'Sebab kalau firman yang dikatakan dengan perantaraan malaikat-malaikat tetap berlaku, dan setiap pelanggaran dan ketidaktaatan mendapat balasan yang setimpal,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 3, 'bagaimanakah kita akan luput, jikalau kita menyia-nyiakan keselamatan yang sebesar itu, yang mula-mula diberitakan oleh Tuhan dan oleh mereka yang telah mendengarnya, kepada kita dengan cara yang dapat dipercayai, sedangkan', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 4, 'Allah meneguhkan kesaksian mereka oleh tanda-tanda dan mujizat-mujizat dan oleh berbagai-bagai penyataan kekuasaan dan karena Roh Kudus, yang dibagi-bagikan-Nya menurut kehendak-Nya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 5, 'Sebab bukan kepada malaikat-malaikat telah Ia taklukkan dunia yang akan datang, yang kita bicarakan ini.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 6, 'Ada orang yang pernah memberi kesaksian di dalam suatu nas, katanya: "Apakah manusia, sehingga Engkau mengingatnya, atau anak manusia, sehingga Engkau mengindahkannya?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 7, 'Namun Engkau telah membuatnya untuk waktu yang singkat sedikit lebih rendah dari pada malaikat-malaikat, dan telah memahkotainya dengan kemuliaan dan hormat,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 8, 'segala sesuatu telah Engkau taklukkan di bawah kaki-Nya." Sebab dalam menaklukkan segala sesuatu kepada-Nya, tidak ada suatupun yang Ia kecualikan, yang tidak takluk kepada-Nya. Tetapi sekarang ini belum kita lihat, bahwa segala sesuatu telah ditaklukkan kepada-Nya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 9, 'Tetapi Dia, yang untuk waktu yang singkat dibuat sedikit lebih rendah dari pada malaikat-malaikat, yaitu Yesus, kita lihat, yang oleh karena penderitaan maut, dimahkotai dengan kemuliaan dan hormat, supaya oleh kasih karunia Allah Ia mengalami maut bagi semua manusia.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 10, 'Sebab memang sesuai dengan keadaan Allah?yang bagi-Nya dan oleh-Nya segala sesuatu dijadikan?,yaitu Allah yang membawa banyak orang kepada kemuliaan, juga menyempurnakan Yesus, yang memimpin mereka kepada keselamatan, dengan penderitaan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 11, 'Sebab Ia yang menguduskan dan mereka yang dikuduskan, mereka semua berasal dari Satu; itulah sebabnya Ia tidak malu menyebut mereka saudara,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 12, 'kata-Nya: "Aku akan memberitakan nama-Mu kepada saudara-saudara-Ku, dan memuji-muji Engkau di tengah-tengah jemaat,"', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 13, 'dan lagi: "Aku akan menaruh kepercayaan kepada-Nya," dan lagi: "Sesungguhnya, inilah Aku dan anak-anak yang telah diberikan Allah kepada-Ku."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 14, 'Karena anak-anak itu adalah anak-anak dari darah dan daging, maka Ia juga menjadi sama dengan mereka dan mendapat bagian dalam keadaan mereka, supaya oleh kematian-Nya Ia memusnahkan dia, yaitu Iblis, yang berkuasa atas maut;', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 15, 'dan supaya dengan jalan demikian Ia membebaskan mereka yang seumur hidupnya berada dalam perhambaan oleh karena takutnya kepada maut.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 16, 'Sebab sesungguhnya, bukan malaikat-malaikat yang Ia kasihani, tetapi keturunan Abraham yang Ia kasihani.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 17, 'Itulah sebabnya, maka dalam segala hal Ia harus disamakan dengan saudara-saudara-Nya, supaya Ia menjadi Imam Besar yang menaruh belas kasihan dan yang setia kepada Allah untuk mendamaikan dosa seluruh bangsa.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 2, 18, 'Sebab oleh karena Ia sendiri telah menderita karena pencobaan, maka Ia dapat menolong mereka yang dicobai.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 1, 'Sebab itu, hai saudara-saudara yang kudus, yang mendapat bagian dalam panggilan sorgawi, pandanglah kepada Rasul dan Imam Besar yang kita akui, yaitu Yesus,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 2, 'yang setia kepada Dia yang telah menetapkan-Nya, sebagaimana Musapun setia dalam segenap rumah-Nya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 3, 'Sebab Ia dipandang layak mendapat kemuliaan lebih besar dari pada Musa, sama seperti ahli bangunan lebih dihormati dari pada rumah yang dibangunnya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 4, 'Sebab setiap rumah dibangun oleh seorang ahli bangunan, tetapi ahli bangunan segala sesuatu ialah Allah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 5, 'Dan Musa memang setia dalam segenap rumah Allah sebagai pelayan untuk memberi kesaksian tentang apa yang akan diberitakan kemudian,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 6, 'tetapi Kristus setia sebagai Anak yang mengepalai rumah-Nya; dan rumah-Nya ialah kita, jika kita sampai kepada akhirnya teguh berpegang pada kepercayaan dan pengharapan yang kita megahkan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 7, 'Sebab itu, seperti yang dikatakan Roh Kudus: "Pada hari ini, jika kamu mendengar suara-Nya,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 8, 'janganlah keraskan hatimu seperti dalam kegeraman pada waktu pencobaan di padang gurun,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 9, 'di mana nenek moyangmu mencobai Aku dengan jalan menguji Aku, sekalipun mereka melihat perbuatan-perbuatan-Ku, empat puluh tahun lamanya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 10, 'Itulah sebabnya Aku murka kepada angkatan itu, dan berkata: Selalu mereka sesat hati, dan mereka tidak mengenal jalan-Ku,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 11, 'sehingga Aku bersumpah dalam murka-Ku: Mereka takkan masuk ke tempat perhentian-Ku."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 12, 'Waspadalah, hai saudara-saudara, supaya di antara kamu jangan terdapat seorang yang hatinya jahat dan yang tidak percaya oleh karena ia murtad dari Allah yang hidup.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 13, 'Tetapi nasihatilah seorang akan yang lain setiap hari, selama masih dapat dikatakan "hari ini", supaya jangan ada di antara kamu yang menjadi tegar hatinya karena tipu daya dosa.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 14, 'Karena kita telah beroleh bagian di dalam Kristus, asal saja kita teguh berpegang sampai kepada akhirnya pada keyakinan iman kita yang semula.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 15, 'Tetapi apabila pernah dikatakan: "Pada hari ini, jika kamu mendengar suara-Nya, janganlah keraskan hatimu seperti dalam kegeraman",', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 16, 'siapakah mereka yang membangkitkan amarah Allah, sekalipun mereka mendengar suara-Nya? Bukankah mereka semua yang keluar dari Mesir di bawah pimpinan Musa?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 17, 'Dan siapakah yang Ia murkai empat puluh tahun lamanya? Bukankah mereka yang berbuat dosa dan yang mayatnya bergelimpangan di padang gurun?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 18, 'Dan siapakah yang telah Ia sumpahi, bahwa mereka takkan masuk ke tempat perhentian-Nya? Bukankah mereka yang tidak taat?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 3, 19, 'Demikianlah kita lihat, bahwa mereka tidak dapat masuk oleh karena ketidakpercayaan mereka.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 1, 'Sebab itu, baiklah kita waspada, supaya jangan ada seorang di antara kamu yang dianggap ketinggalan, sekalipun janji akan masuk ke dalam perhentian-Nya masih berlaku.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 2, 'Karena kepada kita diberitakan juga kabar kesukaan sama seperti kepada mereka, tetapi firman pemberitaan itu tidak berguna bagi mereka, karena tidak bertumbuh bersama-sama oleh iman dengan mereka yang mendengarnya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 3, 'Sebab kita yang beriman, akan masuk ke tempat perhentian seperti yang Ia katakan: "Sehingga Aku bersumpah dalam murka-Ku: Mereka takkan masuk ke tempat perhentian-Ku," sekalipun pekerjaan-Nya sudah selesai sejak dunia dijadikan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 4, 'Sebab tentang hari ketujuh pernah dikatakan di dalam suatu nas: "Dan Allah berhenti pada hari ketujuh dari segala pekerjaan-Nya."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 5, 'Dan dalam nas itu kita baca: "Mereka takkan masuk ke tempat perhentian-Ku."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 6, 'Jadi sudah jelas, bahwa ada sejumlah orang akan masuk ke tempat perhentian itu, sedangkan mereka yang kepadanya lebih dahulu diberitakan kabar kesukaan itu, tidak masuk karena ketidaktaatan mereka.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 7, 'Sebab itu Ia menetapkan pula suatu hari, yaitu "hari ini", ketika Ia setelah sekian lama berfirman dengan perantaraan Daud seperti dikatakan di atas: "Pada hari ini, jika kamu mendengar suara-Nya, janganlah keraskan hatimu!"', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 8, 'Sebab, andaikata Yosua telah membawa mereka masuk ke tempat perhentian, pasti Allah tidak akan berkata-kata kemudian tentang suatu hari lain.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 9, 'Jadi masih tersedia suatu hari perhentian, hari ketujuh, bagi umat Allah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 10, 'Sebab barangsiapa telah masuk ke tempat perhentian-Nya, ia sendiri telah berhenti dari segala pekerjaannya, sama seperti Allah berhenti dari pekerjaan-Nya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 11, 'Karena itu baiklah kita berusaha untuk masuk ke dalam perhentian itu, supaya jangan seorangpun jatuh karena mengikuti contoh ketidaktaatan itu juga.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 12, 'Sebab firman Allah hidup dan kuat dan lebih tajam dari pada pedang bermata dua manapun; ia menusuk amat dalam sampai memisahkan jiwa dan roh, sendi-sendi dan sumsum; ia sanggup membedakan pertimbangan dan pikiran hati kita.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 13, 'Dan tidak ada suatu makhlukpun yang tersembunyi di hadapan-Nya, sebab segala sesuatu telanjang dan terbuka di depan mata Dia, yang kepada-Nya kita harus memberikan pertanggungan jawab.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 14, 'Karena kita sekarang mempunyai Imam Besar Agung, yang telah melintasi semua langit, yaitu Yesus, Anak Allah, baiklah kita teguh berpegang pada pengakuan iman kita.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 15, 'Sebab Imam Besar yang kita punya, bukanlah imam besar yang tidak dapat turut merasakan kelemahan-kelemahan kita, sebaliknya sama dengan kita, Ia telah dicobai, hanya tidak berbuat dosa.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 4, 16, 'Sebab itu marilah kita dengan penuh keberanian menghampiri takhta kasih karunia, supaya kita menerima rahmat dan menemukan kasih karunia untuk mendapat pertolongan kita pada waktunya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 1, 'Sebab setiap imam besar, yang dipilih dari antara manusia, ditetapkan bagi manusia dalam hubungan mereka dengan Allah, supaya ia mempersembahkan persembahan dan korban karena dosa.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 2, 'Ia harus dapat mengerti orang-orang yang jahil dan orang-orang yang sesat, karena ia sendiri penuh dengan kelemahan,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 3, 'yang mengharuskannya untuk mempersembahkan korban karena dosa, bukan saja bagi umat, tetapi juga bagi dirinya sendiri.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 4, 'Dan tidak seorangpun yang mengambil kehormatan itu bagi dirinya sendiri, tetapi dipanggil untuk itu oleh Allah, seperti yang telah terjadi dengan Harun.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 5, 'Demikian pula Kristus tidak memuliakan diri-Nya sendiri dengan menjadi Imam Besar, tetapi dimuliakan oleh Dia yang berfirman kepada-Nya: "Anak-Ku Engkau! Engkau telah Kuperanakkan pada hari ini",', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 6, 'sebagaimana firman-Nya dalam suatu nas lain: "Engkau adalah Imam untuk selama-lamanya, menurut peraturan Melkisedek."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 7, 'Dalam hidup-Nya sebagai manusia, Ia telah mempersembahkan doa dan permohonan dengan ratap tangis dan keluhan kepada Dia, yang sanggup menyelamatkan-Nya dari maut, dan karena kesalehan-Nya Ia telah didengarkan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 8, 'Dan sekalipun Ia adalah Anak, Ia telah belajar menjadi taat dari apa yang telah diderita-Nya,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 9, 'dan sesudah Ia mencapai kesempurnaan-Nya, Ia menjadi pokok keselamatan yang abadi bagi semua orang yang taat kepada-Nya,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 10, 'dan Ia dipanggil menjadi Imam Besar oleh Allah, menurut peraturan Melkisedek.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 11, 'Tentang hal itu banyak yang harus kami katakan, tetapi yang sukar untuk dijelaskan, karena kamu telah lamban dalam hal mendengarkan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 12, 'Sebab sekalipun kamu, ditinjau dari sudut waktu, sudah seharusnya menjadi pengajar, kamu masih perlu lagi diajarkan asas-asas pokok dari penyataan Allah, dan kamu masih memerlukan susu, bukan makanan keras.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 13, 'Sebab barangsiapa masih memerlukan susu ia tidak memahami ajaran tentang kebenaran, sebab ia adalah anak kecil.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 5, 14, 'Tetapi makanan keras adalah untuk orang-orang dewasa, yang karena mempunyai pancaindera yang terlatih untuk membedakan yang baik dari pada yang jahat.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 1, 'Sebab itu marilah kita tinggalkan asas-asas pertama dari ajaran tentang Kristus dan beralih kepada perkembangannya yang penuh. Janganlah kita meletakkan lagi dasar pertobatan dari perbuatan-perbuatan yang sia-sia, dan dasar kepercayaan kepada Allah,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 2, 'yaitu ajaran tentang pelbagai pembaptisan, penumpangan tangan, kebangkitan orang-orang mati dan hukuman kekal.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 3, 'Dan itulah yang akan kita perbuat, jika Allah mengizinkannya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 4, 'Sebab mereka yang pernah diterangi hatinya, yang pernah mengecap karunia sorgawi, dan yang pernah mendapat bagian dalam Roh Kudus,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 5, 'dan yang mengecap firman yang baik dari Allah dan karunia-karunia dunia yang akan datang,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 6, 'namun yang murtad lagi, tidak mungkin dibaharui sekali lagi sedemikian, hingga mereka bertobat, sebab mereka menyalibkan lagi Anak Allah bagi diri mereka dan menghina-Nya di muka umum.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 7, 'Sebab tanah yang menghisap air hujan yang sering turun ke atasnya, dan yang menghasilkan tumbuh-tumbuhan yang berguna bagi mereka yang mengerjakannya, menerima berkat dari Allah;', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 8, 'tetapi jikalau tanah itu menghasilkan semak duri dan rumput duri, tidaklah ia berguna dan sudah dekat pada kutuk, yang berakhir dengan pembakaran.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 9, 'Tetapi, hai saudara-saudaraku yang kekasih, sekalipun kami berkata demikian tentang kamu, kami yakin, bahwa kamu memiliki sesuatu yang lebih baik, yang mengandung keselamatan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 10, 'Sebab Allah bukan tidak adil, sehingga Ia lupa akan pekerjaanmu dan kasihmu yang kamu tunjukkan terhadap nama-Nya oleh pelayanan kamu kepada orang-orang kudus, yang masih kamu lakukan sampai sekarang.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 11, 'Tetapi kami ingin, supaya kamu masing-masing menunjukkan kesungguhan yang sama untuk menjadikan pengharapanmu suatu milik yang pasti, sampai pada akhirnya,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 12, 'agar kamu jangan menjadi lamban, tetapi menjadi penurut-penurut mereka yang oleh iman dan kesabaran mendapat bagian dalam apa yang dijanjikan Allah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 13, 'Sebab ketika Allah memberikan janji-Nya kepada Abraham, Ia bersumpah demi diri-Nya sendiri, karena tidak ada orang yang lebih tinggi dari pada-Nya,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 14, 'kata-Nya: "Sesungguhnya Aku akan memberkati engkau berlimpah-limpah dan akan membuat engkau sangat banyak."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 15, 'Abraham menanti dengan sabar dan dengan demikian ia memperoleh apa yang dijanjikan kepadanya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 16, 'Sebab manusia bersumpah demi orang yang lebih tinggi, dan sumpah itu menjadi suatu pengokohan baginya, yang mengakhiri segala bantahan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 17, 'Karena itu, untuk lebih meyakinkan mereka yang berhak menerima janji itu akan kepastian putusan-Nya, Allah telah mengikat diri-Nya dengan sumpah,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 18, 'supaya oleh dua kenyataan yang tidak berubah-ubah, tentang mana Allah tidak mungkin berdusta, kita yang mencari perlindungan, beroleh dorongan yang kuat untuk menjangkau pengharapan yang terletak di depan kita.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 19, 'Pengharapan itu adalah sauh yang kuat dan aman bagi jiwa kita, yang telah dilabuhkan sampai ke belakang tabir,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 6, 20, 'di mana Yesus telah masuk sebagai Perintis bagi kita, ketika Ia, menurut peraturan Melkisedek, menjadi Imam Besar sampai selama-lamanya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 1, 'Sebab Melkisedek adalah raja Salem dan imam Allah Yang Mahatinggi; ia pergi menyongsong Abraham ketika Abraham kembali dari mengalahkan raja-raja, dan memberkati dia.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 2, 'Kepadanyapun Abraham memberikan sepersepuluh dari semuanya. Menurut arti namanya Melkisedek adalah pertama-tama raja kebenaran, dan juga raja Salem, yaitu raja damai sejahtera.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 3, 'Ia tidak berbapa, tidak beribu, tidak bersilsilah, harinya tidak berawal dan hidupnya tidak berkesudahan, dan karena ia dijadikan sama dengan Anak Allah, ia tetap menjadi imam sampai selama-lamanya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 4, 'Camkanlah betapa besarnya orang itu, yang kepadanya Abraham, bapa leluhur kita, memberikan sepersepuluh dari segala rampasan yang paling baik.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 5, 'Dan mereka dari anak-anak Lewi, yang menerima jabatan imam, mendapat tugas, menurut hukum Taurat, untuk memungut persepuluhan dari umat Israel, yaitu dari saudara-saudara mereka, sekalipun mereka ini juga adalah keturunan Abraham.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 6, 'Tetapi Melkisedek, yang bukan keturunan mereka, memungut persepuluhan dari Abraham dan memberkati dia, walaupun ia adalah pemilik janji.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 7, 'Memang tidak dapat disangkal, bahwa yang lebih rendah diberkati oleh yang lebih tinggi.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 8, 'Dan di sini manusia-manusia fana menerima persepuluhan, dan di sana Ia, yang tentang Dia diberi kesaksian, bahwa Ia hidup.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 9, 'Maka dapatlah dikatakan, bahwa dengan perantaraan Abraham dipungut juga persepuluhan dari Lewi, yang berhak menerima persepuluhan,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 10, 'sebab ia masih berada dalam tubuh bapa leluhurnya, ketika Melkisedek menyongsong bapa leluhurnya itu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 11, 'Karena itu, andaikata oleh imamat Lewi telah tercapai kesempurnaan?sebab karena imamat itu umat Israel telah menerima Taurat?apakah sebabnya masih perlu seorang lain ditetapkan menjadi imam besar menurut peraturan Melkisedek dan yang tentang dia tidak dikatakan menurut peraturan Harun?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 12, 'Sebab, jikalau imamat berubah, dengan sendirinya akan berubah pula hukum Taurat itu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 13, 'Sebab Ia, yang dimaksudkan di sini, termasuk suku lain; dari suku ini tidak ada seorangpun yang pernah melayani di mezbah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 14, 'Sebab telah diketahui semua orang, bahwa Tuhan kita berasal dari suku Yehuda dan mengenai suku itu Musa tidak pernah mengatakan suatu apapun tentang imam-imam.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 15, 'Dan hal itu jauh lebih nyata lagi, jikalau ditetapkan seorang imam lain menurut cara Melkisedek,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 16, 'yang menjadi imam bukan berdasarkan peraturan-peraturan manusia, tetapi berdasarkan hidup yang tidak dapat binasa.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 17, 'Sebab tentang Dia diberi kesaksian: "Engkau adalah Imam untuk selama-lamanya, menurut peraturan Melkisedek."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 18, 'Memang suatu hukum yang dikeluarkan dahulu dibatalkan, kalau hukum itu tidak mempunyai kekuatan dan karena itu tidak berguna,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 19, '?sebab hukum Taurat sama sekali tidak membawa kesempurnaan?tetapi sekarang ditimbulkan pengharapan yang lebih baik, yang mendekatkan kita kepada Allah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 20, 'Dan sama seperti hal ini tidak terjadi tanpa sumpah?memang mereka telah menjadi imam tanpa sumpah,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 21, 'tetapi Ia dengan sumpah, diucapkan oleh Dia yang berfirman kepada-Nya: "Tuhan telah bersumpah dan Ia tidak akan menyesal: Engkau adalah Imam untuk selama-lamanya" ?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 22, 'demikian pula Yesus adalah jaminan dari suatu perjanjian yang lebih kuat.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 23, 'Dan dalam jumlah yang besar mereka telah menjadi imam, karena mereka dicegah oleh maut untuk tetap menjabat imam.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 24, 'Tetapi, karena Ia tetap selama-lamanya, imamat-Nya tidak dapat beralih kepada orang lain.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 25, 'Karena itu Ia sanggup juga menyelamatkan dengan sempurna semua orang yang oleh Dia datang kepada Allah. Sebab Ia hidup senantiasa untuk menjadi Pengantara mereka.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 26, 'Sebab Imam Besar yang demikianlah yang kita perlukan: yaitu yang saleh, tanpa salah, tanpa noda, yang terpisah dari orang-orang berdosa dan lebih tinggi dari pada tingkat-tingkat sorga,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 27, 'yang tidak seperti imam-imam besar lain, yang setiap hari harus mempersembahkan korban untuk dosanya sendiri dan sesudah itu barulah untuk dosa umatnya, sebab hal itu telah dilakukan-Nya satu kali untuk selama-lamanya, ketika Ia mempersembahkan diri-Nya sendiri sebagai korban.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 7, 28, 'Sebab hukum Taurat menetapkan orang-orang yang diliputi kelemahan menjadi Imam Besar, tetapi sumpah, yang diucapkan kemudian dari pada hukum Taurat, menetapkan Anak, yang telah menjadi sempurna sampai selama-lamanya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 1, 'Inti segala yang kita bicarakan itu ialah: kita mempunyai Imam Besar yang demikian, yang duduk di sebelah kanan takhta Yang Mahabesar di sorga,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 2, 'dan yang melayani ibadah di tempat kudus, yaitu di dalam kemah sejati, yang didirikan oleh Tuhan dan bukan oleh manusia.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 3, 'Sebab setiap Imam Besar ditetapkan untuk mempersembahkan korban dan persembahan dan karena itu Yesus perlu mempunyai sesuatu untuk dipersembahkan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 4, 'Sekiranya Ia di bumi ini, Ia sama sekali tidak akan menjadi imam, karena di sini telah ada orang-orang yang mempersembahkan persembahan menurut hukum Taurat.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 5, 'Pelayanan mereka adalah gambaran dan bayangan dari apa yang ada di sorga, sama seperti yang diberitahukan kepada Musa, ketika ia hendak mendirikan kemah: "Ingatlah," demikian firman-Nya, "bahwa engkau membuat semuanya itu menurut contoh yang telah ditunjukkan kepadamu di atas gunung itu."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 6, 'Tetapi sekarang Ia telah mendapat suatu pelayanan yang jauh lebih agung, karena Ia menjadi Pengantara dari perjanjian yang lebih mulia, yang didasarkan atas janji yang lebih tinggi.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 7, 'Sebab, sekiranya perjanjian yang pertama itu tidak bercacat, tidak akan dicari lagi tempat untuk yang kedua.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 8, 'Sebab Ia menegor mereka ketika Ia berkata: "Sesungguhnya, akan datang waktunya," demikianlah firman Tuhan, "Aku akan mengadakan perjanjian baru dengan kaum Israel dan dengan kaum Yehuda,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 9, 'bukan seperti perjanjian yang telah Kuadakan dengan nenek moyang mereka, pada waktu Aku memegang tangan mereka untuk membawa mereka keluar dari tanah Mesir. Sebab mereka tidak setia kepada perjanjian-Ku, dan Aku menolak mereka," demikian firman Tuhan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 10, '"Maka inilah perjanjian yang Kuadakan dengan kaum Israel sesudah waktu itu," demikianlah firman Tuhan. "Aku akan menaruh hukum-Ku dalam akal budi mereka dan menuliskannya dalam hati mereka, maka Aku akan menjadi Allah mereka dan mereka akan menjadi umat-Ku.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 11, 'Dan mereka tidak akan mengajar lagi sesama warganya, atau sesama saudaranya dengan mengatakan: Kenallah Tuhan! Sebab mereka semua, besar kecil, akan mengenal Aku.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 12, 'Sebab Aku akan menaruh belas kasihan terhadap kesalahan mereka dan tidak lagi mengingat dosa-dosa mereka."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 8, 13, 'Oleh karena Ia berkata-kata tentang perjanjian yang baru, Ia menyatakan yang pertama sebagai perjanjian yang telah menjadi tua. Dan apa yang telah menjadi tua dan usang, telah dekat kepada kemusnahannya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 1, 'Memang perjanjian yang pertama juga mempunyai peraturan-peraturan untuk ibadah dan untuk tempat kudus buatan tangan manusia.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 2, 'Sebab ada dipersiapkan suatu kemah, yaitu bagian yang paling depan dan di situ terdapat kaki dian dan meja dengan roti sajian. Bagian ini disebut tempat yang kudus.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 3, 'Di belakang tirai yang kedua terdapat suatu kemah lagi yang disebut tempat yang maha kudus.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 4, 'Di situ terdapat mezbah pembakaran ukupan dari emas, dan tabut perjanjian, yang seluruhnya disalut dengan emas; di dalam tabut perjanjian itu tersimpan buli-buli emas berisi manna, tongkat Harun yang pernah bertunas dan loh-loh batu yang bertuliskan perjanjian,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 5, 'dan di atasnya kedua kerub kemuliaan yang menaungi tutup pendamaian. Tetapi hal ini tidak dapat kita bicarakan sekarang secara terperinci.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 6, 'Demikianlah caranya tempat yang kudus itu diatur. Maka imam-imam senantiasa masuk ke dalam kemah yang paling depan itu untuk melakukan ibadah mereka,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 7, 'tetapi ke dalam kemah yang kedua hanya Imam Besar saja yang masuk sekali setahun, dan harus dengan darah yang ia persembahkan karena dirinya sendiri dan karena pelanggaran-pelanggaran, yang dibuat oleh umatnya dengan tidak sadar.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 8, 'Dengan ini Roh Kudus menyatakan, bahwa jalan ke tempat yang kudus itu belum terbuka, selama kemah yang pertama itu masih ada.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 9, 'Itu adalah kiasan masa sekarang. Sesuai dengan itu dipersembahkan korban dan persembahan yang tidak dapat menyempurnakan mereka yang mempersembahkannya menurut hati nurani mereka,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 10, 'karena semuanya itu, di samping makanan minuman dan pelbagai macam pembasuhan, hanyalah peraturan-peraturan untuk hidup insani, yang hanya berlaku sampai tibanya waktu pembaharuan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 11, 'Tetapi Kristus telah datang sebagai Imam Besar untuk hal-hal yang baik yang akan datang: Ia telah melintasi kemah yang lebih besar dan yang lebih sempurna, yang bukan dibuat oleh tangan manusia, ?artinya yang tidak termasuk ciptaan ini, ?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 12, 'dan Ia telah masuk satu kali untuk selama-lamanya ke dalam tempat yang kudus bukan dengan membawa darah domba jantan dan darah anak lembu, tetapi dengan membawa darah-Nya sendiri. Dan dengan itu Ia telah mendapat kelepasan yang kekal.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 13, 'Sebab, jika darah domba jantan dan darah lembu jantan dan percikan abu lembu muda menguduskan mereka yang najis, sehingga mereka disucikan secara lahiriah,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 14, 'betapa lebihnya darah Kristus, yang oleh Roh yang kekal telah mempersembahkan diri-Nya sendiri kepada Allah sebagai persembahan yang tak bercacat, akan menyucikan hati nurani kita dari perbuatan-perbuatan yang sia-sia, supaya kita dapat beribadah kepada Allah yang hidup.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 15, 'Karena itu Ia adalah Pengantara dari suatu perjanjian yang baru, supaya mereka yang telah terpanggil dapat menerima bagian kekal yang dijanjikan, sebab Ia telah mati untuk menebus pelanggaran-pelanggara yang telah dilakukan selama perjanjian yang pertama.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 16, 'Sebab di mana ada wasiat, di situ harus diberitahukan tentang kematian pembuat wasiat itu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 17, 'Karena suatu wasiat barulah sah, kalau pembuat wasiat itu telah mati, sebab ia tidak berlaku, selama pembuat wasiat itu masih hidup.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 18, 'Itulah sebabnya, maka perjanjian yang pertama tidak disahkan tanpa darah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 19, 'Sebab sesudah Musa memberitahukan semua perintah hukum Taurat kepada seluruh umat, ia mengambil darah anak lembu dan darah domba jantan serta air, dan bulu merah dan hisop, lalu memerciki kitab itu sendiri dan seluruh umat,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 20, 'sambil berkata: "Inilah darah perjanjian yang ditetapkan Allah bagi kamu."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 21, 'Dan juga kemah dan semua alat untuk ibadah dipercikinya secara demikian dengan darah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 22, 'Dan hampir segala sesuatu disucikan menurut hukum Taurat dengan darah, dan tanpa penumpahan darah tidak ada pengampunan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 23, 'Jadi segala sesuatu yang melambangkan apa yang ada di sorga haruslah ditahirkan secara demikian, tetapi benda-benda sorgawi sendiri oleh persembahan-persembahan yang lebih baik dari pada itu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 24, 'Sebab Kristus bukan masuk ke dalam tempat kudus buatan tangan manusia yang hanya merupakan gambaran saja dari yang sebenarnya, tetapi ke dalam sorga sendiri untuk menghadap hadirat Allah guna kepentingan kita.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 25, 'Dan Ia bukan masuk untuk berulang-ulang mempersembahkan diri-Nya sendiri, sebagaimana Imam Besar setiap tahun masuk ke dalam tempat kudus dengan darah yang bukan darahnya sendiri.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 26, 'Sebab jika demikian Ia harus berulang-ulang menderita sejak dunia ini dijadikan. Tetapi sekarang Ia hanya satu kali saja menyatakan diri-Nya, pada zaman akhir untuk menghapuskan dosa oleh korban-Nya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 27, 'Dan sama seperti manusia ditetapkan untuk mati hanya satu kali saja, dan sesudah itu dihakimi,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 9, 28, 'demikian pula Kristus hanya satu kali saja mengorbankan diri-Nya untuk menanggung dosa banyak orang. Sesudah itu Ia akan menyatakan diri-Nya sekali lagi tanpa menanggung dosa untuk menganugerahkan keselamatan kepada mereka, yang menantikan Dia.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 1, 'Di dalam hukum Taurat hanya terdapat bayangan saja dari keselamatan yang akan datang, dan bukan hakekat dari keselamatan itu sendiri. Karena itu dengan korban yang sama, yang setiap tahun terus-menerus dipersembahkan, hukum Taurat tidak mungkin menyempurnakan mereka yang datang mengambil bagian di dalamnya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 2, 'Sebab jika hal itu mungkin, pasti orang tidak mempersembahkan korban lagi, sebab mereka yang melakukan ibadah itu tidak sadar lagi akan dosa setelah disucikan sekali untuk selama-lamanya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 3, 'Tetapi justru oleh korban-korban itu setiap tahun orang diperingatkan akan adanya dosa.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 4, 'Sebab tidak mungkin darah lembu jantan atau darah domba jantan menghapuskan dosa.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 5, 'Karena itu ketika Ia masuk ke dunia, Ia berkata: "Korban dan persembahan tidak Engkau kehendaki?tetapi Engkau telah menyediakan tubuh bagiku?.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 6, 'Kepada korban bakaran dan korban penghapus dosa Engkau tidak berkenan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 7, 'Lalu Aku berkata: Sungguh, Aku datang; dalam gulungan kitab ada tertulis tentang Aku untuk melakukan kehendak-Mu, ya Allah-Ku."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 8, 'Di atas Ia berkata: "Korban dan persembahan, korban bakaran dan korban penghapus dosa tidak Engkau kehendaki dan Engkau tidak berkenan kepadanya" ?meskipun dipersembahkan menurut hukum Taurat?.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 9, 'Dan kemudian kata-Nya: "Sungguh, Aku datang untuk melakukan kehendak-Mu." Yang pertama Ia hapuskan, supaya menegakkan yang kedua.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 10, 'Dan karena kehendak-Nya inilah kita telah dikuduskan satu kali untuk selama-lamanya oleh persembahan tubuh Yesus Kristus.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 11, 'Selanjutnya setiap imam melakukan tiap-tiap hari pelayanannya dan berulang-ulang mempersembahkan korban yang sama, yang sama sekali tidak dapat menghapuskan dosa.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 12, 'Tetapi Ia, setelah mempersembahkan hanya satu korban saja karena dosa, Ia duduk untuk selama-lamanya di sebelah kanan Allah,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 13, 'dan sekarang Ia hanya menantikan saatnya, di mana musuh-musuh-Nya akan dijadikan tumpuan kaki-Nya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 14, 'Sebab oleh satu korban saja Ia telah menyempurnakan untuk selama-lamanya mereka yang Ia kuduskan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 15, 'Dan tentang hal itu Roh Kudus juga memberi kesaksian kepada kita,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 16, 'sebab setelah Ia berfirman: "Inilah perjanjian yang akan Kuadakan dengan mereka sesudah waktu itu," Ia berfirman pula: "Aku akan menaruh hukum-Ku di dalam hati mereka dan menuliskannya dalam akal budi mereka,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 17, 'dan Aku tidak lagi mengingat dosa-dosa dan kesalahan mereka."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 18, 'Jadi apabila untuk semuanya itu ada pengampunan, tidak perlu lagi dipersembahkan korban karena dosa.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 19, 'Jadi, saudara-saudara, oleh darah Yesus kita sekarang penuh keberanian dapat masuk ke dalam tempat kudus,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 20, 'karena Ia telah membuka jalan yang baru dan yang hidup bagi kita melalui tabir, yaitu diri-Nya sendiri,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 21, 'dan kita mempunyai seorang Imam Besar sebagai kepala Rumah Allah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 22, 'Karena itu marilah kita menghadap Allah dengan hati yang tulus ikhlas dan keyakinan iman yang teguh, oleh karena hati kita telah dibersihkan dari hati nurani yang jahat dan tubuh kita telah dibasuh dengan air yang murni.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 23, 'Marilah kita teguh berpegang pada pengakuan tentang pengharapan kita, sebab Ia, yang menjanjikannya, setia.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 24, 'Dan marilah kita saling memperhatikan supaya kita saling mendorong dalam kasih dan dalam pekerjaan baik.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 25, 'Janganlah kita menjauhkan diri dari pertemuan-pertemuan ibadah kita, seperti dibiasakan oleh beberapa orang, tetapi marilah kita saling menasihati, dan semakin giat melakukannya menjelang hari Tuhan yang mendekat.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 26, 'Sebab jika kita sengaja berbuat dosa, sesudah memperoleh pengetahuan tentang kebenaran, maka tidak ada lagi korban untuk menghapus dosa itu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 27, 'Tetapi yang ada ialah kematian yang mengerikan akan penghakiman dan api yang dahsyat yang akan menghanguskan semua orang durhaka.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 28, 'Jika ada orang yang menolak hukum Musa, ia dihukum mati tanpa belas kasihan atas keterangan dua atau tiga orang saksi.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 29, 'Betapa lebih beratnya hukuman yang harus dijatuhkan atas dia, yang menginjak-injak Anak Allah, yang menganggap najis darah perjanjian yang menguduskannya, dan yang menghina Roh kasih karunia?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 30, 'Sebab kita mengenal Dia yang berkata: "Pembalasan adalah hak-Ku. Akulah yang akan menuntut pembalasan." Dan lagi: "Tuhan akan menghakimi umat-Nya."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 31, 'Ngeri benar, kalau jatuh ke dalam tangan Allah yang hidup.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 32, 'Ingatlah akan masa yang lalu. Sesudah kamu menerima terang, kamu banyak menderita oleh karena kamu bertahan dalam perjuangan yang berat,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 33, 'baik waktu kamu dijadikan tontonan oleh cercaan dan penderitaan, maupun waktu kamu mengambil bagian dalam penderitaan mereka yang diperlakukan sedemikian.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 34, 'Memang kamu telah turut mengambil bagian dalam penderitaan orang-orang hukuman dan ketika harta kamu dirampas, kamu menerima hal itu dengan sukacita, sebab kamu tahu, bahwa kamu memiliki harta yang lebih baik dan yang lebih menetap sifatnya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 35, 'Sebab itu janganlah kamu melepaskan kepercayaanmu, karena besar upah yang menantinya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 36, 'Sebab kamu memerlukan ketekunan, supaya sesudah kamu melakukan kehendak Allah, kamu memperoleh apa yang dijanjikan itu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 37, '"Sebab sedikit, bahkan sangat sedikit waktu lagi, dan Ia yang akan datang, sudah akan ada, tanpa menangguhkan kedatangan-Nya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 38, 'Tetapi orang-Ku yang benar akan hidup oleh iman, dan apabila ia mengundurkan diri, maka Aku tidak berkenan kepadanya."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 10, 39, 'Tetapi kita bukanlah orang-orang yang mengundurkan diri dan binasa, tetapi orang-orang yang percaya dan yang beroleh hidup.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 1, 'Iman adalah dasar dari segala sesuatu yang kita harapkan dan bukti dari segala sesuatu yang tidak kita lihat.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 2, 'Sebab oleh imanlah telah diberikan kesaksian kepada nenek moyang kita.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 3, 'Karena iman kita mengerti, bahwa alam semesta telah dijadikan oleh firman Allah, sehingga apa yang kita lihat telah terjadi dari apa yang tidak dapat kita lihat.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 4, 'Karena iman Habel telah mempersembahkan kepada Allah korban yang lebih baik dari pada korban Kain. Dengan jalan itu ia memperoleh kesaksian kepadanya, bahwa ia benar, karena Allah berkenan akan persembahannya itu dan karena iman ia masih berbicara, sesudah ia mati.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 5, 'Karena iman Henokh terangkat, supaya ia tidak mengalami kematian, dan ia tidak ditemukan, karena Allah telah mengangkatnya. Sebab sebelum ia terangkat, ia memperoleh kesaksian, bahwa ia berkenan kepada Allah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 6, 'Tetapi tanpa iman tidak mungkin orang berkenan kepada Allah. Sebab barangsiapa berpaling kepada Allah, ia harus percaya bahwa Allah ada, dan bahwa Allah memberi upah kepada orang yang sungguh-sungguh mencari Dia.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 7, 'Karena iman, maka Nuh?dengan petunjuk Allah tentang sesuatu yang belum kelihatan?dengan taat mempersiapkan bahtera untuk menyelamatkan keluarganya; dan karena iman itu ia menghukum dunia, dan ia ditentukan untuk menerima kebenaran, sesuai dengan imannya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 8, 'Karena iman Abraham taat, ketika ia dipanggil untuk berangkat ke negeri yang akan diterimanya menjadi milik pusakanya, lalu ia berangkat dengan tidak mengetahui tempat yang ia tujui.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 9, 'Karena iman ia diam di tanah yang dijanjikan itu seolah-olah di suatu tanah asing dan di situ ia tinggal di kemah dengan Ishak dan Yakub, yang turut menjadi ahli waris janji yang satu itu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 10, 'Sebab ia menanti-nantikan kota yang mempunyai dasar, yang direncanakan dan dibangun oleh Allah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 11, 'Karena iman ia juga dan Sara beroleh kekuatan untuk menurunkan anak cucu, walaupun usianya sudah lewat, karena ia menganggap Dia, yang memberikan janji itu setia.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 12, 'Itulah sebabnya, maka dari satu orang, malahan orang yang telah mati pucuk, terpancar keturunan besar, seperti bintang di langit dan seperti pasir di tepi laut, yang tidak terhitung banyaknya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 13, 'Dalam iman mereka semua ini telah mati sebagai orang-orang yang tidak memperoleh apa yang dijanjikan itu, tetapi yang hanya dari jauh melihatnya dan melambai-lambai kepadanya dan yang mengakui, bahwa mereka adalah orang asing dan pendatang di bumi ini.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 14, 'Sebab mereka yang berkata demikian menyatakan, bahwa mereka dengan rindu mencari suatu tanah air.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 15, 'Dan kalau sekiranya dalam hal itu mereka ingat akan tanah asal, yang telah mereka tinggalkan, maka mereka cukup mempunyai kesempatan untuk pulang ke situ.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 16, 'Tetapi sekarang mereka merindukan tanah air yang lebih baik yaitu satu tanah air sorgawi. Sebab itu Allah tidak malu disebut Allah mereka, karena Ia telah mempersiapkan sebuah kota bagi mereka.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 17, 'Karena iman maka Abraham, tatkala ia dicobai, mempersembahkan Ishak. Ia, yang telah menerima janji itu, rela mempersembahkan anaknya yang tunggal,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 18, 'walaupun kepadanya telah dikatakan: "Keturunan yang berasal dari Ishaklah yang akan disebut keturunanmu."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 19, 'Karena ia berpikir, bahwa Allah berkuasa membangkitkan orang-orang sekalipun dari antara orang mati. Dan dari sana ia seakan-akan telah menerimanya kembali.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 20, 'Karena iman maka Ishak, sambil memandang jauh ke depan, memberikan berkatnya kepada Yakub dan Esau.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 21, 'Karena iman maka Yakub, ketika hampir waktunya akan mati, memberkati kedua anak Yusuf, lalu menyembah sambil bersandar pada kepala tongkatnya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 22, 'Karena iman maka Yusuf menjelang matinya memberitakan tentang keluarnya orang-orang Israel dan memberi pesan tentang tulang-belulangnya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 23, 'Karena iman maka Musa, setelah ia lahir, disembunyikan selama tiga bulan oleh orang tuanya, karena mereka melihat, bahwa anak itu elok rupanya dan mereka tidak takut akan perintah raja.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 24, 'Karena iman maka Musa, setelah dewasa, menolak disebut anak puteri Firaun,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 25, 'karena ia lebih suka menderita sengsara dengan umat Allah dari pada untuk sementara menikmati kesenangan dari dosa.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 26, 'Ia menganggap penghinaan karena Kristus sebagai kekayaan yang lebih besar dari pada semua harta Mesir, sebab pandangannya ia arahkan kepada upah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 27, 'Karena iman maka ia telah meninggalkan Mesir dengan tidak takut akan murka raja. Ia bertahan sama seperti ia melihat apa yang tidak kelihatan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 28, 'Karena iman maka ia mengadakan Paskah dan pemercikan darah, supaya pembinasa anak-anak sulung jangan menyentuh mereka.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 29, 'Karena iman maka mereka telah melintasi Laut Merah sama seperti melintasi tanah kering, sedangkan orang-orang Mesir tenggelam, ketika mereka mencobanya juga.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 30, 'Karena iman maka runtuhlah tembok-tembok Yerikho, setelah kota itu dikelilingi tujuh hari lamanya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 31, 'Karena iman maka Rahab, perempuan sundal itu, tidak turut binasa bersama-sama dengan orang-orang durhaka, karena ia telah menyambut pengintai-pengintai itu dengan baik.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 32, 'Dan apakah lagi yang harus aku sebut? Sebab aku akan kekurangan waktu, apabila aku hendak menceriterakan tentang Gideon, Barak, Simson, Yefta, Daud dan Samuel dan para nabi,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 33, 'yang karena iman telah menaklukkan kerajaan-kerajaan, mengamalkan kebenaran, memperoleh apa yang dijanjikan, menutup mulut singa-singa,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 34, 'memadamkan api yang dahsyat. Mereka telah luput dari mata pedang, telah beroleh kekuatan dalam kelemahan, telah menjadi kuat dalam peperangan dan telah memukul mundur pasukan-pasukan tentara asing.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 35, 'Ibu-ibu telah menerima kembali orang-orangnya yang telah mati, sebab dibangkitkan. Tetapi orang-orang lain membiarkan dirinya disiksa dan tidak mau menerima pembebasan, supaya mereka beroleh kebangkitan yang lebih baik.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 36, 'Ada pula yang diejek dan didera, bahkan yang dibelenggu dan dipenjarakan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 37, 'Mereka dilempari, digergaji, dibunuh dengan pedang; mereka mengembara dengan berpakaian kulit domba dan kulit kambing sambil menderita kekurangan, kesesakan dan siksaan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 38, 'Dunia ini tidak layak bagi mereka. Mereka mengembara di padang gurun dan di pegunungan, dalam gua-gua dan celah-celah gunung.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 39, 'Dan mereka semua tidak memperoleh apa yang dijanjikan itu, sekalipun iman mereka telah memberikan kepada mereka suatu kesaksian yang baik.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 11, 40, 'Sebab Allah telah menyediakan sesuatu yang lebih baik bagi kita; tanpa kita mereka tidak dapat sampai kepada kesempurnaan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 1, 'Karena kita mempunyai banyak saksi, bagaikan awan yang mengelilingi kita, marilah kita menanggalkan semua beban dan dosa yang begitu merintangi kita, dan berlomba dengan tekun dalam perlombaan yang diwajibkan bagi kita.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 2, 'Marilah kita melakukannya dengan mata yang tertuju kepada Yesus, yang memimpin kita dalam iman, dan yang membawa iman kita itu kepada kesempurnaan, yang dengan mengabaikan kehinaan tekun memikul salib ganti sukacita yang disediakan bagi Dia, yang sekarang duduk di sebelah kanan takhta Allah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 3, 'Ingatlah selalu akan Dia, yang tekun menanggung bantahan yang sehebat itu terhadap diri-Nya dari pihak orang-orang berdosa, supaya jangan kamu menjadi lemah dan putus asa.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 4, 'Dalam pergumulan kamu melawan dosa kamu belum sampai mencucurkan darah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 5, 'Dan sudah lupakah kamu akan nasihat yang berbicara kepada kamu seperti kepada anak-anak: "Hai anakku, janganlah anggap enteng didikan Tuhan, dan janganlah putus asa apabila engkau diperingatkan-Nya;', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 6, 'karena Tuhan menghajar orang yang dikasihi-Nya, dan Ia menyesah orang yang diakui-Nya sebagai anak."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 7, 'Jika kamu harus menanggung ganjaran; Allah memperlakukan kamu seperti anak. Di manakah terdapat anak yang tidak dihajar oleh ayahnya?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 8, 'Tetapi, jikalau kamu bebas dari ganjaran, yang harus diderita setiap orang, maka kamu bukanlah anak, tetapi anak-anak gampang.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 9, 'Selanjutnya: dari ayah kita yang sebenarnya kita beroleh ganjaran, dan mereka kita hormati; kalau demikian bukankah kita harus lebih taat kepada Bapa segala roh, supaya kita boleh hidup?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 10, 'Sebab mereka mendidik kita dalam waktu yang pendek sesuai dengan apa yang mereka anggap baik, tetapi Dia menghajar kita untuk kebaikan kita, supaya kita beroleh bagian dalam kekudusan-Nya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 11, 'Memang tiap-tiap ganjaran pada waktu ia diberikan tidak mendatangkan sukacita, tetapi dukacita. Tetapi kemudian ia menghasilkan buah kebenaran yang memberikan damai kepada mereka yang dilatih olehnya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 12, 'Sebab itu kuatkanlah tangan yang lemah dan lutut yang goyah;', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 13, 'dan luruskanlah jalan bagi kakimu, sehingga yang pincang jangan terpelecok, tetapi menjadi sembuh.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 14, 'Berusahalah hidup damai dengan semua orang dan kejarlah kekudusan, sebab tanpa kekudusan tidak seorangpun akan melihat Tuhan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 15, 'Jagalah supaya jangan ada seorangpun menjauhkan diri dari kasih karunia Allah, agar jangan tumbuh akar yang pahit yang menimbulkan kerusuhan dan yang mencemarkan banyak orang.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 16, 'Janganlah ada orang yang menjadi cabul atau yang mempunyai nafsu yang rendah seperti Esau, yang menjual hak kesulungannya untuk sepiring makanan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 17, 'Sebab kamu tahu, bahwa kemudian, ketika ia hendak menerima berkat itu, ia ditolak, sebab ia tidak beroleh kesempatan untuk memperbaiki kesalahannya, sekalipun ia mencarinya dengan mencucurkan air mata.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 18, 'Sebab kamu tidak datang kepada gunung yang dapat disentuh dan api yang menyala-nyala, kepada kekelaman, kegelapan dan angin badai,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 19, 'kepada bunyi sangkakala dan bunyi suara yang membuat mereka yang mendengarnya memohon, supaya jangan lagi berbicara kepada mereka,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 20, 'sebab mereka tidak tahan mendengar perintah ini: "Bahkan jika binatangpun yang menyentuh gunung, ia harus dilempari dengan batu."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 21, 'Dan sangat mengerikan pemandangan itu, sehingga Musa berkata: "Aku sangat ketakutan dan sangat gemetar."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 22, 'Tetapi kamu sudah datang ke Bukit Sion, ke kota Allah yang hidup, Yerusalem sorgawi dan kepada beribu-ribu malaikat, suatu kumpulan yang meriah,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 23, 'dan kepada jemaat anak-anak sulung, yang namanya terdaftar di sorga, dan kepada Allah, yang menghakimi semua orang, dan kepada roh-roh orang-orang benar yang telah menjadi sempurna,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 24, 'dan kepada Yesus, Pengantara perjanjian baru, dan kepada darah pemercikan, yang berbicara lebih kuat dari pada darah Habel.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 25, 'Jagalah supaya kamu jangan menolak Dia, yang berfirman. Sebab jikalau mereka, yang menolak Dia yang menyampaikan firman Allah di bumi, tidak luput, apa lagi kita, jika kita berpaling dari Dia yang berbicara dari sorga?', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 26, 'Waktu itu suara-Nya menggoncangkan bumi, tetapi sekarang Ia memberikan janji: "Satu kali lagi Aku akan menggoncangkan bukan hanya bumi saja, melainkan langit juga."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 27, 'Ungkapan "Satu kali lagi" menunjuk kepada perubahan pada apa yang dapat digoncangkan, karena ia dijadikan supaya tinggal tetap apa yang tidak tergoncangkan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 28, 'Jadi, karena kita menerima kerajaan yang tidak tergoncangkan, marilah kita mengucap syukur dan beribadah kepada Allah menurut cara yang berkenan kepada-Nya, dengan hormat dan takut.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 12, 29, 'Sebab Allah kita adalah api yang menghanguskan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 1, 'Peliharalah kasih persaudaraan!', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 2, 'Jangan kamu lupa memberi tumpangan kepada orang, sebab dengan berbuat demikian beberapa orang dengan tidak diketahuinya telah menjamu malaikat-malaikat.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 3, 'Ingatlah akan orang-orang hukuman, karena kamu sendiri juga adalah orang-orang hukuman. Dan ingatlah akan orang-orang yang diperlakukan sewenang-wenang, karena kamu sendiri juga masih hidup di dunia ini.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 4, 'Hendaklah kamu semua penuh hormat terhadap perkawinan dan janganlah kamu mencemarkan tempat tidur, sebab orang-orang sundal dan pezinah akan dihakimi Allah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 5, 'Janganlah kamu menjadi hamba uang dan cukupkanlah dirimu dengan apa yang ada padamu. Karena Allah telah berfirman: "Aku sekali-kali tidak akan membiarkan engkau dan Aku sekali-kali tidak akan meninggalkan engkau."', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 6, 'Sebab itu dengan yakin kita dapat berkata: "Tuhan adalah Penolongku. Aku tidak akan takut. Apakah yang dapat dilakukan manusia terhadap aku?"', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 7, 'Ingatlah akan pemimpin-pemimpin kamu, yang telah menyampaikan firman Allah kepadamu. Perhatikanlah akhir hidup mereka dan contohlah iman mereka.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 8, 'Yesus Kristus tetap sama, baik kemarin maupun hari ini dan sampai selama-lamanya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 9, 'Janganlah kamu disesatkan oleh berbagai-bagai ajaran asing. Sebab yang baik ialah, bahwa hati kamu diperkuat dengan kasih karunia dan bukan dengan pelbagai makanan yang tidak memberi faedah kepada mereka yang menuruti aturan-aturan makanan macam itu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 10, 'Kita mempunyai suatu mezbah dan orang-orang yang melayani kemah tidak boleh makan dari apa yang di dalamnya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 11, 'Karena tubuh binatang-binatang yang darahnya dibawa masuk ke tempat kudus oleh Imam Besar sebagai korban penghapus dosa, dibakar di luar perkemahan.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 12, 'Itu jugalah sebabnya Yesus telah menderita di luar pintu gerbang untuk menguduskan umat-Nya dengan darah-Nya sendiri.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 13, 'Karena itu marilah kita pergi kepada-Nya di luar perkemahan dan menanggung kehinaan-Nya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 14, 'Sebab di sini kita tidak mempunyai tempat tinggal yang tetap; kita mencari kota yang akan datang.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 15, 'Sebab itu marilah kita, oleh Dia, senantiasa mempersembahkan korban syukur kepada Allah, yaitu ucapan bibir yang memuliakan nama-Nya.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 16, 'Dan janganlah kamu lupa berbuat baik dan memberi bantuan, sebab korban-korban yang demikianlah yang berkenan kepada Allah.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 17, 'Taatilah pemimpin-pemimpinmu dan tunduklah kepada mereka, sebab mereka berjaga-jaga atas jiwamu, sebagai orang-orang yang harus bertanggung jawab atasnya. Dengan jalan itu mereka akan melakukannya dengan gembira, bukan dengan keluh kesah, sebab hal itu tidak akan membawa keuntungan bagimu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 18, 'Berdoalah terus untuk kami; sebab kami yakin, bahwa hati nurani kami adalah baik, karena di dalam segala hal kami menginginkan suatu hidup yang baik.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 19, 'Dan secara khusus aku menasihatkan kamu, agar kamu melakukannya, supaya aku lebih lekas dikembalikan kepada kamu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 20, 'Maka Allah damai sejahtera, yang oleh darah perjanjian yang kekal telah membawa kembali dari antara orang mati Gembala Agung segala domba, yaitu Yesus, Tuhan kita,', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 21, 'kiranya memperlengkapi kamu dengan segala yang baik untuk melakukan kehendak-Nya, dan mengerjakan di dalam kita apa yang berkenan kepada-Nya, oleh Yesus Kristus. Bagi Dialah kemuliaan sampai selama-lamanya! Amin.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 22, 'Dan aku menasihatkan kamu, saudara-saudara, supaya kata-kata nasihat ini kamu sambut dengan rela hati, sekalipun pendek saja suratku ini kepada kamu.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 23, 'Ketahuilah, bahwa Timotius, saudara kita, telah berangkat. Segera sesudah ia datang, aku akan mengunjungi kamu bersama-sama dengan dia.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 24, 'Sampaikanlah salam kepada semua pemimpin kamu dan semua orang kudus. Terimalah salam dari saudara-saudara di Italia.', 'id', 'TB'),
  ('58', 'ibr', 'Ibrani', 13, 25, 'Kasih karunia menyertai kamu sekalian.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 1, 'Salam dari Yakobus, hamba Allah dan Tuhan Yesus Kristus, kepada kedua belas suku di perantauan.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 2, 'Saudara-saudaraku, anggaplah sebagai suatu kebahagiaan, apabila kamu jatuh ke dalam berbagai-bagai pencobaan,', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 3, 'sebab kamu tahu, bahwa ujian terhadap imanmu itu menghasilkan ketekunan.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 4, 'Dan biarkanlah ketekunan itu memperoleh buah yang matang, supaya kamu menjadi sempurna dan utuh dan tak kekurangan suatu apapun.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 5, 'Tetapi apabila di antara kamu ada yang kekurangan hikmat, hendaklah ia memintakannya kepada Allah, ?yang memberikan kepada semua orang dengan murah hati dan dengan tidak membangkit-bangkit?,maka hal itu akan diberikan kepadanya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 6, 'Hendaklah ia memintanya dalam iman, dan sama sekali jangan bimbang, sebab orang yang bimbang sama dengan gelombang laut, yang diombang-ambingkan kian ke mari oleh angin.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 7, 'Orang yang demikian janganlah mengira, bahwa ia akan menerima sesuatu dari Tuhan.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 8, 'Sebab orang yang mendua hati tidak akan tenang dalam hidupnya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 9, 'Baiklah saudara yang berada dalam keadaan yang rendah bermegah karena kedudukannya yang tinggi,', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 10, 'dan orang kaya karena kedudukannya yang rendah sebab ia akan lenyap seperti bunga rumput.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 11, 'Karena matahari terbit dengan panasnya yang terik dan melayukan rumput itu, sehingga gugurlah bunganya dan hilanglah semaraknya. Demikian jugalah halnya dengan orang kaya; di tengah-tengah segala usahanya ia akan lenyap.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 12, 'Berbahagialah orang yang bertahan dalam pencobaan, sebab apabila ia sudah tahan uji, ia akan menerima mahkota kehidupan yang dijanjikan Allah kepada barangsiapa yang mengasihi Dia.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 13, 'Apabila seorang dicobai, janganlah ia berkata: "Pencobaan ini datang dari Allah!" Sebab Allah tidak dapat dicobai oleh yang jahat, dan Ia sendiri tidak mencobai siapapun.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 14, 'Tetapi tiap-tiap orang dicobai oleh keinginannya sendiri, karena ia diseret dan dipikat olehnya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 15, 'Dan apabila keinginan itu telah dibuahi, ia melahirkan dosa; dan apabila dosa itu sudah matang, ia melahirkan maut.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 16, 'Saudara-saudara yang kukasihi, janganlah sesat!', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 17, 'Setiap pemberian yang baik dan setiap anugerah yang sempurna, datangnya dari atas, diturunkan dari Bapa segala terang; pada-Nya tidak ada perubahan atau bayangan karena pertukaran.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 18, 'Atas kehendak-Nya sendiri Ia telah menjadikan kita oleh firman kebenaran, supaya kita pada tingkat yang tertentu menjadi anak sulung di antara semua ciptaan-Nya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 19, 'Hai saudara-saudara yang kukasihi, ingatlah hal ini: setiap orang hendaklah cepat untuk mendengar, tetapi lambat untuk berkata-kata, dan juga lambat untuk marah;', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 20, 'sebab amarah manusia tidak mengerjakan kebenaran di hadapan Allah.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 21, 'Sebab itu buanglah segala sesuatu yang kotor dan kejahatan yang begitu banyak itu dan terimalah dengan lemah lembut firman yang tertanam di dalam hatimu, yang berkuasa menyelamatkan jiwamu.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 22, 'Tetapi hendaklah kamu menjadi pelaku firman dan bukan hanya pendengar saja; sebab jika tidak demikian kamu menipu diri sendiri.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 23, 'Sebab jika seorang hanya mendengar firman saja dan tidak melakukannya, ia adalah seumpama seorang yang sedang mengamat-amati mukanya yang sebenarnya di depan cermin.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 24, 'Baru saja ia memandang dirinya, ia sudah pergi atau ia segera lupa bagaimana rupanya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 25, 'Tetapi barangsiapa meneliti hukum yang sempurna, yaitu hukum yang memerdekakan orang, dan ia bertekun di dalamnya, jadi bukan hanya mendengar untuk melupakannya, tetapi sungguh-sungguh melakukannya, ia akan berbahagia oleh perbuatannya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 26, 'Jikalau ada seorang menganggap dirinya beribadah, tetapi tidak mengekang lidahnya, ia menipu dirinya sendiri, maka sia-sialah ibadahnya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 1, 27, 'Ibadah yang murni dan yang tak bercacat di hadapan Allah, Bapa kita, ialah mengunjungi yatim piatu dan janda-janda dalam kesusahan mereka, dan menjaga supaya dirinya sendiri tidak dicemarkan oleh dunia.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 1, 'Saudara-saudaraku, sebagai orang yang beriman kepada Yesus Kristus, Tuhan kita yang mulia, janganlah iman itu kamu amalkan dengan memandang muka.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 2, 'Sebab, jika ada seorang masuk ke dalam kumpulanmu dengan memakai cincin emas dan pakaian indah dan datang juga seorang miskin ke situ dengan memakai pakaian buruk,', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 3, 'dan kamu menghormati orang yang berpakaian indah itu dan berkata kepadanya: "Silakan tuan duduk di tempat yang baik ini!", sedang kepada orang yang miskin itu kamu berkata: "Berdirilah di sana!" atau: "Duduklah di lantai ini dekat tumpuan kakiku!",', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 4, 'bukankah kamu telah membuat pembedaan di dalam hatimu dan bertindak sebagai hakim dengan pikiran yang jahat?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 5, 'Dengarkanlah, hai saudara-saudara yang kukasihi! Bukankah Allah memilih orang-orang yang dianggap miskin oleh dunia ini untuk menjadi kaya dalam iman dan menjadi ahli waris Kerajaan yang telah dijanjikan-Nya kepada barangsiapa yang mengasihi Dia?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 6, 'Tetapi kamu telah menghinakan orang-orang miskin. Bukankah justru orang-orang kaya yang menindas kamu dan yang menyeret kamu ke pengadilan?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 7, 'Bukankah mereka yang menghujat Nama yang mulia, yang oleh-Nya kamu menjadi milik Allah?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 8, 'Akan tetapi, jikalau kamu menjalankan hukum utama yang tertulis dalam Kitab Suci: "Kasihilah sesamamu manusia seperti dirimu sendiri", kamu berbuat baik.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 9, 'Tetapi, jikalau kamu memandang muka, kamu berbuat dosa, dan oleh hukum itu menjadi nyata, bahwa kamu melakukan pelanggaran.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 10, 'Sebab barangsiapa menuruti seluruh hukum itu, tetapi mengabaikan satu bagian dari padanya, ia bersalah terhadap seluruhnya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 11, 'Sebab Ia yang mengatakan: "Jangan berzinah", Ia mengatakan juga: "Jangan membunuh". Jadi jika kamu tidak berzinah tetapi membunuh, maka kamu menjadi pelanggar hukum juga.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 12, 'Berkatalah dan berlakulah seperti orang-orang yang akan dihakimi oleh hukum yang memerdekakan orang.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 13, 'Sebab penghakiman yang tak berbelas kasihan akan berlaku atas orang yang tidak berbelas kasihan. Tetapi belas kasihan akan menang atas penghakiman.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 14, 'Apakah gunanya, saudara-saudaraku, jika seorang mengatakan, bahwa ia mempunyai iman, padahal ia tidak mempunyai perbuatan? Dapatkah iman itu menyelamatkan dia?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 15, 'Jika seorang saudara atau saudari tidak mempunyai pakaian dan kekurangan makanan sehari-hari,', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 16, 'dan seorang dari antara kamu berkata: "Selamat jalan, kenakanlah kain panas dan makanlah sampai kenyang!", tetapi ia tidak memberikan kepadanya apa yang perlu bagi tubuhnya, apakah gunanya itu?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 17, 'Demikian juga halnya dengan iman: Jika iman itu tidak disertai perbuatan, maka iman itu pada hakekatnya adalah mati.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 18, 'Tetapi mungkin ada orang berkata: "Padamu ada iman dan padaku ada perbuatan", aku akan menjawab dia: "Tunjukkanlah kepadaku imanmu itu tanpa perbuatan, dan aku akan menunjukkan kepadamu imanku dari perbuatan-perbuatanku."', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 19, 'Engkau percaya, bahwa hanya ada satu Allah saja? Itu baik! Tetapi setan-setanpun juga percaya akan hal itu dan mereka gemetar.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 20, 'Hai manusia yang bebal, maukah engkau mengakui sekarang, bahwa iman tanpa perbuatan adalah iman yang kosong?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 21, 'Bukankah Abraham, bapa kita, dibenarkan karena perbuatan-perbuatannya, ketika ia mempersembahkan Ishak, anaknya, di atas mezbah?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 22, 'Kamu lihat, bahwa iman bekerjasama dengan perbuatan-perbuatan dan oleh perbuatan-perbuatan itu iman menjadi sempurna.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 23, 'Dengan jalan demikian genaplah nas yang mengatakan: "Lalu percayalah Abraham kepada Allah, maka Allah memperhitungkan hal itu kepadanya sebagai kebenaran." Karena itu Abraham disebut: "Sahabat Allah."', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 24, 'Jadi kamu lihat, bahwa manusia dibenarkan karena perbuatan-perbuatannya dan bukan hanya karena iman.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 25, 'Dan bukankah demikian juga Rahab, pelacur itu, dibenarkan karena perbuatan-perbuatannya, ketika ia menyembunyikan orang-orang yang disuruh itu di dalam rumahnya, lalu menolong mereka lolos melalui jalan yang lain?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 2, 26, 'Sebab seperti tubuh tanpa roh adalah mati, demikian jugalah iman tanpa perbuatan-perbuatan adalah mati.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 1, 'Saudara-saudaraku, janganlah banyak orang di antara kamu mau menjadi guru; sebab kita tahu, bahwa sebagai guru kita akan dihakimi menurut ukuran yang lebih berat.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 2, 'Sebab kita semua bersalah dalam banyak hal; barangsiapa tidak bersalah dalam perkataannya, ia adalah orang sempurna, yang dapat juga mengendalikan seluruh tubuhnya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 3, 'Kita mengenakan kekang pada mulut kuda, sehingga ia menuruti kehendak kita, dengan jalan demikian kita dapat juga mengendalikan seluruh tubuhnya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 4, 'Dan lihat saja kapal-kapal, walaupun amat besar dan digerakkan oleh angin keras, namun dapat dikendalikan oleh kemudi yang amat kecil menurut kehendak jurumudi.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 5, 'Demikian juga lidah, walaupun suatu anggota kecil dari tubuh, namun dapat memegahkan perkara-perkara yang besar. Lihatlah, betapapun kecilnya api, ia dapat membakar hutan yang besar.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 6, 'Lidahpun adalah api; ia merupakan suatu dunia kejahatan dan mengambil tempat di antara anggota-anggota tubuh kita sebagai sesuatu yang dapat menodai seluruh tubuh dan menyalakan roda kehidupan kita, sedang ia sendiri dinyalakan oleh api neraka.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 7, 'Semua jenis binatang liar, burung-burung, serta binatang-binatang menjalar dan binatang-binatang laut dapat dijinakkan dan telah dijinakkan oleh sifat manusia,', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 8, 'tetapi tidak seorangpun yang berkuasa menjinakkan lidah; ia adalah sesuatu yang buas, yang tak terkuasai, dan penuh racun yang mematikan.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 9, 'Dengan lidah kita memuji Tuhan, Bapa kita; dan dengan lidah kita mengutuk manusia yang diciptakan menurut rupa Allah,', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 10, 'dari mulut yang satu keluar berkat dan kutuk. Hal ini, saudara-saudaraku, tidak boleh demikian terjadi.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 11, 'Adakah sumber memancarkan air tawar dan air pahit dari mata air yang sama?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 12, 'Saudara-saudaraku, adakah pohon ara dapat menghasilkan buah zaitun dan adakah pokok anggur dapat menghasilkan buah ara? Demikian juga mata air asin tidak dapat mengeluarkan air tawar.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 13, 'Siapakah di antara kamu yang bijak dan berbudi? Baiklah ia dengan cara hidup yang baik menyatakan perbuatannya oleh hikmat yang lahir dari kelemahlembutan.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 14, 'Jika kamu menaruh perasaan iri hati dan kamu mementingkan diri sendiri, janganlah kamu memegahkan diri dan janganlah berdusta melawan kebenaran!', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 15, 'Itu bukanlah hikmat yang datang dari atas, tetapi dari dunia, dari nafsu manusia, dari setan-setan.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 16, 'Sebab di mana ada iri hati dan mementingkan diri sendiri di situ ada kekacauan dan segala macam perbuatan jahat.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 17, 'Tetapi hikmat yang dari atas adalah pertama-tama murni, selanjutnya pendamai, peramah, penurut, penuh belas kasihan dan buah-buah yang baik, tidak memihak dan tidak munafik.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 3, 18, 'Dan buah yang terdiri dari kebenaran ditaburkan dalam damai untuk mereka yang mengadakan damai.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 1, 'Dari manakah datangnya sengketa dan pertengkaran di antara kamu? Bukankah datangnya dari hawa nafsumu yang saling berjuang di dalam tubuhmu?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 2, 'Kamu mengingini sesuatu, tetapi kamu tidak memperolehnya, lalu kamu membunuh; kamu iri hati, tetapi kamu tidak mencapai tujuanmu, lalu kamu bertengkar dan kamu berkelahi. Kamu tidak memperoleh apa-apa, karena kamu tidak berdoa.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 3, 'Atau kamu berdoa juga, tetapi kamu tidak menerima apa-apa, karena kamu salah berdoa, sebab yang kamu minta itu hendak kamu habiskan untuk memuaskan hawa nafsumu.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 4, 'Hai kamu, orang-orang yang tidak setia! Tidakkah kamu tahu, bahwa persahabatan dengan dunia adalah permusuhan dengan Allah? Jadi barangsiapa hendak menjadi sahabat dunia ini, ia menjadikan dirinya musuh Allah.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 5, 'Janganlah kamu menyangka, bahwa Kitab Suci tanpa alasan berkata: "Roh yang ditempatkan Allah di dalam diri kita, diingini-Nya dengan cemburu!"', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 6, 'Tetapi kasih karunia, yang dianugerahkan-Nya kepada kita, lebih besar dari pada itu. Karena itu Ia katakan: "Allah menentang orang yang congkak, tetapi mengasihani orang yang rendah hati."', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 7, 'Karena itu tunduklah kepada Allah, dan lawanlah Iblis, maka ia akan lari dari padamu!', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 8, 'Mendekatlah kepada Allah, dan Ia akan mendekat kepadamu. Tahirkanlah tanganmu, hai kamu orang-orang berdosa! dan sucikanlah hatimu, hai kamu yang mendua hati!', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 9, 'Sadarilah kemalanganmu, berdukacita dan merataplah; hendaklah tertawamu kamu ganti dengan ratap dan sukacitamu dengan dukacita.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 10, 'Rendahkanlah dirimu di hadapan Tuhan, dan Ia akan meninggikan kamu.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 11, 'Saudara-saudaraku, janganlah kamu saling memfitnah! Barangsiapa memfitnah saudaranya atau menghakiminya, ia mencela hukum dan menghakiminya; dan jika engkau menghakimi hukum, maka engkau bukanlah penurut hukum, tetapi hakimnya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 12, 'Hanya ada satu Pembuat hukum dan Hakim, yaitu Dia yang berkuasa menyelamatkan dan membinasakan. Tetapi siapakah engkau, sehingga engkau mau menghakimi sesamamu manusia?', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 13, 'Jadi sekarang, hai kamu yang berkata: "Hari ini atau besok kami berangkat ke kota anu, dan di sana kami akan tinggal setahun dan berdagang serta mendapat untung",', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 14, 'sedang kamu tidak tahu apa yang akan terjadi besok. Apakah arti hidupmu? Hidupmu itu sama seperti uap yang sebentar saja kelihatan lalu lenyap.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 15, 'Sebenarnya kamu harus berkata: "Jika Tuhan menghendakinya, kami akan hidup dan berbuat ini dan itu."', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 16, 'Tetapi sekarang kamu memegahkan diri dalam congkakmu, dan semua kemegahan yang demikian adalah salah.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 4, 17, 'Jadi jika seorang tahu bagaimana ia harus berbuat baik, tetapi ia tidak melakukannya, ia berdosa.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 1, 'Jadi sekarang hai kamu orang-orang kaya, menangislah dan merataplah atas sengsara yang akan menimpa kamu!', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 2, 'Kekayaanmu sudah busuk, dan pakaianmu telah dimakan ngengat!', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 3, 'Emas dan perakmu sudah berkarat, dan karatnya akan menjadi kesaksian terhadap kamu dan akan memakan dagingmu seperti api. Kamu telah mengumpulkan harta pada hari-hari yang sedang berakhir.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 4, 'Sesungguhnya telah terdengar teriakan besar, karena upah yang kamu tahan dari buruh yang telah menuai hasil ladangmu, dan telah sampai ke telinga Tuhan semesta alam keluhan mereka yang menyabit panenmu.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 5, 'Dalam kemewahan kamu telah hidup dan berfoya-foya di bumi, kamu telah memuaskan hatimu sama seperti pada hari penyembelihan.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 6, 'Kamu telah menghukum, bahkan membunuh orang yang benar dan ia tidak dapat melawan kamu.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 7, 'Karena itu, saudara-saudara, bersabarlah sampai kepada kedatangan Tuhan! Sesungguhnya petani menantikan hasil yang berharga dari tanahnya dan ia sabar sampai telah turun hujan musim gugur dan hujan musim semi.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 8, 'Kamu juga harus bersabar dan harus meneguhkan hatimu, karena kedatangan Tuhan sudah dekat!', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 9, 'Saudara-saudara, janganlah kamu bersungut-sungut dan saling mempersalahkan, supaya kamu jangan dihukum. Sesungguhnya Hakim telah berdiri di ambang pintu.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 10, 'Saudara-saudara, turutilah teladan penderitaan dan kesabaran para nabi yang telah berbicara demi nama Tuhan.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 11, 'Sesungguhnya kami menyebut mereka berbahagia, yaitu mereka yang telah bertekun; kamu telah mendengar tentang ketekunan Ayub dan kamu telah tahu apa yang pada akhirnya disediakan Tuhan baginya, karena Tuhan maha penyayang dan penuh belas kasihan.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 12, 'Tetapi yang terutama, saudara-saudara, janganlah kamu bersumpah demi sorga maupun demi bumi atau demi sesuatu yang lain. Jika ya, hendaklah kamu katakan ya, jika tidak hendaklah kamu katakan tidak, supaya kamu jangan kena hukuman.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 13, 'Kalau ada seorang di antara kamu yang menderita, baiklah ia berdoa! Kalau ada seorang yang bergembira baiklah ia menyanyi!', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 14, 'Kalau ada seorang di antara kamu yang sakit, baiklah ia memanggil para penatua jemaat, supaya mereka mendoakan dia serta mengolesnya dengan minyak dalam nama Tuhan.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 15, 'Dan doa yang lahir dari iman akan menyelamatkan orang sakit itu dan Tuhan akan membangunkan dia; dan jika ia telah berbuat dosa, maka dosanya itu akan diampuni.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 16, 'Karena itu hendaklah kamu saling mengaku dosamu dan saling mendoakan, supaya kamu sembuh. Doa orang yang benar, bila dengan yakin didoakan, sangat besar kuasanya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 17, 'Elia adalah manusia biasa sama seperti kita, dan ia telah bersungguh-sungguh berdoa, supaya hujan jangan turun, dan hujanpun tidak turun di bumi selama tiga tahun dan enam bulan.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 18, 'Lalu ia berdoa pula dan langit menurunkan hujan dan bumipun mengeluarkan buahnya.', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 19, 'Saudara-saudaraku, jika ada di antara kamu yang menyimpang dari kebenaran dan ada seorang yang membuat dia berbalik,', 'id', 'TB'),
  ('59', 'yak', 'Yakobus', 5, 20, 'ketahuilah, bahwa barangsiapa membuat orang berdosa berbalik dari jalannya yang sesat, ia akan menyelamatkan jiwa orang itu dari maut dan menutupi banyak dosa.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 1, 'Dari Petrus, rasul Yesus Kristus, kepada orang-orang pendatang, yang tersebar di Pontus, Galatia, Kapadokia, Asia Kecil dan Bitinia,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 2, 'yaitu orang-orang yang dipilih, sesuai dengan rencana Allah, Bapa kita, dan yang dikuduskan oleh Roh, supaya taat kepada Yesus Kristus dan menerima percikan darah-Nya. Kiranya kasih karunia dan damai sejahtera makin melimpah atas kamu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 3, 'Terpujilah Allah dan Bapa Tuhan kita Yesus Kristus, yang karena rahmat-Nya yang besar telah melahirkan kita kembali oleh kebangkitan Yesus Kristus dari antara orang mati, kepada suatu hidup yang penuh pengharapan,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 4, 'untuk menerima suatu bagian yang tidak dapat binasa, yang tidak dapat cemar dan yang tidak dapat layu, yang tersimpan di sorga bagi kamu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 5, 'Yaitu kamu, yang dipelihara dalam kekuatan Allah karena imanmu sementara kamu menantikan keselamatan yang telah tersedia untuk dinyatakan pada zaman akhir.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 6, 'Bergembiralah akan hal itu, sekalipun sekarang ini kamu seketika harus berdukacita oleh berbagai-bagai pencobaan.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 7, 'Maksud semuanya itu ialah untuk membuktikan kemurnian imanmu?yang jauh lebih tinggi nilainya dari pada emas yang fana, yang diuji kemurniannya dengan api?sehingga kamu memperoleh puji-pujian dan kemuliaan dan kehormatan pada hari Yesus Kristus menyatakan diri-Nya.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 8, 'Sekalipun kamu belum pernah melihat Dia, namun kamu mengasihi-Nya. Kamu percaya kepada Dia, sekalipun kamu sekarang tidak melihat-Nya. Kamu bergembira karena sukacita yang mulia dan yang tidak terkatakan,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 9, 'karena kamu telah mencapai tujuan imanmu, yaitu keselamatan jiwamu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 10, 'Keselamatan itulah yang diselidiki dan diteliti oleh nabi-nabi, yang telah bernubuat tentang kasih karunia yang diuntukkan bagimu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 11, 'Dan mereka meneliti saat yang mana dan yang bagaimana yang dimaksudkan oleh Roh Kristus, yang ada di dalam mereka, yaitu Roh yang sebelumnya memberi kesaksian tentang segala penderitaan yang akan menimpa Kristus dan tentang segala kemuliaan yang menyusul sesudah itu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 12, 'Kepada mereka telah dinyatakan, bahwa mereka bukan melayani diri mereka sendiri, tetapi melayani kamu dengan segala sesuatu yang telah diberitakan sekarang kepada kamu dengan perantaraan mereka, yang oleh Roh Kudus, yang diutus dari sorga, menyampaikan berita Injil kepada kamu, yaitu hal-hal yang ingin diketahui oleh malaikat-malaikat.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 13, 'Sebab itu siapkanlah akal budimu, waspadalah dan letakkanlah pengharapanmu seluruhnya atas kasih karunia yang dianugerahkan kepadamu pada waktu penyataan Yesus Kristus.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 14, 'Hiduplah sebagai anak-anak yang taat dan jangan turuti hawa nafsu yang menguasai kamu pada waktu kebodohanmu,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 15, 'tetapi hendaklah kamu menjadi kudus di dalam seluruh hidupmu sama seperti Dia yang kudus, yang telah memanggil kamu,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 16, 'sebab ada tertulis: Kuduslah kamu, sebab Aku kudus.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 17, 'Dan jika kamu menyebut-Nya Bapa, yaitu Dia yang tanpa memandang muka menghakimi semua orang menurut perbuatannya, maka hendaklah kamu hidup dalam ketakutan selama kamu menumpang di dunia ini.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 18, 'Sebab kamu tahu, bahwa kamu telah ditebus dari cara hidupmu yang sia-sia yang kamu warisi dari nenek moyangmu itu bukan dengan barang yang fana, bukan pula dengan perak atau emas,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 19, 'melainkan dengan darah yang mahal, yaitu darah Kristus yang sama seperti darah anak domba yang tak bernoda dan tak bercacat.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 20, 'Ia telah dipilih sebelum dunia dijadikan, tetapi karena kamu baru menyatakan diri-Nya pada zaman akhir.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 21, 'Oleh Dialah kamu percaya kepada Allah, yang telah membangkitkan Dia dari antara orang mati dan yang telah memuliakan-Nya, sehingga imanmu dan pengharapanmu tertuju kepada Allah.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 22, 'Karena kamu telah menyucikan dirimu oleh ketaatan kepada kebenaran, sehingga kamu dapat mengamalkan kasih persaudaraan yang tulus ikhlas, hendaklah kamu bersungguh-sungguh saling mengasihi dengan segenap hatimu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 23, 'Karena kamu telah dilahirkan kembali bukan dari benih yang fana, tetapi dari benih yang tidak fana, oleh firman Allah, yang hidup dan yang kekal.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 24, 'Sebab: "Semua yang hidup adalah seperti rumput dan segala kemuliaannya seperti bunga rumput, rumput menjadi kering, dan bunga gugur,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 1, 25, 'tetapi firman Tuhan tetap untuk selama-lamanya." Inilah firman yang disampaikan Injil kepada kamu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 1, 'Karena itu buanglah segala kejahatan, segala tipu muslihat dan segala macam kemunafikan, kedengkian dan fitnah.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 2, 'Dan jadilah sama seperti bayi yang baru lahir, yang selalu ingin akan air susu yang murni dan yang rohani, supaya olehnya kamu bertumbuh dan beroleh keselamatan,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 3, 'jika kamu benar-benar telah mengecap kebaikan Tuhan.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 4, 'Dan datanglah kepada-Nya, batu yang hidup itu, yang memang dibuang oleh manusia, tetapi yang dipilih dan dihormat di hadirat Allah.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 5, 'Dan biarlah kamu juga dipergunakan sebagai batu hidup untuk pembangunan suatu rumah rohani, bagi suatu imamat kudus, untuk mempersembahkan persembahan rohani yang karena Yesus Kristus berkenan kepada Allah.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 6, 'Sebab ada tertulis dalam Kitab Suci: "Sesungguhnya, Aku meletakkan di Sion sebuah batu yang terpilih, sebuah batu penjuru yang mahal, dan siapa yang percaya kepada-Nya, tidak akan dipermalukan."', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 7, 'Karena itu bagi kamu, yang percaya, ia mahal, tetapi bagi mereka yang tidak percaya: "Batu yang telah dibuang oleh tukang-tukang bangunan, telah menjadi batu penjuru, juga telah menjadi batu sentuhan dan suatu batu sandungan."', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 8, 'Mereka tersandung padanya, karena mereka tidak taat kepada Firman Allah; dan untuk itu mereka juga telah disediakan.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 9, 'Tetapi kamulah bangsa yang terpilih, imamat yang rajani, bangsa yang kudus, umat kepunyaan Allah sendiri, supaya kamu memberitakan perbuatan-perbuatan yang besar dari Dia, yang telah memanggil kamu keluar dari kegelapan kepada terang-Nya yang ajaib:', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 10, 'kamu, yang dahulu bukan umat Allah, tetapi yang sekarang telah menjadi umat-Nya, yang dahulu tidak dikasihani tetapi yang sekarang telah beroleh belas kasihan.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 11, 'Saudara-saudaraku yang kekasih, aku menasihati kamu, supaya sebagai pendatang dan perantau, kamu menjauhkan diri dari keinginan-keinginan daging yang berjuang melawan jiwa.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 12, 'Milikilah cara hidup yang baik di tengah-tengah bangsa-bangsa bukan Yahudi, supaya apabila mereka memfitnah kamu sebagai orang durjana, mereka dapat melihatnya dari perbuatan-perbuatanmu yang baik dan memuliakan Allah pada hari Ia melawat mereka.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 13, 'Tunduklah, karena Allah, kepada semua lembaga manusia, baik kepada raja sebagai pemegang kekuasaan yang tertinggi,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 14, 'maupun kepada wali-wali yang diutusnya untuk menghukum orang-orang yang berbuat jahat dan menghormati orang-orang yang berbuat baik.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 15, 'Sebab inilah kehendak Allah, yaitu supaya dengan berbuat baik kamu membungkamkan kepicikan orang-orang yang bodoh.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 16, 'Hiduplah sebagai orang merdeka dan bukan seperti mereka yang menyalahgunakan kemerdekaan itu untuk menyelubungi kejahatan-kejahatan mereka, tetapi hiduplah sebagai hamba Allah.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 17, 'Hormatilah semua orang, kasihilah saudara-saudaramu, takutlah akan Allah, hormatilah raja!', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 18, 'Hai kamu, hamba-hamba, tunduklah dengan penuh ketakutan kepada tuanmu, bukan saja kepada yang baik dan peramah, tetapi juga kepada yang bengis.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 19, 'Sebab adalah kasih karunia, jika seorang karena sadar akan kehendak Allah menanggung penderitaan yang tidak harus ia tanggung.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 20, 'Sebab dapatkah disebut pujian, jika kamu menderita pukulan karena kamu berbuat dosa? Tetapi jika kamu berbuat baik dan karena itu kamu harus menderita, maka itu adalah kasih karunia pada Allah.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 21, 'Sebab untuk itulah kamu dipanggil, karena Kristuspun telah menderita untuk kamu dan telah meninggalkan teladan bagimu, supaya kamu mengikuti jejak-Nya.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 22, 'Ia tidak berbuat dosa, dan tipu tidak ada dalam mulut-Nya.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 23, 'Ketika Ia dicaci maki, Ia tidak membalas dengan mencaci maki; ketika Ia menderita, Ia tidak mengancam, tetapi Ia menyerahkannya kepada Dia, yang menghakimi dengan adil.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 24, 'Ia sendiri telah memikul dosa kita di dalam tubuh-Nya di kayu salib, supaya kita, yang telah mati terhadap dosa, hidup untuk kebenaran. Oleh bilur-bilur-Nya kamu telah sembuh.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 2, 25, 'Sebab dahulu kamu sesat seperti domba, tetapi sekarang kamu telah kembali kepada gembala dan pemelihara jiwamu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 1, 'Demikian juga kamu, hai isteri-isteri, tunduklah kepada suamimu, supaya jika ada di antara mereka yang tidak taat kepada Firman, mereka juga tanpa perkataan dimenangkan oleh kelakuan isterinya,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 2, 'jika mereka melihat, bagaimana murni dan salehnya hidup isteri mereka itu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 3, 'Perhiasanmu janganlah secara lahiriah, yaitu dengan mengepang-ngepang rambut, memakai perhiasan emas atau dengan mengenakan pakaian yang indah-indah,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 4, 'tetapi perhiasanmu ialah manusia batiniah yang tersembunyi dengan perhiasan yang tidak binasa yang berasal dari roh yang lemah lembut dan tenteram, yang sangat berharga di mata Allah.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 5, 'Sebab demikianlah caranya perempuan-perempuan kudus dahulu berdandan, yaitu perempuan-perempuan yang menaruh pengharapannya kepada Allah; mereka tunduk kepada suaminya,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 6, 'sama seperti Sara taat kepada Abraham dan menamai dia tuannya. Dan kamu adalah anak-anaknya, jika kamu berbuat baik dan tidak takut akan ancaman.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 7, 'Demikian juga kamu, hai suami-suami, hiduplah bijaksana dengan isterimu, sebagai kaum yang lebih lemah! Hormatilah mereka sebagai teman pewaris dari kasih karunia, yaitu kehidupan, supaya doamu jangan terhalang.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 8, 'Dan akhirnya, hendaklah kamu semua seia sekata, seperasaan, mengasihi saudara-saudara, penyayang dan rendah hati,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 9, 'dan janganlah membalas kejahatan dengan kejahatan, atau caci maki dengan caci maki, tetapi sebaliknya, hendaklah kamu memberkati, karena untuk itulah kamu dipanggil, yaitu untuk memperoleh berkat. Sebab:', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 10, '"Siapa yang mau mencintai hidup dan mau melihat hari-hari baik, ia harus menjaga lidahnya terhadap yang jahat dan bibirnya terhadap ucapan-ucapan yang menipu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 11, 'Ia harus menjauhi yang jahat dan melakukan yang baik, ia harus mencari perdamaian dan berusaha mendapatkannya.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 12, 'Sebab mata Tuhan tertuju kepada orang-orang benar, dan telinga-Nya kepada permohonan mereka yang minta tolong, tetapi wajah Tuhan menentang orang-orang yang berbuat jahat."', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 13, 'Dan siapakah yang akan berbuat jahat terhadap kamu, jika kamu rajin berbuat baik?', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 14, 'Tetapi sekalipun kamu harus menderita juga karena kebenaran, kamu akan berbahagia. Sebab itu janganlah kamu takuti apa yang mereka takuti dan janganlah gentar.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 15, 'Tetapi kuduskanlah Kristus di dalam hatimu sebagai Tuhan! Dan siap sedialah pada segala waktu untuk memberi pertanggungan jawab kepada tiap-tiap orang yang meminta pertanggungan jawab dari kamu tentang pengharapan yang ada padamu, tetapi haruslah dengan lemah lembut dan hormat,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 16, 'dan dengan hati nurani yang murni, supaya mereka, yang memfitnah kamu karena hidupmu yang saleh dalam Kristus, menjadi malu karena fitnahan mereka itu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 17, 'Sebab lebih baik menderita karena berbuat baik, jika hal itu dikehendaki Allah, dari pada menderita karena berbuat jahat.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 18, 'Sebab juga Kristus telah mati sekali untuk segala dosa kita, Ia yang benar untuk orang-orang yang tidak benar, supaya Ia membawa kita kepada Allah; Ia, yang telah dibunuh dalam keadaan-Nya sebagai manusia, tetapi yang telah dibangkitkan menurut Roh,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 19, 'dan di dalam Roh itu juga Ia pergi memberitakan Injil kepada roh-roh yang di dalam penjara,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 20, 'yaitu kepada roh-roh mereka yang dahulu pada waktu Nuh tidak taat kepada Allah, ketika Allah tetap menanti dengan sabar waktu Nuh sedang mempersiapkan bahteranya, di mana hanya sedikit, yaitu delapan orang, yang diselamatkan oleh air bah itu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 21, 'Juga kamu sekarang diselamatkan oleh kiasannya, yaitu baptisan?maksudnya bukan untuk membersihkan kenajisan jasmani, melainkan untuk memohonkan hati nurani yang baik kepada Allah?oleh kebangkitan Yesus Kristus,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 3, 22, 'yang duduk di sebelah kanan Allah, setelah Ia naik ke sorga sesudah segala malaikat, kuasa dan kekuatan ditaklukkan kepada-Nya.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 1, 'Jadi, karena Kristus telah menderita penderitaan badani, kamupun harus juga mempersenjatai dirimu dengan pikiran yang demikian, ?karena barangsiapa telah menderita penderitaan badani, ia telah berhenti berbuat dosa?,', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 2, 'supaya waktu yang sisa jangan kamu pergunakan menurut keinginan manusia, tetapi menurut kehendak Allah.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 3, 'Sebab telah cukup banyak waktu kamu pergunakan untuk melakukan kehendak orang-orang yang tidak mengenal Allah. Kamu telah hidup dalam rupa-rupa hawa nafsu, keinginan, kemabukan, pesta pora, perjamuan minum dan penyembahan berhala yang terlarang.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 4, 'Sebab itu mereka heran, bahwa kamu tidak turut mencemplungkan diri bersama-sama mereka di dalam kubangan ketidaksenonohan yang sama, dan mereka memfitnah kamu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 5, 'Tetapi mereka harus memberi pertanggungan jawab kepada Dia, yang telah siap sedia menghakimi orang yang hidup dan yang mati.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 6, 'Itulah sebabnya maka Injil telah diberitakan juga kepada orang-orang mati, supaya mereka, sama seperti semua manusia, dihakimi secara badani; tetapi oleh roh dapat hidup menurut kehendak Allah.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 7, 'Kesudahan segala sesuatu sudah dekat. Karena itu kuasailah dirimu dan jadilah tenang, supaya kamu dapat berdoa.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 8, 'Tetapi yang terutama: kasihilah sungguh-sungguh seorang akan yang lain, sebab kasih menutupi banyak sekali dosa.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 9, 'Berilah tumpangan seorang akan yang lain dengan tidak bersungut-sungut.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 10, 'Layanilah seorang akan yang lain, sesuai dengan karunia yang telah diperoleh tiap-tiap orang sebagai pengurus yang baik dari kasih karunia Allah.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 11, 'Jika ada orang yang berbicara, baiklah ia berbicara sebagai orang yang menyampaikan firman Allah; jika ada orang yang melayani, baiklah ia melakukannya dengan kekuatan yang dianugerahkan Allah, supaya Allah dimuliakan dalam segala sesuatu karena Yesus Kristus. Ialah yang empunya kemuliaan dan kuasa sampai selama-lamanya! Amin.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 12, 'Saudara-saudara yang kekasih, janganlah kamu heran akan nyala api siksaan yang datang kepadamu sebagai ujian, seolah-olah ada sesuatu yang luar biasa terjadi atas kamu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 13, 'Sebaliknya, bersukacitalah, sesuai dengan bagian yang kamu dapat dalam penderitaan Kristus, supaya kamu juga boleh bergembira dan bersukacita pada waktu Ia menyatakan kemuliaan-Nya.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 14, 'Berbahagialah kamu, jika kamu dinista karena nama Kristus, sebab Roh kemuliaan, yaitu Roh Allah ada padamu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 15, 'Janganlah ada di antara kamu yang harus menderita sebagai pembunuh atau pencuri atau penjahat, atau pengacau.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 16, 'Tetapi, jika ia menderita sebagai orang Kristen, maka janganlah ia malu, melainkan hendaklah ia memuliakan Allah dalam nama Kristus itu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 17, 'Karena sekarang telah tiba saatnya penghakiman dimulai, dan pada rumah Allah sendiri yang harus pertama-tama dihakimi. Dan jika penghakiman itu dimulai pada kita, bagaimanakah kesudahannya dengan mereka yang tidak percaya pada Injil Allah?', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 18, 'Dan jika orang benar hampir-hampir tidak diselamatkan, apakah yang akan terjadi dengan orang fasik dan orang berdosa?', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 4, 19, 'Karena itu baiklah juga mereka yang harus menderita karena kehendak Allah, menyerahkan jiwanya, dengan selalu berbuat baik, kepada Pencipta yang setia.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 1, 'Aku menasihatkan para penatua di antara kamu, aku sebagai teman penatua dan saksi penderitaan Kristus, yang juga akan mendapat bagian dalam kemuliaan yang akan dinyatakan kelak.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 2, 'Gembalakanlah kawanan domba Allah yang ada padamu, jangan dengan paksa, tetapi dengan sukarela sesuai dengan kehendak Allah, dan jangan karena mau mencari keuntungan, tetapi dengan pengabdian diri.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 3, 'Janganlah kamu berbuat seolah-olah kamu mau memerintah atas mereka yang dipercayakan kepadamu, tetapi hendaklah kamu menjadi teladan bagi kawanan domba itu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 4, 'Maka kamu, apabila Gembala Agung datang, kamu akan menerima mahkota kemuliaan yang tidak dapat layu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 5, 'Demikian jugalah kamu, hai orang-orang muda, tunduklah kepada orang-orang yang tua. Dan kamu semua, rendahkanlah dirimu seorang terhadap yang lain, sebab: "Allah menentang orang yang congkak, tetapi mengasihani orang yang rendah hati."', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 6, 'Karena itu rendahkanlah dirimu di bawah tangan Tuhan yang kuat, supaya kamu ditinggikan-Nya pada waktunya.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 7, 'Serahkanlah segala kekuatiranmu kepada-Nya, sebab Ia yang memelihara kamu.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 8, 'Sadarlah dan berjaga-jagalah! Lawanmu, si Iblis, berjalan keliling sama seperti singa yang mengaum-aum dan mencari orang yang dapat ditelannya.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 9, 'Lawanlah dia dengan iman yang teguh, sebab kamu tahu, bahwa semua saudaramu di seluruh dunia menanggung penderitaan yang sama.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 10, 'Dan Allah, sumber segala kasih karunia, yang telah memanggil kamu dalam Kristus kepada kemuliaan-Nya yang kekal, akan melengkapi, meneguhkan, menguatkan dan mengokohkan kamu, sesudah kamu menderita seketika lamanya.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 11, 'Ialah yang empunya kuasa sampai selama-lamanya! Amin.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 12, 'Dengan perantaraan Silwanus, yang kuanggap sebagai seorang saudara yang dapat dipercayai, aku menulis dengan singkat kepada kamu untuk menasihati dan meyakinkan kamu, bahwa ini adalah kasih karunia yang benar-benar dari Allah. Berdirilah dengan teguh di dalamnya!', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 13, 'Salam kepada kamu sekalian dari kawanmu yang terpilih yang di Babilon, dan juga dari Markus, anakku.', 'id', 'TB'),
  ('60', '1ptr', '1 Petrus', 5, 14, 'Berilah salam seorang kepada yang lain dengan cium yang kudus. Damai sejahtera menyertai kamu sekalian yang berada dalam Kristus. Amin.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 1, 'Dari Simon Petrus, hamba dan rasul Yesus Kristus, kepada mereka yang bersama-sama dengan kami memperoleh iman oleh karena keadilan Allah dan Juruselamat kita, Yesus Kristus.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 2, 'Kasih karunia dan damai sejahtera melimpahi kamu oleh pengenalan akan Allah dan akan Yesus, Tuhan kita.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 3, 'Karena kuasa ilahi-Nya telah menganugerahkan kepada kita segala sesuatu yang berguna untuk hidup yang saleh oleh pengenalan kita akan Dia, yang telah memanggil kita oleh kuasa-Nya yang mulia dan ajaib.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 4, 'Dengan jalan itu Ia telah menganugerahkan kepada kita janji-janji yang berharga dan yang sangat besar, supaya olehnya kamu boleh mengambil bagian dalam kodrat ilahi, dan luput dari hawa nafsu duniawi yang membinasakan dunia.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 5, 'Justru karena itu kamu harus dengan sungguh-sungguh berusaha untuk menambahkan kepada imanmu kebajikan, dan kepada kebajikan pengetahuan,', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 6, 'dan kepada pengetahuan penguasaan diri, kepada penguasaan diri ketekunan, dan kepada ketekunan kesalehan,', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 7, 'dan kepada kesalehan kasih akan saudara-saudara, dan kepada kasih akan saudara-saudara kasih akan semua orang.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 8, 'Sebab apabila semuanya itu ada padamu dengan berlimpah-limpah, kamu akan dibuatnya menjadi giat dan berhasil dalam pengenalanmu akan Yesus Kristus, Tuhan kita.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 9, 'Tetapi barangsiapa tidak memiliki semuanya itu, ia menjadi buta dan picik, karena ia lupa, bahwa dosa-dosanya yang dahulu telah dihapuskan.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 10, 'Karena itu, saudara-saudaraku, berusahalah sungguh-sungguh, supaya panggilan dan pilihanmu makin teguh. Sebab jikalau kamu melakukannya, kamu tidak akan pernah tersandung.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 11, 'Dengan demikian kepada kamu akan dikaruniakan hak penuh untuk memasuki Kerajaan kekal, yaitu Kerajaan Tuhan dan Juruselamat kita, Yesus Kristus.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 12, 'Karena itu aku senantiasa bermaksud mengingatkan kamu akan semuanya itu, sekalipun kamu telah mengetahuinya dan telah teguh dalam kebenaran yang telah kamu terima.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 13, 'Aku menganggap sebagai kewajibanku untuk tetap mengingatkan kamu akan semuanya itu selama aku belum menanggalkan kemah tubuhku ini.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 14, 'Sebab aku tahu, bahwa aku akan segera menanggalkan kemah tubuhku ini, sebagaimana yang telah diberitahukan kepadaku oleh Yesus Kristus, Tuhan kita.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 15, 'Tetapi aku akan berusaha, supaya juga sesudah kepergianku itu kamu selalu mengingat semuanya itu.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 16, 'Sebab kami tidak mengikuti dongeng-dongeng isapan jempol manusia, ketika kami memberitahukan kepadamu kuasa dan kedatangan Tuhan kita, Yesus Kristus sebagai raja, tetapi kami adalah saksi mata dari kebesaran-Nya.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 17, 'Kami menyaksikan, bagaimana Ia menerima kehormatan dan kemuliaan dari Allah Bapa, ketika datang kepada-Nya suara dari Yang Mahamulia, yang mengatakan: "Inilah Anak yang Kukasihi, kepada-Nyalah Aku berkenan."', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 18, 'Suara itu kami dengar datang dari sorga, ketika kami bersama-sama dengan Dia di atas gunung yang kudus.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 19, 'Dengan demikian kami makin diteguhkan oleh firman yang telah disampaikan oleh para nabi. Alangkah baiknya kalau kamu memperhatikannya sama seperti memperhatikan pelita yang bercahaya di tempat yang gelap sampai fajar menyingsing dan bintang timur terbit bersinar di dalam hatimu.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 20, 'Yang terutama harus kamu ketahui, ialah bahwa nubuat-nubuat dalam Kitab Suci tidak boleh ditafsirkan menurut kehendak sendiri,', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 1, 21, 'sebab tidak pernah nubuat dihasilkan oleh kehendak manusia, tetapi oleh dorongan Roh Kudus orang-orang berbicara atas nama Allah.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 1, 'Sebagaimana nabi-nabi palsu dahulu tampil di tengah-tengah umat Allah, demikian pula di antara kamu akan ada guru-guru palsu. Mereka akan memasukkan pengajaran-pengajaran sesat yang membinasakan, bahkan mereka akan menyangkal Penguasa yang telah menebus mereka dan dengan jalan demikian segera mendatangkan kebinasaan atas diri mereka.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 2, 'Banyak orang akan mengikuti cara hidup mereka yang dikuasai hawa nafsu, dan karena mereka Jalan Kebenaran akan dihujat.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 3, 'Dan karena serakahnya guru-guru palsu itu akan berusaha mencari untung dari kamu dengan ceritera-ceritera isapan jempol mereka. Tetapi untuk perbuatan mereka itu hukuman telah lama tersedia dan kebinasaan tidak akan tertunda.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 4, 'Sebab jikalau Allah tidak menyayangkan malaikat-malaikat yang berbuat dosa tetapi melemparkan mereka ke dalam neraka dan dengan demikian menyerahkannya ke dalam gua-gua yang gelap untuk menyimpan mereka sampai hari penghakiman;', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 5, 'dan jikalau Allah tidak menyayangkan dunia purba, tetapi hanya menyelamatkan Nuh, pemberita kebenaran itu, dengan tujuh orang lain, ketika Ia mendatangkan air bah atas dunia orang-orang yang fasik;', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 6, 'dan jikalau Allah membinasakan kota Sodom dan Gomora dengan api, dan dengan demikian memusnahkannya dan menjadikannya suatu peringatan untuk mereka yang hidup fasik di masa-masa kemudian,', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 7, 'tetapi Ia menyelamatkan Lot, orang yang benar, yang terus-menerus menderita oleh cara hidup orang-orang yang tak mengenal hukum dan yang hanya mengikuti hawa nafsu mereka saja, ?', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 8, 'sebab orang benar ini tinggal di tengah-tengah mereka dan setiap hari melihat dan mendengar perbuatan-perbuatan mereka yang jahat itu, sehingga jiwanya yang benar itu tersiksa?', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 9, 'maka nyata, bahwa Tuhan tahu menyelamatkan orang-orang saleh dari pencobaan dan tahu menyimpan orang-orang jahat untuk disiksa pada hari penghakiman,', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 10, 'terutama mereka yang menuruti hawa nafsunya karena ingin mencemarkan diri dan yang menghina pemerintahan Allah. Mereka begitu berani dan angkuh, sehingga tidak segan-segan menghujat kemuliaan,', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 11, 'padahal malaikat-malaikat sendiri, yang sekalipun lebih kuat dan lebih berkuasa dari pada mereka, tidak memakai kata-kata hujat, kalau malaikat-malaikat menuntut hukuman atas mereka di hadapan Allah.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 12, 'Tetapi mereka itu sama dengan hewan yang tidak berakal, sama dengan binatang yang hanya dilahirkan untuk ditangkap dan dimusnahkan. Mereka menghujat apa yang tidak mereka ketahui, sehingga oleh perbuatan mereka yang jahat mereka sendiri akan binasa seperti binatang liar,', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 13, 'dan akan mengalami nasib yang buruk sebagai upah kejahatan mereka. Berfoya-foya pada siang hari, mereka anggap kenikmatan. Mereka adalah kotoran dan noda, yang mabuk dalam hawa nafsu mereka kalau mereka duduk makan minum bersama-sama dengan kamu.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 14, 'Mata mereka penuh nafsu zinah dan mereka tidak pernah jemu berbuat dosa. Mereka memikat orang-orang yang lemah. Hati mereka telah terlatih dalam keserakahan. Mereka adalah orang-orang yang terkutuk!', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 15, 'Oleh karena mereka telah meninggalkan jalan yang benar, maka tersesatlah mereka, lalu mengikuti jalan Bileam, anak Beor, yang suka menerima upah untuk perbuatan-perbuatan yang jahat.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 16, 'Tetapi Bileam beroleh peringatan keras untuk kejahatannya, sebab keledai beban yang bisu berbicara dengan suara manusia dan mencegah kebebalan nabi itu.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 17, 'Guru-guru palsu itu adalah seperti mata air yang kering, seperti kabut yang dihalaukan taufan; bagi mereka telah tersedia tempat dalam kegelapan yang paling dahsyat.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 18, 'Sebab mereka mengucapkan kata-kata yang congkak dan hampa dan mempergunakan hawa nafsu cabul untuk memikat orang-orang yang baru saja melepaskan diri dari mereka yang hidup dalam kesesatan.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 19, 'Mereka menjanjikan kemerdekaan kepada orang lain, padahal mereka sendiri adalah hamba-hamba kebinasaan, karena siapa yang dikalahkan orang, ia adalah hamba orang itu.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 20, 'Sebab jika mereka, oleh pengenalan mereka akan Tuhan dan Juruselamat kita, Yesus Kristus, telah melepaskan diri dari kecemaran-kecemaran dunia, tetapi terlibat lagi di dalamnya, maka akhirnya keadaan mereka lebih buruk dari pada yang semula.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 21, 'Karena itu bagi mereka adalah lebih baik, jika mereka tidak pernah mengenal Jalan Kebenaran dari pada mengenalnya, tetapi kemudian berbalik dari perintah kudus yang disampaikan kepada mereka.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 2, 22, 'Bagi mereka cocok apa yang dikatakan peribahasa yang benar ini: "Anjing kembali lagi ke muntahnya, dan babi yang mandi kembali lagi ke kubangannya."', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 1, 'Saudara-saudara yang kekasih, ini sudah surat yang kedua, yang kutulis kepadamu. Di dalam kedua surat itu aku berusaha menghidupkan pengertian yang murni oleh peringatan-peringatan,', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 2, 'supaya kamu mengingat akan perkataan yang dahulu telah diucapkan oleh nabi-nabi kudus dan mengingat akan perintah Tuhan dan Juruselamat yang telah disampaikan oleh rasul-rasulmu kepadamu.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 3, 'Yang terutama harus kamu ketahui ialah, bahwa pada hari-hari zaman akhir akan tampil pengejek-pengejek dengan ejekan-ejekannya, yaitu orang-orang yang hidup menuruti hawa nafsunya.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 4, 'Kata mereka: "Di manakah janji tentang kedatangan-Nya itu? Sebab sejak bapa-bapa leluhur kita meninggal, segala sesuatu tetap seperti semula, pada waktu dunia diciptakan."', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 5, 'Mereka sengaja tidak mau tahu, bahwa oleh firman Allah langit telah ada sejak dahulu, dan juga bumi yang berasal dari air dan oleh air,', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 6, 'dan bahwa oleh air itu, bumi yang dahulu telah binasa, dimusnahkan oleh air bah.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 7, 'Tetapi oleh firman itu juga langit dan bumi yang sekarang terpelihara dari api dan disimpan untuk hari penghakiman dan kebinasaan orang-orang fasik.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 8, 'Akan tetapi, saudara-saudaraku yang kekasih, yang satu ini tidak boleh kamu lupakan, yaitu, bahwa di hadapan Tuhan satu hari sama seperti seribu tahun dan seribu tahun sama seperti satu hari.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 9, 'Tuhan tidak lalai menepati janji-Nya, sekalipun ada orang yang menganggapnya sebagai kelalaian, tetapi Ia sabar terhadap kamu, karena Ia menghendaki supaya jangan ada yang binasa, melainkan supaya semua orang berbalik dan bertobat.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 10, 'Tetapi hari Tuhan akan tiba seperti pencuri. Pada hari itu langit akan lenyap dengan gemuruh yang dahsyat dan unsur-unsur dunia akan hangus dalam nyala api, dan bumi dan segala yang ada di atasnya akan hilang lenyap.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 11, 'Jadi, jika segala sesuatu ini akan hancur secara demikian, betapa suci dan salehnya kamu harus hidup', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 12, 'yaitu kamu yang menantikan dan mempercepat kedatangan hari Allah. Pada hari itu langit akan binasa dalam api dan unsur-unsur dunia akan hancur karena nyalanya.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 13, 'Tetapi sesuai dengan janji-Nya, kita menantikan langit yang baru dan bumi yang baru, di mana terdapat kebenaran.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 14, 'Sebab itu, saudara-saudaraku yang kekasih, sambil menantikan semuanya ini, kamu harus berusaha, supaya kamu kedapatan tak bercacat dan tak bernoda di hadapan-Nya, dalam perdamaian dengan Dia.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 15, 'Anggaplah kesabaran Tuhan kita sebagai kesempatan bagimu untuk beroleh selamat, seperti juga Paulus, saudara kita yang kekasih, telah menulis kepadamu menurut hikmat yang dikaruniakan kepadanya.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 16, 'Hal itu dibuatnya dalam semua suratnya, apabila ia berbicara tentang perkara-perkara ini. Dalam surat-suratnya itu ada hal-hal yang sukar difahami, sehingga orang-orang yang tidak memahaminya dan yang tidak teguh imannya, memutarbalikkannya menjadi kebinasaan mereka sendiri, sama seperti yang juga mereka buat dengan tulisan-tulisan yang lain.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 17, 'Tetapi kamu, saudara-saudaraku yang kekasih, kamu telah mengetahui hal ini sebelumnya. Karena itu waspadalah, supaya kamu jangan terseret ke dalam kesesatan orang-orang yang tak mengenal hukum, dan jangan kehilangan peganganmu yang teguh.', 'id', 'TB'),
  ('61', '2ptr', '2 Petrus', 3, 18, 'Tetapi bertumbuhlah dalam kasih karunia dan dalam pengenalan akan Tuhan dan Juruselamat kita, Yesus Kristus. Bagi-Nya kemuliaan, sekarang dan sampai selama-lamanya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 1, 1, 'Apa yang telah ada sejak semula, yang telah kami dengar, yang telah kami lihat dengan mata kami, yang telah kami saksikan dan yang telah kami raba dengan tangan kami tentang Firman hidup?itulah yang kami tuliskan kepada kamu.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 1, 2, 'Hidup itu telah dinyatakan, dan kami telah melihatnya dan sekarang kami bersaksi dan memberitakan kepada kamu tentang hidup kekal, yang ada bersama-sama dengan Bapa dan yang telah dinyatakan kepada kami.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 1, 3, 'Apa yang telah kami lihat dan yang telah kami dengar itu, kami beritakan kepada kamu juga, supaya kamupun beroleh persekutuan dengan kami. Dan persekutuan kami adalah persekutuan dengan Bapa dan dengan Anak-Nya, Yesus Kristus.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 1, 4, 'Dan semuanya ini kami tuliskan kepada kamu, supaya sukacita kami menjadi sempurna.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 1, 5, 'Dan inilah berita, yang telah kami dengar dari Dia, dan yang kami sampaikan kepada kamu: Allah adalah terang dan di dalam Dia sama sekali tidak ada kegelapan.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 1, 6, 'Jika kita katakan, bahwa kita beroleh persekutuan dengan Dia, namun kita hidup di dalam kegelapan, kita berdusta dan kita tidak melakukan kebenaran.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 1, 7, 'Tetapi jika kita hidup di dalam terang sama seperti Dia ada di dalam terang, maka kita beroleh persekutuan seorang dengan yang lain, dan darah Yesus, Anak-Nya itu, menyucikan kita dari pada segala dosa.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 1, 8, 'Jika kita berkata, bahwa kita tidak berdosa, maka kita menipu diri kita sendiri dan kebenaran tidak ada di dalam kita.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 1, 9, 'Jika kita mengaku dosa kita, maka Ia adalah setia dan adil, sehingga Ia akan mengampuni segala dosa kita dan menyucikan kita dari segala kejahatan.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 1, 10, 'Jika kita berkata, bahwa kita tidak ada berbuat dosa, maka kita membuat Dia menjadi pendusta dan firman-Nya tidak ada di dalam kita.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 1, 'Anak-anakku, hal-hal ini kutuliskan kepada kamu, supaya kamu jangan berbuat dosa, namun jika seorang berbuat dosa, kita mempunyai seorang pengantara pada Bapa, yaitu Yesus Kristus, yang adil.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 2, 'Dan Ia adalah pendamaian untuk segala dosa kita, dan bukan untuk dosa kita saja, tetapi juga untuk dosa seluruh dunia.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 3, 'Dan inilah tandanya, bahwa kita mengenal Allah, yaitu jikalau kita menuruti perintah-perintah-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 4, 'Barangsiapa berkata: Aku mengenal Dia, tetapi ia tidak menuruti perintah-Nya, ia adalah seorang pendusta dan di dalamnya tidak ada kebenaran.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 5, 'Tetapi barangsiapa menuruti firman-Nya, di dalam orang itu sungguh sudah sempurna kasih Allah; dengan itulah kita ketahui, bahwa kita ada di dalam Dia.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 6, 'Barangsiapa mengatakan, bahwa ia ada di dalam Dia, ia wajib hidup sama seperti Kristus telah hidup.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 7, 'Saudara-saudara yang kekasih, bukan perintah baru yang kutuliskan kepada kamu, melainkan perintah lama yang telah ada padamu dari mulanya. Perintah lama itu ialah firman yang telah kamu dengar.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 8, 'Namun perintah baru juga yang kutuliskan kepada kamu, telah ternyata benar di dalam Dia dan di dalam kamu; sebab kegelapan sedang lenyap dan terang yang benar telah bercahaya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 9, 'Barangsiapa berkata, bahwa ia berada di dalam terang, tetapi ia membenci saudaranya, ia berada di dalam kegelapan sampai sekarang.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 10, 'Barangsiapa mengasihi saudaranya, ia tetap berada di dalam terang, dan di dalam dia tidak ada penyesatan.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 11, 'Tetapi barangsiapa membenci saudaranya, ia berada di dalam kegelapan dan hidup di dalam kegelapan. Ia tidak tahu ke mana ia pergi, karena kegelapan itu telah membutakan matanya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 12, 'Aku menulis kepada kamu, hai anak-anak, sebab dosamu telah diampuni oleh karena nama-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 13, 'Aku menulis kepada kamu, hai bapa-bapa, karena kamu telah mengenal Dia, yang ada dari mulanya. Aku menulis kepada kamu, hai orang-orang muda, karena kamu telah mengalahkan yang jahat.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 14, 'Aku menulis kepada kamu, hai anak-anak, karena kamu mengenal Bapa. Aku menulis kepada kamu, hai bapa-bapa, karena kamu mengenal Dia, yang ada dari mulanya. Aku menulis kepada kamu, hai orang-orang muda, karena kamu kuat dan firman Allah diam di dalam kamu dan kamu telah mengalahkan yang jahat.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 15, 'Janganlah kamu mengasihi dunia dan apa yang ada di dalamnya. Jikalau orang mengasihi dunia, maka kasih akan Bapa tidak ada di dalam orang itu.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 16, 'Sebab semua yang ada di dalam dunia, yaitu keinginan daging dan keinginan mata serta keangkuhan hidup, bukanlah berasal dari Bapa, melainkan dari dunia.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 17, 'Dan dunia ini sedang lenyap dengan keinginannya, tetapi orang yang melakukan kehendak Allah tetap hidup selama-lamanya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 18, 'Anak-anakku, waktu ini adalah waktu yang terakhir, dan seperti yang telah kamu dengar, seorang antikristus akan datang, sekarang telah bangkit banyak antikristus. Itulah tandanya, bahwa waktu ini benar-benar adalah waktu yang terakhir.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 19, 'Memang mereka berasal dari antara kita, tetapi mereka tidak sungguh-sungguh termasuk pada kita; sebab jika mereka sungguh-sungguh termasuk pada kita, niscaya mereka tetap bersama-sama dengan kita. Tetapi hal itu terjadi, supaya menjadi nyata, bahwa tidak semua mereka sungguh-sungguh termasuk pada kita.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 20, 'Tetapi kamu telah beroleh pengurapan dari Yang Kudus, dan dengan demikian kamu semua mengetahuinya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 21, 'Aku menulis kepadamu, bukan karena kamu tidak mengetahui kebenaran, tetapi justru karena kamu mengetahuinya dan karena kamu juga mengetahui, bahwa tidak ada dusta yang berasal dari kebenaran.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 22, 'Siapakah pendusta itu? Bukankah dia yang menyangkal bahwa Yesus adalah Kristus? Dia itu adalah antikristus, yaitu dia yang menyangkal baik Bapa maupun Anak.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 23, 'Sebab barangsiapa menyangkal Anak, ia juga tidak memiliki Bapa. Barangsiapa mengaku Anak, ia juga memiliki Bapa.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 24, 'Dan kamu, apa yang telah kamu dengar dari mulanya, itu harus tetap tinggal di dalam kamu. Jika apa yang telah kamu dengar dari mulanya itu tetap tinggal di dalam kamu, maka kamu akan tetap tinggal di dalam Anak dan di dalam Bapa.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 25, 'Dan inilah janji yang telah dijanjikan-Nya sendiri kepada kita, yaitu hidup yang kekal.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 26, 'Semua itu kutulis kepadamu, yaitu mengenai orang-orang yang berusaha menyesatkan kamu.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 27, 'Sebab di dalam diri kamu tetap ada pengurapan yang telah kamu terima dari pada-Nya. Karena itu tidak perlu kamu diajar oleh orang lain. Tetapi sebagaimana pengurapan-Nya mengajar kamu tentang segala sesuatu?dan pengajaran-Nya itu benar, tidak dusta?dan sebagaimana Ia dahulu telah mengajar kamu, demikianlah hendaknya kamu tetap tinggal di dalam Dia.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 28, 'Maka sekarang, anak-anakku, tinggallah di dalam Kristus, supaya apabila Ia menyatakan diri-Nya, kita beroleh keberanian percaya dan tidak usah malu terhadap Dia pada hari kedatangan-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 2, 29, 'Jikalau kamu tahu, bahwa Ia adalah benar, kamu harus tahu juga, bahwa setiap orang, yang berbuat kebenaran, lahir dari pada-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 1, 'Lihatlah, betapa besarnya kasih yang dikaruniakan Bapa kepada kita, sehingga kita disebut anak-anak Allah, dan memang kita adalah anak-anak Allah. Karena itu dunia tidak mengenal kita, sebab dunia tidak mengenal Dia.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 2, 'Saudara-saudaraku yang kekasih, sekarang kita adalah anak-anak Allah, tetapi belum nyata apa keadaan kita kelak; akan tetapi kita tahu, bahwa apabila Kristus menyatakan diri-Nya, kita akan menjadi sama seperti Dia, sebab kita akan melihat Dia dalam keadaan-Nya yang sebenarnya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 3, 'Setiap orang yang menaruh pengharapan itu kepada-Nya, menyucikan diri sama seperti Dia yang adalah suci.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 4, 'Setiap orang yang berbuat dosa, melanggar juga hukum Allah, sebab dosa ialah pelanggaran hukum Allah.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 5, 'Dan kamu tahu, bahwa Ia telah menyatakan diri-Nya, supaya Ia menghapus segala dosa, dan di dalam Dia tidak ada dosa.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 6, 'Karena itu setiap orang yang tetap berada di dalam Dia, tidak berbuat dosa lagi; setiap orang yang tetap berbuat dosa, tidak melihat dan tidak mengenal Dia.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 7, 'Anak-anakku, janganlah membiarkan seorangpun menyesatkan kamu. Barangsiapa yang berbuat kebenaran adalah benar, sama seperti Kristus adalah benar;', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 8, 'barangsiapa yang tetap berbuat dosa, berasal dari Iblis, sebab Iblis berbuat dosa dari mulanya. Untuk inilah Anak Allah menyatakan diri-Nya, yaitu supaya Ia membinasakan perbuatan-perbuatan Iblis itu.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 9, 'Setiap orang yang lahir dari Allah, tidak berbuat dosa lagi; sebab benih ilahi tetap ada di dalam dia dan ia tidak dapat berbuat dosa, karena ia lahir dari Allah.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 10, 'Inilah tandanya anak-anak Allah dan anak-anak Iblis: setiap orang yang tidak berbuat kebenaran, tidak berasal dari Allah, demikian juga barangsiapa yang tidak mengasihi saudaranya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 11, 'Sebab inilah berita yang telah kamu dengar dari mulanya, yaitu bahwa kita harus saling mengasihi;', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 12, 'bukan seperti Kain, yang berasal dari si jahat dan yang membunuh adiknya. Dan apakah sebabnya ia membunuhnya? Sebab segala perbuatannya jahat dan perbuatan adiknya benar.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 13, 'Janganlah kamu heran, saudara-saudara, apabila dunia membenci kamu.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 14, 'Kita tahu, bahwa kita sudah berpindah dari dalam maut ke dalam hidup, yaitu karena kita mengasihi saudara kita. Barangsiapa tidak mengasihi, ia tetap di dalam maut.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 15, 'Setiap orang yang membenci saudaranya, adalah seorang pembunuh manusia. Dan kamu tahu, bahwa tidak ada seorang pembunuh yang tetap memiliki hidup yang kekal di dalam dirinya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 16, 'Demikianlah kita ketahui kasih Kristus, yaitu bahwa Ia telah menyerahkan nyawa-Nya untuk kita; jadi kitapun wajib menyerahkan nyawa kita untuk saudara-saudara kita.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 17, 'Barangsiapa mempunyai harta duniawi dan melihat saudaranya menderita kekurangan tetapi menutup pintu hatinya terhadap saudaranya itu, bagaimanakah kasih Allah dapat tetap di dalam dirinya?', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 18, 'Anak-anakku, marilah kita mengasihi bukan dengan perkataan atau dengan lidah, tetapi dengan perbuatan dan dalam kebenaran.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 19, 'Demikianlah kita ketahui, bahwa kita berasal dari kebenaran. Demikian pula kita boleh menenangkan hati kita di hadapan Allah,', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 20, 'sebab jika kita dituduh olehnya, Allah adalah lebih besar dari pada hati kita serta mengetahui segala sesuatu.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 21, 'Saudara-saudaraku yang kekasih, jikalau hati kita tidak menuduh kita, maka kita mempunyai keberanian percaya untuk mendekati Allah,', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 22, 'dan apa saja yang kita minta, kita memperolehnya dari pada-Nya, karena kita menuruti segala perintah-Nya dan berbuat apa yang berkenan kepada-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 23, 'Dan inilah perintah-Nya itu: supaya kita percaya akan nama Yesus Kristus, Anak-Nya, dan supaya kita saling mengasihi sesuai dengan perintah yang diberikan Kristus kepada kita.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 3, 24, 'Barangsiapa menuruti segala perintah-Nya, ia diam di dalam Allah dan Allah di dalam dia. Dan demikianlah kita ketahui, bahwa Allah ada di dalam kita, yaitu Roh yang telah Ia karuniakan kepada kita.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 1, 'Saudara-saudaraku yang kekasih, janganlah percaya akan setiap roh, tetapi ujilah roh-roh itu, apakah mereka berasal dari Allah; sebab banyak nabi-nabi palsu yang telah muncul dan pergi ke seluruh dunia.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 2, 'Demikianlah kita mengenal Roh Allah: setiap roh yang mengaku, bahwa Yesus Kristus telah datang sebagai manusia, berasal dari Allah,', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 3, 'dan setiap roh, yang tidak mengaku Yesus, tidak berasal dari Allah. Roh itu adalah roh antikristus dan tentang dia telah kamu dengar, bahwa ia akan datang dan sekarang ini ia sudah ada di dalam dunia.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 4, 'Kamu berasal dari Allah, anak-anakku, dan kamu telah mengalahkan nabi-nabi palsu itu; sebab Roh yang ada di dalam kamu, lebih besar dari pada roh yang ada di dalam dunia.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 5, 'Mereka berasal dari dunia; sebab itu mereka berbicara tentang hal-hal duniawi dan dunia mendengarkan mereka.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 6, 'Kami berasal dari Allah: barangsiapa mengenal Allah, ia mendengarkan kami; barangsiapa tidak berasal dari Allah, ia tidak mendengarkan kami. Itulah tandanya Roh kebenaran dan roh yang menyesatkan.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 7, 'Saudara-saudaraku yang kekasih, marilah kita saling mengasihi, sebab kasih itu berasal dari Allah; dan setiap orang yang mengasihi, lahir dari Allah dan mengenal Allah.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 8, 'Barangsiapa tidak mengasihi, ia tidak mengenal Allah, sebab Allah adalah kasih.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 9, 'Dalam hal inilah kasih Allah dinyatakan di tengah-tengah kita, yaitu bahwa Allah telah mengutus Anak-Nya yang tunggal ke dalam dunia, supaya kita hidup oleh-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 10, 'Inilah kasih itu: Bukan kita yang telah mengasihi Allah, tetapi Allah yang telah mengasihi kita dan yang telah mengutus Anak-Nya sebagai pendamaian bagi dosa-dosa kita.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 11, 'Saudara-saudaraku yang kekasih, jikalau Allah sedemikian mengasihi kita, maka haruslah kita juga saling mengasihi.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 12, 'Tidak ada seorangpun yang pernah melihat Allah. Jika kita saling mengasihi, Allah tetap di dalam kita, dan kasih-Nya sempurna di dalam kita.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 13, 'Demikianlah kita ketahui, bahwa kita tetap berada di dalam Allah dan Dia di dalam kita: Ia telah mengaruniakan kita mendapat bagian dalam Roh-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 14, 'Dan kami telah melihat dan bersaksi, bahwa Bapa telah mengutus Anak-Nya menjadi Juruselamat dunia.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 15, 'Barangsiapa mengaku, bahwa Yesus adalah Anak Allah, Allah tetap berada di dalam dia dan dia di dalam Allah.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 16, 'Kita telah mengenal dan telah percaya akan kasih Allah kepada kita. Allah adalah kasih, dan barangsiapa tetap berada di dalam kasih, ia tetap berada di dalam Allah dan Allah di dalam dia.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 17, 'Dalam hal inilah kasih Allah sempurna di dalam kita, yaitu kalau kita mempunyai keberanian percaya pada hari penghakiman, karena sama seperti Dia, kita juga ada di dalam dunia ini.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 18, 'Di dalam kasih tidak ada ketakutan: kasih yang sempurna melenyapkan ketakutan; sebab ketakutan mengandung hukuman dan barangsiapa takut, ia tidak sempurna di dalam kasih.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 19, 'Kita mengasihi, karena Allah lebih dahulu mengasihi kita.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 20, 'Jikalau seorang berkata: "Aku mengasihi Allah," dan ia membenci saudaranya, maka ia adalah pendusta, karena barangsiapa tidak mengasihi saudaranya yang dilihatnya, tidak mungkin mengasihi Allah, yang tidak dilihatnya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 4, 21, 'Dan perintah ini kita terima dari Dia: Barangsiapa mengasihi Allah, ia harus juga mengasihi saudaranya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 1, 'Setiap orang yang percaya, bahwa Yesus adalah Kristus, lahir dari Allah; dan setiap orang yang mengasihi Dia yang melahirkan, mengasihi juga Dia yang lahir dari pada-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 2, 'Inilah tandanya, bahwa kita mengasihi anak-anak Allah, yaitu apabila kita mengasihi Allah serta melakukan perintah-perintah-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 3, 'Sebab inilah kasih kepada Allah, yaitu, bahwa kita menuruti perintah-perintah-Nya. Perintah-perintah-Nya itu tidak berat,', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 4, 'sebab semua yang lahir dari Allah, mengalahkan dunia. Dan inilah kemenangan yang mengalahkan dunia: iman kita.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 5, 'Siapakah yang mengalahkan dunia, selain dari pada dia yang percaya, bahwa Yesus adalah Anak Allah?', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 6, 'Inilah Dia yang telah datang dengan air dan darah, yaitu Yesus Kristus, bukan saja dengan air, tetapi dengan air dan dengan darah. Dan Rohlah yang memberi kesaksian, karena Roh adalah kebenaran.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 7, 'Sebab ada tiga yang memberi kesaksian (di dalam sorga: Bapa, Firman dan Roh Kudus; dan ketiganya adalah satu.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 8, 'Dan ada tiga yang memberi kesaksian di bumi): Roh dan air dan darah dan ketiganya adalah satu.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 9, 'Kita menerima kesaksian manusia, tetapi kesaksian Allah lebih kuat. Sebab demikianlah kesaksian yang diberikan Allah tentang Anak-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 10, 'Barangsiapa percaya kepada Anak Allah, ia mempunyai kesaksian itu di dalam dirinya; barangsiapa tidak percaya kepada Allah, ia membuat Dia menjadi pendusta, karena ia tidak percaya akan kesaksian yang diberikan Allah tentang Anak-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 11, 'Dan inilah kesaksian itu: Allah telah mengaruniakan hidup yang kekal kepada kita dan hidup itu ada di dalam Anak-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 12, 'Barangsiapa memiliki Anak, ia memiliki hidup; barangsiapa tidak memiliki Anak, ia tidak memiliki hidup.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 13, 'Semuanya itu kutuliskan kepada kamu, supaya kamu yang percaya kepada nama Anak Allah, tahu, bahwa kamu memiliki hidup yang kekal.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 14, 'Dan inilah keberanian percaya kita kepada-Nya, yaitu bahwa Ia mengabulkan doa kita, jikalau kita meminta sesuatu kepada-Nya menurut kehendak-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 15, 'Dan jikalau kita tahu, bahwa Ia mengabulkan apa saja yang kita minta, maka kita juga tahu, bahwa kita telah memperoleh segala sesuatu yang telah kita minta kepada-Nya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 16, 'Kalau ada seorang melihat saudaranya berbuat dosa, yaitu dosa yang tidak mendatangkan maut, hendaklah ia berdoa kepada Allah dan Dia akan memberikan hidup kepadanya, yaitu mereka, yang berbuat dosa yang tidak mendatangkan maut. Ada dosa yang mendatangkan maut: tentang itu tidak kukatakan, bahwa ia harus berdoa.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 17, 'Semua kejahatan adalah dosa, tetapi ada dosa yang tidak mendatangkan maut.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 18, 'Kita tahu, bahwa setiap orang yang lahir dari Allah, tidak berbuat dosa; tetapi Dia yang lahir dari Allah melindunginya, dan si jahat tidak dapat menjamahnya.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 19, 'Kita tahu, bahwa kita berasal dari Allah dan seluruh dunia berada di bawah kuasa si jahat.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 20, 'Akan tetapi kita tahu, bahwa Anak Allah telah datang dan telah mengaruniakan pengertian kepada kita, supaya kita mengenal Yang Benar; dan kita ada di dalam Yang Benar, di dalam Anak-Nya Yesus Kristus. Dia adalah Allah yang benar dan hidup yang kekal.', 'id', 'TB'),
  ('62', '1yoh', '1 Yohanes', 5, 21, 'Anak-anakku, waspadalah terhadap segala berhala.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 1, 'Dari penatua kepada Ibu yang terpilih dan anak-anaknya yang benar-benar aku kasihi. Bukan aku saja yang mengasihi kamu, tetapi juga semua orang yang telah mengenal kebenaran,', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 2, 'oleh karena kebenaran yang tetap di dalam kita dan yang akan menyertai kita sampai selama-lamanya.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 3, 'Kasih karunia, rahmat dan damai sejahtera dari Allah Bapa, dan dari Yesus Kristus, Anak Bapa, akan menyertai kita dalam kebenaran dan kasih.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 4, 'Aku sangat bersukacita, bahwa aku mendapati, bahwa separuh dari anak-anakmu hidup dalam kebenaran sesuai dengan perintah yang telah kita terima dari Bapa.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 5, 'Dan sekarang aku minta kepadamu, Ibu?bukan seolah-olah aku menuliskan perintah baru bagimu, tetapi menurut perintah yang sudah ada pada kita dari mulanya?supaya kita saling mengasihi.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 6, 'Dan inilah kasih itu, yaitu bahwa kita harus hidup menurut perintah-Nya. Dan inilah perintah itu, yaitu bahwa kamu harus hidup di dalam kasih, sebagaimana telah kamu dengar dari mulanya.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 7, 'Sebab banyak penyesat telah muncul dan pergi ke seluruh dunia, yang tidak mengaku, bahwa Yesus Kristus telah datang sebagai manusia. Itu adalah si penyesat dan antikristus.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 8, 'Waspadalah, supaya kamu jangan kehilangan apa yang telah kami kerjakan itu, tetapi supaya kamu mendapat upahmu sepenuhnya.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 9, 'Setiap orang yang tidak tinggal di dalam ajaran Kristus, tetapi yang melangkah keluar dari situ, tidak memiliki Allah. Barangsiapa tinggal di dalam ajaran itu, ia memiliki Bapa maupun Anak.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 10, 'Jikalau seorang datang kepadamu dan ia tidak membawa ajaran ini, janganlah kamu menerima dia di dalam rumahmu dan janganlah memberi salam kepadanya.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 11, 'Sebab barangsiapa memberi salam kepadanya, ia mendapat bagian dalam perbuatannya yang jahat.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 12, 'Sungguhpun banyak yang harus kutulis kepadamu, aku tidak mau melakukannya dengan kertas dan tinta, tetapi aku berharap datang sendiri kepadamu dan berbicara berhadapan muka dengan kamu, supaya sempurnalah sukacita kita.', 'id', 'TB'),
  ('63', '2yoh', '2 Yohanes', 1, 13, 'Salam kepada kamu dari anak-anak saudaramu yang terpilih.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 1, 'Dari penatua kepada Gayus yang kekasih, yang kukasihi dalam kebenaran.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 2, 'Saudaraku yang kekasih, aku berdoa, semoga engkau baik-baik dan sehat-sehat saja dalam segala sesuatu, sama seperti jiwamu baik-baik saja.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 3, 'Sebab aku sangat bersukacita, ketika beberapa saudara datang dan memberi kesaksian tentang hidupmu dalam kebenaran, sebab memang engkau hidup dalam kebenaran.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 4, 'Bagiku tidak ada sukacita yang lebih besar dari pada mendengar, bahwa anak-anakku hidup dalam kebenaran.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 5, 'Saudaraku yang kekasih, engkau bertindak sebagai orang percaya, di mana engkau berbuat segala sesuatu untuk saudara-saudara, sekalipun mereka adalah orang-orang asing.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 6, 'Mereka telah memberi kesaksian di hadapan jemaat tentang kasihmu. Baik benar perbuatanmu, jikalau engkau menolong mereka dalam perjalanan mereka, dengan suatu cara yang berkenan kepada Allah.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 7, 'Sebab karena nama-Nya mereka telah berangkat dengan tidak menerima sesuatupun dari orang-orang yang tidak mengenal Allah.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 8, 'Kita wajib menerima orang-orang yang demikian, supaya kita boleh mengambil bagian dalam pekerjaan mereka untuk kebenaran.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 9, 'Aku telah menulis sedikit kepada jemaat, tetapi Diotrefes yang ingin menjadi orang terkemuka di antara mereka, tidak mau mengakui kami.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 10, 'Karena itu, apabila aku datang, aku akan meminta perhatian atas segala perbuatan yang telah dilakukannya, sebab ia meleter melontarkan kata-kata yang kasar terhadap kami; dan belum merasa puas dengan itu, ia sendiri bukan saja tidak mau menerima saudara-saudara yang datang, tetapi juga mencegah orang-orang, yang mau menerima mereka dan mengucilkan orang-orang itu dari jemaat.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 11, 'Saudaraku yang kekasih, janganlah meniru yang jahat, melainkan yang baik. Barangsiapa berbuat baik, ia berasal dari Allah, tetapi barangsiapa berbuat jahat, ia tidak pernah melihat Allah.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 12, 'Tentang Demetrius semua orang memberi kesaksian yang baik, malah kebenaran sendiri memberi kesaksian yang demikian. Dan kami juga memberi kesaksian yang baik tentang dia, dan engkau tahu, bahwa kesaksian kami adalah benar.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 13, 'Banyak hal yang harus kutuliskan kepadamu, tetapi aku tidak mau menulis kepadamu dengan tinta dan pena.', 'id', 'TB'),
  ('64', '3yoh', '3 Yohanes', 1, 14, 'Aku harap segera berjumpa dengan engkau dan berbicara berhadapan muka. (1-15) Damai sejahtera menyertai engkau! Salam dari sahabat-sahabatmu. Sampaikanlah salamku kepada sahabat-sahabat satu per satu.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 1, 'Dari Yudas, hamba Yesus Kristus dan saudara Yakobus, kepada mereka, yang terpanggil, yang dikasihi dalam Allah Bapa, dan yang dipelihara untuk Yesus Kristus.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 2, 'Rahmat, damai sejahtera dan kasih kiranya melimpahi kamu.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 3, 'Saudara-saudaraku yang kekasih, sementara aku bersungguh-sungguh berusaha menulis kepada kamu tentang keselamatan kita bersama, aku merasa terdorong untuk menulis ini kepada kamu dan menasihati kamu, supaya kamu tetap berjuang untuk mempertahankan iman yang telah disampaikan kepada orang-orang kudus.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 4, 'Sebab ternyata ada orang tertentu yang telah masuk menyelusup di tengah-tengah kamu, yaitu orang-orang yang telah lama ditentukan untuk dihukum. Mereka adalah orang-orang yang fasik, yang menyalahgunakan kasih karunia Allah kita untuk melampiaskan hawa nafsu mereka, dan yang menyangkal satu-satunya Penguasa dan Tuhan kita, Yesus Kristus.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 5, 'Tetapi, sekalipun kamu telah mengetahui semuanya itu dan tidak meragukannya lagi, aku ingin mengingatkan kamu bahwa memang Tuhan menyelamatkan umat-Nya dari tanah Mesir, namun sekali lagi membinasakan mereka yang tidak percaya.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 6, 'Dan bahwa Ia menahan malaikat-malaikat yang tidak taat pada batas-batas kekuasaan mereka, tetapi yang meninggalkan tempat kediaman mereka, dengan belenggu abadi di dalam dunia kekelaman sampai penghakiman pada hari besar,', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 7, 'sama seperti Sodom dan Gomora dan kota-kota sekitarnya, yang dengan cara yang sama melakukan percabulan dan mengejar kepuasan-kepuasan yang tak wajar, telah menanggung siksaan api kekal sebagai peringatan kepada semua orang.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 8, 'Namun demikian orang-orang yang bermimpi-mimpian ini juga mencemarkan tubuh mereka dan menghina kekuasaan Allah serta menghujat semua yang mulia di sorga.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 9, 'Tetapi penghulu malaikat, Mikhael, ketika dalam suatu perselisihan bertengkar dengan Iblis mengenai mayat Musa, tidak berani menghakimi Iblis itu dengan kata-kata hujatan, tetapi berkata: "Kiranya Tuhan menghardik engkau!"', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 10, 'Akan tetapi mereka menghujat segala sesuatu yang tidak mereka ketahui dan justru apa yang mereka ketahui dengan nalurinya seperti binatang yang tidak berakal, itulah yang mengakibatkan kebinasaan mereka.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 11, 'Celakalah mereka, karena mereka mengikuti jalan yang ditempuh Kain dan karena mereka, oleh sebab upah, menceburkan diri ke dalam kesesatan Bileam, dan mereka binasa karena kedurhakaan seperti Korah.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 12, 'Mereka inilah noda dalam perjamuan kasihmu, di mana mereka tidak malu-malu melahap dan hanya mementingkan dirinya sendiri; mereka bagaikan awan yang tak berair, yang berlalu ditiup angin; mereka bagaikan pohon-pohon yang dalam musim gugur tidak menghasilkan buah, pohon-pohon yang terbantun dengan akar-akarnya dan yang mati sama sekali.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 13, 'Mereka bagaikan ombak laut yang ganas, yang membuihkan keaiban mereka sendiri; mereka bagaikan bintang-bintang yang baginya telah tersedia tempat di dunia kekelaman untuk selama-lamanya.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 14, 'Juga tentang mereka Henokh, keturunan ketujuh dari Adam, telah bernubuat, katanya: "Sesungguhnya Tuhan datang dengan beribu-ribu orang kudus-Nya,', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 15, 'hendak menghakimi semua orang dan menjatuhkan hukuman atas orang-orang fasik karena semua perbuatan fasik, yang mereka lakukan dan karena semua kata-kata nista, yang diucapkan orang-orang berdosa yang fasik itu terhadap Tuhan."', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 16, 'Mereka itu orang-orang yang menggerutu dan mengeluh tentang nasibnya, hidup menuruti hawa nafsunya, tetapi mulut mereka mengeluarkan perkataan-perkataan yang bukan-bukan dan mereka menjilat orang untuk mendapat keuntungan.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 17, 'Tetapi kamu, saudara-saudaraku yang kekasih, ingatlah akan apa yang dahulu telah dikatakan kepada kamu oleh rasul-rasul Tuhan kita, Yesus Kristus.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 18, 'Sebab mereka telah mengatakan kepada kamu: "Menjelang akhir zaman akan tampil pengejek-pengejek yang akan hidup menuruti hawa nafsu kefasikan mereka."', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 19, 'Mereka adalah pemecah belah yang dikuasai hanya oleh keinginan-keinginan dunia ini dan yang hidup tanpa Roh Kudus.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 20, 'Akan tetapi kamu, saudara-saudaraku yang kekasih, bangunlah dirimu sendiri di atas dasar imanmu yang paling suci dan berdoalah dalam Roh Kudus.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 21, 'Peliharalah dirimu demikian dalam kasih Allah sambil menantikan rahmat Tuhan kita, Yesus Kristus, untuk hidup yang kekal.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 22, 'Tunjukkanlah belas kasihan kepada mereka yang ragu-ragu,', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 23, 'selamatkanlah mereka dengan jalan merampas mereka dari api. Tetapi tunjukkanlah belas kasihan yang disertai ketakutan kepada orang-orang lain juga, dan bencilah pakaian mereka yang dicemarkan oleh keinginan-keinginan dosa.', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 24, 'Bagi Dia, yang berkuasa menjaga supaya jangan kamu tersandung dan yang membawa kamu dengan tak bernoda dan penuh kegembiraan di hadapan kemuliaan-Nya,', 'id', 'TB'),
  ('65', 'yud', 'Yudas', 1, 25, 'Allah yang esa, Juruselamat kita oleh Yesus Kristus, Tuhan kita, bagi Dia adalah kemuliaan, kebesaran, kekuatan dan kuasa sebelum segala abad dan sekarang dan sampai selama-lamanya. Amin. ?3Yoh?, ?1?, ?', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 1, 'Inilah wahyu Yesus Kristus, yang dikaruniakan Allah kepada-Nya, supaya ditunjukkan-Nya kepada hamba-hamba-Nya apa yang harus segera terjadi. Dan oleh malaikat-Nya yang diutus-Nya, Ia telah menyatakannya kepada hamba-Nya Yohanes.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 2, 'Yohanes telah bersaksi tentang firman Allah dan tentang kesaksian yang diberikan oleh Yesus Kristus, yaitu segala sesuatu yang telah dilihatnya.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 3, 'Berbahagialah ia yang membacakan dan mereka yang mendengarkan kata-kata nubuat ini, dan yang menuruti apa yang ada tertulis di dalamnya, sebab waktunya sudah dekat.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 4, 'Dari Yohanes kepada ketujuh jemaat yang di Asia Kecil: Kasih karunia dan damai sejahtera menyertai kamu, dari Dia, yang ada dan yang sudah ada dan yang akan datang, dan dari ketujuh roh yang ada di hadapan takhta-Nya,', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 5, 'dan dari Yesus Kristus, Saksi yang setia, yang pertama bangkit dari antara orang mati dan yang berkuasa atas raja-raja bumi ini. Bagi Dia, yang mengasihi kita dan yang telah melepaskan kita dari dosa kita oleh darah-Nya?', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 6, 'dan yang telah membuat kita menjadi suatu kerajaan, menjadi imam-imam bagi Allah, Bapa-Nya, bagi Dialah kemuliaan dan kuasa sampai selama-lamanya. Amin.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 7, 'Lihatlah, Ia datang dengan awan-awan dan setiap mata akan melihat Dia, juga mereka yang telah menikam Dia. Dan semua bangsa di bumi akan meratapi Dia. Ya, amin.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 8, '"Aku adalah Alfa dan Omega, firman Tuhan Allah, yang ada dan yang sudah ada dan yang akan datang, Yang Mahakuasa."', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 9, 'Aku, Yohanes, saudara dan sekutumu dalam kesusahan, dalam Kerajaan dan dalam ketekunan menantikan Yesus, berada di pulau yang bernama Patmos oleh karena firman Allah dan kesaksian yang diberikan oleh Yesus.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 10, 'Pada hari Tuhan aku dikuasai oleh Roh dan aku mendengar dari belakangku suatu suara yang nyaring, seperti bunyi sangkakala,', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 11, 'katanya: "Apa yang engkau lihat, tuliskanlah di dalam sebuah kitab dan kirimkanlah kepada ketujuh jemaat ini: ke Efesus, ke Smirna, ke Pergamus, ke Tiatira, ke Sardis, ke Filadelfia dan ke Laodikia."', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 12, 'Lalu aku berpaling untuk melihat suara yang berbicara kepadaku. Dan setelah aku berpaling, tampaklah kepadaku tujuh kaki dian dari emas.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 13, 'Dan di tengah-tengah kaki dian itu ada seorang serupa Anak Manusia, berpakaian jubah yang panjangnya sampai di kaki, dan dadanya berlilitkan ikat pinggang dari emas.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 14, 'Kepala dan rambut-Nya putih bagaikan bulu yang putih metah, dan mata-Nya bagaikan nyala api.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 15, 'Dan kaki-Nya mengkilap bagaikan tembaga membara di dalam perapian; suara-Nya bagaikan desau air bah.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 16, 'Dan di tangan kanan-Nya Ia memegang tujuh bintang dan dari mulut-Nya keluar sebilah pedang tajam bermata dua, dan wajah-Nya bersinar-sinar bagaikan matahari yang terik.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 17, 'Ketika aku melihat Dia, tersungkurlah aku di depan kaki-Nya sama seperti orang yang mati; tetapi Ia meletakkan tangan kanan-Nya di atasku, lalu berkata: "Jangan takut! Aku adalah Yang Awal dan Yang Akhir,', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 18, 'dan Yang Hidup. Aku telah mati, namun lihatlah, Aku hidup, sampai selama-lamanya dan Aku memegang segala kunci maut dan kerajaan maut.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 19, 'Karena itu tuliskanlah apa yang telah kaulihat, baik yang terjadi sekarang maupun yang akan terjadi sesudah ini.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 1, 20, 'Dan rahasia ketujuh bintang yang telah kaulihat pada tangan kanan-Ku dan ketujuh kaki dian emas itu: ketujuh bintang itu ialah malaikat ketujuh jemaat dan ketujuh kaki dian itu ialah ketujuh jemaat."', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 2, 1, '"Tuliskanlah kepada malaikat jemaat di Efesus: Inilah firman dari Dia, yang memegang ketujuh bintang itu di tangan kanan-Nya dan berjalan di antara ketujuh kaki dian emas itu.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 2, 2, 'Aku tahu segala pekerjaanmu: baik jerih payahmu maupun ketekunanmu. Aku tahu, bahwa engkau tidak dapat sabar terhadap orang-orang jahat, bahwa engkau telah mencobai mereka yang menyebut dirinya rasul, tetapi yang sebenarnya tidak demikian, bahwa engkau telah mendapati mereka pendusta.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 2, 3, 'Dan engkau tetap sabar dan menderita oleh karena nama-Ku; dan engkau tidak mengenal lelah.', 'id', 'TB'),
  ('66', 'why', 'Wahyu', 2, 4, 'Namun demikian Aku mencela engkau, karena engkau telah meninggalkan kasihmu yang semula.', 'id', 'TB')
